CATALOG.push(...[{"id":"k12-server","grade":"12","subject":{"de":"IT-Systeme · Server & Automation","fa":"سیستم‌های IT؛ سرور و خودکارسازی","en":"IT systems · servers and automation"},"order":["serverdienst","virtualisierung","identitaet","automation","monitoring","backup"],"de":{"serverdienst":{"title":"Serverdienste planen und bereitstellen","goal":"Du leitest aus einem Kundenbedarf einen prüfbaren Serverdienst ab.","definition":"Ein Serverdienst stellt anderen Geräten eine bestimmte Funktion über ein Netzwerk bereit. Beispiele sind Dateizugriff, Namensauflösung oder eine Webanwendung. Server bezeichnet dabei eine Rolle; mehrere Dienste können auf derselben Hardware laufen.","explanation":"1. Anforderungen erheben: Kläre zuerst Benutzerzahl, Datenmenge, Zugriffszeiten und erlaubte Ausfälle. Beschreibe den Nutzen, beispielsweise gemeinsame Projektdateien. Ohne diese Angaben lässt sich die passende Plattform nicht begründet auswählen.\n\n2. Plattform und Konfiguration wählen: Vergleiche Betriebssystem, Ressourcen, unterstützte Protokolle und Lizenzbedingungen. Plane Dienstkonto, Netzwerkadresse, Freigaben und Firewallregeln. Ein Dienst benötigt nur die Berechtigungen, die seine Aufgabe erfordert.\n\n3. Testen und in Betrieb nehmen: Teste aus Sicht eines berechtigten Clients und zusätzlich mit einem unberechtigten Konto. Prüfe Neustart, Protokollierung und Wiederherstellung. Dokumentiere Zuständigkeit, Konfiguration und Wartungsfenster, damit der Dienst auch nach der Installation betreut werden kann.","sections":[{"title":"1. Anforderungen erheben","body":"Kläre zuerst Benutzerzahl, Datenmenge, Zugriffszeiten und erlaubte Ausfälle. Beschreibe den Nutzen, beispielsweise gemeinsame Projektdateien. Ohne diese Angaben lässt sich die passende Plattform nicht begründet auswählen."},{"title":"2. Plattform und Konfiguration wählen","body":"Vergleiche Betriebssystem, Ressourcen, unterstützte Protokolle und Lizenzbedingungen. Plane Dienstkonto, Netzwerkadresse, Freigaben und Firewallregeln. Ein Dienst benötigt nur die Berechtigungen, die seine Aufgabe erfordert."},{"title":"3. Testen und in Betrieb nehmen","body":"Teste aus Sicht eines berechtigten Clients und zusätzlich mit einem unberechtigten Konto. Prüfe Neustart, Protokollierung und Wiederherstellung. Dokumentiere Zuständigkeit, Konfiguration und Wartungsfenster, damit der Dienst auch nach der Installation betreut werden kann."}],"example":"Ein Büro benötigt gemeinsame Dateien für 25 Personen. Du vereinbarst Gruppenrechte, 2 TB nutzbaren Speicher und tägliche Sicherung. Danach prüfst du, ob ein Teammitglied Dateien bearbeiten kann und ein Gast keinen Zugriff erhält. Erst diese Ergebnisse zeigen, ob der Kundenbedarf erfüllt ist.","mistake":"Eine erfolgreiche Installation beweist noch nicht, dass Rechte, Datensicherung und Clientzugriff richtig funktionieren.","terms":[["Serverdienst","Netzwerkfunktion, die Clients nutzen können."],["Client","Gerät oder Programm, das einen Dienst anfordert."],["Dienstkonto","Identität, unter der ein Dienst ausgeführt wird."],["Wartungsfenster","Vereinbarter Zeitraum für geplante Arbeiten."],["Berechtigung","Erlaubte Aktion auf einer Ressource."],["Funktionstest","Prüfung einer vereinbarten Funktion."]],"q":"Was beschreibt eine prüfbare Anforderung an einen Dateidienst?","options":["Der Server soll modern sein.","25 Benutzer sollen ihre Teamdateien bearbeiten können.","Wir installieren irgendein Betriebssystem."],"answer":1,"feedback":"Benutzerzahl und erlaubte Aktion lassen sich mit Testkonten konkret prüfen.","remember":["Ein Serverdienst wird nach Nutzerbedarf ausgewählt.","Zugriffe mit berechtigten und unberechtigten Konten testen.","Betrieb braucht Verantwortliche, Wartung und Wiederherstellung."],"summary":"Ein Serverdienst ist erst sinnvoll bereitgestellt, wenn seine benötigte Funktion und sein weiterer Betrieb überprüfbar gesichert sind."},"virtualisierung":{"title":"Virtualisierung und Container unterscheiden","goal":"Du erklärst Hypervisor, virtuelle Maschine und Container und wählst passend zum Einsatz.","definition":"Virtualisierung teilt physische Rechenressourcen in voneinander getrennte virtuelle Systeme. So können mehrere Arbeitsumgebungen auf einem Host betrieben und Ressourcen gezielter genutzt werden.","explanation":"1. Host und Hypervisor: Der Host stellt CPU, RAM, Speicher und Netzwerk bereit. Ein Hypervisor verwaltet virtuelle Maschinen und teilt ihnen Ressourcen zu. Aus Sicht einer VM erscheinen diese Ressourcen wie eigene Hardware.\n\n2. Virtuelle Maschine: Eine VM besitzt gewöhnlich ein eigenes Gastbetriebssystem einschließlich Kernel. Dadurch lassen sich verschiedene Betriebssysteme getrennt betreiben. Jede VM benötigt Ressourcen; Überbelegung kann mehrere Dienste gleichzeitig verlangsamen.\n\n3. Container: Container isolieren Anwendungen und ihre Abhängigkeiten auf Betriebssystemebene. Sie teilen gewöhnlich den Kernel ihres Hosts. Ein Container ist deshalb keine kleine VM mit eigenem Kernel. Für beide Varianten müssen Updates, Datenhaltung und Wiederherstellung geplant werden.","sections":[{"title":"1. Host und Hypervisor","body":"Der Host stellt CPU, RAM, Speicher und Netzwerk bereit. Ein Hypervisor verwaltet virtuelle Maschinen und teilt ihnen Ressourcen zu. Aus Sicht einer VM erscheinen diese Ressourcen wie eigene Hardware."},{"title":"2. Virtuelle Maschine","body":"Eine VM besitzt gewöhnlich ein eigenes Gastbetriebssystem einschließlich Kernel. Dadurch lassen sich verschiedene Betriebssysteme getrennt betreiben. Jede VM benötigt Ressourcen; Überbelegung kann mehrere Dienste gleichzeitig verlangsamen."},{"title":"3. Container","body":"Container isolieren Anwendungen und ihre Abhängigkeiten auf Betriebssystemebene. Sie teilen gewöhnlich den Kernel ihres Hosts. Ein Container ist deshalb keine kleine VM mit eigenem Kernel. Für beide Varianten müssen Updates, Datenhaltung und Wiederherstellung geplant werden."}],"example":"Ein Host besitzt 32 GB RAM. Zwei VMs bekommen je 8 GB, eine weitere 4 GB. Die geplanten 20 GB lassen Reserven für Host und Verwaltung; zusätzlich prüfst du den tatsächlichen Lastbedarf. Ein Snapshot hilft bei bestimmten Änderungen, ersetzt aber keine unabhängig gespeicherte Datensicherung.","mistake":"Eine VM ist nur so ausfallsicher wie die tatsächlich geplante Host-, Speicher- und Wiederherstellungsarchitektur.","terms":[["Host","Physisches oder übergeordnetes System, das Ressourcen bereitstellt."],["Hypervisor","Software zur Verwaltung virtueller Maschinen."],["VM","Virtuelle Maschine mit eigenem Gastbetriebssystem."],["Container","Isolierte Anwendungsumgebung auf Betriebssystemebene."],["Snapshot","Zustandsabbild zu einem bestimmten Zeitpunkt."],["Overcommitment","Zuweisung von mehr virtuellen als gleichzeitig verfügbaren physischen Ressourcen."]],"q":"Was teilen Container gewöhnlich mit ihrem Host?","options":["Den Betriebssystemkernel","Alle Passwörter","Jeden Anwendungsprozess"],"answer":0,"feedback":"Container isolieren Anwendungen, nutzen aber normalerweise den Kernel des Hosts.","remember":["Der Hypervisor verteilt Ressourcen an VMs.","Eine VM hat gewöhnlich einen eigenen Kernel; Container teilen gewöhnlich den Hostkernel.","Snapshot und unabhängig gespeichertes Backup erfüllen unterschiedliche Aufgaben."],"summary":"Die passende Isolierung ergibt sich aus Betriebssystembedarf, Ressourcen und Ausfallplanung statt allein aus der Anzahl virtueller Systeme."},"identitaet":{"title":"Identitäten, Gruppen und Rechte verwalten","goal":"Du trennst Anmeldung von Berechtigungsprüfung und setzt Gruppenrechte nachvollziehbar ein.","definition":"Identitätsverwaltung organisiert Benutzerkonten und ihre Zuordnung zu Menschen oder Diensten. Sie schafft eine gemeinsame Grundlage dafür, wer sich anmelden und auf welche Ressourcen zugreifen darf.","explanation":"1. Authentifizierung: Das System prüft die behauptete Identität, zum Beispiel mit Kennwort und einem zusätzlichen Faktor. Das beantwortet die Frage: Wer bist du? Ein Verzeichnis speichert Konten und Gruppen; der konkrete Anmeldedienst führt die Prüfung durch.\n\n2. Autorisierung: Nach erfolgreicher Anmeldung wird geprüft, welche Aktionen erlaubt sind. Gruppen bündeln Rechte nach Aufgaben. Vergib Dateizugriff möglichst an fachlich sinnvolle Gruppen und ordne Benutzer diesen Gruppen zu.\n\n3. Kontenlebenszyklus: Beim Eintritt werden nur benötigte Rechte vergeben. Bei einem Abteilungswechsel werden sie angepasst. Beim Austritt wird der Zugang zeitnah beendet. Administrative Aufgaben sollten über getrennte, besonders geschützte Konten erfolgen.","sections":[{"title":"1. Authentifizierung","body":"Das System prüft die behauptete Identität, zum Beispiel mit Kennwort und einem zusätzlichen Faktor. Das beantwortet die Frage: Wer bist du? Ein Verzeichnis speichert Konten und Gruppen; der konkrete Anmeldedienst führt die Prüfung durch."},{"title":"2. Autorisierung","body":"Nach erfolgreicher Anmeldung wird geprüft, welche Aktionen erlaubt sind. Gruppen bündeln Rechte nach Aufgaben. Vergib Dateizugriff möglichst an fachlich sinnvolle Gruppen und ordne Benutzer diesen Gruppen zu."},{"title":"3. Kontenlebenszyklus","body":"Beim Eintritt werden nur benötigte Rechte vergeben. Bei einem Abteilungswechsel werden sie angepasst. Beim Austritt wird der Zugang zeitnah beendet. Administrative Aufgaben sollten über getrennte, besonders geschützte Konten erfolgen."}],"example":"Eine neue Mitarbeiterin im Einkauf erhält ein persönliches Konto und wird Mitglied der Gruppe Einkauf. Diese Gruppe darf Angebote bearbeiten. Sie erhält keine Rechte für Personalakten. Beim Wechsel in den Vertrieb entfernst du die alte Gruppenzuordnung und prüfst die neue.","mistake":"Ein erfolgreich angemeldeter Benutzer ist nicht automatisch berechtigt, jede Datei zu lesen.","terms":[["Authentifizierung","Prüfung einer behaupteten Identität."],["Autorisierung","Prüfung erlaubter Aktionen nach der Anmeldung."],["Verzeichnisdienst","Zentrale Verwaltung von Identitäten und weiteren Objekten."],["Gruppe","Zusammenfassung von Konten oder Rollen für gemeinsame Verwaltung."],["Least Privilege","Nur die für eine Aufgabe notwendigen Rechte."],["Kontenlebenszyklus","Anlegen, Anpassen, Sperren und Entfernen von Konten."]],"q":"Welche Frage beantwortet Autorisierung?","options":["Wer bist du?","Was darfst du tun?","Wie schnell ist dein Netzwerk?"],"answer":1,"feedback":"Autorisierung entscheidet über erlaubte Handlungen auf einer Ressource.","remember":["Authentifizierung prüft Identität; Autorisierung prüft Rechte.","Gruppen bündeln Berechtigungen nach Aufgaben.","Eintritt, Wechsel und Austritt erfordern passende Rechteänderungen."],"summary":"Zuverlässige Identitätsverwaltung verbindet persönliche Konten mit aufgabenbezogenen Gruppen und einem gepflegten Kontenlebenszyklus."},"automation":{"title":"Administration mit Skripten automatisieren","goal":"Du beschreibst einen sicheren Automatisierungsablauf mit Eingabeprüfung, Test und Protokoll.","definition":"Automatisierung lässt wiederkehrende Administrationsaufgaben nach festgelegten Regeln ausführen. Ein Skript kann etwa Konten anlegen oder Sicherungsstände prüfen. Es soll reproduzierbare Ergebnisse liefern und Fehler sichtbar machen.","explanation":"1. Eingaben und Zielzustand: Lege fest, was eingegeben wird und welches Ergebnis entstehen soll. Prüfe Dateiformat, Pflichtfelder und zulässige Werte, bevor Änderungen erfolgen. Geheimnisse gehören nicht als Klartext in ein veröffentlichtes Skript.\n\n2. Kontrolliert ausführen: Teste zuerst in einer geeigneten Testumgebung oder mit ungefährlicher Beispielmenge. Nutze bei passenden Werkzeugen eine Vorschau. Idempotenz bedeutet: Wiederholtes Anwenden führt zum gleichen gewünschten Zustand, ohne unnötige zusätzliche Änderungen.\n\n3. Fehler behandeln und dokumentieren: Prüfe Rückgabewerte und protokolliere Ergebnis sowie Fehler. Benenne, welche Schritte erfolgreich waren und wie ein Abbruch behandelt wird. Plane Ausführungszeit, benötigte Rechte und verantwortliche Person.","sections":[{"title":"1. Eingaben und Zielzustand","body":"Lege fest, was eingegeben wird und welches Ergebnis entstehen soll. Prüfe Dateiformat, Pflichtfelder und zulässige Werte, bevor Änderungen erfolgen. Geheimnisse gehören nicht als Klartext in ein veröffentlichtes Skript."},{"title":"2. Kontrolliert ausführen","body":"Teste zuerst in einer geeigneten Testumgebung oder mit ungefährlicher Beispielmenge. Nutze bei passenden Werkzeugen eine Vorschau. Idempotenz bedeutet: Wiederholtes Anwenden führt zum gleichen gewünschten Zustand, ohne unnötige zusätzliche Änderungen."},{"title":"3. Fehler behandeln und dokumentieren","body":"Prüfe Rückgabewerte und protokolliere Ergebnis sowie Fehler. Benenne, welche Schritte erfolgreich waren und wie ein Abbruch behandelt wird. Plane Ausführungszeit, benötigte Rechte und verantwortliche Person."}],"example":"Eine CSV-Datei enthält zehn neue Benutzer. Das Skript prüft jede E-Mail-Adresse, legt nur noch nicht vorhandene Konten an und protokolliert jede Zeile. Beim zweiten Lauf sollen keine doppelten Konten entstehen. Eine ungültige Zeile wird mit verständlicher Fehlermeldung zurückgewiesen.","mistake":"Ein Skript, das ohne Meldung endet, ist nicht automatisch erfolgreich. Der gewünschte Zustand muss geprüft werden.","terms":[["Skript","Abfolge ausführbarer Anweisungen."],["Parameter","Wert, der einem Skript beim Aufruf übergeben wird."],["Validierung","Prüfung von Eingaben gegen Regeln."],["Idempotenz","Wiederholung verändert einen bereits erreichten Zielzustand nicht erneut."],["Rückgabewert","Ergebnis, mit dem ein Programm seinen Ausgang meldet."],["Protokoll","Nachvollziehbare Aufzeichnung wichtiger Ereignisse."]],"q":"Was bedeutet Idempotenz beim Anlegen von Konten?","options":["Jeder Lauf legt dieselben Konten noch einmal an.","Ein weiterer Lauf erzeugt keine unnötigen Doppelkonten.","Fehler werden grundsätzlich ignoriert."],"answer":1,"feedback":"Das Skript prüft den bestehenden Zustand und führt nur die noch erforderlichen Änderungen aus.","remember":["Eingaben vor Änderungen validieren.","Idempotente Abläufe erzeugen bei Wiederholung keine unnötigen Änderungen.","Erfolg wird am Zielzustand und Protokoll geprüft."],"summary":"Ein gutes Administrationsskript ist kontrolliert testbar, nachvollziehbar wiederholbar und meldet Fehler verständlich."},"monitoring":{"title":"Monitoring: Messen, bewerten, reagieren","goal":"Du unterscheidest Messwert, Grenzwert und Alarm und formulierst eine hilfreiche Überwachung.","definition":"Monitoring beobachtet technische Zustände fortlaufend. Es soll Probleme erkennbar machen, bevor oder während Benutzer beeinträchtigt werden. Ein Messwert allein ist noch keine Bewertung des Dienstes.","explanation":"1. Geeignete Werte erfassen: Erfasse zur Anforderung passende Daten: Antwortzeit, erfolgreiche Anmeldungen, freien Speicher oder Sicherungsfehler. Infrastrukturwerte wie CPU-Auslastung ergänzen Diensttests, ersetzen sie aber nicht.\n\n2. Werte im Kontext bewerten: Ein kurzer Lastanstieg kann normal sein. Ein Alarm sollte auf sinnvollen Grenzwerten, Dauer und Auswirkung beruhen. Über Trends erkennst du, ob Speicher in einigen Wochen knapp wird. Wartungen werden berücksichtigt, damit erwartete Ausfälle nicht unnötig alarmieren.\n\n3. Verantwortlich reagieren: Ein Alarm braucht Empfänger, Priorität und Handlungsanweisung. Dokumentiere Prüfung, Ursache und Maßnahme. Kontrolliere nach der Behebung auch den Dienst aus Nutzersicht. Zu viele unwichtige Meldungen können wichtige Warnungen verdecken.","sections":[{"title":"1. Geeignete Werte erfassen","body":"Erfasse zur Anforderung passende Daten: Antwortzeit, erfolgreiche Anmeldungen, freien Speicher oder Sicherungsfehler. Infrastrukturwerte wie CPU-Auslastung ergänzen Diensttests, ersetzen sie aber nicht."},{"title":"2. Werte im Kontext bewerten","body":"Ein kurzer Lastanstieg kann normal sein. Ein Alarm sollte auf sinnvollen Grenzwerten, Dauer und Auswirkung beruhen. Über Trends erkennst du, ob Speicher in einigen Wochen knapp wird. Wartungen werden berücksichtigt, damit erwartete Ausfälle nicht unnötig alarmieren."},{"title":"3. Verantwortlich reagieren","body":"Ein Alarm braucht Empfänger, Priorität und Handlungsanweisung. Dokumentiere Prüfung, Ursache und Maßnahme. Kontrolliere nach der Behebung auch den Dienst aus Nutzersicht. Zu viele unwichtige Meldungen können wichtige Warnungen verdecken."}],"example":"Eine Dateifreigabe soll mindestens 15 % freien Speicher behalten. Das Monitoring meldet eine Warnung, wenn dieser Wert länger unterschritten wird. Der Trend zeigt zusätzlich 30 GB Zuwachs pro Woche. Du kannst dadurch Kapazität planen, bevor der Dienst keine Dateien mehr speichern kann.","mistake":"Ein antwortender Server beweist nicht, dass seine Anwendung korrekt arbeitet. Prüfe auch die eigentliche Dienstfunktion.","terms":[["Messwert","Erfasste technische Größe."],["Grenzwert","Festgelegte Schwelle für eine Bewertung."],["Alarm","Meldung eines handlungsbedürftigen Zustands."],["Trend","Entwicklung eines Wertes über Zeit."],["Verfügbarkeit","Nutzbarkeit eines Dienstes im betrachteten Zeitraum."],["Alarmmüdigkeit","Nachlassende Aufmerksamkeit durch zu viele unwichtige Meldungen."]],"q":"Welche Prüfung ist für einen Webdienst besonders aussagekräftig?","options":["Nur prüfen, ob der Rechner Strom hat.","Nur den Gehäuseaufkleber lesen.","Eine erwartete Webseite abrufen und Antwort prüfen."],"answer":2,"feedback":"Der Diensttest prüft näher an der tatsächlichen Nutzerfunktion als ein reiner Hardwarezustand.","remember":["Diensttests ergänzen Infrastrukturmesswerte.","Grenzwerte brauchen Kontext, Dauer und passende Empfänger.","Trends unterstützen frühzeitige Kapazitätsplanung."],"summary":"Monitoring wird wirksam, wenn aus passenden Messungen eine begründete Warnung und eine klare Handlung entstehen."},"backup":{"title":"Datensicherung und Wiederherstellung planen","goal":"Du unterscheidest Backup, Restore, RPO und RTO und planst einen Wiederherstellungstest.","definition":"Eine Datensicherung erstellt wiederherstellbare Kopien wichtiger Daten. Ihr Zweck ist die Rückkehr zu einem brauchbaren Zustand nach Verlust, Beschädigung oder einem Angriff. Entscheidend ist, ob die Rücksicherung funktioniert.","explanation":"1. Sicherungsziel festlegen: Bestimme Daten, Verantwortliche und Aufbewahrung. RPO beschreibt den maximal tolerierbaren Datenverlust als Zeitspanne. RTO beschreibt die angestrebte maximale Wiederherstellungsdauer. Diese Ziele bestimmen Häufigkeit und Verfahren.\n\n2. Kopien getrennt schützen: Eine Vollsicherung kopiert den ausgewählten Datenbestand vollständig. Inkrementelle Sicherungen erfassen Änderungen seit der letzten relevanten Sicherung. Bewahre geeignete Kopien getrennt auf und schütze sie vor unberechtigter Änderung oder Löschung.\n\n3. Restore testen: Stelle Daten in einer geeigneten Testumgebung wieder her. Prüfe Inhalt, Zugriffsrechte und benötigte Zeit. Ein Backupbericht mit Erfolgsmeldung ersetzt diesen Test nicht. Dokumentiere, wer im Notfall welche Schritte ausführt.","sections":[{"title":"1. Sicherungsziel festlegen","body":"Bestimme Daten, Verantwortliche und Aufbewahrung. RPO beschreibt den maximal tolerierbaren Datenverlust als Zeitspanne. RTO beschreibt die angestrebte maximale Wiederherstellungsdauer. Diese Ziele bestimmen Häufigkeit und Verfahren."},{"title":"2. Kopien getrennt schützen","body":"Eine Vollsicherung kopiert den ausgewählten Datenbestand vollständig. Inkrementelle Sicherungen erfassen Änderungen seit der letzten relevanten Sicherung. Bewahre geeignete Kopien getrennt auf und schütze sie vor unberechtigter Änderung oder Löschung."},{"title":"3. Restore testen","body":"Stelle Daten in einer geeigneten Testumgebung wieder her. Prüfe Inhalt, Zugriffsrechte und benötigte Zeit. Ein Backupbericht mit Erfolgsmeldung ersetzt diesen Test nicht. Dokumentiere, wer im Notfall welche Schritte ausführt."}],"example":"Ein Team toleriert höchstens vier Stunden Datenverlust: RPO = 4 h. Eine tägliche Sicherung allein kann dieses Ziel nicht zuverlässig erfüllen. Für RTO = 2 h misst du im Test, wie lange Datenbereitstellung, Rücksicherung und Funktionskontrolle zusammen dauern.","mistake":"RAID erhöht je nach Aufbau die Ausfalltoleranz von Laufwerken, schützt aber nicht zuverlässig vor versehentlichem Löschen und ersetzt kein Backup.","terms":[["Backup","Wiederherstellbare Kopie wichtiger Daten."],["Restore","Rücksicherung von Daten oder Systemen."],["RPO","Maximal tolerierter Datenverlust, als Zeitspanne beschrieben."],["RTO","Angestrebte maximale Dauer der Wiederherstellung."],["Vollsicherung","Sicherung des gesamten ausgewählten Bestands."],["Inkrementell","Sicherung der Änderungen seit der letzten relevanten Sicherung."]],"q":"Eine tägliche Sicherung: Erfüllt sie sicher ein RPO von vier Stunden?","options":["Ja, unabhängig vom Zeitpunkt.","Nein, die Sicherungsabstände sind dafür zu groß.","RPO betrifft ausschließlich CPU-Leistung."],"answer":1,"feedback":"Bei täglichen Sicherungen kann seit dem letzten Sicherungsstand deutlich mehr als vier Stunden Arbeit verloren gehen.","remember":["RPO beschreibt tolerierbaren Datenverlust, RTO die angestrebte Wiederherstellungsdauer.","Kopien müssen auch vor unberechtigter Änderung geschützt sein.","Ein Restore-Test prüft Daten, Rechte und benötigte Zeit."],"summary":"Eine brauchbare Datensicherung richtet Sicherungsabstände und Wiederherstellung an den vereinbarten Verlust- und Ausfallgrenzen aus."}},"fa":{"serverdienst":{"title":"برنامه‌ریزی و راه‌اندازی سرویس سرور","goal":"از نیاز مشتری یک سرویس قابل آزمایش طراحی کنی.","definition":"سرویس سرور یک قابلیت مشخص را از طریق شبکه در اختیار دستگاه‌ها می‌گذارد؛ مثل اشتراک فایل، DNS یا برنامهٔ وب. سرور در اینجا یک نقش است و یک دستگاه می‌تواند چند سرویس داشته باشد.","explanation":"۱. نیاز را بفهم: ابتدا تعداد کاربران، حجم داده، ساعت دسترسی و مدت قطعی مجاز را بپرس. کاربرد را مشخص کن؛ مثلاً دسترسی مشترک به فایل‌های پروژه. انتخاب سیستم بدون شناخت این نیازها دلیل روشنی ندارد.\n\n۲. سیستم و تنظیمات را انتخاب کن: سیستم‌عامل، منابع، پروتکل‌های مورد نیاز و مجوز نرم‌افزار را مقایسه کن. برای حساب سرویس، آدرس شبکه، پوشه‌های مشترک و قواعد فایروال برنامه داشته باش. سرویس فقط دسترسی لازم برای کار خودش را می‌گیرد.\n\n۳. آزمایش و تحویل: با حساب مجاز و حساب غیرمجاز آزمایش کن. راه‌اندازی دوباره، ثبت رویداد و بازیابی را هم بررسی کن. تنظیمات، مسئول نگهداری و زمان تعمیرات را ثبت کن تا سرویس پس از نصب هم قابل مدیریت باشد.","sections":[{"title":"۱. نیاز را بفهم","body":"ابتدا تعداد کاربران، حجم داده، ساعت دسترسی و مدت قطعی مجاز را بپرس. کاربرد را مشخص کن؛ مثلاً دسترسی مشترک به فایل‌های پروژه. انتخاب سیستم بدون شناخت این نیازها دلیل روشنی ندارد."},{"title":"۲. سیستم و تنظیمات را انتخاب کن","body":"سیستم‌عامل، منابع، پروتکل‌های مورد نیاز و مجوز نرم‌افزار را مقایسه کن. برای حساب سرویس، آدرس شبکه، پوشه‌های مشترک و قواعد فایروال برنامه داشته باش. سرویس فقط دسترسی لازم برای کار خودش را می‌گیرد."},{"title":"۳. آزمایش و تحویل","body":"با حساب مجاز و حساب غیرمجاز آزمایش کن. راه‌اندازی دوباره، ثبت رویداد و بازیابی را هم بررسی کن. تنظیمات، مسئول نگهداری و زمان تعمیرات را ثبت کن تا سرویس پس از نصب هم قابل مدیریت باشد."}],"example":"یک دفتر برای ۲۵ نفر فایل مشترک می‌خواهد. دسترسی گروه‌ها، ۲ ترابایت فضای قابل استفاده و پشتیبان روزانه را توافق می‌کنی. سپس بررسی می‌کنی عضو تیم بتواند فایل را ویرایش کند ولی مهمان دسترسی نداشته باشد. این نتیجه نشان می‌دهد نیاز مشتری برآورده شده است.","mistake":"نصب موفق به‌تنهایی ثابت نمی‌کند که دسترسی‌ها، پشتیبان‌گیری و اتصال کاربران درست کار می‌کنند.","terms":[["Serverdienst","قابلیتی که کلاینت‌ها در شبکه استفاده می‌کنند."],["Client","دستگاه یا برنامهٔ درخواست‌کنندهٔ سرویس."],["Dienstkonto","حسابی که سرویس با آن اجرا می‌شود."],["Wartungsfenster","زمان توافق‌شده برای کارهای نگهداری."],["Berechtigung","اجازهٔ یک عمل روی منبع."],["Funktionstest","آزمایش عملکرد توافق‌شده."]],"q":"کدام نیاز سرویس فایل قابل آزمایش است؟","options":["سرور مدرن باشد.","۲۵ کاربر بتوانند فایل‌های تیم خود را ویرایش کنند.","یک سیستم‌عامل دلخواه نصب کنیم."],"answer":1,"feedback":"تعداد کاربر و عمل مجاز را می‌توان با حساب‌های آزمایشی بررسی کرد.","remember":["سرویس بر پایهٔ نیاز کاربر انتخاب می‌شود.","با حساب مجاز و غیرمجاز دسترسی را آزمایش کن.","مسئول، نگهداری و بازیابی بخشی از بهره‌برداری‌اند."],"summary":"راه‌اندازی سرویس زمانی کامل است که عملکرد لازم و ادامهٔ نگهداری آن روشن و قابل بررسی باشد."},"virtualisierung":{"title":"تفاوت ماشین مجازی و Container","goal":"نقش Host، Hypervisor، ماشین مجازی و Container را توضیح بدهی.","definition":"مجازی‌سازی منابع یک دستگاه را به محیط‌های مجازی جدا تقسیم می‌کند. به این شکل چند محیط کاری روی یک Host اجرا می‌شود و استفاده از منابع قابل برنامه‌ریزی است.","explanation":"۱. Host و Hypervisor: Host پردازنده، RAM، فضای ذخیره و شبکه را فراهم می‌کند. Hypervisor ماشین‌های مجازی را مدیریت و منابع را بین آن‌ها تقسیم می‌کند. از دید ماشین مجازی، این منابع شبیه سخت‌افزار خودش هستند.\n\n۲. ماشین مجازی: یک VM معمولاً سیستم‌عامل مهمان و Kernel جداگانه دارد؛ بنابراین می‌توان سیستم‌عامل‌های مختلف را جدا اجرا کرد. هر VM منابع مصرف می‌کند و اختصاص بیش از حد منابع می‌تواند چند سرویس را هم‌زمان کند کند.\n\n۳. Container: Container برنامه و وابستگی‌های آن را در سطح سیستم‌عامل جدا می‌کند و معمولاً Kernel را با Host مشترک دارد. پس Container یک VM کوچک با Kernel مستقل نیست. در هر دو روش باید به‌روزرسانی، نگهداری داده و بازیابی مشخص باشد.","sections":[{"title":"۱. Host و Hypervisor","body":"Host پردازنده، RAM، فضای ذخیره و شبکه را فراهم می‌کند. Hypervisor ماشین‌های مجازی را مدیریت و منابع را بین آن‌ها تقسیم می‌کند. از دید ماشین مجازی، این منابع شبیه سخت‌افزار خودش هستند."},{"title":"۲. ماشین مجازی","body":"یک VM معمولاً سیستم‌عامل مهمان و Kernel جداگانه دارد؛ بنابراین می‌توان سیستم‌عامل‌های مختلف را جدا اجرا کرد. هر VM منابع مصرف می‌کند و اختصاص بیش از حد منابع می‌تواند چند سرویس را هم‌زمان کند کند."},{"title":"۳. Container","body":"Container برنامه و وابستگی‌های آن را در سطح سیستم‌عامل جدا می‌کند و معمولاً Kernel را با Host مشترک دارد. پس Container یک VM کوچک با Kernel مستقل نیست. در هر دو روش باید به‌روزرسانی، نگهداری داده و بازیابی مشخص باشد."}],"example":"Host دارای ۳۲ گیگابایت RAM است. دو VM هرکدام ۸ و یک VM دیگر ۴ گیگابایت می‌گیرند؛ مجموع ۲۰ گیگابایت است و برای Host هم فضا باقی می‌ماند. مصرف واقعی نیز باید بررسی شود. Snapshot برای بعضی تغییرات مفید است اما جای پشتیبان مستقل را نمی‌گیرد.","mistake":"ماشین مجازی به‌تنهایی مانع قطعی نیست؛ خرابی Host و محل ذخیره هنوز باید در طرح دیده شود.","terms":[["Host","سیستم میزبان که منابع را فراهم می‌کند."],["Hypervisor","نرم‌افزار مدیریت ماشین‌های مجازی."],["VM","ماشین مجازی با سیستم‌عامل مهمان."],["Container","محیط جداشدهٔ اجرای برنامه در سطح سیستم‌عامل."],["Snapshot","ثبت وضعیت یک لحظهٔ مشخص."],["Overcommitment","اختصاص منابع مجازی بیشتر از منابع فیزیکی هم‌زمان موجود."]],"q":"Container معمولاً چه چیزی را با Host شریک است؟","options":["Kernel سیستم‌عامل","همهٔ رمزهای عبور","همهٔ پردازش‌های برنامه"],"answer":0,"feedback":"Container برنامه‌ها را جدا می‌کند اما معمولاً Kernel میزبان را به کار می‌گیرد.","remember":["Hypervisor منابع را بین ماشین‌های مجازی تقسیم می‌کند.","VM معمولاً Kernel مستقل دارد؛ Container معمولاً Kernel میزبان را شریک است.","Snapshot با پشتیبان مستقل یک کار انجام نمی‌دهد."],"summary":"انتخاب روش جداسازی به نیاز سیستم‌عامل، منابع و طرح مقابله با خرابی بستگی دارد؛ نه فقط تعداد محیط‌های مجازی."},"identitaet":{"title":"مدیریت حساب‌ها، گروه‌ها و دسترسی‌ها","goal":"احراز هویت را از بررسی مجوز جدا کنی و دسترسی گروهی را درست به کار ببری.","definition":"مدیریت هویت، حساب کاربران و سرویس‌ها را منظم می‌کند. این کار پایه‌ای برای پاسخ به دو سؤال است: چه کسی وارد می‌شود و اجازهٔ استفاده از چه منابعی را دارد؟","explanation":"۱. احراز هویت: سیستم بررسی می‌کند شخص همان کسی باشد که ادعا می‌کند؛ مثلاً با رمز و عامل دوم. سؤال این بخش «تو کی هستی؟» است. سرویس دایرکتوری حساب‌ها و گروه‌ها را نگه می‌دارد و سرویس ورود، بررسی را اجرا می‌کند.\n\n۲. بررسی مجوز: پس از ورود موفق، مشخص می‌شود چه کارهایی مجاز است. گروه‌ها دسترسی‌های یک وظیفه را جمع می‌کنند. بهتر است دسترسی پوشه را به گروه مناسب بدهی و کاربر را عضو همان گروه کنی.\n\n۳. چرخهٔ حساب: هنگام شروع کار فقط دسترسی لازم داده می‌شود. با تغییر بخش، دسترسی هم تغییر می‌کند و هنگام خروج از شرکت پایان می‌یابد. کار مدیریتی باید با حساب جداگانه و حفاظت بیشتر انجام شود.","sections":[{"title":"۱. احراز هویت","body":"سیستم بررسی می‌کند شخص همان کسی باشد که ادعا می‌کند؛ مثلاً با رمز و عامل دوم. سؤال این بخش «تو کی هستی؟» است. سرویس دایرکتوری حساب‌ها و گروه‌ها را نگه می‌دارد و سرویس ورود، بررسی را اجرا می‌کند."},{"title":"۲. بررسی مجوز","body":"پس از ورود موفق، مشخص می‌شود چه کارهایی مجاز است. گروه‌ها دسترسی‌های یک وظیفه را جمع می‌کنند. بهتر است دسترسی پوشه را به گروه مناسب بدهی و کاربر را عضو همان گروه کنی."},{"title":"۳. چرخهٔ حساب","body":"هنگام شروع کار فقط دسترسی لازم داده می‌شود. با تغییر بخش، دسترسی هم تغییر می‌کند و هنگام خروج از شرکت پایان می‌یابد. کار مدیریتی باید با حساب جداگانه و حفاظت بیشتر انجام شود."}],"example":"کارمند جدید خرید، حساب شخصی می‌گیرد و عضو گروه Einkauf می‌شود. گروه می‌تواند پیشنهادهای خرید را ویرایش کند اما پروندهٔ پرسنلی را نمی‌بیند. وقتی کارمند به فروش منتقل شد، عضویت قبلی را حذف و دسترسی جدید را بررسی می‌کنی.","mistake":"ورود موفق به سیستم به معنای اجازهٔ خواندن همهٔ فایل‌ها نیست.","terms":[["Authentifizierung","بررسی هویت ادعاشده."],["Autorisierung","بررسی اجازهٔ عمل پس از ورود."],["Verzeichnisdienst","مدیریت مرکزی هویت‌ها و اشیای مرتبط."],["Gruppe","مجموعهٔ حساب‌ها یا نقش‌ها برای مدیریت مشترک."],["Least Privilege","فقط دسترسی لازم برای انجام وظیفه."],["Kontenlebenszyklus","ساخت، تغییر، مسدودکردن و حذف حساب."]],"q":"Autorisierung به کدام سؤال پاسخ می‌دهد؟","options":["تو کی هستی؟","چه کاری اجازه داری انجام بدهی؟","سرعت شبکه چقدر است؟"],"answer":1,"feedback":"این مرحله اجازهٔ انجام عمل روی یک منبع را بررسی می‌کند.","remember":["احراز هویت، هویت را بررسی می‌کند و Autorisierung اجازهٔ عمل را.","گروه، دسترسی‌های یک وظیفه را جمع می‌کند.","شروع کار، تغییر بخش و خروج به اصلاح دسترسی نیاز دارد."],"summary":"مدیریت درست هویت، حساب شخصی را به گروه شغلی مناسب و چرخهٔ منظم تغییر و پایان دسترسی وصل می‌کند."},"automation":{"title":"خودکارسازی مدیریت با اسکریپت","goal":"مراحل امن خودکارسازی را از بررسی ورودی تا آزمایش و ثبت نتیجه توضیح بدهی.","definition":"خودکارسازی یعنی انجام کار تکراری مدیریت طبق قواعد مشخص؛ مثلاً ساخت حساب یا بررسی پشتیبان. اسکریپت باید نتیجهٔ قابل تکرار داشته باشد و خطا را قابل مشاهده کند.","explanation":"۱. ورودی و وضعیت هدف: مشخص کن چه اطلاعاتی دریافت می‌شود و چه نتیجه‌ای باید ساخته شود. قالب فایل، فیلدهای ضروری و مقادیر مجاز را پیش از تغییر بررسی کن. رمز و کلید محرمانه نباید به شکل ساده در اسکریپت منتشرشده باشد.\n\n۲. اجرای کنترل‌شده: ابتدا در محیط آزمایشی مناسب یا با تعداد کمی دادهٔ بی‌خطر آزمایش کن. اگر ابزار امکان پیش‌نمایش دارد از آن استفاده کن. Idempotenz یعنی اجرای دوباره همان وضعیت مطلوب را حفظ می‌کند و تغییر اضافی نمی‌سازد.\n\n۳. مدیریت خطا: نتیجه و خطاها را بررسی و ثبت کن. روشن باشد کدام مرحله موفق بوده و در توقف چه باید کرد. زمان اجرا، دسترسی لازم و مسئول اجرا را مشخص کن.","sections":[{"title":"۱. ورودی و وضعیت هدف","body":"مشخص کن چه اطلاعاتی دریافت می‌شود و چه نتیجه‌ای باید ساخته شود. قالب فایل، فیلدهای ضروری و مقادیر مجاز را پیش از تغییر بررسی کن. رمز و کلید محرمانه نباید به شکل ساده در اسکریپت منتشرشده باشد."},{"title":"۲. اجرای کنترل‌شده","body":"ابتدا در محیط آزمایشی مناسب یا با تعداد کمی دادهٔ بی‌خطر آزمایش کن. اگر ابزار امکان پیش‌نمایش دارد از آن استفاده کن. Idempotenz یعنی اجرای دوباره همان وضعیت مطلوب را حفظ می‌کند و تغییر اضافی نمی‌سازد."},{"title":"۳. مدیریت خطا","body":"نتیجه و خطاها را بررسی و ثبت کن. روشن باشد کدام مرحله موفق بوده و در توقف چه باید کرد. زمان اجرا، دسترسی لازم و مسئول اجرا را مشخص کن."}],"example":"فایل CSV ده کاربر جدید دارد. اسکریپت آدرس ایمیل‌ها را بررسی می‌کند، فقط حساب‌های موجودنبود‌ه را می‌سازد و نتیجهٔ هر ردیف را ثبت می‌کند. اجرای دوم نباید حساب تکراری بسازد. ردیف خراب با پیام واضح رد می‌شود.","mistake":"پایان بدون پیام به معنای موفقیت نیست؛ باید نتیجهٔ واقعی با وضعیت هدف مقایسه شود.","terms":[["Skript","مجموعه‌ای از دستورهای قابل اجرا."],["Parameter","مقدار داده‌شده هنگام اجرای اسکریپت."],["Validierung","سنجش ورودی با قواعد مشخص."],["Idempotenz","اجرای دوباره، وضعیت مطلوب موجود را دوباره تغییر نمی‌دهد."],["Rückgabewert","مقدار اعلام‌کنندهٔ نتیجهٔ برنامه."],["Protokoll","ثبت قابل پیگیری رویدادهای مهم."]],"q":"Idempotenz در ساخت حساب یعنی چه؟","options":["هر اجرا حساب‌ها را دوباره می‌سازد.","اجرای بعدی حساب تکراری اضافی نمی‌سازد.","همهٔ خطاها نادیده گرفته می‌شوند."],"answer":1,"feedback":"اسکریپت وضعیت موجود را می‌سنجد و فقط تغییر لازم را انجام می‌دهد.","remember":["پیش از تغییر، ورودی را بررسی کن.","اجرای دوبارهٔ فرایند Idempotent تغییر اضافی نمی‌سازد.","موفقیت با وضعیت واقعی و گزارش بررسی می‌شود."],"summary":"اسکریپت خوب قابل آزمایش کنترل‌شده و تکرار قابل پیگیری است و خطا را روشن گزارش می‌کند."},"monitoring":{"title":"Monitoring؛ اندازه‌گیری و واکنش","goal":"تفاوت مقدار اندازه‌گیری، حد هشدار و Alarm را بدانی.","definition":"Monitoring وضعیت فنی را پیوسته مشاهده می‌کند تا مشکل پیش از آسیب یا هنگام آن مشخص شود. خود عدد هنوز نمی‌گوید سرویس برای کاربر درست کار می‌کند.","explanation":"۱. مقدار مناسب را بسنج: دادهٔ مرتبط با نیاز را بگیر؛ مثل زمان پاسخ، ورود موفق، فضای آزاد یا خطای پشتیبان. مصرف CPU برای شناخت زیرساخت مفید است اما جای آزمایش خود سرویس را نمی‌گیرد.\n\n۲. با زمینه مقایسه کن: افزایش کوتاه مصرف ممکن است عادی باشد. هشدار باید با حد مناسب، مدت و اثر مشکل تعریف شود. روند تغییر نشان می‌دهد مثلاً چند هفته بعد فضا کم خواهد شد. تعمیرات برنامه‌ریزی‌شده نیز باید در ارزیابی دیده شود.\n\n۳. مسئولانه واکنش بده: هشدار باید گیرنده، اولویت و راهنمای اقدام داشته باشد. بررسی، علت و اقدام را ثبت کن. پس از رفع مشکل، کارکرد سرویس را از دید کاربر هم بسنج. پیام‌های کم‌اهمیت زیاد می‌توانند هشدار اصلی را پنهان کنند.","sections":[{"title":"۱. مقدار مناسب را بسنج","body":"دادهٔ مرتبط با نیاز را بگیر؛ مثل زمان پاسخ، ورود موفق، فضای آزاد یا خطای پشتیبان. مصرف CPU برای شناخت زیرساخت مفید است اما جای آزمایش خود سرویس را نمی‌گیرد."},{"title":"۲. با زمینه مقایسه کن","body":"افزایش کوتاه مصرف ممکن است عادی باشد. هشدار باید با حد مناسب، مدت و اثر مشکل تعریف شود. روند تغییر نشان می‌دهد مثلاً چند هفته بعد فضا کم خواهد شد. تعمیرات برنامه‌ریزی‌شده نیز باید در ارزیابی دیده شود."},{"title":"۳. مسئولانه واکنش بده","body":"هشدار باید گیرنده، اولویت و راهنمای اقدام داشته باشد. بررسی، علت و اقدام را ثبت کن. پس از رفع مشکل، کارکرد سرویس را از دید کاربر هم بسنج. پیام‌های کم‌اهمیت زیاد می‌توانند هشدار اصلی را پنهان کنند."}],"example":"برای فایل‌سرور حداقل ۱۵ درصد فضای آزاد توافق شده است. اگر کمبود برای مدتی ادامه داشت، هشدار می‌آید. روند مصرف رشد هفتگی ۳۰ گیگابایت را نشان می‌دهد؛ بنابراین قبل از پرشدن کامل می‌توان ظرفیت را افزایش داد.","mistake":"پاسخ‌دادن دستگاه ثابت نمی‌کند برنامهٔ آن درست کار می‌کند؛ عملکرد خود سرویس را هم بررسی کن.","terms":[["Messwert","مقدار فنی اندازه‌گیری‌شده."],["Grenzwert","مرز مشخص برای ارزیابی وضعیت."],["Alarm","پیام وضعیت نیازمند اقدام."],["Trend","روند تغییر یک مقدار در زمان."],["Verfügbarkeit","قابل استفاده بودن سرویس در بازهٔ بررسی."],["Alarmmüdigkeit","کم‌شدن توجه به علت هشدارهای غیرمهم فراوان."]],"q":"برای سرویس وب کدام آزمایش بهتر است؟","options":["فقط روشن بودن دستگاه.","خواندن برچسب کیس.","دریافت صفحهٔ مورد انتظار و بررسی پاسخ."],"answer":2,"feedback":"این آزمایش به کاری که کاربر واقعاً انجام می‌دهد نزدیک‌تر است.","remember":["آزمایش خود سرویس، اندازه‌گیری زیرساخت را کامل می‌کند.","حد هشدار به زمینه، مدت و گیرندهٔ مناسب نیاز دارد.","روند تغییر برای برنامه‌ریزی ظرفیت مفید است."],"summary":"Monitoring وقتی مؤثر است که اندازه‌گیری مناسب به هشدار مستدل و اقدام روشن منجر شود."},"backup":{"title":"برنامه‌ریزی پشتیبان و بازیابی","goal":"Backup، Restore، RPO و RTO را از هم جدا کنی.","definition":"پشتیبان‌گیری، نسخه‌ای قابل بازیابی از دادهٔ مهم می‌سازد تا پس از حذف، خرابی یا حمله بتوان به وضعیت قابل استفاده برگشت. مهم این است که بازگرداندن داده واقعاً موفق شود.","explanation":"۱. هدف را تعیین کن: داده‌ها، مسئول و مدت نگهداری را مشخص کن. RPO میزان تحمل ازدست‌رفتن داده را به شکل زمان می‌گوید. RTO مدت هدف برای بازگرداندن سرویس است. این دو مقدار فاصلهٔ پشتیبان‌ها و روش بازیابی را تعیین می‌کنند.\n\n۲. نسخه‌ها را جدا محافظت کن: پشتیبان کامل تمام دادهٔ انتخابی را کپی می‌کند. پشتیبان افزایشی تغییرات پس از پشتیبان مرتبط قبلی را می‌گیرد. نسخه‌های مناسب را جدا نگه دار و در برابر تغییر یا حذف غیرمجاز حفاظت کن.\n\n۳. بازیابی را آزمایش کن: در محیط مناسب داده را برگردان؛ محتوا، دسترسی‌ها و زمان را بررسی کن. پیام موفق پشتیبان جای آزمایش بازیابی را نمی‌گیرد. مسئول و مراحل کار اضطراری را ثبت کن.","sections":[{"title":"۱. هدف را تعیین کن","body":"داده‌ها، مسئول و مدت نگهداری را مشخص کن. RPO میزان تحمل ازدست‌رفتن داده را به شکل زمان می‌گوید. RTO مدت هدف برای بازگرداندن سرویس است. این دو مقدار فاصلهٔ پشتیبان‌ها و روش بازیابی را تعیین می‌کنند."},{"title":"۲. نسخه‌ها را جدا محافظت کن","body":"پشتیبان کامل تمام دادهٔ انتخابی را کپی می‌کند. پشتیبان افزایشی تغییرات پس از پشتیبان مرتبط قبلی را می‌گیرد. نسخه‌های مناسب را جدا نگه دار و در برابر تغییر یا حذف غیرمجاز حفاظت کن."},{"title":"۳. بازیابی را آزمایش کن","body":"در محیط مناسب داده را برگردان؛ محتوا، دسترسی‌ها و زمان را بررسی کن. پیام موفق پشتیبان جای آزمایش بازیابی را نمی‌گیرد. مسئول و مراحل کار اضطراری را ثبت کن."}],"example":"تیم حداکثر چهار ساعت ازدست‌رفتن داده را تحمل می‌کند؛ یعنی RPO چهار ساعت. پشتیبان روزانه به‌تنهایی کافی نیست. اگر RTO دو ساعت باشد، زمان آماده‌سازی، بازگرداندن و آزمایش عملکرد را با هم اندازه می‌گیری.","mistake":"RAID در بعضی حالت‌ها خرابی دیسک را تحمل می‌کند اما جای پشتیبان را نمی‌گیرد و حذف اشتباهی را جبران نمی‌کند.","terms":[["Backup","نسخهٔ قابل بازیابی دادهٔ مهم."],["Restore","برگرداندن داده یا سیستم از پشتیبان."],["RPO","حد تحمل ازدست‌رفتن داده بر حسب زمان."],["RTO","مدت هدف برای بازگرداندن سرویس."],["Vollsicherung","پشتیبان کامل دادهٔ انتخاب‌شده."],["Inkrementell","ثبت تغییرات پس از پشتیبان مرتبط قبلی."]],"q":"آیا پشتیبان روزانه قطعاً RPO چهار ساعت را تأمین می‌کند؟","options":["بله، در هر زمان.","خیر، فاصلهٔ پشتیبان‌ها خیلی زیاد است.","RPO فقط به قدرت CPU مربوط است."],"answer":1,"feedback":"ممکن است از آخرین پشتیبان روزانه بیش از چهار ساعت گذشته باشد و همان داده‌ها از دست برود.","remember":["RPO تحمل ازدست‌رفتن داده و RTO مدت هدف بازیابی را بیان می‌کند.","نسخهٔ پشتیبان باید از تغییر غیرمجاز هم محافظت شود.","تست Restore داده، دسترسی و زمان را بررسی می‌کند."],"summary":"پشتیبان مناسب، فاصلهٔ نسخه‌ها و روش بازیابی را با حد قابل تحمل ازدست‌رفتن داده و قطعی هماهنگ می‌کند."}},"learningField":"10b","coverage":{"de":"Eigenständige Lerntexte zur Vertiefung; keine vollständige IHK-Prüfungsabdeckung.","fa":"درس‌های تألیفی برای یادگیری عمیق‌تر؛ پوشش کامل امتحان IHK نیست."},"visual":{"icon":"▣","color":"#e7eef8","ink":"#4e77a2","desc":["Serverdienste bereitstellen, Identitäten verwalten und Administration automatisieren.","راه‌اندازی سرویس‌های سرور، مدیریت هویت و خودکارسازی مدیریت سیستم."]}},{"id":"k12-security","grade":"12","subject":{"de":"IT-Systeme · Betrieb & Sicherheit","fa":"سیستم‌های IT؛ بهره‌برداری و امنیت","en":"IT systems · operations and security"},"order":["schutzziele","risiko","firewall","kryptografie","patch","notfall"],"de":{"schutzziele":{"title":"Schutzziele und Schutzbedarf bestimmen","goal":"Du ordnest Schäden den drei grundlegenden Schutzzielen zu.","definition":"Informationssicherheit schützt Informationen und die Systeme, die sie verarbeiten. Die grundlegenden Schutzziele sind Vertraulichkeit, Integrität und Verfügbarkeit. Sie helfen, Anforderungen zu formulieren, bevor Schutzmaßnahmen ausgewählt werden.","explanation":"1. Vertraulichkeit: Nur berechtigte Personen dürfen bestimmte Informationen erhalten. Bei Personalakten ist schon unbefugtes Lesen ein Schaden. Zugriffsrechte, Verschlüsselung und sichere Freigaben können dieses Ziel unterstützen.\n\n2. Integrität: Informationen sollen vollständig und korrekt bleiben; unberechtigte Änderungen müssen verhindert oder erkannt werden. Änderungsprotokolle, geeignete Prüfwerte und kontrollierte Schreibrechte unterstützen dieses Ziel.\n\n3. Verfügbarkeit: Informationen und Dienste sollen dann nutzbar sein, wenn sie benötigt werden. Redundanz, Wartung und getestete Wiederherstellung unterstützen die Verfügbarkeit. Schutzbedarf richtet sich nach möglichen Schäden, nicht nach dem Kaufpreis eines Geräts.","sections":[{"title":"1. Vertraulichkeit","body":"Nur berechtigte Personen dürfen bestimmte Informationen erhalten. Bei Personalakten ist schon unbefugtes Lesen ein Schaden. Zugriffsrechte, Verschlüsselung und sichere Freigaben können dieses Ziel unterstützen."},{"title":"2. Integrität","body":"Informationen sollen vollständig und korrekt bleiben; unberechtigte Änderungen müssen verhindert oder erkannt werden. Änderungsprotokolle, geeignete Prüfwerte und kontrollierte Schreibrechte unterstützen dieses Ziel."},{"title":"3. Verfügbarkeit","body":"Informationen und Dienste sollen dann nutzbar sein, wenn sie benötigt werden. Redundanz, Wartung und getestete Wiederherstellung unterstützen die Verfügbarkeit. Schutzbedarf richtet sich nach möglichen Schäden, nicht nach dem Kaufpreis eines Geräts."}],"example":"Bei einer Lohnabrechnung verletzt ein öffentlich lesbares Gehaltsdokument die Vertraulichkeit. Eine veränderte Kontonummer betrifft die Integrität. Ein ausgefallener Abrechnungsdienst vor dem Zahlungslauf betrifft die Verfügbarkeit. Dasselbe System kann bei allen drei Zielen hohen Schutzbedarf haben.","mistake":"Verschlüsselung allein löst nicht jedes Sicherheitsproblem: Ein verschlüsseltes System kann trotzdem ausfallen oder durch ein berechtigtes Konto falsch verändert werden.","terms":[["Vertraulichkeit","Informationen sind nur Berechtigten zugänglich."],["Integrität","Informationen bleiben korrekt und vollständig."],["Verfügbarkeit","Benötigte Informationen und Dienste sind nutzbar."],["Schutzbedarf","Erforderlicher Schutz entsprechend möglicher Schäden."],["Schaden","Nachteil durch Verletzung eines Schutzziels."],["Schutzmaßnahme","Handlung oder Technik zur Verringerung eines Risikos."]],"q":"Welches Schutzziel ist durch eine unberechtigt geänderte Kontonummer betroffen?","options":["Vertraulichkeit","Integrität","Nur Speicherplatz"],"answer":1,"feedback":"Die Korrektheit der Daten wurde verletzt; damit ist Integrität betroffen.","remember":["Vertraulichkeit schützt vor unberechtigtem Lesen.","Integrität betrifft korrekte und vollständige Informationen.","Verfügbarkeit betrifft die Nutzbarkeit zum benötigten Zeitpunkt."],"summary":"Der mögliche Schaden an Vertraulichkeit, Integrität und Verfügbarkeit bestimmt den benötigten Schutz eines Systems."},"risiko":{"title":"Risikoanalyse verständlich durchführen","goal":"Du unterscheidest Bedrohung, Schwachstelle, Risiko und Restrisiko.","definition":"Eine Risikoanalyse untersucht, welche Ereignisse wichtige Werte schädigen könnten, wie wahrscheinlich sie sind und welche Folgen entstehen. Dadurch lassen sich Schutzmaßnahmen begründen und priorisieren.","explanation":"1. Werte und Bedrohungen erfassen: Bestimme zu schützende Daten und Dienste. Eine Bedrohung ist eine mögliche schädliche Einwirkung, beispielsweise Diebstahl oder ein Stromausfall. Eine Schwachstelle ist eine ausnutzbare oder schadensbegünstigende Eigenschaft.\n\n2. Risiko bewerten: Bewerte Eintrittswahrscheinlichkeit und Schadensausmaß mit einer festgelegten, verständlichen Methode. Eine Risikomatrix kann qualitative Stufen verbinden. Die Ergebnisse sind Annahmen mit Begründung, keine sichere Vorhersage einer exakten Schadenshöhe.\n\n3. Risiko behandeln: Du kannst ein Risiko durch Maßnahmen reduzieren, bestimmte Tätigkeiten vermeiden, Folgen teilweise übertragen oder es bewusst akzeptieren lassen. Nach einer Maßnahme wird das verbleibende Restrisiko erneut bewertet. Zuständigkeit und Entscheidung werden dokumentiert.","sections":[{"title":"1. Werte und Bedrohungen erfassen","body":"Bestimme zu schützende Daten und Dienste. Eine Bedrohung ist eine mögliche schädliche Einwirkung, beispielsweise Diebstahl oder ein Stromausfall. Eine Schwachstelle ist eine ausnutzbare oder schadensbegünstigende Eigenschaft."},{"title":"2. Risiko bewerten","body":"Bewerte Eintrittswahrscheinlichkeit und Schadensausmaß mit einer festgelegten, verständlichen Methode. Eine Risikomatrix kann qualitative Stufen verbinden. Die Ergebnisse sind Annahmen mit Begründung, keine sichere Vorhersage einer exakten Schadenshöhe."},{"title":"3. Risiko behandeln","body":"Du kannst ein Risiko durch Maßnahmen reduzieren, bestimmte Tätigkeiten vermeiden, Folgen teilweise übertragen oder es bewusst akzeptieren lassen. Nach einer Maßnahme wird das verbleibende Restrisiko erneut bewertet. Zuständigkeit und Entscheidung werden dokumentiert."}],"example":"Ein Notebook enthält vertrauliche Kundendaten. Verlust ist die Bedrohung; fehlende Datenträgerverschlüsselung begünstigt unbefugtes Lesen. Verschlüsselung und sichere Schlüsselverwaltung reduzieren dieses Risiko. Der Ausfall des verlorenen Geräts bleibt dennoch bestehen und muss gesondert behandelt werden.","mistake":"Eine Schwachstelle und ein Risiko sind nicht dasselbe: Zur Risikobewertung gehören auch eine mögliche Bedrohung und deren Auswirkungen.","terms":[["Bedrohung","Mögliche schädliche Einwirkung."],["Schwachstelle","Eigenschaft, die eine Schädigung begünstigen kann."],["Eintrittswahrscheinlichkeit","Bewertung, wie wahrscheinlich ein Ereignis ist."],["Schadensausmaß","Bewertete Schwere möglicher Folgen."],["Restrisiko","Risiko, das nach Maßnahmen bestehen bleibt."],["Risikoakzeptanz","Bewusste Entscheidung, ein bewertetes Risiko zu tragen."]],"q":"Was ist das Restrisiko?","options":["Jedes Risiko vor einer Maßnahme","Das nach Maßnahmen verbleibende Risiko","Nur ein Softwarefehler"],"answer":1,"feedback":"Auch wirksame Schutzmaßnahmen beseitigen nicht zwangsläufig alle Risiken.","remember":["Bedrohung, Schwachstelle und Risiko sind unterschiedliche Begriffe.","Bewertung braucht Wahrscheinlichkeit und Schadensausmaß.","Nach Maßnahmen bleibt ein zu bewertendes Restrisiko."],"summary":"Risikoanalyse macht Schutzentscheidungen nachvollziehbar, indem sie mögliche Schäden, Maßnahmen und verbleibende Risiken zusammen betrachtet."},"firewall":{"title":"Firewallregeln und Netzsegmentierung","goal":"Du liest eine Regel anhand von Quelle, Ziel, Dienst und Aktion.","definition":"Eine Firewall kontrolliert Netzwerkverkehr nach festgelegten Regeln. Netzsegmentierung trennt Bereiche mit unterschiedlichen Aufgaben oder Schutzbedürfnissen. Zusammen begrenzen sie unerwünschte Zugriffe und die Ausbreitung eines Vorfalls.","explanation":"1. Kommunikationsbedarf bestimmen: Notiere, welcher Client welchen Dienst auf welchem Server benötigt. Eine Regel braucht Quelle, Ziel, Protokoll, gegebenenfalls Port und Aktion. Ein Port bezeichnet hier einen Dienstendpunkt, keine physische Netzwerkbuchse.\n\n2. Regeln gezielt erlauben: Erlaube nur benötigte Verbindungen und berücksichtige die Reihenfolge der Regeln. Bei zustandsbehafteter Prüfung kann die Firewall Verbindungszustände verfolgen. Rückverkehr muss zum jeweiligen Regelwerk und Verbindungsmodell passen.\n\n3. Trennung und Prüfung: VLANs bilden getrennte Layer-2-Bereiche, sind aber allein keine vollständige Sicherheitskontrolle zwischen gerouteten Netzen. Prüfe sowohl erlaubte als auch verbotene Verbindungen. Dokumentiere den Zweck jeder Freigabe und entferne überflüssige Regeln.","sections":[{"title":"1. Kommunikationsbedarf bestimmen","body":"Notiere, welcher Client welchen Dienst auf welchem Server benötigt. Eine Regel braucht Quelle, Ziel, Protokoll, gegebenenfalls Port und Aktion. Ein Port bezeichnet hier einen Dienstendpunkt, keine physische Netzwerkbuchse."},{"title":"2. Regeln gezielt erlauben","body":"Erlaube nur benötigte Verbindungen und berücksichtige die Reihenfolge der Regeln. Bei zustandsbehafteter Prüfung kann die Firewall Verbindungszustände verfolgen. Rückverkehr muss zum jeweiligen Regelwerk und Verbindungsmodell passen."},{"title":"3. Trennung und Prüfung","body":"VLANs bilden getrennte Layer-2-Bereiche, sind aber allein keine vollständige Sicherheitskontrolle zwischen gerouteten Netzen. Prüfe sowohl erlaubte als auch verbotene Verbindungen. Dokumentiere den Zweck jeder Freigabe und entferne überflüssige Regeln."}],"example":"Gäste dürfen per HTTPS auf einen öffentlichen Webdienst zugreifen, aber nicht auf den internen Dateiserver. Du trennst das Gastnetz und setzt passende Regeln am Übergang. Der Test umfasst einen erfolgreichen Webzugriff und den nachweislich blockierten Zugriff auf die interne Freigabe.","mistake":"Ein VLAN trennt Broadcastdomänen. Ob zwischen VLANs Zugriff möglich ist, entscheiden zusätzlich Routing und passende Zugriffskontrollen.","terms":[["Firewall","Kontrollinstanz für Netzwerkverkehr."],["Quelle","Ursprung einer Verbindung oder eines Pakets."],["Ziel","Adressierter Empfänger."],["Port","Nummer eines Transportprotokoll-Endpunkts."],["Stateful Inspection","Prüfung unter Berücksichtigung des Verbindungszustands."],["Segmentierung","Aufteilung eines Netzes in sinnvoll getrennte Bereiche."]],"q":"Was gehört in eine nachvollziehbare Firewallregel?","options":["Nur der Name des Administrators","Quelle, Ziel, Dienst und Aktion","Nur das Kaufdatum des Routers"],"answer":1,"feedback":"Diese Angaben beschreiben, welcher Verkehr erlaubt oder blockiert werden soll.","remember":["Regeln beschreiben Quelle, Ziel, Dienst und Aktion.","Regelreihenfolge und Verbindungszustand beeinflussen das Ergebnis.","Erlaubte und verbotene Verbindungen getrennt testen."],"summary":"Wirksame Netztrennung kombiniert einen begründeten Kommunikationsplan mit passenden Zugriffskontrollen und Gegenproben."},"kryptografie":{"title":"Verschlüsselung, Hash und Signatur","goal":"Du wählst das passende Verfahren für Geheimhaltung, Prüfen und Herkunftsnachweis.","definition":"Kryptografische Verfahren erfüllen unterschiedliche Aufgaben. Verschlüsselung schützt die Lesbarkeit, Hashverfahren bilden einen Prüfwert und digitale Signaturen verbinden eine Nachricht mit einem überprüfbaren Signaturschlüssel.","explanation":"1. Verschlüsselung: Symmetrische Verfahren verwenden einen gemeinsamen geheimen Schlüssel. Asymmetrische Verfahren arbeiten mit einem Schlüsselpaar. In realen Protokollen werden diese oft kombiniert: asymmetrische Mechanismen unterstützen den sicheren Aufbau, symmetrische Verschlüsselung schützt größere Datenmengen.\n\n2. Hashwert: Ein kryptografischer Hash bildet Eingaben auf einen Prüfwert fester Länge ab. Er ist keine umkehrbare Verschlüsselung. Ein erwarteter Hash kann Veränderungen erkennbar machen, wenn der Vergleichswert selbst aus einer vertrauenswürdigen Quelle stammt.\n\n3. Signatur und Vertrauen: Eine digitale Signatur wird mit einem privaten Schlüssel erstellt und mit dem passenden öffentlichen Schlüssel geprüft. Sie schützt nicht automatisch die Vertraulichkeit. Die Zuordnung des Schlüssels zum Absender muss vertrauenswürdig geprüft werden, etwa über eine passende Zertifikatskette.","sections":[{"title":"1. Verschlüsselung","body":"Symmetrische Verfahren verwenden einen gemeinsamen geheimen Schlüssel. Asymmetrische Verfahren arbeiten mit einem Schlüsselpaar. In realen Protokollen werden diese oft kombiniert: asymmetrische Mechanismen unterstützen den sicheren Aufbau, symmetrische Verschlüsselung schützt größere Datenmengen."},{"title":"2. Hashwert","body":"Ein kryptografischer Hash bildet Eingaben auf einen Prüfwert fester Länge ab. Er ist keine umkehrbare Verschlüsselung. Ein erwarteter Hash kann Veränderungen erkennbar machen, wenn der Vergleichswert selbst aus einer vertrauenswürdigen Quelle stammt."},{"title":"3. Signatur und Vertrauen","body":"Eine digitale Signatur wird mit einem privaten Schlüssel erstellt und mit dem passenden öffentlichen Schlüssel geprüft. Sie schützt nicht automatisch die Vertraulichkeit. Die Zuordnung des Schlüssels zum Absender muss vertrauenswürdig geprüft werden, etwa über eine passende Zertifikatskette."}],"example":"Du lädst ein Installationspaket. Ein geprüfter Hersteller-Signaturweg unterstützt den Herkunftsnachweis und die Integritätsprüfung. Ein bloßer Hash auf derselben manipulierten Downloadseite reicht nicht als verlässlicher Herkunftsnachweis. Vertrauliche Übertragung wird zusätzlich durch einen geeigneten verschlüsselten Kanal geschützt.","mistake":"Hashen bedeutet nicht verschlüsseln. Eine Signatur versteckt den Inhalt nicht.","terms":[["Symmetrisch","Verfahren mit gemeinsamem geheimem Schlüssel."],["Asymmetrisch","Verfahren mit öffentlichem und privatem Schlüssel."],["Hashwert","Prüfwert aus einer Hashfunktion."],["Digitale Signatur","Kryptografisch prüfbare Signatur einer Nachricht."],["Privater Schlüssel","Geheim zu haltender Teil eines Schlüsselpaares."],["Zertifikat","Signierte Bindung von Identitätsangaben an einen öffentlichen Schlüssel."]],"q":"Welches Verfahren macht einen Inhalt nicht automatisch geheim?","options":["Digitale Signatur","Geeignete Verschlüsselung","Verschlüsselter Transport"],"answer":0,"feedback":"Eine Signatur dient insbesondere der prüfbaren Signaturherkunft und Integrität; der Inhalt kann dabei lesbar bleiben.","remember":["Verschlüsselung, Hash und Signatur erfüllen verschiedene Zwecke.","Ein Hash ist nur mit vertrauenswürdigem Vergleichswert aussagekräftig.","Eine Signatur allein macht den Inhalt nicht geheim."],"summary":"Kryptografischer Schutz funktioniert, wenn Verfahren und Schlüsselvertrauen zum gewünschten Schutzziel passen."},"patch":{"title":"Updates und Änderungen kontrolliert einführen","goal":"Du planst ein Update einschließlich Test, Rückfalloption und Funktionskontrolle.","definition":"Patchmanagement organisiert Sicherheits- und Fehlerkorrekturen für Systeme. Ein Patch verändert Software; deshalb muss er sowohl das Sicherheitsrisiko als auch mögliche Auswirkungen auf den Betrieb berücksichtigen.","explanation":"1. Erfassen und priorisieren: Eine aktuelle Inventarliste zeigt betroffene Systeme und Versionen. Bewerte Herstellerhinweise, Ausnutzbarkeit, Erreichbarkeit und geschäftliche Bedeutung. Eine kritisch verwundbare, öffentlich erreichbare Anwendung kann dringender sein als ein weniger relevantes internes System.\n\n2. Test und Freigabe: Prüfe Voraussetzungen und Abhängigkeiten. Plane Datensicherung, Wartungszeit und einen realistischen Rückfallweg. Teste in einer passenden Umgebung oder mit einer kontrollierten Pilotgruppe. Die zuständige Stelle muss Änderungen passend zum Betriebsprozess freigeben.\n\n3. Ausrollen und überprüfen: Verteile das Update nachvollziehbar. Prüfe danach Version, Dienststart und wichtige Geschäftsabläufe. Dokumentiere Erfolg, Fehler und Ausnahmen. Ein fehlgeschlagenes Update darf nicht still als erledigt in der Übersicht stehen.","sections":[{"title":"1. Erfassen und priorisieren","body":"Eine aktuelle Inventarliste zeigt betroffene Systeme und Versionen. Bewerte Herstellerhinweise, Ausnutzbarkeit, Erreichbarkeit und geschäftliche Bedeutung. Eine kritisch verwundbare, öffentlich erreichbare Anwendung kann dringender sein als ein weniger relevantes internes System."},{"title":"2. Test und Freigabe","body":"Prüfe Voraussetzungen und Abhängigkeiten. Plane Datensicherung, Wartungszeit und einen realistischen Rückfallweg. Teste in einer passenden Umgebung oder mit einer kontrollierten Pilotgruppe. Die zuständige Stelle muss Änderungen passend zum Betriebsprozess freigeben."},{"title":"3. Ausrollen und überprüfen","body":"Verteile das Update nachvollziehbar. Prüfe danach Version, Dienststart und wichtige Geschäftsabläufe. Dokumentiere Erfolg, Fehler und Ausnahmen. Ein fehlgeschlagenes Update darf nicht still als erledigt in der Übersicht stehen."}],"example":"Ein Update betrifft die Druckverwaltung. Du testest zunächst mit zwei unterschiedlichen Druckermodellen und einer Pilotgruppe. Nach Freigabe erfolgt der Rollout im Wartungsfenster. Anschließend prüfst du Ausdruck, Anmeldung und Ereignisprotokoll. Falls eine kritische Funktion ausfällt, wird der vorher geplante Rückfallweg genutzt.","mistake":"Eine Rückfalloption muss praktisch funktionieren; „irgendwie zurücksetzen“ ist kein belastbarer Plan.","terms":[["Patch","Korrektur oder Aktualisierung vorhandener Software."],["Inventar","Übersicht verwalteter Geräte, Software und Versionen."],["Pilotgruppe","Kleine ausgewählte Gruppe für kontrollierte Einführung."],["Rollback","Geplanter Rückweg zu einem vorherigen Zustand."],["Abhängigkeit","Voraussetzung durch eine andere Komponente."],["Change","Kontrolliert bearbeitete Änderung an einem Dienst oder System."]],"q":"Was gehört nach einem Update dazu?","options":["Nur den Installer schließen","Wichtige Dienste und Funktionen prüfen","Die Dokumentation löschen"],"answer":1,"feedback":"Erst eine Funktionsprüfung zeigt, ob der gewünschte Dienst nach der Änderung tatsächlich nutzbar ist.","remember":["Updates nach Betroffenheit und Risiko priorisieren.","Vor dem Rollout Test, Wartungszeit und Rückfallweg planen.","Nach der Installation Version und Geschäftsabläufe prüfen."],"summary":"Patchmanagement verbindet die zeitnahe Fehlerkorrektur mit einem kontrollierten und überprüften Betriebswechsel."},"notfall":{"title":"Notfälle und Sicherheitsvorfälle behandeln","goal":"Du ordnest Erkennen, Eindämmen, Wiederherstellen und Nachbereiten in einen sinnvollen Ablauf.","definition":"Ein Sicherheitsvorfall ist ein Ereignis, das die Sicherheit von Informationen oder Diensten beeinträchtigt oder bedroht. Notfallmanagement bereitet den Umgang mit schweren Störungen vor, damit im Ernstfall Zuständigkeiten und wichtige Schritte bekannt sind.","explanation":"1. Erkennen und melden: Beobachtungen werden über den vorgesehenen Meldeweg weitergegeben. Beschreibe Zeitpunkt, betroffene Systeme und sichtbare Auswirkungen. Handle nach dem Notfallplan; voreilige Änderungen können wichtige Spuren oder die Betriebsfähigkeit beeinträchtigen.\n\n2. Eindämmen und analysieren: Begrenze die Ausbreitung mit abgestimmten Maßnahmen. Zuständige Personen bewerten Umfang und Ursache. Technische Beweise und Protokolle werden nach dem festgelegten Verfahren gesichert. Nicht jede Person darf eigenmächtig Systeme löschen oder abschalten.\n\n3. Wiederherstellen und lernen: Stelle einen vertrauenswürdigen Betriebszustand her und prüfe die Funktion. Überwache besonders sorgfältig. In der Nachbereitung werden Ursachen, wirksame Schritte und Verbesserungen dokumentiert. Übungen zeigen vorher, ob der Plan verständlich und ausführbar ist.","sections":[{"title":"1. Erkennen und melden","body":"Beobachtungen werden über den vorgesehenen Meldeweg weitergegeben. Beschreibe Zeitpunkt, betroffene Systeme und sichtbare Auswirkungen. Handle nach dem Notfallplan; voreilige Änderungen können wichtige Spuren oder die Betriebsfähigkeit beeinträchtigen."},{"title":"2. Eindämmen und analysieren","body":"Begrenze die Ausbreitung mit abgestimmten Maßnahmen. Zuständige Personen bewerten Umfang und Ursache. Technische Beweise und Protokolle werden nach dem festgelegten Verfahren gesichert. Nicht jede Person darf eigenmächtig Systeme löschen oder abschalten."},{"title":"3. Wiederherstellen und lernen","body":"Stelle einen vertrauenswürdigen Betriebszustand her und prüfe die Funktion. Überwache besonders sorgfältig. In der Nachbereitung werden Ursachen, wirksame Schritte und Verbesserungen dokumentiert. Übungen zeigen vorher, ob der Plan verständlich und ausführbar ist."}],"example":"Ein Client verschlüsselt plötzlich Dateien. Du meldest das Ereignis sofort, dokumentierst die Beobachtung und lässt den Zugang nach festgelegtem Plan isolieren. Das zuständige Team prüft weitere Systeme und die Wiederherstellung aus geprüften Sicherungen. Ein einfaches Neustarten würde die Ursache noch nicht beseitigen.","mistake":"Wiederherstellung ohne Ursachenbehebung kann dazu führen, dass derselbe Angriff erneut wirksam wird.","terms":[["Vorfall","Sicherheitsrelevantes Ereignis mit möglicher Beeinträchtigung."],["Meldeweg","Vorgesehener Kommunikationsweg für Ereignisse."],["Eindämmung","Begrenzung weiterer Auswirkungen."],["Notfallplan","Vorbereiteter Ablauf für schwere Störungen."],["Wiederanlauf","Kontrollierte Rückkehr zum nutzbaren Betrieb."],["Nachbereitung","Auswertung eines Ereignisses zur Verbesserung."]],"q":"Warum wird nach einem Vorfall eine Nachbereitung durchgeführt?","options":["Damit keine Verantwortung mehr besteht","Um Ursachen und Verbesserungen festzuhalten","Nur um die Uhrzeit zu ändern"],"answer":1,"feedback":"Eine dokumentierte Auswertung verbessert Maßnahmen, Abläufe und Vorbereitung.","remember":["Beobachtungen schnell über den vorgesehenen Weg melden.","Eindämmung und Spurensicherung müssen abgestimmt erfolgen.","Wiederherstellung braucht Funktionsprüfung und Nachbereitung."],"summary":"Ein geübter Notfallablauf begrenzt Schäden und ermöglicht die kontrollierte Rückkehr zu einem vertrauenswürdigen Betrieb."}},"fa":{"schutzziele":{"title":"هدف‌های امنیت و نیاز حفاظتی","goal":"آسیب را به سه هدف پایهٔ امنیت مرتبط کنی.","definition":"امنیت اطلاعات از داده و سیستم پردازش آن محافظت می‌کند. سه هدف پایه شامل محرمانگی، یکپارچگی و دسترس‌پذیری است. پیش از انتخاب ابزار باید بدانیم کدام هدف و با چه اهمیتی لازم است.","explanation":"۱. محرمانگی: فقط افراد مجاز باید اطلاعات را ببینند. در پروندهٔ پرسنلی، خواندن غیرمجاز خودش آسیب است. مجوز دسترسی، رمزنگاری و اشتراک‌گذاری امن می‌تواند از این هدف محافظت کند.\n\n۲. یکپارچگی: اطلاعات باید درست و کامل بماند و تغییر غیرمجاز پیشگیری یا تشخیص داده شود. ثبت تغییرات، مقادیر بررسی مناسب و کنترل نوشتن به این هدف کمک می‌کند.\n\n۳. دسترس‌پذیری: داده و سرویس باید هنگام نیاز قابل استفاده باشد. افزونگی، نگهداری و بازیابی آزمایش‌شده کمک می‌کنند. نیاز حفاظتی بر پایهٔ آسیب احتمالی است؛ نه قیمت خرید دستگاه.","sections":[{"title":"۱. محرمانگی","body":"فقط افراد مجاز باید اطلاعات را ببینند. در پروندهٔ پرسنلی، خواندن غیرمجاز خودش آسیب است. مجوز دسترسی، رمزنگاری و اشتراک‌گذاری امن می‌تواند از این هدف محافظت کند."},{"title":"۲. یکپارچگی","body":"اطلاعات باید درست و کامل بماند و تغییر غیرمجاز پیشگیری یا تشخیص داده شود. ثبت تغییرات، مقادیر بررسی مناسب و کنترل نوشتن به این هدف کمک می‌کند."},{"title":"۳. دسترس‌پذیری","body":"داده و سرویس باید هنگام نیاز قابل استفاده باشد. افزونگی، نگهداری و بازیابی آزمایش‌شده کمک می‌کنند. نیاز حفاظتی بر پایهٔ آسیب احتمالی است؛ نه قیمت خرید دستگاه."}],"example":"در حقوق و دستمزد، انتشار عمومی فیش حقوق محرمانگی را نقض می‌کند. تغییر غیرمجاز شمارهٔ حساب به یکپارچگی مربوط است و قطع سرویس پیش از پرداخت، دسترس‌پذیری را تهدید می‌کند. یک سیستم ممکن است در هر سه هدف نیاز حفاظتی بالا داشته باشد.","mistake":"رمزنگاری همهٔ مشکلات را حل نمی‌کند؛ سیستم رمز‌شده هم ممکن است قطع شود یا کاربر مجاز داده را اشتباه تغییر دهد.","terms":[["Vertraulichkeit","فقط شخص مجاز اطلاعات را می‌بیند."],["Integrität","درستی و کامل‌بودن اطلاعات."],["Verfügbarkeit","قابل استفاده بودن داده و سرویس هنگام نیاز."],["Schutzbedarf","مقدار حفاظت لازم بر پایهٔ آسیب احتمالی."],["Schaden","پیامد منفی نقض هدف حفاظتی."],["Schutzmaßnahme","اقدام یا فناوری کاهش خطر."]],"q":"تغییر غیرمجاز شمارهٔ حساب کدام هدف را نقض می‌کند؟","options":["محرمانگی","یکپارچگی","فقط فضای ذخیره"],"answer":1,"feedback":"درستی داده تغییر کرده است؛ پس یکپارچگی آسیب دیده است.","remember":["محرمانگی جلوی خواندن غیرمجاز را می‌گیرد.","یکپارچگی به درستی و کامل‌بودن داده مربوط است.","دسترس‌پذیری یعنی قابل استفاده بودن هنگام نیاز."],"summary":"آسیب احتمالی به محرمانگی، یکپارچگی و دسترس‌پذیری مقدار حفاظت لازم سیستم را تعیین می‌کند."},"risiko":{"title":"تحلیل ریسک به زبان ساده","goal":"تهدید، ضعف، ریسک و ریسک باقی‌مانده را جدا کنی.","definition":"تحلیل ریسک بررسی می‌کند چه اتفاقی ممکن است به دارایی مهم آسیب بزند، احتمال آن چقدر است و چه پیامدی دارد. به این ترتیب می‌توان اولویت حفاظت را با دلیل تعیین کرد.","explanation":"۱. دارایی و تهدید: داده و سرویس نیازمند حفاظت را مشخص کن. تهدید، اثر آسیب‌زای ممکن است؛ مثل سرقت یا قطع برق. ضعف، ویژگی‌ای است که امکان آسیب را بیشتر می‌کند.\n\n۲. ارزیابی: احتمال رخداد و شدت پیامد را با روش روشن بسنج. ماتریس ریسک می‌تواند سطح‌های کیفی را به هم مرتبط کند. این ارزیابی فرض مستدل است، نه پیشگویی قطعی عدد دقیق خسارت.\n\n۳. برخورد با ریسک: می‌توان با اقدام مناسب ریسک را کاهش داد، از فعالیت پرخطر صرف‌نظر کرد، بخشی از پیامد را منتقل کرد یا آگاهانه پذیرفت. پس از اقدام، ریسک باقی‌مانده دوباره ارزیابی و مسئول و تصمیم ثبت می‌شود.","sections":[{"title":"۱. دارایی و تهدید","body":"داده و سرویس نیازمند حفاظت را مشخص کن. تهدید، اثر آسیب‌زای ممکن است؛ مثل سرقت یا قطع برق. ضعف، ویژگی‌ای است که امکان آسیب را بیشتر می‌کند."},{"title":"۲. ارزیابی","body":"احتمال رخداد و شدت پیامد را با روش روشن بسنج. ماتریس ریسک می‌تواند سطح‌های کیفی را به هم مرتبط کند. این ارزیابی فرض مستدل است، نه پیشگویی قطعی عدد دقیق خسارت."},{"title":"۳. برخورد با ریسک","body":"می‌توان با اقدام مناسب ریسک را کاهش داد، از فعالیت پرخطر صرف‌نظر کرد، بخشی از پیامد را منتقل کرد یا آگاهانه پذیرفت. پس از اقدام، ریسک باقی‌مانده دوباره ارزیابی و مسئول و تصمیم ثبت می‌شود."}],"example":"لپ‌تاپ دادهٔ محرمانه دارد. گم‌شدن تهدید است و نبود رمزنگاری دیسک خواندن غیرمجاز را آسان می‌کند. رمزنگاری و نگهداری امن کلید خطر را کم می‌کند؛ اما ازدست‌رفتن خود دستگاه و قطعی کار هنوز مسئله‌ای جداست.","mistake":"ضعف و ریسک یکی نیستند؛ ریسک علاوه بر ضعف به تهدید و اثر احتمالی هم مربوط است.","terms":[["Bedrohung","عامل آسیب‌زای ممکن."],["Schwachstelle","ویژگی آسان‌کنندهٔ آسیب."],["Eintrittswahrscheinlichkeit","ارزیابی احتمال رخداد."],["Schadensausmaß","شدت پیامد احتمالی."],["Restrisiko","ریسکی که پس از اقدام باقی می‌ماند."],["Risikoakzeptanz","پذیرش آگاهانهٔ ریسک ارزیابی‌شده."]],"q":"Restrisiko یعنی چه؟","options":["تمام خطرها پیش از حفاظت","خطر باقی‌مانده پس از اقدام حفاظتی","فقط خطای نرم‌افزار"],"answer":1,"feedback":"اقدام مؤثر هم لزوماً همهٔ خطرها را حذف نمی‌کند.","remember":["تهدید، ضعف و ریسک سه مفهوم متفاوت‌اند.","ارزیابی به احتمال رخداد و شدت آسیب نیاز دارد.","پس از اقدام، ریسک باقی‌مانده دوباره سنجیده می‌شود."],"summary":"تحلیل ریسک با دیدن هم‌زمان آسیب، اقدام و خطر باقی‌مانده، تصمیم حفاظتی را قابل توضیح می‌کند."},"firewall":{"title":"قواعد فایروال و جداسازی شبکه","goal":"قاعدهٔ فایروال را با مبدأ، مقصد، سرویس و عمل بخوانی.","definition":"فایروال ترافیک شبکه را بر اساس قواعد کنترل می‌کند. جداسازی شبکه، قسمت‌هایی با کار و نیاز حفاظتی متفاوت می‌سازد. این دو کار دسترسی ناخواسته و انتشار حادثه را محدود می‌کنند.","explanation":"۱. نیاز ارتباطی: بنویس کدام دستگاه به کدام سرویس روی کدام سرور نیاز دارد. قاعده شامل مبدأ، مقصد، پروتکل، در صورت نیاز پورت، و عمل است. پورت اینجا شمارهٔ نقطهٔ ارتباط سرویس است؛ نه سوکت فیزیکی.\n\n۲. اجازهٔ هدفمند: فقط ارتباط لازم را مجاز کن و ترتیب قواعد را در نظر بگیر. فایروال Stateful می‌تواند وضعیت اتصال را پیگیری کند. ترافیک پاسخ باید با مدل اتصال و قواعد آن سازگار باشد.\n\n۳. جداسازی و آزمایش: VLAN شبکهٔ لایهٔ دو را جدا می‌کند اما به‌تنهایی کنترل کامل ارتباط بین شبکه‌های Routeشده نیست. ارتباط مجاز و ممنوع را هر دو آزمایش کن. علت هر اجازه را ثبت و قواعد اضافی را حذف کن.","sections":[{"title":"۱. نیاز ارتباطی","body":"بنویس کدام دستگاه به کدام سرویس روی کدام سرور نیاز دارد. قاعده شامل مبدأ، مقصد، پروتکل، در صورت نیاز پورت، و عمل است. پورت اینجا شمارهٔ نقطهٔ ارتباط سرویس است؛ نه سوکت فیزیکی."},{"title":"۲. اجازهٔ هدفمند","body":"فقط ارتباط لازم را مجاز کن و ترتیب قواعد را در نظر بگیر. فایروال Stateful می‌تواند وضعیت اتصال را پیگیری کند. ترافیک پاسخ باید با مدل اتصال و قواعد آن سازگار باشد."},{"title":"۳. جداسازی و آزمایش","body":"VLAN شبکهٔ لایهٔ دو را جدا می‌کند اما به‌تنهایی کنترل کامل ارتباط بین شبکه‌های Routeشده نیست. ارتباط مجاز و ممنوع را هر دو آزمایش کن. علت هر اجازه را ثبت و قواعد اضافی را حذف کن."}],"example":"مهمان باید با HTTPS به وب‌سرویس عمومی برسد اما نباید فایل‌سرور داخلی را ببیند. شبکهٔ مهمان را جدا و گذرگاه را با قواعد مناسب کنترل می‌کنی. آزمایش شامل وب موفق و دسترسی مسدودشده به فایل داخلی است.","mistake":"VLAN دامنهٔ Broadcast را جدا می‌کند؛ ارتباط بین VLANها همچنین به Routing و کنترل دسترسی مربوط است.","terms":[["Firewall","کنترل‌کنندهٔ ترافیک شبکه."],["Quelle","مبدأ بسته یا اتصال."],["Ziel","گیرندهٔ مورد نظر."],["Port","شمارهٔ نقطهٔ ارتباط در پروتکل انتقال."],["Stateful Inspection","بررسی با توجه به وضعیت اتصال."],["Segmentierung","تقسیم شبکه به قسمت‌های جدا و هدفمند."]],"q":"چه چیزی باید در قاعدهٔ روشن فایروال باشد؟","options":["فقط نام مدیر","مبدأ، مقصد، سرویس و عمل","فقط تاریخ خرید روتر"],"answer":1,"feedback":"این موارد مشخص می‌کنند چه ترافیکی باید مجاز یا مسدود شود.","remember":["قاعده شامل مبدأ، مقصد، سرویس و عمل است.","ترتیب قواعد و وضعیت اتصال روی نتیجه اثر دارد.","ارتباط مجاز و ممنوع را جداگانه آزمایش کن."],"summary":"جداسازی مؤثر شبکه، طرح ارتباطی مستدل را با کنترل دسترسی و آزمایش حالت ممنوع ترکیب می‌کند."},"kryptografie":{"title":"رمزنگاری، Hash و امضای دیجیتال","goal":"برای پنهان‌سازی، بررسی تغییر و بررسی امضا روش مناسب را انتخاب کنی.","definition":"روش‌های رمزنگاری یک کار واحد ندارند. Encryption خواندن داده را محدود می‌کند؛ Hash مقدار بررسی می‌سازد و امضای دیجیتال ارتباط داده با کلید امضا را قابل بررسی می‌کند.","explanation":"۱. رمزگذاری: روش متقارن کلید محرمانهٔ مشترک دارد. روش نامتقارن از جفت کلید استفاده می‌کند. پروتکل‌های واقعی اغلب هر دو را ترکیب می‌کنند؛ سازوکار نامتقارن به برقراری امن کمک می‌کند و رمز متقارن حجم داده را محافظت می‌کند.\n\n۲. Hash: تابع Hash رمزنگاری، ورودی را به مقدار با طول ثابت تبدیل می‌کند و رمزگذاری قابل بازگشت نیست. مقایسه با Hash مورد انتظار می‌تواند تغییر را نشان دهد؛ به شرطی که خود مقدار مرجع قابل اعتماد باشد.\n\n۳. امضا و اعتماد: امضا با کلید خصوصی ساخته و با کلید عمومی متناظر بررسی می‌شود. امضا لزوماً محتوا را پنهان نمی‌کند. ارتباط کلید با صاحب آن هم باید از راه معتبر مثل زنجیرهٔ گواهی مناسب بررسی شود.","sections":[{"title":"۱. رمزگذاری","body":"روش متقارن کلید محرمانهٔ مشترک دارد. روش نامتقارن از جفت کلید استفاده می‌کند. پروتکل‌های واقعی اغلب هر دو را ترکیب می‌کنند؛ سازوکار نامتقارن به برقراری امن کمک می‌کند و رمز متقارن حجم داده را محافظت می‌کند."},{"title":"۲. Hash","body":"تابع Hash رمزنگاری، ورودی را به مقدار با طول ثابت تبدیل می‌کند و رمزگذاری قابل بازگشت نیست. مقایسه با Hash مورد انتظار می‌تواند تغییر را نشان دهد؛ به شرطی که خود مقدار مرجع قابل اعتماد باشد."},{"title":"۳. امضا و اعتماد","body":"امضا با کلید خصوصی ساخته و با کلید عمومی متناظر بررسی می‌شود. امضا لزوماً محتوا را پنهان نمی‌کند. ارتباط کلید با صاحب آن هم باید از راه معتبر مثل زنجیرهٔ گواهی مناسب بررسی شود."}],"example":"برای بستهٔ نصب، امضای سازنده را از مسیر معتبر بررسی می‌کنی. Hash روی همان صفحهٔ دست‌کاری‌شده به‌تنهایی منبع واقعی را اثبات نمی‌کند. برای محرمانگی انتقال نیز کانال رمز‌شدهٔ مناسب لازم است.","mistake":"Hash رمزگذاری نیست و امضا هم خودبه‌خود محتوا را مخفی نمی‌کند.","terms":[["Symmetrisch","روش دارای کلید محرمانهٔ مشترک."],["Asymmetrisch","روش دارای کلید عمومی و خصوصی."],["Hashwert","مقدار بررسی خروجی تابع Hash."],["Digitale Signatur","امضای رمزنگاری‌شدهٔ قابل بررسی."],["Privater Schlüssel","قسمت محرمانهٔ جفت کلید."],["Zertifikat","پیوند امضاشدهٔ مشخصات هویت با کلید عمومی."]],"q":"کدام روش به‌تنهایی محتوا را محرمانه نمی‌کند؟","options":["امضای دیجیتال","رمزگذاری مناسب","انتقال رمز‌شده"],"answer":0,"feedback":"امضا برای بررسی امضا و یکپارچگی است؛ متن ممکن است همچنان خوانا بماند.","remember":["رمزگذاری، Hash و امضا هدف‌های متفاوت دارند.","Hash با مقدار مرجع قابل اعتماد معنا پیدا می‌کند.","امضا به‌تنهایی متن را محرمانه نمی‌کند."],"summary":"حفاظت رمزنگاری وقتی درست کار می‌کند که روش و اعتماد به کلید با هدف امنیتی سازگار باشد."},"patch":{"title":"به‌روزرسانی و تغییر کنترل‌شده","goal":"Update را همراه آزمایش، راه برگشت و بررسی عملکرد برنامه‌ریزی کنی.","definition":"Patchmanagement اصلاحات امنیتی و خطاهای نرم‌افزار را مدیریت می‌کند. چون Patch سیستم را تغییر می‌دهد، هم خطر امنیتی و هم اثر احتمالی روی کار شرکت باید دیده شود.","explanation":"۱. شناسایی و اولویت: فهرست دستگاه و نسخه نشان می‌دهد چه سیستم‌هایی درگیرند. اطلاعیهٔ سازنده، امکان سوءاستفاده، دسترسی از بیرون و اهمیت کاری را بسنج. برنامهٔ آسیب‌پذیر عمومی ممکن است فوری‌تر از سیستم داخلی کم‌اهمیت باشد.\n\n۲. آزمایش و اجازهٔ اجرا: پیش‌نیاز و وابستگی‌ها را بررسی کن. پشتیبان، زمان نگهداری و راه برگشت واقعی داشته باش. ابتدا در محیط مناسب یا گروه کوچک آزمایش کن. مسئول مربوط طبق فرایند شرکت تغییر را تأیید می‌کند.\n\n۳. انتشار و بررسی: Update را قابل پیگیری اجرا کن. سپس نسخه، شروع سرویس و کارهای مهم را آزمایش کن. موفقیت، خطا و موارد استثنا را ثبت کن؛ اجرای ناموفق نباید انجام‌شده حساب شود.","sections":[{"title":"۱. شناسایی و اولویت","body":"فهرست دستگاه و نسخه نشان می‌دهد چه سیستم‌هایی درگیرند. اطلاعیهٔ سازنده، امکان سوءاستفاده، دسترسی از بیرون و اهمیت کاری را بسنج. برنامهٔ آسیب‌پذیر عمومی ممکن است فوری‌تر از سیستم داخلی کم‌اهمیت باشد."},{"title":"۲. آزمایش و اجازهٔ اجرا","body":"پیش‌نیاز و وابستگی‌ها را بررسی کن. پشتیبان، زمان نگهداری و راه برگشت واقعی داشته باش. ابتدا در محیط مناسب یا گروه کوچک آزمایش کن. مسئول مربوط طبق فرایند شرکت تغییر را تأیید می‌کند."},{"title":"۳. انتشار و بررسی","body":"Update را قابل پیگیری اجرا کن. سپس نسخه، شروع سرویس و کارهای مهم را آزمایش کن. موفقیت، خطا و موارد استثنا را ثبت کن؛ اجرای ناموفق نباید انجام‌شده حساب شود."}],"example":"Update روی مدیریت چاپ اثر دارد. ابتدا دو مدل پرینتر و گروه آزمایشی را بررسی می‌کنی. پس از تأیید، در زمان نگهداری اجرا می‌شود. چاپ، ورود و لاگ بررسی می‌شود و برای خرابی مهم راه برگشت از قبل آماده است.","mistake":"راه برگشت باید عملی باشد؛ «یک‌جوری برمی‌گردانیم» برنامهٔ معتبر نیست.","terms":[["Patch","اصلاح یا به‌روزرسانی نرم‌افزار."],["Inventar","فهرست دستگاه، نرم‌افزار و نسخه."],["Pilotgruppe","گروه کوچک برای شروع کنترل‌شده."],["Rollback","راه برنامه‌ریزی‌شده به وضعیت قبلی."],["Abhängigkeit","نیاز یک جزء به جزء دیگر."],["Change","تغییر کنترل‌شدهٔ سرویس یا سیستم."]],"q":"پس از Update چه کاری لازم است؟","options":["فقط بستن Installer","بررسی سرویس‌ها و عملکردهای مهم","حذف مستندات"],"answer":1,"feedback":"فقط آزمایش عملکرد نشان می‌دهد سرویس پس از تغییر قابل استفاده است.","remember":["Update را بر پایهٔ درگیری سیستم و خطر اولویت‌بندی کن.","پیش از انتشار، تست، زمان تعمیر و راه برگشت را آماده کن.","پس از نصب، نسخه و کارهای مهم را بررسی کن."],"summary":"مدیریت Patch اصلاح به‌موقع خطا را با تغییر کنترل‌شده و بررسی‌شدهٔ سیستم همراه می‌کند."},"notfall":{"title":"رسیدگی به حادثه و وضعیت اضطراری","goal":"تشخیص، مهار، بازیابی و بررسی پس از حادثه را مرتب کنی.","definition":"حادثهٔ امنیتی رویدادی است که امنیت داده یا سرویس را تهدید یا مختل می‌کند. مدیریت اضطراری از قبل مسئول‌ها و مراحل اختلال شدید را مشخص می‌کند تا هنگام بحران تصمیم‌ها روشن باشد.","explanation":"۱. تشخیص و گزارش: مشاهده را از راه تعیین‌شده گزارش کن. زمان، سیستم‌های درگیر و اثر قابل مشاهده را بنویس. طبق برنامه عمل کن؛ تغییر عجولانه ممکن است آثار مهم یا عملکرد سیستم را از بین ببرد.\n\n۲. مهار و تحلیل: با اقدام هماهنگ جلوی گسترش را بگیر. افراد مسئول دامنه و علت را بررسی می‌کنند. لاگ و شواهد طبق روش تعیین‌شده حفظ می‌شود. هر شخص اجازه ندارد خودسرانه سیستم را حذف یا خاموش کند.\n\n۳. بازیابی و یادگیری: وضعیت قابل اعتماد را بازگردان و کارکرد را آزمایش کن. نظارت بیشتری انجام بده. سپس علت، اقدامات مؤثر و بهبودهای لازم ثبت می‌شود. تمرین قبلی نشان می‌دهد برنامه قابل فهم و اجرا هست یا نه.","sections":[{"title":"۱. تشخیص و گزارش","body":"مشاهده را از راه تعیین‌شده گزارش کن. زمان، سیستم‌های درگیر و اثر قابل مشاهده را بنویس. طبق برنامه عمل کن؛ تغییر عجولانه ممکن است آثار مهم یا عملکرد سیستم را از بین ببرد."},{"title":"۲. مهار و تحلیل","body":"با اقدام هماهنگ جلوی گسترش را بگیر. افراد مسئول دامنه و علت را بررسی می‌کنند. لاگ و شواهد طبق روش تعیین‌شده حفظ می‌شود. هر شخص اجازه ندارد خودسرانه سیستم را حذف یا خاموش کند."},{"title":"۳. بازیابی و یادگیری","body":"وضعیت قابل اعتماد را بازگردان و کارکرد را آزمایش کن. نظارت بیشتری انجام بده. سپس علت، اقدامات مؤثر و بهبودهای لازم ثبت می‌شود. تمرین قبلی نشان می‌دهد برنامه قابل فهم و اجرا هست یا نه."}],"example":"یک کلاینت ناگهان فایل‌ها را رمز می‌کند. فوراً گزارش می‌دهی، مشاهده را ثبت می‌کنی و دسترسی طبق برنامه جدا می‌شود. تیم مسئول سیستم‌های دیگر و بازیابی از نسخهٔ سالم را بررسی می‌کند. راه‌اندازی دوبارهٔ ساده علت را برطرف نمی‌کند.","mistake":"بازیابی بدون رفع علت می‌تواند باعث تکرار همان حمله شود.","terms":[["Vorfall","رویداد دارای اثر یا خطر امنیتی."],["Meldeweg","راه مشخص گزارش حادثه."],["Eindämmung","محدودکردن پیامد و گسترش."],["Notfallplan","برنامهٔ آمادهٔ اختلال شدید."],["Wiederanlauf","بازگشت کنترل‌شده به کار."],["Nachbereitung","ارزیابی پس از رویداد برای بهبود."]],"q":"چرا پس از حادثه بررسی نهایی انجام می‌شود؟","options":["برای حذف مسئولیت","برای ثبت علت و بهبودها","فقط برای تغییر ساعت"],"answer":1,"feedback":"ارزیابی ثبت‌شده به بهترشدن اقدامات، روش‌ها و آمادگی کمک می‌کند.","remember":["مشاهده را سریع از مسیر تعیین‌شده گزارش کن.","مهار و حفظ شواهد باید هماهنگ باشد.","بازیابی به آزمایش عملکرد و بررسی پس از حادثه نیاز دارد."],"summary":"برنامهٔ اضطراری تمرین‌شده آسیب را محدود و بازگشت کنترل‌شده به کار قابل اعتماد را ممکن می‌کند."}},"learningField":"11b","coverage":{"de":"Eigenständige Lerntexte zur Vertiefung; keine vollständige IHK-Prüfungsabdeckung.","fa":"درس‌های تألیفی برای یادگیری عمیق‌تر؛ پوشش کامل امتحان IHK نیست."},"visual":{"icon":"◇","color":"#e8f1eb","ink":"#36745a","desc":["Schutzziele, Risiken und Maßnahmen für einen sicheren Systembetrieb verstehen.","هدف‌های امنیت، خطرها و روش‌های کارکرد امن سیستم را بفهم."]}},{"id":"k12-projekt","grade":"12","subject":{"de":"IT-Projekt · Systemintegration","fa":"پروژهٔ IT؛ یکپارچه‌سازی سیستم","en":"IT project · systems integration"},"order":["anforderungen","varianten","planung","wirtschaft","test","dokumentation"],"de":{"anforderungen":{"title":"Kundenanforderungen und Projektziel klären","goal":"Du formulierst aus einem Wunsch eine messbare Anforderung mit Abnahmekriterium.","definition":"Eine Anforderungsanalyse klärt, welches Problem ein Kunde lösen möchte und welche Bedingungen die Lösung erfüllen muss. Das Projektziel beschreibt den gewünschten Zustand; Anforderungen machen diesen Zustand konkret überprüfbar.","explanation":"1. Ist-Zustand und Bedarf: Erfrage Arbeitsabläufe, Probleme, Beteiligte und vorhandene Systeme. Unterscheide den eigentlichen Bedarf von einer schon vorgeschlagenen Technik. „Wir brauchen einen neuen Server“ erklärt noch nicht, welches Problem gelöst werden soll.\n\n2. Soll-Zustand beschreiben: Funktionale Anforderungen sagen, was eine Lösung leisten soll. Qualitätsanforderungen beschreiben beispielsweise Antwortzeit, Sicherheit oder Verfügbarkeit. Rahmenbedingungen begrenzen Budget, Termin, Plattform oder benötigte Schnittstellen.\n\n3. Kriterien abstimmen: Formuliere zu wichtigen Anforderungen ein Test- oder Abnahmekriterium. Kläre Prioritäten und ausdrücklich ausgeschlossene Aufgaben. Halte Annahmen fest und bestätige sie mit den zuständigen Beteiligten. So lassen sich spätere Änderungen bewusst bewerten.","sections":[{"title":"1. Ist-Zustand und Bedarf","body":"Erfrage Arbeitsabläufe, Probleme, Beteiligte und vorhandene Systeme. Unterscheide den eigentlichen Bedarf von einer schon vorgeschlagenen Technik. „Wir brauchen einen neuen Server“ erklärt noch nicht, welches Problem gelöst werden soll."},{"title":"2. Soll-Zustand beschreiben","body":"Funktionale Anforderungen sagen, was eine Lösung leisten soll. Qualitätsanforderungen beschreiben beispielsweise Antwortzeit, Sicherheit oder Verfügbarkeit. Rahmenbedingungen begrenzen Budget, Termin, Plattform oder benötigte Schnittstellen."},{"title":"3. Kriterien abstimmen","body":"Formuliere zu wichtigen Anforderungen ein Test- oder Abnahmekriterium. Kläre Prioritäten und ausdrücklich ausgeschlossene Aufgaben. Halte Annahmen fest und bestätige sie mit den zuständigen Beteiligten. So lassen sich spätere Änderungen bewusst bewerten."}],"example":"Der Kunde sagt: „Der Dateizugriff ist zu langsam.“ Du misst den Ist-Zustand und vereinbarst einen Test: Eine definierte 500-MB-Datei soll unter festgelegten Netzbedingungen innerhalb von 15 Sekunden bereitgestellt werden. Damit gibt es eine prüfbare Anforderung statt nur des Wortes „schnell“.","mistake":"Ein technischer Produktname ersetzt keine Anforderung. Zuerst muss klar sein, welches überprüfbare Ergebnis gebraucht wird.","terms":[["Ist-Zustand","Erfasste Ausgangssituation."],["Soll-Zustand","Gewünschte Situation nach dem Projekt."],["Funktionale Anforderung","Benötigte Funktion der Lösung."],["Qualitätsanforderung","Gewünschte Eigenschaft wie Leistung oder Sicherheit."],["Rahmenbedingung","Vorgegebene Begrenzung des Projekts."],["Abnahmekriterium","Vereinbarter Maßstab für die Prüfung eines Ergebnisses."]],"q":"Welche Formulierung ist am besten überprüfbar?","options":["Die Lösung soll schön schnell sein.","Die festgelegte Datei wird unter definierten Bedingungen in höchstens 15 Sekunden übertragen.","Wir nehmen ein bekanntes Produkt."],"answer":1,"feedback":"Testdaten, Bedingungen und Grenzwert machen die Anforderung messbar.","remember":["Erst den Bedarf klären, dann Produkte auswählen.","Funktion, Qualität und Rahmenbedingungen getrennt beschreiben.","Abnahmekriterien machen Anforderungen prüfbar."],"summary":"Eine verständliche Anforderungsanalyse übersetzt den Kundenwunsch in ein gemeinsames, messbares Projektziel."},"varianten":{"title":"Lösungsvarianten mit Kriterien vergleichen","goal":"Du führst einen einfachen gewichteten Vergleich durch und erklärst seine Grenzen.","definition":"Ein Variantenvergleich stellt mehrere geeignete Lösungen nach denselben Kriterien gegenüber. Er hilft, eine Entscheidung nachvollziehbar zu begründen. Die teuerste oder bekannteste Lösung ist nicht automatisch die passende.","explanation":"1. Muss-Kriterien prüfen: Muss-Kriterien sind zwingende Anforderungen, etwa eine benötigte Schnittstelle oder ein verbindliches Budget. Eine Variante, die ein echtes Muss-Kriterium nicht erfüllt, wird ausgeschlossen oder muss angepasst werden, bevor sie weiter bewertet wird.\n\n2. Gewichtete Bewertung: Für geeignete Varianten definierst du Kriterien und Gewichte. Gewichte drücken die Wichtigkeit aus; Punkte bewerten die Erfüllung nach einer einheitlichen Skala. Multipliziere Punkte mit Gewicht und addiere die Ergebnisse. Dokumentiere, worauf die Punktwerte beruhen.\n\n3. Ergebnis prüfen: Eine Nutzwertzahl strukturiert die Entscheidung, ist aber kein objektiver Naturwert. Kleine Änderungen der Gewichte können die Rangfolge ändern. Prüfe außerdem Risiken, Betriebskosten, Sicherheit und Abhängigkeiten. Stimme die begründete Auswahl mit dem Kunden ab.","sections":[{"title":"1. Muss-Kriterien prüfen","body":"Muss-Kriterien sind zwingende Anforderungen, etwa eine benötigte Schnittstelle oder ein verbindliches Budget. Eine Variante, die ein echtes Muss-Kriterium nicht erfüllt, wird ausgeschlossen oder muss angepasst werden, bevor sie weiter bewertet wird."},{"title":"2. Gewichtete Bewertung","body":"Für geeignete Varianten definierst du Kriterien und Gewichte. Gewichte drücken die Wichtigkeit aus; Punkte bewerten die Erfüllung nach einer einheitlichen Skala. Multipliziere Punkte mit Gewicht und addiere die Ergebnisse. Dokumentiere, worauf die Punktwerte beruhen."},{"title":"3. Ergebnis prüfen","body":"Eine Nutzwertzahl strukturiert die Entscheidung, ist aber kein objektiver Naturwert. Kleine Änderungen der Gewichte können die Rangfolge ändern. Prüfe außerdem Risiken, Betriebskosten, Sicherheit und Abhängigkeiten. Stimme die begründete Auswahl mit dem Kunden ab."}],"example":"Kriterien: Leistung mit Gewicht 3 und Administrierbarkeit mit Gewicht 2. Variante A bekommt 4 und 2 Punkte: 3×4 + 2×2 = 16. Variante B bekommt 3 und 4 Punkte: 3×3 + 2×4 = 17. Bei dieser begründeten Gewichtung liegt B knapp vorn; die Punkteskala muss für beide gleich sein.","mistake":"Ein nicht erfülltes Muss-Kriterium darf nicht durch viele Punkte bei unwichtigen Eigenschaften verdeckt werden.","terms":[["Variante","Mögliche Ausführung einer Lösung."],["Muss-Kriterium","Zwingend zu erfüllende Bedingung."],["Gewicht","Festgelegte Wichtigkeit eines Kriteriums."],["Bewertungsskala","Einheitlicher Maßstab für Punkte."],["Nutzwert","Zusammengefasster bewerteter Nutzen."],["Sensitivität","Änderung des Ergebnisses bei veränderten Annahmen."]],"q":"Was geschieht mit einer Variante, die ein echtes Muss-Kriterium nicht erfüllt?","options":["Sie gewinnt automatisch.","Sie muss ausgeschlossen oder entsprechend angepasst werden.","Man ignoriert das Kriterium nachträglich."],"answer":1,"feedback":"Zwingende Anforderungen müssen zuerst erfüllt sein; eine Punktesumme ersetzt das nicht.","remember":["Muss-Kriterien vor der Punktebewertung prüfen.","Gewichte und Skalen müssen für alle Varianten gleich gelten.","Ein Nutzwert braucht begründete Annahmen und eine Plausibilitätsprüfung."],"summary":"Ein Variantenvergleich begründet eine passende Auswahl, indem er zwingende Anforderungen zuerst und bewertbare Vorteile danach prüft."},"planung":{"title":"Arbeitspakete, Zeiten und Abhängigkeiten","goal":"Du zerlegst ein Projekt in prüfbare Arbeitspakete und erkennst Zeitabhängigkeiten.","definition":"Projektplanung ordnet Aufgaben, Ressourcen und Termine so, dass ein vereinbartes Ergebnis erreichbar wird. Ein Plan zeigt nicht nur, was zu tun ist, sondern auch, in welcher Reihenfolge und mit welchen Voraussetzungen.","explanation":"1. Arbeitspakete bilden: Zerlege das Ergebnis in überschaubare Aufgaben. Jedes Arbeitspaket erhält Ergebnis, Verantwortung und geschätzten Aufwand. „Netzwerk fertig machen“ ist zu ungenau; „VLAN-Konfiguration dokumentiert und getestet“ liefert einen prüfbaren Abschluss.\n\n2. Reihenfolge und Ressourcen: Manche Aufgaben können parallel laufen, andere benötigen ein vorheriges Ergebnis. Aufwand ist benötigte Arbeitszeit; Dauer ist die verstrichene Zeit. Eine Stunde Arbeit kann wegen einer Lieferfrist erst nächste Woche abgeschlossen sein. Berücksichtige verfügbare Personen und Geräte.\n\n3. Meilensteine und Kontrolle: Ein Meilenstein markiert einen wichtigen erreichten Zustand, zum Beispiel die bestätigte Testfreigabe. Vergleiche während des Projekts Plan und Ist. Bewerte Abweichungen früh und stimme Änderungen ab, statt den Plan erst am Ende passend zu schreiben.","sections":[{"title":"1. Arbeitspakete bilden","body":"Zerlege das Ergebnis in überschaubare Aufgaben. Jedes Arbeitspaket erhält Ergebnis, Verantwortung und geschätzten Aufwand. „Netzwerk fertig machen“ ist zu ungenau; „VLAN-Konfiguration dokumentiert und getestet“ liefert einen prüfbaren Abschluss."},{"title":"2. Reihenfolge und Ressourcen","body":"Manche Aufgaben können parallel laufen, andere benötigen ein vorheriges Ergebnis. Aufwand ist benötigte Arbeitszeit; Dauer ist die verstrichene Zeit. Eine Stunde Arbeit kann wegen einer Lieferfrist erst nächste Woche abgeschlossen sein. Berücksichtige verfügbare Personen und Geräte."},{"title":"3. Meilensteine und Kontrolle","body":"Ein Meilenstein markiert einen wichtigen erreichten Zustand, zum Beispiel die bestätigte Testfreigabe. Vergleiche während des Projekts Plan und Ist. Bewerte Abweichungen früh und stimme Änderungen ab, statt den Plan erst am Ende passend zu schreiben."}],"example":"Die Konfiguration dauert 3 Stunden, der Test 2 Stunden. Der Test beginnt erst nach der Konfiguration. Zusammen brauchen diese abhängigen Aufgaben mindestens 5 Stunden Arbeitszeit; eine zusätzliche Lieferfrist oder fehlende Testperson kann die Kalenderdauer verlängern. Dokumentation kann teilweise parallel vorbereitet werden.","mistake":"Aufwand und Dauer sind unterschiedliche Größen. Drei Personen machen eine nicht teilbare Aufgabe nicht automatisch dreimal schneller.","terms":[["Arbeitspaket","Abgegrenzte Aufgabe mit Ergebnis und Verantwortung."],["Aufwand","Benötigte Arbeitszeit."],["Dauer","Verstrichener Zeitraum einer Aufgabe."],["Abhängigkeit","Eine Aufgabe benötigt ein vorheriges Ergebnis."],["Meilenstein","Wichtiger, überprüfbarer Projektzustand."],["Plan-Ist-Vergleich","Gegenüberstellung geplanter und tatsächlicher Werte."]],"q":"Was beschreibt den Aufwand?","options":["Die benötigte Arbeitszeit","Immer die gesamte Kalenderdauer","Nur den Liefertermin"],"answer":0,"feedback":"Aufwand zählt Arbeit; Dauer berücksichtigt den zeitlichen Ablauf und mögliche Wartezeiten.","remember":["Arbeitspakete brauchen Ergebnis, Verantwortung und Aufwand.","Aufwand ist Arbeitszeit; Dauer ist verstrichene Zeit.","Abhängigkeiten und Ressourcen begrenzen mögliche Parallelität."],"summary":"Ein nutzbarer Projektplan verbindet überprüfbare Ergebnisse mit realistischen Reihenfolgen, Ressourcen und laufender Kontrolle."},"wirtschaft":{"title":"Kosten und Wirtschaftlichkeit berechnen","goal":"Du unterscheidest einmalige und laufende Kosten und berechnest eine einfache Amortisationszeit.","definition":"Wirtschaftlichkeit vergleicht den Nutzen einer Lösung mit ihrem Ressourceneinsatz. Eine technische Entscheidung berücksichtigt deshalb nicht nur den Kaufpreis, sondern auch Einführung, Betrieb, Wartung und mögliche Einsparungen.","explanation":"1. Kosten vollständig sammeln: Einmalige Kosten entstehen beispielsweise für Hardware, Einrichtung und Schulung. Laufende Kosten betreffen etwa Lizenzen, Energie, Wartung und Administration. Bei Arbeitszeit wird der vereinbarte kalkulatorische Stundensatz genutzt. Der Betrachtungszeitraum muss für alle Varianten gleich sein.\n\n2. Nutzen messbar machen: Nutzen kann in gesparter Arbeitszeit, weniger Ausfällen oder höherer Qualität bestehen. Nicht jede Verbesserung lässt sich zuverlässig in Euro ausdrücken. Benenne deshalb Annahmen und qualitative Vorteile getrennt, statt scheinbar genaue Zahlen zu erfinden.\n\n3. Amortisation einordnen: Eine einfache statische Amortisationsrechnung teilt die Anfangsinvestition durch den jährlichen Netto-Rückfluss beziehungsweise die jährliche Netto-Einsparung. Sie setzt vereinfachend gleichbleibende Werte voraus und berücksichtigt den Zeitwert des Geldes nicht. Sie ist eine Orientierung, keine vollständige Investitionsbewertung.","sections":[{"title":"1. Kosten vollständig sammeln","body":"Einmalige Kosten entstehen beispielsweise für Hardware, Einrichtung und Schulung. Laufende Kosten betreffen etwa Lizenzen, Energie, Wartung und Administration. Bei Arbeitszeit wird der vereinbarte kalkulatorische Stundensatz genutzt. Der Betrachtungszeitraum muss für alle Varianten gleich sein."},{"title":"2. Nutzen messbar machen","body":"Nutzen kann in gesparter Arbeitszeit, weniger Ausfällen oder höherer Qualität bestehen. Nicht jede Verbesserung lässt sich zuverlässig in Euro ausdrücken. Benenne deshalb Annahmen und qualitative Vorteile getrennt, statt scheinbar genaue Zahlen zu erfinden."},{"title":"3. Amortisation einordnen","body":"Eine einfache statische Amortisationsrechnung teilt die Anfangsinvestition durch den jährlichen Netto-Rückfluss beziehungsweise die jährliche Netto-Einsparung. Sie setzt vereinfachend gleichbleibende Werte voraus und berücksichtigt den Zeitwert des Geldes nicht. Sie ist eine Orientierung, keine vollständige Investitionsbewertung."}],"example":"Eine Lösung kostet einmalig 6.000 €. Sie spart jährlich 3.000 €, verursacht aber 1.000 € zusätzliche jährliche Betriebskosten. Netto-Einsparung: 2.000 € pro Jahr. Einfache Amortisationszeit: 6.000 / 2.000 = 3 Jahre. Weitere Risiken und nicht bezifferte Vorteile werden zusätzlich dokumentiert.","mistake":"Die jährlichen Zusatzkosten dürfen nicht vergessen werden. Sonst sieht die Investition fälschlich schneller bezahlt aus.","terms":[["Investition","Anfangsausgabe für eine längerfristig genutzte Lösung."],["Betriebskosten","Kosten während der laufenden Nutzung."],["Stundensatz","Kalkulatorischer Betrag je Arbeitsstunde."],["Netto-Einsparung","Einsparung nach Abzug zusätzlicher Kosten."],["Amortisationszeit","Vereinfachte Zeit bis zum Ausgleich einer Investition."],["TCO","Gesamtkosten über einen festgelegten Betrachtungszeitraum."]],"q":"6.000 € Investition und 2.000 € jährliche Netto-Einsparung ergeben vereinfacht?","options":["3 Jahre","12 Jahre","2 Monate"],"answer":0,"feedback":"6.000 € geteilt durch 2.000 € pro Jahr ergibt 3 Jahre.","remember":["Einmalige und laufende Kosten vollständig erfassen.","Netto-Einsparung berücksichtigt zusätzliche Betriebskosten.","Einfache Amortisation berücksichtigt den Zeitwert des Geldes nicht."],"summary":"Eine belastbare Wirtschaftlichkeitsbetrachtung macht Kosten, messbaren Nutzen und vereinfachende Annahmen gemeinsam sichtbar."},"test":{"title":"Testfälle und Abnahme vorbereiten","goal":"Du formulierst einen Test mit Voraussetzung, Aktion und erwartetem Ergebnis.","definition":"Ein Test prüft, ob ein System eine bestimmte Anforderung erfüllt. Die Abnahme bewertet das vereinbarte Projektergebnis mit dem Kunden. Gute Testfälle machen nachvollziehbar, was tatsächlich geprüft und welches Ergebnis festgestellt wurde.","explanation":"1. Test aus Anforderungen ableiten: Jede wichtige Anforderung braucht passende Prüfungen. Definiere Ausgangszustand, Testdaten, Schritte und erwartetes Ergebnis. Ein positiver Test prüft erlaubte Nutzung; ein negativer Test prüft beispielsweise, ob unberechtigter Zugriff verhindert wird.\n\n2. Ergebnis dokumentieren: Halte den tatsächlichen Ausgang und relevante Belege fest. „Hat funktioniert“ ist zu wenig, wenn niemand Testkonto, Datum oder geprüfte Funktion kennt. Fehler werden beschrieben, priorisiert, behoben und erneut geprüft. Eine Testumgebung soll den relevanten Bedingungen ausreichend entsprechen.\n\n3. Abnahme durchführen: Vergleiche die Ergebnisse mit den vereinbarten Abnahmekriterien. Dokumentiere erfüllte Punkte, bekannte Mängel und vereinbarte nächste Schritte. Eine Abnahme ist keine bloße Präsentation; sie braucht eine klare Prüfung des vereinbarten Leistungsumfangs.","sections":[{"title":"1. Test aus Anforderungen ableiten","body":"Jede wichtige Anforderung braucht passende Prüfungen. Definiere Ausgangszustand, Testdaten, Schritte und erwartetes Ergebnis. Ein positiver Test prüft erlaubte Nutzung; ein negativer Test prüft beispielsweise, ob unberechtigter Zugriff verhindert wird."},{"title":"2. Ergebnis dokumentieren","body":"Halte den tatsächlichen Ausgang und relevante Belege fest. „Hat funktioniert“ ist zu wenig, wenn niemand Testkonto, Datum oder geprüfte Funktion kennt. Fehler werden beschrieben, priorisiert, behoben und erneut geprüft. Eine Testumgebung soll den relevanten Bedingungen ausreichend entsprechen."},{"title":"3. Abnahme durchführen","body":"Vergleiche die Ergebnisse mit den vereinbarten Abnahmekriterien. Dokumentiere erfüllte Punkte, bekannte Mängel und vereinbarte nächste Schritte. Eine Abnahme ist keine bloße Präsentation; sie braucht eine klare Prüfung des vereinbarten Leistungsumfangs."}],"example":"Testfall: Ein Gastkonto darf die Personal-Freigabe nicht lesen. Voraussetzung: aktives Gastkonto ohne Personalgruppe. Aktion: Zugriff auf die Freigabe versuchen. Erwartet: Zugriff verweigert. Tatsächlich: Zugriff verweigert; Test bestanden. Mit einem berechtigten Personalkonto prüfst du zusätzlich, ob notwendiger Zugriff möglich bleibt.","mistake":"Nur erfolgreiche Standardfälle zu testen reicht nicht. Rechte, fehlerhafte Eingaben und wichtige Ausfallsituationen brauchen passende Gegenproben.","terms":[["Testfall","Beschriebene Prüfung mit erwartetem Ergebnis."],["Voraussetzung","Zustand, der vor dem Test vorhanden sein muss."],["Testdaten","Für eine Prüfung ausgewählte Eingabedaten."],["Negativtest","Prüfung, ob unerlaubte oder fehlerhafte Fälle korrekt behandelt werden."],["Soll-Ergebnis","Erwarteter Ausgang einer Prüfung."],["Abnahmeprotokoll","Dokumentiertes Ergebnis der vereinbarten Leistungsprüfung."]],"q":"Was gehört neben Testschritten in einen Testfall?","options":["Nur das Lieblingswerkzeug","Voraussetzungen und erwartetes Ergebnis","Nur der Preis des Geräts"],"answer":1,"feedback":"Ohne Ausgangszustand und Erwartung ist der Testerfolg nicht eindeutig bewertbar.","remember":["Testfälle aus Anforderungen und Abnahmekriterien ableiten.","Voraussetzung, Aktion und erwartetes Ergebnis festhalten.","Negative Tests prüfen unerlaubte oder fehlerhafte Fälle."],"summary":"Nachvollziehbare Tests liefern die Belege, mit denen Kunde und Projektteam die vereinbarte Leistung bewerten können."},"dokumentation":{"title":"Dokumentation, Übergabe und Projektbewertung","goal":"Du unterscheidest technische Dokumentation von einer Anleitung und bewertest das Ergebnis anhand des Ziels.","definition":"Dokumentation macht eine Lösung für andere nachvollziehbar und weiter betreibbar. Die Übergabe stellt sicher, dass der Kunde das Ergebnis nutzen und die zuständige Betriebsstelle es betreuen kann. Sie gehört zum Projektabschluss.","explanation":"1. Technische Dokumentation: Erkläre Aufbau, Adressen, wichtige Konfigurationen, Abhängigkeiten und Zuständigkeiten. Dokumentiere außerdem Sicherung, Wiederherstellung und Wartung. Geheimnisse werden über geeignete geschützte Verfahren übergeben; sie gehören nicht offen in eine allgemein verteilte Anleitung.\n\n2. Benutzer und Betrieb einweisen: Eine Benutzeranleitung beschreibt die benötigten Arbeitsschritte in verständlicher Sprache. Eine Betriebseinweisung erklärt Überwachung, typische Störungen und Eskalationswege. Prüfe mit den Empfängern, ob die Unterlagen tatsächlich verständlich und nutzbar sind.\n\n3. Ergebnis bewerten: Vergleiche Projektziel und tatsächliches Ergebnis: Funktion, Qualität, Kosten und Termine. Begründe Abweichungen und benenne sinnvolle Verbesserungen. Rückmeldungen des Kunden sind wichtig. Eine sachliche Reflexion nennt auch Grenzen und offene Punkte, statt nur den Erfolg zu behaupten.","sections":[{"title":"1. Technische Dokumentation","body":"Erkläre Aufbau, Adressen, wichtige Konfigurationen, Abhängigkeiten und Zuständigkeiten. Dokumentiere außerdem Sicherung, Wiederherstellung und Wartung. Geheimnisse werden über geeignete geschützte Verfahren übergeben; sie gehören nicht offen in eine allgemein verteilte Anleitung."},{"title":"2. Benutzer und Betrieb einweisen","body":"Eine Benutzeranleitung beschreibt die benötigten Arbeitsschritte in verständlicher Sprache. Eine Betriebseinweisung erklärt Überwachung, typische Störungen und Eskalationswege. Prüfe mit den Empfängern, ob die Unterlagen tatsächlich verständlich und nutzbar sind."},{"title":"3. Ergebnis bewerten","body":"Vergleiche Projektziel und tatsächliches Ergebnis: Funktion, Qualität, Kosten und Termine. Begründe Abweichungen und benenne sinnvolle Verbesserungen. Rückmeldungen des Kunden sind wichtig. Eine sachliche Reflexion nennt auch Grenzen und offene Punkte, statt nur den Erfolg zu behaupten."}],"example":"Bei Übergabe eines Dateiservers erhält die IT den Netzplan, die Rechteübersicht und das Wiederherstellungsverfahren. Benutzer erhalten eine kurze Anleitung zum Einbinden der Freigabe. Im Abschlussgespräch zeigst du, welche Testkriterien erfüllt wurden und dass eine vereinbarte Zusatzfunktion noch außerhalb des aktuellen Auftrags liegt.","mistake":"Eine Sammlung von Screenshots ohne Erklärung ist keine ausreichende Betriebsdokumentation. Die nächste Person muss verstehen, was und warum konfiguriert wurde.","terms":[["Technische Dokumentation","Nachvollziehbare Beschreibung von Aufbau und Betrieb."],["Benutzeranleitung","Verständliche Anleitung zur Nutzung."],["Übergabe","Geordnete Übermittlung von Ergebnis und benötigtem Wissen."],["Einweisung","Erklärung der Bedienung oder Betreuung."],["Projektbewertung","Vergleich von Ziel und Ergebnis anhand von Kriterien."],["Lessons Learned","Festgehaltene Erkenntnisse für spätere Vorhaben."]],"q":"Welche Unterlage hilft dem Betrieb bei einem Datenverlust besonders?","options":["Nur ein Bild des Servergehäuses","Ein geprüftes Wiederherstellungsverfahren","Nur der Projektname"],"answer":1,"feedback":"Ein nachvollziehbarer und getesteter Restore-Ablauf unterstützt die tatsächliche Wiederaufnahme des Betriebs.","remember":["Technische Dokumentation erklärt Aufbau und Betrieb.","Benutzeranleitungen orientieren sich an den Arbeitsschritten der Nutzer.","Projektbewertung vergleicht Ziel, Ergebnis und begründete Abweichungen."],"summary":"Eine gute Übergabe macht die Lösung nutzbar, betreibbar und anhand der vereinbarten Ziele ehrlich bewertbar."}},"fa":{"anforderungen":{"title":"روشن‌کردن نیاز مشتری و هدف پروژه","goal":"از خواستهٔ مشتری یک نیاز قابل سنجش و معیار تحویل بسازی.","definition":"تحلیل نیاز روشن می‌کند مشتری چه مسئله‌ای دارد و راه‌حل باید چه شرایطی را برآورده کند. هدف پروژه وضعیت مطلوب را می‌گوید و نیازها آن را قابل آزمایش می‌کنند.","explanation":"۱. وضعیت فعلی و نیاز: روش کار، مشکل، افراد درگیر و سیستم فعلی را بپرس. نیاز واقعی را از فناوری پیشنهادی جدا کن. جملهٔ «سرور جدید می‌خواهیم» هنوز علت و مسئله را توضیح نمی‌دهد.\n\n۲. وضعیت مطلوب: نیاز عملکردی می‌گوید راه‌حل چه کاری انجام دهد. نیاز کیفی، زمان پاسخ، امنیت یا دسترس‌پذیری را مشخص می‌کند. محدودیت‌ها بودجه، زمان، پلتفرم و رابط لازم را تعیین می‌کنند.\n\n۳. توافق روی معیار: برای نیاز مهم معیار آزمایش یا پذیرش بنویس. اولویت و کارهای خارج از پروژه را روشن کن. فرض‌ها را ثبت و با مسئول مربوط تأیید کن تا تغییر بعدی آگاهانه بررسی شود.","sections":[{"title":"۱. وضعیت فعلی و نیاز","body":"روش کار، مشکل، افراد درگیر و سیستم فعلی را بپرس. نیاز واقعی را از فناوری پیشنهادی جدا کن. جملهٔ «سرور جدید می‌خواهیم» هنوز علت و مسئله را توضیح نمی‌دهد."},{"title":"۲. وضعیت مطلوب","body":"نیاز عملکردی می‌گوید راه‌حل چه کاری انجام دهد. نیاز کیفی، زمان پاسخ، امنیت یا دسترس‌پذیری را مشخص می‌کند. محدودیت‌ها بودجه، زمان، پلتفرم و رابط لازم را تعیین می‌کنند."},{"title":"۳. توافق روی معیار","body":"برای نیاز مهم معیار آزمایش یا پذیرش بنویس. اولویت و کارهای خارج از پروژه را روشن کن. فرض‌ها را ثبت و با مسئول مربوط تأیید کن تا تغییر بعدی آگاهانه بررسی شود."}],"example":"مشتری می‌گوید دسترسی فایل کند است. وضعیت فعلی را اندازه می‌گیری و توافق می‌کنی فایل مشخص ۵۰۰ مگابایتی در شرایط شبکهٔ معلوم حداکثر در ۱۵ ثانیه منتقل شود. اکنون به جای «سریع»، نیاز قابل بررسی داری.","mistake":"نام یک محصول جای نیاز را نمی‌گیرد؛ ابتدا نتیجهٔ قابل آزمایش را مشخص کن.","terms":[["Ist-Zustand","وضعیت فعلی ثبت‌شده."],["Soll-Zustand","وضعیت مطلوب پس از پروژه."],["Funktionale Anforderung","کاری که راه‌حل باید انجام دهد."],["Qualitätsanforderung","ویژگی مورد انتظار مثل سرعت یا امنیت."],["Rahmenbedingung","محدودیت تعیین‌شدهٔ پروژه."],["Abnahmekriterium","معیار توافق‌شده برای پذیرش نتیجه."]],"q":"کدام جمله قابل آزمایش‌تر است؟","options":["سیستم خیلی سریع باشد.","فایل مشخص در شرایط معلوم حداکثر در ۱۵ ثانیه منتقل شود.","یک محصول معروف بگیریم."],"answer":1,"feedback":"دادهٔ آزمایش، شرایط و حد زمانی نیاز را قابل سنجش می‌کنند.","remember":["اول نیاز را روشن کن و بعد محصول را انتخاب کن.","کارکرد، کیفیت و محدودیت را جدا بنویس.","معیار پذیرش، نیاز را قابل آزمایش می‌کند."],"summary":"تحلیل نیازِ روشن، خواستهٔ مشتری را به هدف مشترک و قابل سنجش پروژه تبدیل می‌کند."},"varianten":{"title":"مقایسهٔ راه‌حل‌ها با معیار","goal":"یک مقایسهٔ وزن‌دار ساده انجام بدهی و محدودیت آن را بفهمی.","definition":"مقایسهٔ گزینه‌ها چند راه‌حل مناسب را با معیار یکسان می‌سنجد تا تصمیم دلیل روشن داشته باشد. گران‌ترین یا معروف‌ترین محصول لزوماً مناسب‌ترین نیست.","explanation":"۱. شرط‌های ضروری: شرط ضروری مثل رابط لازم یا سقف قطعی بودجه باید تأمین شود. گزینهٔ نامناسب پیش از امتیازدهی حذف می‌شود یا باید اصلاح شود.\n\n۲. ارزیابی وزن‌دار: برای گزینه‌های مناسب معیار و وزن تعریف کن. وزن اهمیت را نشان می‌دهد و امتیاز میزان برآورده‌شدن را با مقیاس مشترک می‌سنجد. امتیاز را در وزن ضرب و نتیجه‌ها را جمع کن. دلیل امتیازها باید ثبت شود.\n\n۳. بررسی نتیجه: عدد Nutzwert تصمیم را منظم می‌کند اما حقیقت مطلق نیست. تغییر کوچک وزن ممکن است رتبه را عوض کند. خطر، هزینهٔ نگهداری، امنیت و وابستگی را هم بررسی و انتخاب را با مشتری توافق کن.","sections":[{"title":"۱. شرط‌های ضروری","body":"شرط ضروری مثل رابط لازم یا سقف قطعی بودجه باید تأمین شود. گزینهٔ نامناسب پیش از امتیازدهی حذف می‌شود یا باید اصلاح شود."},{"title":"۲. ارزیابی وزن‌دار","body":"برای گزینه‌های مناسب معیار و وزن تعریف کن. وزن اهمیت را نشان می‌دهد و امتیاز میزان برآورده‌شدن را با مقیاس مشترک می‌سنجد. امتیاز را در وزن ضرب و نتیجه‌ها را جمع کن. دلیل امتیازها باید ثبت شود."},{"title":"۳. بررسی نتیجه","body":"عدد Nutzwert تصمیم را منظم می‌کند اما حقیقت مطلق نیست. تغییر کوچک وزن ممکن است رتبه را عوض کند. خطر، هزینهٔ نگهداری، امنیت و وابستگی را هم بررسی و انتخاب را با مشتری توافق کن."}],"example":"کارایی وزن ۳ و مدیریت‌پذیری وزن ۲ دارد. A امتیاز ۴ و ۲ می‌گیرد: ۳×۴ + ۲×۲ = ۱۶. B امتیاز ۳ و ۴ می‌گیرد: ۳×۳ + ۲×۴ = ۱۷. با این وزن‌ها B کمی بهتر است و مقیاس امتیاز هر دو باید یکسان باشد.","mistake":"امتیاز زیاد در ویژگی کم‌اهمیت نباید نبود یک شرط ضروری را پنهان کند.","terms":[["Variante","یکی از راه‌های اجرای راه‌حل."],["Muss-Kriterium","شرطی که حتماً باید تأمین شود."],["Gewicht","مقدار اهمیت معیار."],["Bewertungsskala","مقیاس یکسان امتیازدهی."],["Nutzwert","فایدهٔ ارزیابی‌شده و جمع‌بندی‌شده."],["Sensitivität","تغییر نتیجه با تغییر فرض‌ها."]],"q":"گزینه‌ای که شرط ضروری را ندارد چه می‌شود؟","options":["خودکار برنده می‌شود.","باید حذف یا برای تأمین شرط اصلاح شود.","شرط را پس از مقایسه نادیده می‌گیریم."],"answer":1,"feedback":"ابتدا نیاز ضروری باید تأمین شود؛ جمع امتیاز جای آن را نمی‌گیرد.","remember":["شرط ضروری را پیش از امتیازدهی بررسی کن.","وزن و مقیاس برای همهٔ گزینه‌ها یکسان باشد.","عدد Nutzwert به فرض مستدل و بررسی منطقی نیاز دارد."],"summary":"مقایسهٔ گزینه‌ها ابتدا شرط‌های ضروری و سپس مزیت‌های قابل ارزیابی را می‌سنجد تا انتخاب دلیل روشن داشته باشد."},"planung":{"title":"بستهٔ کاری، زمان و وابستگی","goal":"پروژه را به کارهای قابل بررسی تقسیم و وابستگی زمانی را تشخیص بدهی.","definition":"برنامه‌ریزی پروژه کار، منابع و زمان را برای رسیدن به نتیجه مرتب می‌کند. برنامه باید نشان دهد چه کاری با چه ترتیب و چه پیش‌نیازی انجام می‌شود.","explanation":"۱. بستهٔ کاری: نتیجه را به وظیفه‌های قابل مدیریت تقسیم کن. هر بسته نتیجه، مسئول و برآورد زمان کار دارد. «شبکه را تمام کن» مبهم است؛ «VLAN تنظیم، مستند و آزمایش شده» پایان مشخص دارد.\n\n۲. ترتیب و منابع: بعضی کارها هم‌زمان و بعضی پس از کار قبلی ممکن‌اند. Aufwand زمان کار لازم است و Dauer زمان سپری‌شده. یک ساعت کار به دلیل انتظار قطعه شاید هفتهٔ بعد تمام شود. زمان افراد و دستگاه‌ها را هم لحاظ کن.\n\n۳. نقطهٔ عطف و کنترل: نقطهٔ عطف وضعیت مهم قابل بررسی است؛ مثلاً تأیید آمادگی آزمایش. در طول پروژه وضعیت واقعی را با برنامه مقایسه کن و انحراف را زود بررسی کن؛ نه اینکه آخر کار برنامه را مطابق گذشته بازنویسی کنی.","sections":[{"title":"۱. بستهٔ کاری","body":"نتیجه را به وظیفه‌های قابل مدیریت تقسیم کن. هر بسته نتیجه، مسئول و برآورد زمان کار دارد. «شبکه را تمام کن» مبهم است؛ «VLAN تنظیم، مستند و آزمایش شده» پایان مشخص دارد."},{"title":"۲. ترتیب و منابع","body":"بعضی کارها هم‌زمان و بعضی پس از کار قبلی ممکن‌اند. Aufwand زمان کار لازم است و Dauer زمان سپری‌شده. یک ساعت کار به دلیل انتظار قطعه شاید هفتهٔ بعد تمام شود. زمان افراد و دستگاه‌ها را هم لحاظ کن."},{"title":"۳. نقطهٔ عطف و کنترل","body":"نقطهٔ عطف وضعیت مهم قابل بررسی است؛ مثلاً تأیید آمادگی آزمایش. در طول پروژه وضعیت واقعی را با برنامه مقایسه کن و انحراف را زود بررسی کن؛ نه اینکه آخر کار برنامه را مطابق گذشته بازنویسی کنی."}],"example":"تنظیم سه ساعت و آزمایش دو ساعت زمان کار می‌خواهد. چون آزمایش بعد از تنظیم است، دست‌کم پنج ساعت کار لازم است. تأخیر قطعه یا نبود آزمایش‌کننده مدت تقویمی را بیشتر می‌کند. بخشی از مستندات می‌تواند هم‌زمان آماده شود.","mistake":"زمان کار و مدت تقویمی یکی نیستند. سه نفر یک کار تقسیم‌ناپذیر را خودکار سه برابر سریع‌تر انجام نمی‌دهند.","terms":[["Arbeitspaket","وظیفهٔ مشخص با نتیجه و مسئول."],["Aufwand","زمان کار مورد نیاز."],["Dauer","بازهٔ زمانی سپری‌شدهٔ کار."],["Abhängigkeit","نیاز یک کار به نتیجهٔ قبلی."],["Meilenstein","وضعیت مهم و قابل بررسی پروژه."],["Plan-Ist-Vergleich","مقایسهٔ برنامه با وضعیت واقعی."]],"q":"Aufwand چه چیزی را بیان می‌کند؟","options":["زمان کار مورد نیاز","همیشه کل زمان تقویمی","فقط موعد تحویل"],"answer":0,"feedback":"Aufwand کار را می‌سنجد؛ Dauer ترتیب و انتظارهای زمانی را هم دربرمی‌گیرد.","remember":["بستهٔ کاری نتیجه، مسئول و زمان کار می‌خواهد.","Aufwand زمان کار است و Dauer زمان سپری‌شده.","وابستگی و منابع امکان کار هم‌زمان را محدود می‌کند."],"summary":"برنامهٔ مفید، نتیجهٔ قابل بررسی را با ترتیب واقعی، منابع موجود و کنترل پیوسته پیوند می‌دهد."},"wirtschaft":{"title":"محاسبهٔ هزینه و اقتصادی‌بودن","goal":"هزینهٔ اولیه و جاری را جدا و زمان بازگشت ساده را حساب کنی.","definition":"اقتصادی‌بودن، فایدهٔ راه‌حل را با منابع مصرف‌شده مقایسه می‌کند. پس تصمیم فنی فقط قیمت خرید نیست؛ راه‌اندازی، بهره‌برداری، نگهداری و صرفه‌جویی هم مهم‌اند.","explanation":"۱. جمع‌آوری هزینه: خرید سخت‌افزار، نصب و آموزش معمولاً هزینهٔ اولیه‌اند. مجوز، برق، نگهداری و مدیریت می‌توانند هزینهٔ جاری باشند. زمان کار با نرخ محاسباتی توافق‌شده سنجیده می‌شود. دورهٔ مقایسهٔ گزینه‌ها باید یکسان باشد.\n\n۲. فایدهٔ قابل سنجش: کاهش زمان کار، قطعی کمتر یا کیفیت بالاتر فایده است. همهٔ فایده‌ها دقیقاً به یورو تبدیل نمی‌شوند؛ فرض‌ها و مزیت کیفی را جدا بنویس و عدد دقیق ساختگی نساز.\n\n۳. زمان بازگشت: در محاسبهٔ ساده، سرمایه‌گذاری اولیه بر صرفه‌جویی خالص سالانه تقسیم می‌شود. فرض ساده این است که مقدار سالانه ثابت است و ارزش زمانی پول لحاظ نمی‌شود. این فقط راهنمای اولیه است؛ نه ارزیابی کامل سرمایه‌گذاری.","sections":[{"title":"۱. جمع‌آوری هزینه","body":"خرید سخت‌افزار، نصب و آموزش معمولاً هزینهٔ اولیه‌اند. مجوز، برق، نگهداری و مدیریت می‌توانند هزینهٔ جاری باشند. زمان کار با نرخ محاسباتی توافق‌شده سنجیده می‌شود. دورهٔ مقایسهٔ گزینه‌ها باید یکسان باشد."},{"title":"۲. فایدهٔ قابل سنجش","body":"کاهش زمان کار، قطعی کمتر یا کیفیت بالاتر فایده است. همهٔ فایده‌ها دقیقاً به یورو تبدیل نمی‌شوند؛ فرض‌ها و مزیت کیفی را جدا بنویس و عدد دقیق ساختگی نساز."},{"title":"۳. زمان بازگشت","body":"در محاسبهٔ ساده، سرمایه‌گذاری اولیه بر صرفه‌جویی خالص سالانه تقسیم می‌شود. فرض ساده این است که مقدار سالانه ثابت است و ارزش زمانی پول لحاظ نمی‌شود. این فقط راهنمای اولیه است؛ نه ارزیابی کامل سرمایه‌گذاری."}],"example":"خرید اولیه ۶۰۰۰ یورو است. صرفه‌جویی سالانه ۳۰۰۰ و هزینهٔ جاری اضافی ۱۰۰۰ یورو است. پس صرفه‌جویی خالص ۲۰۰۰ یورو و بازگشت ساده ۶۰۰۰ تقسیم بر ۲۰۰۰ یعنی سه سال می‌شود. خطر و مزیت غیرعددی جدا ثبت می‌شود.","mistake":"اگر هزینهٔ جاری اضافه را حذف کنی، زمان بازگشت به‌اشتباه کوتاه‌تر دیده می‌شود.","terms":[["Investition","هزینهٔ اولیه برای راه‌حل بلندمدت."],["Betriebskosten","هزینهٔ زمان استفادهٔ جاری."],["Stundensatz","مبلغ محاسباتی هر ساعت کار."],["Netto-Einsparung","صرفه‌جویی پس از کسر هزینهٔ اضافی."],["Amortisationszeit","زمان سادهٔ جبران سرمایه‌گذاری."],["TCO","جمع هزینه‌ها در بازهٔ مشخص."]],"q":"سرمایه‌گذاری ۶۰۰۰ و صرفه‌جویی خالص سالانه ۲۰۰۰ یورو، چه زمان بازگشت ساده دارد؟","options":["سه سال","دوازده سال","دو ماه"],"answer":0,"feedback":"۶۰۰۰ یورو تقسیم بر ۲۰۰۰ یورو در سال برابر سه سال است.","remember":["هزینهٔ اولیه و جاری را کامل ثبت کن.","صرفه‌جویی خالص، هزینهٔ جاری اضافی را کم می‌کند.","بازگشت ساده ارزش زمانی پول را در نظر نمی‌گیرد."],"summary":"بررسی اقتصادی معتبر، هزینه، فایدهٔ قابل سنجش و فرض‌های ساده‌کننده را با هم نشان می‌دهد."},"test":{"title":"آماده‌سازی آزمایش و پذیرش","goal":"آزمایش را با پیش‌نیاز، عمل و نتیجهٔ مورد انتظار بنویسی.","definition":"Test بررسی می‌کند سیستم نیاز مشخص را تأمین می‌کند یا نه. Abnahme نتیجهٔ توافق‌شده را با مشتری ارزیابی می‌کند. آزمایش خوب روشن می‌کند چه چیزی و با چه نتیجه‌ای بررسی شده است.","explanation":"۱. آزمایش از نیاز: هر نیاز مهم آزمایش متناسب می‌خواهد. وضعیت شروع، داده، مراحل و نتیجهٔ مورد انتظار را مشخص کن. آزمایش مثبت استفادهٔ مجاز را می‌سنجد و آزمایش منفی مثلاً جلوگیری از دسترسی غیرمجاز را.\n\n۲. ثبت نتیجه: نتیجهٔ واقعی و شاهد مناسب را بنویس. «کار کرد» کافی نیست اگر حساب آزمایش، تاریخ یا عملکرد مشخص نباشد. خطا شرح، اولویت‌بندی، اصلاح و دوباره آزمایش می‌شود. محیط تست باید شرایط مهم را به اندازهٔ کافی بازنمایی کند.\n\n۳. پذیرش: نتیجه را با معیار توافق‌شده مقایسه کن. موارد موفق، نقص‌های معلوم و کار بعدی را ثبت کن. پذیرش فقط ارائهٔ نمایشی نیست؛ محدودهٔ توافق‌شده باید واقعاً بررسی شود.","sections":[{"title":"۱. آزمایش از نیاز","body":"هر نیاز مهم آزمایش متناسب می‌خواهد. وضعیت شروع، داده، مراحل و نتیجهٔ مورد انتظار را مشخص کن. آزمایش مثبت استفادهٔ مجاز را می‌سنجد و آزمایش منفی مثلاً جلوگیری از دسترسی غیرمجاز را."},{"title":"۲. ثبت نتیجه","body":"نتیجهٔ واقعی و شاهد مناسب را بنویس. «کار کرد» کافی نیست اگر حساب آزمایش، تاریخ یا عملکرد مشخص نباشد. خطا شرح، اولویت‌بندی، اصلاح و دوباره آزمایش می‌شود. محیط تست باید شرایط مهم را به اندازهٔ کافی بازنمایی کند."},{"title":"۳. پذیرش","body":"نتیجه را با معیار توافق‌شده مقایسه کن. موارد موفق، نقص‌های معلوم و کار بعدی را ثبت کن. پذیرش فقط ارائهٔ نمایشی نیست؛ محدودهٔ توافق‌شده باید واقعاً بررسی شود."}],"example":"آزمایش: مهمان نباید پوشهٔ پرسنلی را بخواند. پیش‌نیاز حساب مهمان فعال بدون گروه پرسنل است. عمل، تلاش برای دسترسی است و انتظار، ردشدن. اگر دسترسی رد شد تست موفق است. با حساب مجاز هم بررسی می‌کنی دسترسی لازم همچنان ممکن باشد.","mistake":"فقط حالت عادی موفق را آزمایش نکن؛ مجوز، ورودی خراب و حالت قطعی مهم هم بررسی مناسب می‌خواهد.","terms":[["Testfall","آزمایش شرح‌داده‌شده با انتظار روشن."],["Voraussetzung","شرط لازم پیش از شروع آزمایش."],["Testdaten","دادهٔ انتخاب‌شده برای آزمایش."],["Negativtest","آزمایش برخورد درست با حالت غیرمجاز یا خراب."],["Soll-Ergebnis","نتیجهٔ مورد انتظار."],["Abnahmeprotokoll","ثبت نتیجهٔ بررسی عملکرد توافق‌شده."]],"q":"علاوه بر مراحل، چه چیزی در Testfall لازم است؟","options":["فقط ابزار محبوب","پیش‌نیاز و نتیجهٔ مورد انتظار","فقط قیمت دستگاه"],"answer":1,"feedback":"بدون وضعیت شروع و انتظار نمی‌توان موفقیت تست را روشن سنجید.","remember":["Test را از نیاز و معیار پذیرش بساز.","پیش‌نیاز، عمل و نتیجهٔ مورد انتظار را ثبت کن.","تست منفی، حالت خراب یا غیرمجاز را بررسی می‌کند."],"summary":"تست قابل پیگیری شواهدی می‌دهد که مشتری و تیم بتوانند عملکرد توافق‌شده را ارزیابی کنند."},"dokumentation":{"title":"مستندسازی، تحویل و ارزیابی پروژه","goal":"مستند فنی را از راهنمای کاربر جدا و نتیجه را با هدف مقایسه کنی.","definition":"مستندات باعث می‌شود دیگران راه‌حل را بفهمند و نگهداری کنند. تحویل اطمینان می‌دهد مشتری بتواند نتیجه را استفاده کند و مسئول بهره‌برداری آن را اداره کند. این کار بخشی از پایان پروژه است.","explanation":"۱. مستند فنی: ساختار، آدرس‌ها، تنظیم مهم، وابستگی و مسئول را توضیح بده. روش پشتیبان، بازیابی و نگهداری را هم ثبت کن. اطلاعات محرمانه از راه محافظت‌شدهٔ مناسب تحویل می‌شود؛ نه در راهنمای عمومی.\n\n۲. آموزش کاربر و مسئول: راهنمای کاربر مراحل کار را ساده توضیح می‌دهد. آموزش بهره‌برداری، نظارت، خطاهای معمول و راه ارجاع را روشن می‌کند. با گیرنده بررسی کن که نوشته واقعاً قابل فهم و استفاده باشد.\n\n۳. ارزیابی: هدف و نتیجه را از نظر کارکرد، کیفیت، هزینه و زمان مقایسه کن. اختلاف را دلیل بیاور و بهبود مناسب بنویس. بازخورد مشتری مهم است. ارزیابی واقعی محدودیت و کار باز را هم ذکر می‌کند.","sections":[{"title":"۱. مستند فنی","body":"ساختار، آدرس‌ها، تنظیم مهم، وابستگی و مسئول را توضیح بده. روش پشتیبان، بازیابی و نگهداری را هم ثبت کن. اطلاعات محرمانه از راه محافظت‌شدهٔ مناسب تحویل می‌شود؛ نه در راهنمای عمومی."},{"title":"۲. آموزش کاربر و مسئول","body":"راهنمای کاربر مراحل کار را ساده توضیح می‌دهد. آموزش بهره‌برداری، نظارت، خطاهای معمول و راه ارجاع را روشن می‌کند. با گیرنده بررسی کن که نوشته واقعاً قابل فهم و استفاده باشد."},{"title":"۳. ارزیابی","body":"هدف و نتیجه را از نظر کارکرد، کیفیت، هزینه و زمان مقایسه کن. اختلاف را دلیل بیاور و بهبود مناسب بنویس. بازخورد مشتری مهم است. ارزیابی واقعی محدودیت و کار باز را هم ذکر می‌کند."}],"example":"در تحویل فایل‌سرور، IT نقشهٔ شبکه، جدول دسترسی و روش بازیابی می‌گیرد. کاربر راهنمای کوتاه اتصال پوشه دریافت می‌کند. جلسهٔ پایان نشان می‌دهد کدام تست موفق بوده و قابلیت اضافی مورد توافق خارج از محدودهٔ فعلی است.","mistake":"عکس تنظیمات بدون توضیح مستند کافی نیست؛ شخص بعدی باید بداند چه چیزی و با چه دلیل تنظیم شده است.","terms":[["Technische Dokumentation","شرح قابل پیگیری ساختار و بهره‌برداری."],["Benutzeranleitung","راهنمای قابل فهم استفاده."],["Übergabe","تحویل منظم نتیجه و دانش لازم."],["Einweisung","آموزش استفاده یا نگهداری."],["Projektbewertung","مقایسهٔ هدف و نتیجه با معیار."],["Lessons Learned","درس‌های ثبت‌شده برای پروژه‌های بعد."]],"q":"هنگام ازدست‌رفتن داده کدام مدرک بیشتر به مسئول سیستم کمک می‌کند؟","options":["فقط عکس کیس","روش بازیابی آزمایش‌شده","فقط نام پروژه"],"answer":1,"feedback":"روش روشن و تست‌شدهٔ Restore به بازگشت واقعی سرویس کمک می‌کند.","remember":["مستند فنی، ساختار و بهره‌برداری را توضیح می‌دهد.","راهنمای کاربر بر مراحل کار واقعی او متمرکز است.","ارزیابی، هدف و نتیجه و دلیل اختلاف را مقایسه می‌کند."],"summary":"تحویل خوب راه‌حل را قابل استفاده، قابل نگهداری و بر پایهٔ هدف‌های توافق‌شده قابل ارزیابی می‌کند."}},"learningField":"12b","coverage":{"de":"Eigenständige Lerntexte zur Vertiefung; keine vollständige IHK-Prüfungsabdeckung.","fa":"درس‌های تألیفی برای یادگیری عمیق‌تر؛ پوشش کامل امتحان IHK نیست."},"visual":{"icon":"◈","color":"#f8efdf","ink":"#af8543","desc":["Vom Kundenauftrag zur geplanten, getesteten und dokumentierten IT-Lösung.","از درخواست مشتری تا راه‌حل IT برنامه‌ریزی‌شده، آزمایش‌شده و مستند."]}}]);
Object.assign(REVISED,{"k10-projekt/merkmale":{"de":{"title":"Was ein Projekt ist","goal":"Du unterscheidest ein Projekt von Routinearbeit und formulierst Ziel und Rahmenbedingungen.","definition":"Ein Projekt ist ein zeitlich begrenztes Vorhaben mit einem bestimmten Ergebnis und besonderen Rahmenbedingungen.","explanation":"Ein Projekt ist ein zeitlich begrenztes Vorhaben, mit dem ein bestimmtes Ergebnis unter besonderen Rahmenbedingungen erreicht werden soll. Typisch sind ein klarer Auftrag, begrenzte Mittel, mehrere zusammenhängende Aufgaben und eine eigene Koordination. Nicht jede Definition verlangt wortgleich dieselbe Merkmalsliste; entscheidend ist die Gesamtbetrachtung. Die tägliche Datensicherung ist meist ein wiederkehrender Betriebsprozess. Die Einführung einer neuen Backup-Lösung kann dagegen ein Projekt sein: Ein Zielzustand muss bis zu einem Termin mit festgelegten Ressourcen erreicht werden. Formuliere das Ziel so, dass ein Auftraggeber prüfen kann, ob es erreicht wurde. Meilensteine kennzeichnen wichtige Prüfpunkte; Arbeitspakete beschreiben bearbeitbare Teile des Weges.","example":"„WLAN in Gebäude B bis zum 30. April, eigenes Team, Abnahme als Meilenstein“ ist ein Projekt. „Jeden Montag Druckerpapier holen“ ist keins.","remember":["Projektziel: Überprüfbarer Zustand, der am Ende erreicht sein soll.","Meilenstein: Wichtiger Prüf- oder Entscheidungspunkt im Projekt.","Ein Projektziel beschreibt das gewünschte Ergebnis; eine Tätigkeit allein ist noch kein überprüfbares Ziel."],"summary":"Ein Projekt verfolgt ein überprüfbares Ergebnis in einem zeitlich und organisatorisch begrenzten Rahmen.","sections":[],"terms":[["Projektziel","Überprüfbarer Zustand, der am Ende erreicht sein soll."],["Meilenstein","Wichtiger Prüf- oder Entscheidungspunkt im Projekt."],["Arbeitspaket","Abgegrenzter, zugeordneter Teil der Projektarbeit."],["Ressourcen","Benötigte Mittel wie Zeit, Geld und Personal."]],"q":"Was ist eher ein Projekt?","options":["Der tägliche automatische Backup-Lauf","Die einmalige Einführung einer neuen Backup-Lösung","Das regelmäßige Öffnen des Büros"],"answer":1,"feedback":"Die Einführung hat einen einmaligen Zielzustand, einen Termin und eine eigene Planung.","mistake":"Ein Projektziel beschreibt das gewünschte Ergebnis; eine Tätigkeit allein ist noch kein überprüfbares Ziel."},"fa":{"title":"پروژه چیست","goal":"پروژه را از کار روزمره جدا می‌کنی و هدف و شرایط آن را روشن می‌نویسی.","definition":"پروژه فعالیت دارای زمان محدود، نتیجهٔ مشخص و شرایط ویژه است.","explanation":"پروژه فعالیتی با زمان محدود است که باید در شرایط مشخص به نتیجهٔ معینی برسد. سفارش روشن، منابع محدود، چند کار مرتبط و هماهنگی ویژه از ویژگی‌های معمول آن‌اند. همهٔ تعریف‌ها الزاماً یک فهرست دقیق یکسان ندارند؛ باید کل وضعیت را بررسی کرد. پشتیبان‌گیری روزانه معمولاً فرایند تکراری شرکت است. اما راه‌اندازی سیستم جدید Backup می‌تواند پروژه باشد: نتیجهٔ مشخص باید تا موعدی معین و با منابع معلوم به دست آید. هدف را طوری بنویس که سفارش‌دهنده بتواند تحققش را بررسی کند. Meilenstein نقطهٔ مهم کنترل و Arbeitspaket بخش قابل انجام مسیر است.","example":"«WLAN در ساختمان B تا ۳۰ آوریل، تیم خودش، تحویل به‌عنوان نقطه عطف» پروژه است. «هر دوشنبه کاغذ چاپگر بیاور» نیست.","remember":["Projektziel: وضعیت قابل سنجشی که در پایان باید حاصل شود.","Meilenstein: نقطهٔ مهم کنترل یا تصمیم در پروژه.","هدف نتیجهٔ مورد نظر را بیان می‌کند؛ نام یک کار به‌تنهایی هدف قابل سنجش نیست."],"summary":"پروژه نتیجهٔ قابل سنجش را در چارچوب محدود زمانی و سازمانی دنبال می‌کند.","sections":[],"terms":[["Projektziel","وضعیت قابل سنجشی که در پایان باید حاصل شود."],["Meilenstein","نقطهٔ مهم کنترل یا تصمیم در پروژه."],["Arbeitspaket","بخش مشخص و مسئولیت‌دار از کار پروژه."],["Ressourcen","منابع لازم مثل زمان، پول و کارکنان."]],"q":"کدام مورد بیشتر پروژه است؟","options":["اجرای خودکار روزانهٔ Backup","راه‌اندازی یک‌بارهٔ راهکار جدید Backup","بازکردن همیشگی دفتر"],"answer":1,"feedback":"راه‌اندازی هدف نهایی مشخص، موعد و برنامه‌ریزی ویژه دارد.","mistake":"هدف نتیجهٔ مورد نظر را بیان می‌کند؛ نام یک کار به‌تنهایی هدف قابل سنجش نیست."},"minutes":9,"editorial":true,"source":["PMI · Project and lifecycle","https://www.pmi.org/about/what-is-a-project"]},"k10-projekt/erfolg":{"de":{"title":"Gelingen und Scheitern","goal":"Du erkennst typische Projektrisiken und leitest konkrete Maßnahmen zur Steuerung ab.","definition":"Projekterfolg bedeutet, vereinbarte Ziele und Erwartungen innerhalb des abgestimmten Rahmens zu erfüllen.","explanation":"Ein Projektergebnis muss zu den vereinbarten Anforderungen passen. Dazu gehören meist Qualität, Termin und Kosten. Diese Größen beeinflussen sich: Zusätzliche Funktionen können mehr Zeit oder Geld benötigen. Kläre deshalb zuerst mit dem Auftraggeber, was notwendig ist und woran die Abnahme gemessen wird. Ein Risiko ist ein mögliches zukünftiges Ereignis mit Auswirkungen; ein bereits eingetretenes Problem muss konkret bearbeitet werden. Halte Risiken mit Eintrittswahrscheinlichkeit, Auswirkung und Gegenmaßnahme fest. Regelmäßige kurze Statusgespräche machen Abweichungen sichtbar. Änderungen sollten bewertet und vereinbart werden, statt unbemerkt in die Arbeit zu wandern. Dokumentiere Entscheidungen so, dass andere den Stand und die Gründe nachvollziehen können.","example":"Das Team baut VLAN 30, der Kunde wollte nur neue Access Points im bestehenden Netz. Ohne Abstimmung ist die Technik umsonst.","remember":["Risiko: Mögliches zukünftiges Ereignis mit Einfluss auf Ziele.","Abnahme: Prüfung und Anerkennung des vereinbarten Ergebnisses.","Technisch funktionierende Ergebnisse reichen nicht, wenn sie die vereinbarten Kundenanforderungen verfehlen."],"summary":"Klare Anforderungen, laufende Abstimmung und kontrollierte Änderungen verbinden Technik mit tatsächlichem Kundennutzen.","sections":[],"terms":[["Risiko","Mögliches zukünftiges Ereignis mit Einfluss auf Ziele."],["Abnahme","Prüfung und Anerkennung des vereinbarten Ergebnisses."],["Soll-Ist-Vergleich","Vergleich zwischen Planwert und tatsächlichem Stand."],["Änderungsantrag","Dokumentierter Vorschlag, vereinbarte Anforderungen zu ändern."]],"q":"Ein Kunde möchte zusätzliche Funktionen. Was ist sinnvoll?","options":["Sofort ohne Prüfung zusagen","Auswirkung auf Zeit, Kosten und Qualität prüfen und abstimmen","Die Änderung heimlich umsetzen"],"answer":1,"feedback":"Eine bewertete und vereinbarte Änderung hält Erwartungen und Planung zusammen.","mistake":"Technisch funktionierende Ergebnisse reichen nicht, wenn sie die vereinbarten Kundenanforderungen verfehlen."},"fa":{"title":"موفقیت و شکست","goal":"ریسک‌های معمول پروژه را می‌شناسی و برای کنترل آن‌ها اقدام مشخص پیشنهاد می‌دهی.","definition":"موفقیت پروژه یعنی تحقق هدف‌ها و انتظارهای توافق‌شده در چارچوب تعیین‌شده.","explanation":"نتیجهٔ پروژه باید با نیازهای توافق‌شده سازگار باشد؛ معمولاً کیفیت، زمان و هزینه مهم‌اند. این‌ها بر هم اثر دارند: قابلیت بیشتر ممکن است زمان یا پول بیشتری بخواهد. اول با سفارش‌دهنده روشن کن چه چیزی لازم است و تحویل با چه معیارهایی پذیرفته می‌شود. ریسک یک اتفاق احتمالی آینده با پیامد است؛ مشکلِ رخ‌داده نیاز به رسیدگی واقعی دارد. برای هر ریسک احتمال، اثر و اقدام مقابله بنویس. گفت‌وگوهای کوتاه منظم، انحراف از برنامه را زود نشان می‌دهند. تغییر باید ارزیابی و توافق شود، نه اینکه بی‌خبر وارد کار شود. تصمیم‌ها را طوری ثبت کن که دیگران وضعیت و دلیل‌ها را بفهمند.","example":"تیم VLAN 30 می‌سازد، مشتری فقط نقطه دسترسی تازه در شبکه موجود می‌خواست. بدون توافق فن هدر است.","remember":["Risiko: رویداد احتمالی آینده با اثر بر هدف‌ها.","Abnahme: بررسی و پذیرش نتیجهٔ توافق‌شده.","اگر نتیجه نیاز توافق‌شدهٔ مشتری را تأمین نکند، کارکرد فنی به‌تنهایی کافی نیست."],"summary":"نیاز روشن، هماهنگی پیوسته و تغییر کنترل‌شده، تکنیک را به فایدهٔ واقعی مشتری وصل می‌کنند.","sections":[],"terms":[["Risiko","رویداد احتمالی آینده با اثر بر هدف‌ها."],["Abnahme","بررسی و پذیرش نتیجهٔ توافق‌شده."],["Soll-Ist-Vergleich","مقایسهٔ برنامه با وضعیت واقعی."],["Änderungsantrag","درخواست ثبت‌شده برای تغییر نیازهای توافق‌شده."]],"q":"مشتری قابلیت اضافه می‌خواهد؛ چه کار مناسب است؟","options":["بدون بررسی قول بدهی","اثر بر زمان، هزینه و کیفیت را بررسی و توافق کنی","تغییر را پنهانی اجرا کنی"],"answer":1,"feedback":"تغییر بررسی‌شده و توافق‌شده، انتظار مشتری و برنامه را هماهنگ نگه می‌دارد.","mistake":"اگر نتیجه نیاز توافق‌شدهٔ مشتری را تأمین نکند، کارکرد فنی به‌تنهایی کافی نیست."},"minutes":9,"editorial":true,"source":["PMI · Project and lifecycle","https://www.pmi.org/about/what-is-a-project"]},"k10-projekt/phasen":{"de":{"title":"Phasen","goal":"Du beschreibst Initiierung, Planung, Umsetzung, Kontrolle und Abschluss eines Projekts.","definition":"Projektphasen ordnen die Arbeit von der Zielklärung bis zur Übergabe und Auswertung.","explanation":"Phasen gliedern ein Projekt in verständliche Abschnitte. In der Initiierung werden Problem, Ziel, Auftraggeber und grober Rahmen geklärt. Die Planung zerlegt das Vorhaben in Aufgaben, Verantwortlichkeiten, Termine, Kosten und Risiken. In der Umsetzung wird das vereinbarte Ergebnis erarbeitet. Steuerung und Kontrolle begleiten diese Arbeit: Tatsächliche Werte werden mit der Planung verglichen, Abweichungen bewertet und Maßnahmen vereinbart. Dokumentation läuft während aller Phasen mit. Beim Abschluss werden Ergebnis und Kriterien geprüft, die Übergabe organisiert und Erfahrungen festgehalten. Unterschiedliche Vorgehensmodelle nennen Phasen anders oder wiederholen Planung und Umsetzung in kurzen Zyklen. Entscheidend ist, dass Zielklärung, Nachverfolgung und geordneter Abschluss tatsächlich stattfinden.","example":"Vorbereitung: „Access Points in Gebäude B, Abnahme am 30. April.“ Planung: Liste der Räume und der Termine. Steuerung: jede Woche Soll gegen Ist.","remember":["Initiierung: Klärung von Anlass, Ziel und Auftrag.","Planung: Festlegung von Aufgaben, Mitteln und Terminen.","Steuerung und Dokumentation sind laufende Aufgaben und warten nicht bis zum letzten Projekttag."],"summary":"Zielklärung, Planung, Umsetzung und Abschluss bilden einen nachvollziehbaren Projektweg mit laufender Steuerung.","sections":[],"terms":[["Initiierung","Klärung von Anlass, Ziel und Auftrag."],["Planung","Festlegung von Aufgaben, Mitteln und Terminen."],["Steuerung","Maßnahmen zur Erreichung der Projektziele trotz Abweichungen."],["Projektabschluss","Geordnete Abnahme, Übergabe und Auswertung."]],"q":"Wann sollte dokumentiert werden?","options":["Nur am allerletzten Tag","Während aller Projektphasen","Nur wenn etwas scheitert"],"answer":1,"feedback":"Laufende Dokumentation hält Entscheidungen, Änderungen und Ergebnisse nachvollziehbar.","mistake":"Steuerung und Dokumentation sind laufende Aufgaben und warten nicht bis zum letzten Projekttag."},"fa":{"title":"مراحل","goal":"شروع، برنامه‌ریزی، اجرا، کنترل و پایان پروژه را توضیح می‌دهی.","definition":"مرحله‌های پروژه کار را از روشن‌کردن هدف تا تحویل و بررسی سازمان می‌دهند.","explanation":"مرحله‌ها پروژه را به بخش‌های قابل فهم تقسیم می‌کنند. در شروع، مشکل، هدف، سفارش‌دهنده و چارچوب کلی روشن می‌شوند. برنامه‌ریزی کار را به وظیفه، مسئول، زمان، هزینه و ریسک تقسیم می‌کند. در اجرا نتیجهٔ توافق‌شده ساخته می‌شود. کنترل در کنار کار ادامه دارد: مقدار واقعی با برنامه مقایسه، انحراف ارزیابی و اقدام اصلاحی توافق می‌شود. مستندسازی در همهٔ مرحله‌ها جریان دارد. در پایان، نتیجه با معیارها بررسی، تحویل سازمان‌دهی و تجربه‌ها ثبت می‌شوند. روش‌های مختلف ممکن است نام مرحله‌ها را متفاوت بگذارند یا برنامه‌ریزی و اجرا را در چرخه‌های کوتاه تکرار کنند. مهم این است که هدف روشن، پیگیری منظم و پایان مرتب واقعاً انجام شوند.","example":"آماده‌سازی: «نقطه دسترسی در ساختمان B، تحویل ۳۰ آوریل.» برنامه‌ریزی: فهرست اتاق و تاریخ. هدایت: هر هفته برنامه در برابر واقعی.","remember":["Initiierung: روشن‌کردن دلیل، هدف و سفارش.","Planung: تعیین کارها، منابع و زمان‌ها.","کنترل و مستندسازی کار پیوسته‌اند و نباید تا روز آخر عقب بیفتند."],"summary":"روشن‌کردن هدف، برنامه‌ریزی، اجرا و پایان، مسیر قابل پیگیری پروژه را با کنترل پیوسته می‌سازند.","sections":[],"terms":[["Initiierung","روشن‌کردن دلیل، هدف و سفارش."],["Planung","تعیین کارها، منابع و زمان‌ها."],["Steuerung","اقدام برای رسیدن به هدف با وجود انحراف از برنامه."],["Projektabschluss","پذیرش، تحویل و بررسی منظم پایان پروژه."]],"q":"چه زمانی باید مستندسازی انجام شود؟","options":["فقط روز آخر","در تمام مرحله‌های پروژه","فقط هنگام شکست"],"answer":1,"feedback":"مستندسازی پیوسته تصمیم‌ها، تغییرها و نتیجه‌ها را قابل پیگیری نگه می‌دارد.","mistake":"کنترل و مستندسازی کار پیوسته‌اند و نباید تا روز آخر عقب بیفتند."},"minutes":9,"editorial":true,"source":["PMI · Project and lifecycle","https://www.pmi.org/about/what-is-a-project"]},"k10-aeup/sprache":{"de":{"title":"Warum es Hochsprachen gibt","goal":"Du erklärst den Zweck einer Programmiersprache und den Weg von einer Aufgabe zu einem laufenden Python-Programm.","definition":"Nahe an der Maschine schreibst du, was der Prozessor tut. Eine Hochsprache beschreibt, was das Programm tun soll. Python ist so eine Sprache.","explanation":"Ein Computer braucht eindeutige Anweisungen. Zuerst beschreibst du das gewünschte Ergebnis: Ein Programm soll etwa aus Menge und Einzelpreis einen Gesamtpreis berechnen. Danach zerlegst du die Aufgabe in Eingabe, Verarbeitung und Ausgabe. In einer Hochsprache drückst du diese Schritte mit lesbaren Namen und Regeln aus. Der Quelltext wird in einer Datei gespeichert. Eine geeignete Laufzeitumgebung führt ihn aus. Ein Editor hilft beim Schreiben; der Python-Interpreter übernimmt die Ausführung. Der Prozessor verarbeitet am Ende Maschinenbefehle. Der Vorteil einer Hochsprache ist deshalb nicht, dass der Computer Deutsch versteht, sondern dass Menschen Programme verständlicher entwickeln und ändern können.","example":"print(\"Lager\") beschreibt die Ausgabe. Den dazu passenden Maschinencode erzeugt das Laufzeitsystem.","remember":["Quelltext: Für Menschen lesbarer Programmtext.","Hochsprache: Programmiersprache mit Abstraktionen oberhalb einzelner Maschinenbefehle.","Ein Editor ist ein Schreibwerkzeug; die Programmausführung braucht die passende Laufzeitumgebung."],"summary":"Hochsprachen machen Aufgaben als lesbaren Quelltext formulierbar; eine passende Laufzeitumgebung bringt ihn zur Ausführung.","sections":[],"terms":[["Quelltext","Für Menschen lesbarer Programmtext."],["Hochsprache","Programmiersprache mit Abstraktionen oberhalb einzelner Maschinenbefehle."],["Interpreter","Programm, das die Ausführung des Programmcodes organisiert."],["Editor","Werkzeug zum Schreiben und Bearbeiten von Quelltext."]],"q":"Welches Werkzeug führt eine Python-Datei aus?","options":["Nur die Tastatur","Der Python-Interpreter","Der Dateiname allein"],"answer":1,"feedback":"Der Editor speichert den Text; der Interpreter verarbeitet und führt ihn aus.","mistake":"Ein Editor ist ein Schreibwerkzeug; die Programmausführung braucht die passende Laufzeitumgebung."},"fa":{"title":"چرا زبان سطح بالا وجود دارد","goal":"هدف زبان برنامه‌نویسی و مسیر تبدیل مسئله به برنامهٔ Python را توضیح می‌دهی.","definition":"نزدیک ماشین می‌نویسی پردازنده چه می‌کند. زبان سطح بالا توصیف می‌کند برنامه چه باید بکند. پایتون چنین زبانی است.","explanation":"کامپیوتر به دستور دقیق نیاز دارد. ابتدا نتیجهٔ مورد نظر را مشخص کن: مثلاً برنامه باید از تعداد و قیمت واحد، قیمت کل را حساب کند. سپس مسئله را به ورودی، پردازش و خروجی تقسیم کن. در زبان سطح بالا این مرحله‌ها را با نام‌ها و دستورهای خوانا می‌نویسی. متن برنامه در فایل ذخیره می‌شود و محیط اجرای مناسب آن را اجرا می‌کند. ویرایشگر در نوشتن کمک می‌کند؛ Interpreter پایتون اجرای برنامه را بر عهده دارد. پردازنده در نهایت دستورهای ماشین را پردازش می‌کند. مزیت زبان سطح بالا این است که انسان برنامه را راحت‌تر می‌خواند، می‌سازد و اصلاح می‌کند.","example":"print(\"Lager\") خروجی را توصیف می‌کند. سامانه اجرا کد ماشین متناظر را می‌سازد.","remember":["Quelltext: متن قابل‌خواندن برنامه برای انسان.","Hochsprache: زبان دارای دستورهای سطح بالاتر از فرمان‌های مستقیم ماشین.","ویرایشگر ابزار نوشتن است؛ برای اجرای برنامه محیط اجرای مناسب لازم است."],"summary":"زبان سطح بالا مسئله را به کد خوانا تبدیل می‌کند و محیط اجرای مناسب آن را اجرا می‌کند.","sections":[],"terms":[["Quelltext","متن قابل‌خواندن برنامه برای انسان."],["Hochsprache","زبان دارای دستورهای سطح بالاتر از فرمان‌های مستقیم ماشین."],["Interpreter","برنامه‌ای که اجرای کد را انجام می‌دهد."],["Editor","ابزار نوشتن و ویرایش کد."]],"q":"کدام ابزار فایل Python را اجرا می‌کند؟","options":["فقط صفحه‌کلید","Interpreter پایتون","فقط نام فایل"],"answer":1,"feedback":"ویرایشگر متن را ذخیره می‌کند؛ Interpreter آن را پردازش و اجرا می‌کند.","mistake":"ویرایشگر ابزار نوشتن است؛ برای اجرای برنامه محیط اجرای مناسب لازم است."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/uebersetzung":{"de":{"title":"Übersetzen und Ausführen","goal":"Du unterscheidest Quelltext, Übersetzung und Ausführung und beschreibst den üblichen Ablauf in CPython.","definition":"Übersetzung wandelt Programmcode in eine andere Darstellung um. Ausführung setzt die beschriebenen Aktionen um.","explanation":"Übersetzen bedeutet, eine Darstellung von Code in eine andere umzuwandeln. Ausführen bedeutet, die beschriebenen Aktionen tatsächlich abzuarbeiten. Ein Compiler kann Quelltext in Maschinencode, Objektcode oder eine Zwischensprache übersetzen. Ein Interpreter verarbeitet Code zur Laufzeit. Die Kategorien können in einem System zusammenarbeiten. CPython übersetzt Python-Quelltext normalerweise zunächst in Bytecode. Seine virtuelle Maschine führt diesen anschließend aus. Bei einem Syntaxfehler kann die Übersetzung bereits scheitern. Bei einer Division durch null entsteht dagegen während der Ausführung eine Ausnahme. Für die Fehlersuche fragst du deshalb: War der Text überhaupt gültig, und an welcher Stelle trat das Problem beim Lauf auf?","example":"Eine fehlende Klammer kann einen Syntaxfehler auslösen. Ein Aufruf von prnit statt print ist dagegen syntaktisch möglich, führt ohne entsprechenden Namen aber beim Lauf zu einem NameError.","remember":["Compiler: Übersetzt Code in eine andere Code-Darstellung.","Bytecode: Zwischencode für eine virtuelle Maschine.","Compiler und Interpreter sind keine vollständig getrennten Welten: Ein System kann beide Ansätze verbinden."],"summary":"Übersetzung verändert die Code-Darstellung, Ausführung erledigt die Aktionen; CPython verbindet beide Schritte.","sections":[],"terms":[["Compiler","Übersetzt Code in eine andere Code-Darstellung."],["Bytecode","Zwischencode für eine virtuelle Maschine."],["Laufzeit","Phase, in der ein Programm ausgeführt wird."],["Virtuelle Maschine","Softwareumgebung, die einen definierten Zwischencode ausführt."]],"q":"Welche Beschreibung passt zu CPython?","options":["Quelltext wird gewöhnlich zu Bytecode und dann ausgeführt","Jede .py-Datei ist direkter CPU-Maschinencode","Python benötigt keine Laufzeitumgebung"],"answer":0,"feedback":"Übersetzung und Interpretation sind bei CPython Teil desselben Ablaufs.","mistake":"Compiler und Interpreter sind keine vollständig getrennten Welten: Ein System kann beide Ansätze verbinden."},"fa":{"title":"ترجمه و اجرا","goal":"متن کد، ترجمه و اجرا را تشخیص می‌دهی و مسیر معمول اجرای CPython را می‌فهمی.","definition":"ترجمه کد را به نمایش دیگر تبدیل می‌کند و اجرا دستورهای آن را انجام می‌دهد.","explanation":"ترجمه یعنی تبدیل یک شکل از کد به شکل دیگر. اجرا یعنی انجام واقعی دستورهایی که کد بیان می‌کند. Compiler ممکن است متن برنامه را به کد ماشین، کد شیء یا زبان میانی تبدیل کند. Interpreter هنگام اجرا کد را پردازش می‌کند. این دو روش می‌توانند در یک سیستم کنار هم باشند. CPython معمولاً ابتدا متن Python را به Bytecode تبدیل می‌کند؛ سپس ماشین مجازی آن Bytecode را اجرا می‌کند. خطای نحوی ممکن است در مرحلهٔ ترجمه جلوی کار را بگیرد. تقسیم بر صفر، در مقابل، هنگام اجرای دستور رخ می‌دهد. برای عیب‌یابی بپرس: آیا متن برنامه معتبر است و مشکل هنگام اجرای کدام دستور رخ داده است؟","example":"نبودن پرانتز می‌تواند خطای نحوی بدهد. نوشتن prnit به‌جای print از نظر شکل ممکن است معتبر باشد، ولی اگر چنین نامی تعریف نشده باشد هنگام اجرا NameError می‌دهد.","remember":["Compiler: کد را به نمایش دیگری ترجمه می‌کند.","Bytecode: کد میانی برای ماشین مجازی.","Compiler و Interpreter همیشه دو دنیای کاملاً جدا نیستند؛ یک سیستم می‌تواند هر دو روش را ترکیب کند."],"summary":"ترجمه شکل کد را تغییر می‌دهد و اجرا دستورها را انجام می‌دهد؛ CPython هر دو مرحله را ترکیب می‌کند.","sections":[],"terms":[["Compiler","کد را به نمایش دیگری ترجمه می‌کند."],["Bytecode","کد میانی برای ماشین مجازی."],["Laufzeit","زمانی که برنامه در حال اجراست."],["Virtuelle Maschine","محیط نرم‌افزاری برای اجرای کد میانی مشخص."]],"q":"کدام توضیح برای CPython درست است؟","options":["کد معمولاً به Bytecode تبدیل و سپس اجرا می‌شود","هر فایل .py کد مستقیم پردازنده است","Python به محیط اجرا نیاز ندارد"],"answer":0,"feedback":"در CPython، ترجمه و تفسیر بخش‌های یک مسیر اجرا هستند.","mistake":"Compiler و Interpreter همیشه دو دنیای کاملاً جدا نیستند؛ یک سیستم می‌تواند هر دو روش را ترکیب کند."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/variablen":{"de":{"title":"Name, Typ, Wert","goal":"Du liest eine Zuweisung und erklärst, wie ein Name auf einen Wert verweist.","definition":"Eine Variable ist in Python ein Name, der an ein Objekt gebunden wird. Das Objekt hat einen Typ und einen Wert.","explanation":"In menge = 4 steht links der Name und rechts der Wert. Python bindet den Namen menge an das Objekt mit dem Wert 4. Bei gesamt = menge * 3 wird zuerst der rechte Ausdruck berechnet: 4 mal 3 ergibt 12. Danach wird gesamt an diesen Wert gebunden. Ein späteres menge = 5 verändert gesamt nicht rückwirkend; die Rechnung wird nicht automatisch erneut ausgeführt. Python-Namen besitzen keinen dauerhaft festgeschriebenen Datentyp. Entscheidend ist der Typ des jeweils referenzierten Objekts. Wähle Namen, die eine Bedeutung vermitteln, und verfolge bei Aufgaben die Werte nach jeder Zeile. Eine kleine Wertetabelle verhindert, dass du alte und neue Werte verwechselst.","example":"menge = 12 bindet den Namen menge an einen Integer-Wert. menge = \"12\" bindet ihn anschließend an eine Zeichenkette. Die Objekte besitzen verschiedene Typen.","remember":["Zuweisung: Bindet einen Namen an den Wert eines Ausdrucks.","Ausdruck: Code, der einen Wert ergibt.","Eine spätere Änderung von x berechnet ein früher aus x ermitteltes y nicht automatisch neu."],"summary":"Python bindet Namen an Objekte; bei einer Zuweisung wird zuerst der rechte Ausdruck ausgewertet.","sections":[],"terms":[["Zuweisung","Bindet einen Namen an den Wert eines Ausdrucks."],["Ausdruck","Code, der einen Wert ergibt."],["Bezeichner","Name für eine Variable oder ein anderes Programmelement."],["Objekt","Wert mit Identität und Datentyp im Python-Speicher."]],"q":"x = 2; y = x + 3; x = 7. Welchen Wert hat y?","options":["10","7","5"],"answer":2,"feedback":"y wurde beim zweiten Schritt als 5 berechnet. Eine neue Zuweisung an x berechnet y nicht erneut.","mistake":"Eine spätere Änderung von x berechnet ein früher aus x ermitteltes y nicht automatisch neu."},"fa":{"title":"نام، نوع، مقدار","goal":"یک انتساب را می‌خوانی و می‌فهمی نام چگونه به یک مقدار اشاره می‌کند.","definition":"متغیر در Python نامی متصل به یک شیء است؛ شیء نوع و مقدار دارد.","explanation":"در menge = 4 سمت چپ نام و سمت راست مقدار است. Python نام menge را به شیء دارای مقدار ۴ متصل می‌کند. در gesamt = menge * 3 ابتدا عبارت سمت راست حساب می‌شود: چهار ضرب سه برابر ۱۲؛ سپس gesamt به این مقدار وصل می‌شود. اگر بعداً menge = 5 بنویسی، مقدار gesamt خودکار تغییر نمی‌کند؛ محاسبه دوباره اجرا نشده است. نام‌ها در Python نوع ثابت همیشگی ندارند؛ نوع شیئی مهم است که اکنون به آن اشاره می‌کنند. نام معنادار انتخاب کن و در تمرین‌ها مقدار هر متغیر را پس از هر خط بنویس. جدول مقدارها کمک می‌کند مقدار قدیمی و جدید را اشتباه نگیری.","example":"menge = 12 نام را به عدد صحیح وصل می‌کند. سپس menge = \"12\" آن را به رشتهٔ متن وصل می‌کند؛ این شیءها نوع متفاوت دارند.","remember":["Zuweisung: نام را به مقدار یک عبارت متصل می‌کند.","Ausdruck: بخشی از کد که نتیجهٔ آن یک مقدار است.","تغییر بعدی x، مقدار y را که قبلاً از x حساب شده خودکار دوباره محاسبه نمی‌کند."],"summary":"Python نام را به شیء متصل می‌کند؛ در انتساب ابتدا عبارت سمت راست محاسبه می‌شود.","sections":[],"terms":[["Zuweisung","نام را به مقدار یک عبارت متصل می‌کند."],["Ausdruck","بخشی از کد که نتیجهٔ آن یک مقدار است."],["Bezeichner","نام یک متغیر یا بخش دیگر برنامه."],["Objekt","مقدار دارای هویت و نوع در حافظهٔ Python."]],"q":"پس از x = 2 و y = x + 3 و x = 7، مقدار y چیست؟","options":["۱۰","۷","۵"],"answer":2,"feedback":"در مرحلهٔ دوم y برابر ۵ محاسبه شده است؛ تغییر x باعث محاسبهٔ دوبارهٔ y نمی‌شود.","mistake":"تغییر بعدی x، مقدار y را که قبلاً از x حساب شده خودکار دوباره محاسبه نمی‌کند."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/datentypen":{"de":{"title":"int, float, str, bool","goal":"Du wählst int, float, str und bool passend aus und führst einfache Typumwandlungen aus.","definition":"int ist eine ganze Zahl, float eine Kommazahl, str ein Text, bool ein Wahrheitswert wahr oder falsch.","explanation":"int stellt ganze Zahlen dar, beispielsweise eine Anzahl von Geräten. float beschreibt Gleitkommazahlen, zum Beispiel einen Messwert; manche Dezimalwerte sind dabei nur näherungsweise darstellbar. str speichert Zeichenketten wie Namen oder Artikelnummern. bool besitzt die Werte True und False und wird für Bedingungen verwendet. Eingaben mit input() kommen zunächst als str an. Soll damit gerechnet werden, prüfst und wandelst du die Eingabe um: int(\"12\") ergibt die Zahl 12. Eine Artikelnummer wie \"0012\" soll dagegen oft Text bleiben, damit führende Nullen erhalten bleiben. Der passende Typ richtet sich nach der Bedeutung und den benötigten Operationen, nicht nur danach, wie die Eingabe aussieht.","example":"bestand = 5 ist int. preis = 1.5 ist float. name = \"Schraube\" ist str. lieferbar = True ist bool.","remember":["int: Datentyp für ganze Zahlen.","float: Datentyp für Gleitkommazahlen mit begrenzter Genauigkeit.","\"12\" ist Text. Dass die Zeichen Ziffern sind, macht den Wert noch nicht zu einer Zahl."],"summary":"Der Datentyp bestimmt, welche Bedeutung ein Wert hat und welche Operationen sinnvoll sind.","sections":[],"terms":[["int","Datentyp für ganze Zahlen."],["float","Datentyp für Gleitkommazahlen mit begrenzter Genauigkeit."],["str","Datentyp für Zeichenketten."],["bool","Datentyp mit True oder False."],["Typumwandlung","Ausdrückliche Umwandlung eines Wertes in einen anderen Typ."]],"q":"Welchen Typ liefert input() zunächst?","options":["str","int","bool"],"answer":0,"feedback":"Auch eingegebene Ziffern sind zunächst Text und müssen für Zahlenrechnungen passend umgewandelt werden.","mistake":"\"12\" ist Text. Dass die Zeichen Ziffern sind, macht den Wert noch nicht zu einer Zahl."},"fa":{"title":"int، float، str، bool","goal":"نوع‌های int، float، str و bool را مناسب انتخاب می‌کنی و تبدیل نوع ساده انجام می‌دهی.","definition":"int عدد صحیح است، float عدد اعشاری، str متن، bool مقدار درست یا نادرست.","explanation":"int برای عدد صحیح است؛ مثلاً تعداد دستگاه‌ها. float برای عدد ممیزشناور است؛ مثلاً یک مقدار اندازه‌گیری، اما بعضی اعداد ده‌دهی را فقط تقریبی نمایش می‌دهد. str رشتهٔ متن مثل نام یا شمارهٔ کالا را نگه می‌دارد. bool دو مقدار True و False دارد و برای شرط‌ها به کار می‌رود. خروجی input() در ابتدا str است. اگر بخواهی با ورودی حساب کنی، باید آن را بررسی و تبدیل کنی: int(\"12\") عدد ۱۲ می‌دهد. ولی شمارهٔ کالایی مثل \"0012\" معمولاً باید متن بماند تا صفرهای اول حذف نشود. نوع مناسب را بر اساس معنای داده و عملیاتی که لازم داری انتخاب کن، نه فقط ظاهر آن.","example":"bestand = 5 از نوع int است. preis = 1.5 از نوع float. name = \"Schraube\" از نوع str. lieferbar = True از نوع bool.","remember":["int: نوع عددهای صحیح.","float: نوع عدد ممیزشناور با دقت محدود.","\"12\" متن است؛ رقمی‌بودن کاراکترها خودکار آن را عدد نمی‌کند."],"summary":"نوع داده مشخص می‌کند مقدار چه معنایی دارد و چه عملیاتی برای آن مناسب است.","sections":[],"terms":[["int","نوع عددهای صحیح."],["float","نوع عدد ممیزشناور با دقت محدود."],["str","نوع رشتهٔ متن."],["bool","نوع دارای مقدار True یا False."],["Typumwandlung","تبدیل صریح مقدار به نوع دیگر."]],"q":"دستور input() ابتدا چه نوعی می‌دهد؟","options":["str","int","bool"],"answer":0,"feedback":"حتی رقم‌های واردشده ابتدا متن‌اند و برای محاسبه باید به نوع عدد مناسب تبدیل شوند.","mistake":"\"12\" متن است؛ رقمی‌بودن کاراکترها خودکار آن را عدد نمی‌کند."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/fehler":{"de":{"title":"Drei Arten von Fehlern","goal":"Du ordnest Syntax-, Laufzeit- und Logikfehler ein und wählst einen sinnvollen Prüfweg.","definition":"Ein Syntaxfehler ist ungültige Schreibweise. Ein Laufzeitfehler bricht während der Ausführung ab. Ein Logikfehler läuft durch und liefert das falsche Ergebnis.","explanation":"Bei einem Fehler liest du zuerst die Meldung und die betroffene Zeile. Syntaxfehler verhindern, dass ein Programmabschnitt überhaupt gültig verarbeitet werden kann, zum Beispiel ein fehlender Doppelpunkt nach if. Laufzeitfehler entstehen erst beim Ausführen eines gültigen Ausdrucks, etwa int(\"abc\") oder die Division durch null. Logikfehler liefern ein falsches Ergebnis, obwohl kein Abbruch erfolgt. Berechnet ein Programm 10 Prozent Rabatt durch preis * 0.1 als Endpreis, ist die Formel falsch: Das Ergebnis ist nur der Rabattbetrag. Für einen Test legst du deshalb zuerst eine kleine Eingabe und das erwartete Resultat fest. Danach vergleichst du den tatsächlichen Wert und prüfst Zwischenergebnisse.","example":"gesamt = netto + steuer ist richtig gedacht. gesamt = netto - steuer läuft auch, ist aber logisch falsch, wenn die Steuer hinzukommen soll.","remember":["Syntaxfehler: Verstoß gegen die Schreibregeln der Sprache.","Laufzeitfehler: Fehler bei der Ausführung eines Programms.","Ein Programm ohne Fehlermeldung kann trotzdem logisch falsche Ergebnisse liefern."],"summary":"Syntax, Laufzeit und Logik sind unterschiedliche Fehlerquellen und brauchen passende Prüfungen.","sections":[],"terms":[["Syntaxfehler","Verstoß gegen die Schreibregeln der Sprache."],["Laufzeitfehler","Fehler bei der Ausführung eines Programms."],["Logikfehler","Programmablauf oder Rechnung mit falschem Ergebnis."],["Testfall","Festgelegte Eingabe mit erwartetem Ergebnis."]],"q":"Eine Rechnung läuft ohne Abbruch, liefert aber den falschen Rabatt. Was ist das?","options":["Syntaxfehler","Logikfehler","Fehlendes Programm"],"answer":1,"feedback":"Das Programm ist ausführbar. Der gewählte Rechenweg passt aber nicht zum gewünschten Ergebnis.","mistake":"Ein Programm ohne Fehlermeldung kann trotzdem logisch falsche Ergebnisse liefern."},"fa":{"title":"سه نوع خطا","goal":"خطای نحوی، هنگام اجرا و منطقی را از هم جدا می‌کنی و روش بررسی مناسب انتخاب می‌کنی.","definition":"خطای نحو نوشتن نامعتبر است. خطای زمان اجرا هنگام اجرا قطع می‌کند. خطای منطق تا آخر می‌رود و نتیجه غلط می‌دهد.","explanation":"اول پیام خطا و خط مربوط را بخوان. خطای نحوی یعنی ساختار کد معتبر نیست؛ مثلاً پس از if دونقطه فراموش شده است. خطای هنگام اجرا در زمان اجرای یک عبارت ظاهراً معتبر رخ می‌دهد؛ مثل int(\"abc\") یا تقسیم بر صفر. خطای منطقی برنامه را متوقف نمی‌کند، ولی نتیجه اشتباه می‌شود. اگر برای قیمت پس از تخفیف ۱۰ درصدی از preis * 0.1 استفاده کنی، فقط مبلغ تخفیف را حساب کرده‌ای، نه قیمت نهایی. پس پیش از آزمایش یک ورودی کوچک و نتیجهٔ مورد انتظار را مشخص کن؛ سپس خروجی واقعی و مقدارهای میانی را مقایسه کن. این کار کمک می‌کند محل اشتباه را پیدا کنی.","example":"gesamt = netto + steuer فکر درست است. gesamt = netto - steuer هم اجرا می‌شود، ولی اگر مالیات باید اضافه شود منطقاً غلط است.","remember":["Syntaxfehler: نقض قواعد نوشتاری زبان.","Laufzeitfehler: خطا هنگام اجرای برنامه.","برنامه بدون پیام خطا هم ممکن است نتیجهٔ منطقی نادرست بدهد."],"summary":"نحو، زمان اجرا و منطق منشأهای متفاوت خطا هستند و بررسی مناسب می‌خواهند.","sections":[],"terms":[["Syntaxfehler","نقض قواعد نوشتاری زبان."],["Laufzeitfehler","خطا هنگام اجرای برنامه."],["Logikfehler","اشتباه در منطق یا محاسبه که خروجی نادرست می‌دهد."],["Testfall","ورودی مشخص همراه نتیجهٔ مورد انتظار."]],"q":"محاسبه بدون توقف انجام می‌شود، ولی تخفیف اشتباه است؛ چه خطایی است؟","options":["خطای نحوی","خطای منطقی","نبودن برنامه"],"answer":1,"feedback":"برنامه قابل اجراست، ولی روش محاسبه با نتیجهٔ مورد نظر سازگار نیست.","mistake":"برنامه بدون پیام خطا هم ممکن است نتیجهٔ منطقی نادرست بدهد."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/verzweigung":{"de":{"title":"if und elif","goal":"Du verfolgst if, elif und else und erklärst, welcher Block bei einer Eingabe läuft.","definition":"Eine Verzweigung führt einen Block nur aus, wenn eine Bedingung wahr ist. elif prüft die nächste Bedingung, else den Rest.","explanation":"Mit if prüfst du eine Bedingung. Ist sie wahr, führt Python den eingerückten Block aus. Ein anschließendes elif wird nur geprüft, wenn alle vorherigen Bedingungen dieser Kette falsch waren. else fängt alle übrigen Fälle auf und benötigt keine eigene Bedingung. Die Reihenfolge ist wichtig: Prüfst du zuerst punkte >= 50, erreicht ein Wert von 90 bereits diesen Zweig; ein späteres elif punkte >= 80 wird dann übersprungen. Prüfe deshalb bei abgestuften Grenzen zuerst die passende strengere Grenze oder formuliere eindeutige Intervalle. == vergleicht zwei Werte; = weist einen Wert zu. Teste auch die Grenzwerte selbst, zum Beispiel 49, 50, 79 und 80 Punkte.","example":"Wenn der Bestand unter 5 liegt, wird nachbestellt, sonst nicht. Die Raute trägt „Bestand < 5“, die Zweige „ja“ und „nein“.","remember":["Bedingung: Ausdruck, dessen Wahrheitswert geprüft wird.","if: Startet eine bedingte Verzweigung.","Mehrere einzelne if-Anweisungen sind nicht dasselbe wie eine gemeinsame if-elif-else-Kette."],"summary":"Eine if-elif-else-Kette prüft Bedingungen der Reihe nach und führt höchstens einen passenden Zweig aus.","sections":[],"terms":[["Bedingung","Ausdruck, dessen Wahrheitswert geprüft wird."],["if","Startet eine bedingte Verzweigung."],["elif","Weitere Prüfung innerhalb derselben Entscheidungskette."],["else","Zweig für alle verbleibenden Fälle."],["Einrückung","Kennzeichnet zusammengehörige Python-Anweisungsblöcke."]],"q":"Wie viele Zweige einer if-elif-else-Kette werden bei einem Durchlauf ausgeführt?","options":["Alle wahren Zweige","Höchstens einer","Immer genau drei"],"answer":1,"feedback":"Nach dem ersten passenden Zweig ist diese Entscheidungskette erledigt.","mistake":"Mehrere einzelne if-Anweisungen sind nicht dasselbe wie eine gemeinsame if-elif-else-Kette."},"fa":{"title":"if و elif","goal":"مسیر if، elif و else را دنبال می‌کنی و می‌فهمی برای یک ورودی کدام بخش اجرا می‌شود.","definition":"یک شاخه یک بلوک را فقط وقتی اجرا می‌کند که شرط درست باشد. elif شرط بعدی را می‌سنجد، else بقیه را.","explanation":"if یک شرط را بررسی می‌کند. اگر درست باشد، بخش دارای تورفتگی اجرا می‌شود. elif فقط زمانی بررسی می‌شود که شرط‌های قبلی همین زنجیره نادرست بوده باشند. else همهٔ حالت‌های باقی‌مانده را می‌گیرد و شرط جداگانه ندارد. ترتیب مهم است: اگر ابتدا punkte >= 50 را بررسی کنی، عدد ۹۰ نیز وارد همین شاخه می‌شود و elif بعدی با شرط punkte >= 80 اجرا نخواهد شد. پس در محدوده‌های پله‌ای، شرط سخت‌تر را اول بررسی کن یا بازه‌ها را واضح بنویس. == دو مقدار را مقایسه می‌کند؛ = مقدار را نسبت می‌دهد. مرزها را هم آزمایش کن؛ مثلاً ۴۹، ۵۰، ۷۹ و ۸۰ امتیاز.","example":"اگر موجودی زیر ۵ باشد سفارش مجدد می‌شود، وگرنه نه. لوزی می‌گوید «موجودی < ۵»، شاخه‌ها «بله» و «خیر».","remember":["Bedingung: عبارتی که درست یا نادرست بودنش بررسی می‌شود.","if: شروع یک شاخهٔ شرطی.","چند if مستقل با یک زنجیرهٔ if-elif-else یکسان نیستند."],"summary":"زنجیرهٔ if-elif-else شرط‌ها را به ترتیب بررسی می‌کند و حداکثر یک شاخهٔ مناسب را اجرا می‌کند.","sections":[],"terms":[["Bedingung","عبارتی که درست یا نادرست بودنش بررسی می‌شود."],["if","شروع یک شاخهٔ شرطی."],["elif","شرط بعدی در همان زنجیره."],["else","شاخهٔ حالت‌های باقی‌مانده."],["Einrückung","تورفتگی برای مشخص‌کردن بلوک دستورها."]],"q":"در یک بار عبور از زنجیرهٔ if-elif-else چند شاخه اجرا می‌شود؟","options":["همهٔ شاخه‌های درست","حداکثر یکی","همیشه سه شاخه"],"answer":1,"feedback":"پس از اولین شاخهٔ مناسب، بررسی همین زنجیره تمام می‌شود.","mistake":"چند if مستقل با یک زنجیرهٔ if-elif-else یکسان نیستند."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/schleifen":{"de":{"title":"for und while","goal":"Du wählst for oder while aus und prüfst Abbruchbedingung und Anzahl der Wiederholungen.","definition":"Eine Schleife wiederholt einen Block. for geht eine bekannte Folge durch. while wiederholt, solange eine Bedingung wahr ist.","explanation":"Eine for-Schleife verarbeitet nacheinander die Elemente einer Folge. for geraet in geraete führt den Block einmal für jedes vorhandene Gerät aus. range(3) liefert dabei die Werte 0, 1 und 2; die obere Grenze 3 gehört nicht dazu. Eine while-Schleife prüft vor jeder Wiederholung ihre Bedingung. Solange diese wahr ist, läuft der Block erneut. Der Schleifenkörper muss einen sinnvollen Weg zum Ende ermöglichen, etwa indem ein Zähler steigt oder eine neue Benutzereingabe gelesen wird. Die Bedingung muss sich nicht zwingend in jeder Runde ändern; entscheidend ist, dass der Ablauf den vorgesehenen Abschluss erreichen kann. Schreibe beim Nachvollziehen die Werte nach jeder Runde auf.","example":"for artikel in lager: print(artikel) verarbeitet jeden Eintrag. Bei while menge > 0: kann zum Beispiel menge -= 1 einen Zähler bis zur Abbruchgrenze verändern.","remember":["for-Schleife: Verarbeitet Elemente eines iterierbaren Objekts.","while-Schleife: Wiederholt einen Block, solange die Bedingung wahr ist.","range(3) enthält drei Werte: 0, 1 und 2. Die obere Grenze 3 gehört nicht dazu."],"summary":"for verarbeitet Elemente einer Folge, while wiederholt abhängig von einer Bedingung.","sections":[],"terms":[["for-Schleife","Verarbeitet Elemente eines iterierbaren Objekts."],["while-Schleife","Wiederholt einen Block, solange die Bedingung wahr ist."],["range","Liefert eine Zahlenfolge mit ausgeschlossener oberer Grenze."],["Abbruchbedingung","Legt fest, wann eine Wiederholung beendet werden kann."]],"q":"Wie oft läuft for i in range(3)?","options":["Dreimal","Viermal","Einmal"],"answer":0,"feedback":"Die Werte sind 0, 1 und 2. Das sind drei Durchläufe.","mistake":"range(3) enthält drei Werte: 0, 1 und 2. Die obere Grenze 3 gehört nicht dazu."},"fa":{"title":"for و while","goal":"for یا while را مناسب انتخاب می‌کنی و شرط توقف و تعداد تکرارها را بررسی می‌کنی.","definition":"حلقه یک بلوک را تکرار می‌کند. for یک دنباله معلوم را می‌پیماید. while تا وقتی شرط درست است تکرار می‌کند.","explanation":"حلقهٔ for عنصرهای یک دنباله را یکی‌یکی پردازش می‌کند. عبارت for geraet in geraete بخش کد را برای هر دستگاه موجود یک بار اجرا می‌کند. range(3) مقدارهای ۰، ۱ و ۲ را می‌دهد؛ حد بالای ۳ جزو آن نیست. حلقهٔ while پیش از هر دور شرط را بررسی می‌کند و تا زمانی که درست باشد تکرار می‌شود. بدنه باید راه معقولی برای پایان داشته باشد؛ مثلاً شمارنده زیاد شود یا ورودی تازه خوانده شود. لازم نیست شرط در هر دور حتماً تغییر کند؛ مهم این است که برنامه بتواند به پایان مورد نظر برسد. برای فهم حلقه، مقدارها را پس از هر دور بنویس و با تعداد تکرار مورد انتظار مقایسه کن.","example":"for artikel in lager: print(artikel) هر عنصر را پردازش می‌کند. در while menge > 0: مثلاً menge -= 1 شمارنده را به سمت شرط پایان تغییر می‌دهد.","remember":["for-Schleife: حلقه برای پردازش عنصرهای یک مجموعهٔ قابل پیمایش.","while-Schleife: تا درست‌بودن شرط، بخش کد را تکرار می‌کند.","range(3) سه مقدار ۰، ۱ و ۲ دارد؛ عدد ۳ شامل نمی‌شود."],"summary":"for عنصرهای دنباله را پردازش می‌کند و while بر اساس یک شرط تکرار می‌شود.","sections":[],"terms":[["for-Schleife","حلقه برای پردازش عنصرهای یک مجموعهٔ قابل پیمایش."],["while-Schleife","تا درست‌بودن شرط، بخش کد را تکرار می‌کند."],["range","دنبالهٔ عددی که حد بالای آن شامل نمی‌شود."],["Abbruchbedingung","شرطی که زمان پایان تکرار را مشخص می‌کند."]],"q":"حلقهٔ for i in range(3) چند بار اجرا می‌شود؟","options":["سه بار","چهار بار","یک بار"],"answer":0,"feedback":"مقدارها ۰، ۱ و ۲ هستند؛ پس سه دور اجرا می‌شود.","mistake":"range(3) سه مقدار ۰، ۱ و ۲ دارد؛ عدد ۳ شامل نمی‌شود."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-aeup/listen":{"de":{"title":"Listen","goal":"Du liest Listenindizes, änderst Einträge und unterscheidest Länge von letztem Index.","definition":"Eine Liste speichert mehrere Werte in einer festen Reihenfolge. Der erste Index ist 0. Du kannst Werte anhängen oder ersetzen.","explanation":"Eine Liste ist ein geordnetes, veränderbares Python-Objekt. namen = [\"Ali\", \"Sara\", \"Lea\"] enthält drei Elemente. Über namen[0] erhältst du \"Ali\", weil die Zählung bei null beginnt. Mit namen[1] = \"Mina\" ersetzt du den zweiten Eintrag, ohne die anderen zu verändern. namen.append(\"Tom\") fügt einen neuen Eintrag am Ende hinzu. len(namen) liefert danach 4; der letzte positive Index ist aber 3. Beim Durchlaufen mit for name in namen erhältst du direkt jeden gespeicherten Wert. Listen dürfen in Python unterschiedliche Typen enthalten. Für übersichtliche Programme ist es oft sinnvoll, eine Liste für eine einheitliche Art von Daten zu verwenden, etwa Gerätenamen.","example":"Drei Artikel: Index 0, 1 und 2. Der dritte Artikel ist Index 2, nicht Index 3.","remember":["Liste: Geordnete, veränderbare Sammlung von Elementen.","Index: Position eines Elements; beginnt bei 0.","Bei fünf Elementen ist der letzte positive Index 4. len liefert dagegen 5."],"summary":"Listen speichern geordnete, veränderbare Elemente; Indizes beginnen bei null, die Länge zählt alle Elemente.","sections":[],"terms":[["Liste","Geordnete, veränderbare Sammlung von Elementen."],["Index","Position eines Elements; beginnt bei 0."],["append","Fügt ein Element am Listenende an."],["len","Ermittelt die Anzahl der Elemente."]],"q":"Eine Liste enthält fünf Elemente. Welcher ist der letzte positive Index?","options":["5","4","6"],"answer":1,"feedback":"Die Indizes sind 0, 1, 2, 3 und 4. Länge und letzter Index unterscheiden sich um eins.","mistake":"Bei fünf Elementen ist der letzte positive Index 4. len liefert dagegen 5."},"fa":{"title":"فهرست","goal":"اندیس فهرست را می‌خوانی، عنصرها را تغییر می‌دهی و طول را از آخرین اندیس جدا می‌کنی.","definition":"یک فهرست چند مقدار را به ترتیب ثابت ذخیره می‌کند. اولین نمایه ۰ است. می‌توانی مقدار اضافه یا عوض کنی.","explanation":"List در Python یک شیء مرتب و قابل تغییر است. فهرست namen = [\"Ali\", \"Sara\", \"Lea\"] سه عنصر دارد. namen[0] مقدار Ali را می‌دهد، چون شمارش از صفر شروع می‌شود. با namen[1] = \"Mina\" عنصر دوم را عوض می‌کنی و بقیه ثابت می‌مانند. namen.append(\"Tom\") عنصر تازه را به انتها اضافه می‌کند. سپس len(namen) برابر ۴ است، ولی آخرین اندیس مثبت ۳ است. با for name in namen مستقیماً مقدار هر عنصر را می‌گیری. فهرست Python می‌تواند نوع‌های متفاوت داشته باشد، ولی برای خوانایی معمولاً بهتر است یک فهرست برای یک نوع دادهٔ مشخص مثل نام دستگاه‌ها استفاده شود.","example":"سه قلم: نمایه ۰، ۱ و ۲. قلم سوم نمایه ۲ است، نه نمایه ۳.","remember":["Liste: مجموعهٔ مرتب و قابل تغییر عنصرها.","Index: جایگاه عنصر که از صفر شروع می‌شود.","برای پنج عنصر، آخرین اندیس مثبت ۴ است، ولی len مقدار ۵ می‌دهد."],"summary":"فهرست عنصرهای مرتب و قابل تغییر نگه می‌دارد؛ اندیس از صفر شروع می‌شود و طول تعداد کل عنصرهاست.","sections":[],"terms":[["Liste","مجموعهٔ مرتب و قابل تغییر عنصرها."],["Index","جایگاه عنصر که از صفر شروع می‌شود."],["append","یک عنصر را به انتهای فهرست اضافه می‌کند."],["len","تعداد عنصرها را می‌دهد."]],"q":"فهرست پنج عنصر دارد؛ آخرین اندیس مثبت کدام است؟","options":["۵","۴","۶"],"answer":1,"feedback":"اندیس‌ها ۰، ۱، ۲، ۳ و ۴ هستند؛ طول و آخرین اندیس یک واحد تفاوت دارند.","mistake":"برای پنج عنصر، آخرین اندیس مثبت ۴ است، ولی len مقدار ۵ می‌دهد."},"minutes":9,"editorial":true,"source":["Python · Tutorial","https://docs.python.org/3/tutorial/"]},"k10-pug/motive":{"de":{"title":"Warum ausgebildet wird","goal":"Du erklärst den Nutzen einer geregelten Berufsausbildung aus Sicht von Auszubildenden, Betrieb und Gesellschaft.","definition":"Ausbildung sichert dem Betrieb Fachkräfte und der lernenden Person einen anerkannten Beruf. Arbeit ist dabei mehr als Beschäftigung.","explanation":"Für Auszubildende verbindet Ausbildung berufliches Können mit einem anerkannten Abschluss und einer Vergütung. Sie lernen, Aufgaben zunehmend selbstständig und verantwortungsvoll zu bearbeiten. Ein Betrieb gewinnt die Möglichkeit, Fachkräfte nach einem verbindlichen Berufsbild zu entwickeln und Wissen weiterzugeben. Dafür muss er Zeit, Betreuung und geeignete Lernaufgaben bereitstellen; Auszubildende sind nicht nur günstige Arbeitskräfte. Die Gesellschaft profitiert von beruflichen Qualifikationen und vergleichbaren Standards. Die Ausbildungsordnung beschreibt den betrieblichen Rahmen, der schulische Lehrplan ergänzt fachliche und allgemeine Bildung. Wenn du einen Nutzen erklärst, nenne jeweils die Perspektive und ein konkretes Beispiel. Derselbe Vorgang kann für die Beteiligten unterschiedliche Vorteile und Pflichten mit sich bringen.","example":"Ein Betrieb bildet Fachinformatiker aus, weil er später Systemintegration braucht. Der Abschluss gilt auch in einem anderen Betrieb.","remember":["Auszubildende: Person, die einen anerkannten Ausbildungsberuf erlernt.","Ausbildender Betrieb: Vertragspartner, der die Ausbildung organisiert.","Ausbildung soll berufliches Können entwickeln; reine dauerhafte Hilfsarbeit erfüllt dieses Ziel nicht."],"summary":"Ausbildung entwickelt berufliche Fähigkeiten und verbindet die Interessen von Lernenden, Betrieben und Gesellschaft.","sections":[],"terms":[["Auszubildende","Person, die einen anerkannten Ausbildungsberuf erlernt."],["Ausbildender Betrieb","Vertragspartner, der die Ausbildung organisiert."],["Ausbildungsordnung","Bundesrechtlicher Rahmen für einen Ausbildungsberuf."],["Berufliche Handlungsfähigkeit","Fähigkeit, berufliche Aufgaben fachgerecht und verantwortlich zu bewältigen."]],"q":"Welches Ziel passt besonders zur Berufsausbildung?","options":["Dauerhaft nur Hilfsarbeiten erledigen","Berufliche Handlungsfähigkeit erwerben","Schulunterricht grundsätzlich vermeiden"],"answer":1,"feedback":"Ausbildung soll zur fachgerechten, zunehmend selbstständigen Berufsausübung befähigen.","mistake":"Ausbildung soll berufliches Können entwickeln; reine dauerhafte Hilfsarbeit erfüllt dieses Ziel nicht."},"fa":{"title":"چرا آموزش داده می‌شود","goal":"فایدهٔ آموزش حرفه‌ای را از دید کارآموز، شرکت و جامعه توضیح می‌دهی.","definition":"آموزش برای بنگاه نیروی متخصص و برای شخص در حال یادگیری یک شغل شناخته‌شده تأمین می‌کند. کار بیش از مشغول بودن است.","explanation":"برای کارآموز، Ausbildung مهارت حرفه‌ای، مدرک معتبر و حقوق آموزشی را ترکیب می‌کند. او یاد می‌گیرد کارها را کم‌کم مستقل و مسئولانه انجام دهد. شرکت می‌تواند نیروی متخصص را طبق چارچوب یک حرفه پرورش دهد و دانش را منتقل کند. در مقابل باید زمان، راهنمایی و کار آموزشی مناسب فراهم کند؛ کارآموز فقط نیروی ارزان نیست. جامعه از مهارت حرفه‌ای و معیارهای قابل مقایسه سود می‌برد. Ausbildungsordnung چارچوب آموزش شرکت را مشخص می‌کند و برنامهٔ مدرسه دانش تخصصی و عمومی را تکمیل می‌کند. هنگام توضیح فایده، مشخص کن از دید کدام طرف حرف می‌زنی و یک مثال بزن. یک فعالیت ممکن است برای طرف‌ها فایده و وظیفهٔ متفاوت داشته باشد.","example":"یک بنگاه متخصص IT تربیت می‌کند چون بعداً یکپارچه‌سازی سامانه لازم دارد. مدرک در بنگاه دیگر هم معتبر است.","remember":["Auszubildende: فردی که حرفهٔ آموزشی معتبر را یاد می‌گیرد.","Ausbildender Betrieb: شرکت طرف قرارداد که آموزش را سازمان می‌دهد.","آموزش باید مهارت حرفه‌ای بسازد؛ کار کمکی دائمی به‌تنهایی این هدف را تأمین نمی‌کند."],"summary":"آموزش مهارت حرفه‌ای می‌سازد و منافع کارآموز، شرکت و جامعه را مرتبط می‌کند.","sections":[],"terms":[["Auszubildende","فردی که حرفهٔ آموزشی معتبر را یاد می‌گیرد."],["Ausbildender Betrieb","شرکت طرف قرارداد که آموزش را سازمان می‌دهد."],["Ausbildungsordnung","چارچوب قانونی فدرال یک حرفهٔ آموزشی."],["Berufliche Handlungsfähigkeit","توان انجام درست و مسئولانهٔ کار حرفه‌ای."]],"q":"کدام هدف با آموزش حرفه‌ای سازگار است؟","options":["همیشه فقط کار کمکی انجام دادن","کسب توان انجام مسئولانهٔ کار حرفه‌ای","همیشه کنارگذاشتن مدرسه"],"answer":1,"feedback":"آموزش باید توان انجام تخصصی و به‌تدریج مستقل کار حرفه‌ای را ایجاد کند.","mistake":"آموزش باید مهارت حرفه‌ای بسازد؛ کار کمکی دائمی به‌تنهایی این هدف را تأمین نمی‌کند."},"minutes":9,"editorial":true,"source":["KMK · Duales Ausbildungssystem","https://www.kmk.org/bildungsministerkonferenz/vertiefende-bildungsinhalte/berufliche-bildung/duales-system-der-beruflichen-ausbildung.html"]},"k10-pug/vertrag":{"de":{"title":"Ausbildungsvertrag","goal":"Du erkennst wesentliche Vertragsangaben und unterscheidest Vertragsabschluss von Dokumentation in Textform.","definition":"Der Ausbildungsvertrag legt die wesentlichen Bedingungen des Ausbildungsverhältnisses fest. Sein wesentlicher Inhalt ist in Textform zu dokumentieren.","explanation":"Der Ausbildungsvertrag regelt das Ausbildungsverhältnis zwischen Betrieb und auszubildender Person. Der wesentliche Inhalt muss nach § 11 BBiG spätestens vor Beginn in Textform festgehalten werden. Die Abfassung enthält unter anderem Beruf und Ausbildungsziel, Beginn und Dauer, Ausbildungsstätte, regelmäßige Ausbildungszeit, Probezeit, Vergütung, Überstundenausgleich, Urlaub und Kündigungsbedingungen. Bei elektronischer Übermittlung muss das Dokument speicher- und ausdruckbar sein; der Betrieb muss den Empfang nachweisen. Textform verlangt nicht automatisch eine handschriftliche Unterschrift auf Papier. Die Probezeit liegt nach § 20 BBiG zwischen einem und vier Monaten. Bei Minderjährigen müssen die Regeln zur gesetzlichen Vertretung beachtet werden. Prüfe in einer Aufgabe die Angaben nacheinander und verwechsle Ausbildungspflichten nicht mit frei wählbaren Vorteilen.","example":"Vor Ausbildungsbeginn erhältst du eine elektronische Vertragsabfassung mit Beruf, Zeiten, Vergütung und Urlaub. Du kannst sie speichern und ausdrucken; der Betrieb dokumentiert den Empfang.","remember":["Textform: Lesbare Erklärung auf einem dauerhaften Datenträger mit erkennbarer erklärender Person.","Probezeit: Anfangszeit des Ausbildungsverhältnisses; ein bis vier Monate.","Textform ist nicht dasselbe wie zwingende Papier-Schriftform mit handschriftlicher Unterschrift."],"summary":"Die Vertragsabfassung hält die Ausbildungsbedingungen nachvollziehbar fest und muss die gesetzliche Textform erfüllen.","sections":[],"terms":[["Textform","Lesbare Erklärung auf einem dauerhaften Datenträger mit erkennbarer erklärender Person."],["Probezeit","Anfangszeit des Ausbildungsverhältnisses; ein bis vier Monate."],["Ausbildungsvergütung","Vereinbarte Zahlung für die Ausbildung nach den gesetzlichen Regeln."],["Vertragsabfassung","Dokumentation der wesentlichen Vertragsinhalte."]],"q":"Welche Form verlangt § 11 BBiG für die wesentlichen Vertragsinhalte?","options":["Immer ausschließlich Papier mit Handschrift","Textform","Keine Dokumentation"],"answer":1,"feedback":"Die aktuelle Regel erlaubt Textform; eine elektronische Abfassung muss die zusätzlichen Anforderungen erfüllen.","mistake":"Textform ist nicht dasselbe wie zwingende Papier-Schriftform mit handschriftlicher Unterschrift."},"fa":{"title":"قرارداد آموزش","goal":"اطلاعات اصلی قرارداد را می‌شناسی و بستن قرارداد را از ثبت محتوای آن در Textform جدا می‌کنی.","definition":"قرارداد Ausbildung شرایط اصلی رابطهٔ آموزشی را مشخص می‌کند و محتوای اصلی آن باید در Textform ثبت شود.","explanation":"قرارداد Ausbildung رابطهٔ آموزشی شرکت و کارآموز را تنظیم می‌کند. طبق مادهٔ ۱۱ BBiG، محتوای اصلی باید حداکثر پیش از شروع در Textform ثبت شود. از جمله حرفه و هدف، شروع و مدت، محل آموزش، ساعت معمول، دورهٔ آزمایشی، حقوق، جبران اضافه‌کاری، مرخصی و شرایط پایان قرارداد در آن می‌آید. در ارسال الکترونیکی، سند باید قابل ذخیره و چاپ باشد و شرکت دریافت آن را اثبات کند. Textform الزاماً به معنی امضای دستی روی کاغذ نیست. دورهٔ آزمایشی طبق مادهٔ ۲۰ بین یک تا چهار ماه است. برای افراد زیر سن قانونی باید قواعد نمایندگی قانونی رعایت شوند. در تمرین، اطلاعات را یکی‌یکی بررسی کن و وظیفهٔ قانونی آموزش را با امتیاز اختیاری اشتباه نگیر.","example":"پیش از شروع آموزش، سند الکترونیکی قرارداد با حرفه، زمان، حقوق و مرخصی دریافت می‌کنی؛ قابل ذخیره و چاپ است و شرکت دریافت آن را ثبت می‌کند.","remember":["Textform: بیان خوانا روی رسانهٔ ماندگار با مشخص‌بودن شخص بیان‌کننده.","Probezeit: دورهٔ آغاز آموزش؛ از یک تا چهار ماه.","Textform همان الزام کاغذ و امضای دستی نیست."],"summary":"متن قرارداد شرایط آموزش را روشن ثبت می‌کند و باید Textform قانونی را رعایت کند.","sections":[],"terms":[["Textform","بیان خوانا روی رسانهٔ ماندگار با مشخص‌بودن شخص بیان‌کننده."],["Probezeit","دورهٔ آغاز آموزش؛ از یک تا چهار ماه."],["Ausbildungsvergütung","حقوق آموزش طبق قرارداد و قواعد قانونی."],["Vertragsabfassung","ثبت محتوای اصلی قرارداد."]],"q":"مادهٔ ۱۱ BBiG برای محتوای اصلی قرارداد چه شکلی می‌خواهد؟","options":["همیشه فقط کاغذ و امضای دستی","Textform","هیچ سندی لازم نیست"],"answer":1,"feedback":"قاعدهٔ فعلی Textform را می‌پذیرد؛ سند الکترونیکی باید شرایط تکمیلی را داشته باشد.","mistake":"Textform همان الزام کاغذ و امضای دستی نیست."},"minutes":9,"editorial":true,"source":["BBiG · § 11 Vertragsabfassung","https://www.gesetze-im-internet.de/bbig_2005/__11.html"]},"k10-pug/dual":{"de":{"title":"Duales System","goal":"Du erklärst die Aufgaben von Betrieb und Berufsschule und ihre Verbindung in der dualen Ausbildung.","definition":"Die Ausbildung läuft an zwei Orten: im Betrieb und in der Berufsschule. Beide sind Pflicht, keiner ersetzt den anderen.","explanation":"Dual bedeutet, dass die Berufsausbildung an zwei verbundenen Lernorten stattfindet. Im Betrieb werden berufliche Aufgaben praktisch erlernt; eine Ausbildungsordnung und ein betrieblicher Ausbildungsplan geben den Rahmen. Die Berufsschule vermittelt fachliche Theorie und allgemeinbildende Inhalte nach dem Lehrplan des Landes. Unterricht kann an einzelnen Wochentagen oder in Blöcken stattfinden. Ein Netzwerkproblem aus dem Betrieb kann dadurch in der Schule mit IP-Adressierung und Protokollen erklärt werden; das Wissen fließt wieder in die Praxis zurück. Der Betrieb muss die erforderliche Teilnahme an der Berufsschule ermöglichen. Für die Anrechnung gelten gesetzliche Regeln, unter anderem abhängig von Unterricht und Alter. Fehlende Abstimmung zwischen Lernorten sollte angesprochen werden, damit Ausbildungsinhalte nicht dauerhaft fehlen.","example":"Montags lernst du im Betrieb VLANs. Dienstags erklärst du in der Schule, warum ein Router Netze trennt. Beides gehört zur selben Ausbildung.","remember":["Duales System: Berufsausbildung mit Betrieb und Berufsschule als Lernorten.","Berufsschule: Schulischer Lernort für fachliche und allgemeine Bildung.","Der Schulbesuch ist Teil der geregelten Ausbildung und keine freiwillige Freizeitaktivität."],"summary":"Betrieb und Berufsschule ergänzen sich als zwei Lernorte für denselben Ausbildungsberuf.","sections":[],"terms":[["Duales System","Berufsausbildung mit Betrieb und Berufsschule als Lernorten."],["Berufsschule","Schulischer Lernort für fachliche und allgemeine Bildung."],["Betrieblicher Ausbildungsplan","Konkretisiert den Ablauf der Ausbildung im Betrieb."],["Blockunterricht","Zusammenhängende Unterrichtsabschnitte statt einzelner wöchentlicher Schultage."]],"q":"Was bedeutet dual in der Berufsausbildung?","options":["Zwei Ausbildungsberufe gleichzeitig","Zwei verbundene Lernorte: Betrieb und Berufsschule","Nur Theorie ohne Praxis"],"answer":1,"feedback":"Beide Lernorte ergänzen sich für denselben Ausbildungsberuf.","mistake":"Der Schulbesuch ist Teil der geregelten Ausbildung und keine freiwillige Freizeitaktivität."},"fa":{"title":"نظام دوگانه","goal":"وظیفهٔ شرکت و Berufsschule و ارتباط آن‌ها در آموزش دوگانه را توضیح می‌دهی.","definition":"آموزش در دو جا می‌رود: در بنگاه و در هنرستان شغلی. هر دو واجب‌اند، هیچ‌کدام جای دیگری نیست.","explanation":"دوگانه یعنی آموزش در دو محل مرتبط انجام می‌شود. در شرکت کارهای حرفه‌ای را عملی یاد می‌گیری؛ Ausbildungsordnung و برنامهٔ آموزشی شرکت چارچوب می‌دهند. Berufsschule نظریهٔ تخصصی و درس‌های عمومی را طبق برنامهٔ ایالت آموزش می‌دهد. مدرسه ممکن است روزهای مشخص هفته یا به شکل Block باشد. یک مشکل شبکه در شرکت می‌تواند در مدرسه با IP و پروتکل توضیح داده شود و دانش دوباره در کار عملی استفاده شود. شرکت باید شرکت در مدرسهٔ لازم را ممکن کند. حساب‌کردن زمان مدرسه طبق قواعد قانونی و از جمله شرایط کلاس و سن انجام می‌شود. اگر هماهنگی دو محل کم باشد باید مطرح شود تا بخشی از آموزش برای مدت طولانی جا نماند.","example":"دوشنبه VLAN را در بنگاه یاد می‌گیری. سه‌شنبه در مدرسه توضیح می‌دهی چرا مسیریاب شبکه را جدا می‌کند. هر دو مال همان آموزش‌اند.","remember":["Duales System: آموزش حرفه‌ای با شرکت و مدرسه به عنوان دو محل یادگیری.","Berufsschule: محل مدرسه برای آموزش تخصصی و عمومی.","مدرسه بخشی از آموزش رسمی است، نه فعالیت تفریحی اختیاری."],"summary":"شرکت و مدرسه دو محل مکمل برای یادگیری همان حرفه هستند.","sections":[],"terms":[["Duales System","آموزش حرفه‌ای با شرکت و مدرسه به عنوان دو محل یادگیری."],["Berufsschule","محل مدرسه برای آموزش تخصصی و عمومی."],["Betrieblicher Ausbildungsplan","برنامهٔ دقیق اجرای آموزش در شرکت."],["Blockunterricht","دوره‌های پیوستهٔ مدرسه به‌جای روزهای جدا در هفته."]],"q":"دوگانه در Ausbildung یعنی چه؟","options":["دو حرفه هم‌زمان","دو محل مرتبط: شرکت و مدرسه","فقط نظریه بدون عمل"],"answer":1,"feedback":"هر دو محل برای همان حرفه یکدیگر را تکمیل می‌کنند.","mistake":"مدرسه بخشی از آموزش رسمی است، نه فعالیت تفریحی اختیاری."},"minutes":9,"editorial":true,"source":["KMK · Duales Ausbildungssystem","https://www.kmk.org/bildungsministerkonferenz/vertiefende-bildungsinhalte/berufliche-bildung/duales-system-der-beruflichen-ausbildung.html"]},"k10-pug/jugend":{"de":{"title":"Jugendarbeitsschutz","goal":"Du erkennst die grundlegenden Arbeitszeit- und Pausenregeln für Jugendliche und prüfst mögliche Ausnahmen am Gesetz.","definition":"Das Jugendarbeitsschutzgesetz begrenzt Zeit und Belastung von Beschäftigten unter 18 Jahren. Ausnahmen stehen im Gesetz, nicht in einem Merksatz.","explanation":"Das Jugendarbeitsschutzgesetz schützt grundsätzlich Beschäftigte unter 18 Jahren; für Kinder und vollzeitschulpflichtige Personen gelten zusätzliche Regeln. Jugendliche sind im Gesetz Personen von 15 bis unter 18 Jahren. Die Grundregel lautet höchstens acht Arbeitsstunden täglich und 40 wöchentlich. Bei mehr als 4,5 bis sechs Stunden sind mindestens 30 Minuten Pause nötig, bei mehr als sechs Stunden mindestens 60 Minuten. Zwischen zwei Arbeitstagen sind grundsätzlich zwölf Stunden Freizeit vorgesehen. Nacht-, Wochenend- und Berufsschulregeln werden in eigenen Vorschriften behandelt und besitzen gesetzliche Ausnahmen. Rechne Pausen nicht als Arbeitszeit und trenne Arbeitszeit von Schichtzeit. Für konkrete Dienstpläne müssen Alter, Branche, Tagesablauf und mögliche Sonderregeln gemeinsam geprüft werden.","example":"Eine Schicht von 9 bis 18 Uhr ohne 60 Minuten Pause ist zu lang. Neun Stunden Arbeit plus Schule am selben Tag rechnest du zusammen, nicht getrennt.","remember":["Jugendlicher: Nach JArbSchG: 15, aber noch nicht 18 Jahre alt.","Arbeitszeit: Beschäftigungszeit ohne Ruhepausen.","Pausen zählen nicht zur Arbeitszeit. Arbeitszeit und gesamte Anwesenheit sind deshalb nicht identisch."],"summary":"Jugendarbeitsschutz begrenzt Belastungen und verlangt eine sorgfältige Prüfung von Arbeitszeit, Pausen und Ausnahmen.","sections":[],"terms":[["Jugendlicher","Nach JArbSchG: 15, aber noch nicht 18 Jahre alt."],["Arbeitszeit","Beschäftigungszeit ohne Ruhepausen."],["Schichtzeit","Arbeitszeit einschließlich der Ruhepausen."],["Ruhepause","Vorab feststehende Unterbrechung der Arbeit zur Erholung."]],"q":"Wie viel Pause ist bei mehr als sechs Stunden Arbeit grundsätzlich mindestens erforderlich?","options":["15 Minuten","30 Minuten","60 Minuten"],"answer":2,"feedback":"§ 11 JArbSchG unterscheidet mehr als 4,5 bis sechs Stunden von mehr als sechs Stunden.","mistake":"Pausen zählen nicht zur Arbeitszeit. Arbeitszeit und gesamte Anwesenheit sind deshalb nicht identisch."},"fa":{"title":"حمایت از کار جوانان","goal":"قواعد اصلی کار و استراحت نوجوانان را می‌فهمی و استثناها را از قانون بررسی می‌کنی.","definition":"قانون حمایت از کار جوانان زمان و فشار کارکنان زیر ۱۸ سال را محدود می‌کند. استثنا در قانون است، نه در یک جمله حفظی.","explanation":"قانون حمایت از کار نوجوانان اصولاً کارکنان زیر ۱۸ سال را محافظت می‌کند؛ برای کودکان و افراد مشمول مدرسهٔ تمام‌وقت قواعد اضافی وجود دارد. نوجوان در این قانون ۱۵ تا کمتر از ۱۸ سال است. قاعدهٔ پایه حداکثر ۸ ساعت کار روزانه و ۴۰ ساعت هفتگی است. برای بیش از ۴٫۵ تا ۶ ساعت کار، حداقل ۳۰ دقیقه و برای بیش از ۶ ساعت، حداقل ۶۰ دقیقه وقفه لازم است. بین دو روز کار اصولاً ۱۲ ساعت وقت آزاد لازم است. کار شب، آخر هفته و مدرسه قواعد جدا و استثناهای قانونی دارند. وقفه را جزو زمان کار حساب نکن و Arbeitszeit را از Schichtzeit جدا کن. برای برنامهٔ واقعی، سن، صنعت، روز و استثناها با هم بررسی می‌شوند.","example":"یک شیفت از ۹ تا ۱۸ بدون ۶۰ دقیقه استراحت خیلی بلند است. نه ساعت کار به‌اضافه مدرسه در همان روز را با هم حساب می‌کنی، نه جدا.","remember":["Jugendlicher: در این قانون: ۱۵ ساله تا پیش از ۱۸ سالگی.","Arbeitszeit: زمان اشتغال بدون وقفه‌های استراحت.","وقفه جزو ساعت کار نیست؛ ساعت کار و کل زمان حضور یکسان نیستند."],"summary":"حمایت از کار نوجوانان فشار کار را محدود می‌کند و بررسی دقیق زمان کار، استراحت و استثناها را می‌خواهد.","sections":[],"terms":[["Jugendlicher","در این قانون: ۱۵ ساله تا پیش از ۱۸ سالگی."],["Arbeitszeit","زمان اشتغال بدون وقفه‌های استراحت."],["Schichtzeit","زمان کار همراه وقفه‌های استراحت."],["Ruhepause","وقفهٔ از پیش مشخص برای استراحت."]],"q":"برای بیش از شش ساعت کار، اصولاً حداقل چقدر وقفه لازم است؟","options":["۱۵ دقیقه","۳۰ دقیقه","۶۰ دقیقه"],"answer":2,"feedback":"مادهٔ ۱۱ بین بیش از ۴٫۵ تا ۶ ساعت و بیش از ۶ ساعت تفاوت می‌گذارد.","mistake":"وقفه جزو ساعت کار نیست؛ ساعت کار و کل زمان حضور یکسان نیستند."},"minutes":9,"editorial":true,"source":["JArbSchG · Arbeitszeit und Pausen","https://www.gesetze-im-internet.de/jarbschg/"]},"k10-bgwp/kreislauf":{"de":{"title":"Erweiterter Wirtschaftskreislauf","goal":"Du verfolgst Güter- und Geldströme zwischen Haushalten, Unternehmen, Staat, Banken und Ausland.","definition":"Der erweiterte Kreislauf zeigt, wie Haushalte, Unternehmen, Staat, Banken und das Ausland Leistungen und Geld tauschen.","explanation":"Der Wirtschaftskreislauf ist ein vereinfachtes Modell wirtschaftlicher Beziehungen. Ein Haushalt stellt einem Unternehmen Arbeitsleistung bereit. Dafür erhält er Lohn; mit einem Teil dieses Einkommens kauft er Güter. Unternehmen erhalten damit Umsätze und zahlen unter anderem Löhne und Lieferanten. Der Staat erhebt Steuern, stellt öffentliche Leistungen bereit und vergibt Aufträge. Banken verbinden Sparen und Finanzierung, indem sie Einlagen annehmen und Kredite vergeben. Das Ausland ergänzt Importe und Exporte. Beschrifte einen Pfeil immer mit dem konkreten Vorgang: Eine Warenlieferung und ihre Bezahlung laufen in entgegengesetzte Richtungen. Nicht jede Geldbewegung besitzt jedoch einen unmittelbaren gleichwertigen Gütergegenfluss, etwa eine Transferleistung des Staates.","example":"Ein Haushalt erhält 2.000 Euro Lohn, kauft davon Waren und legt einen Teil auf einem Konto zurück. Das Modell zeigt Einkommen, Konsum und Sparen als verschiedene Geldströme.","remember":["Haushalt: Wirtschaftliche Einheit, die konsumiert und etwa Arbeit anbietet.","Güterstrom: Bewegung von Waren oder Dienstleistungen.","Ein Kreislaufbild vereinfacht reale Beziehungen. Nicht jede Zahlung hat unmittelbar einen entgegengesetzten Güterstrom."],"summary":"Der Wirtschaftskreislauf macht Beziehungen zwischen wirtschaftlichen Akteuren als Güter- und Geldströme sichtbar.","sections":[],"terms":[["Haushalt","Wirtschaftliche Einheit, die konsumiert und etwa Arbeit anbietet."],["Güterstrom","Bewegung von Waren oder Dienstleistungen."],["Geldstrom","Zahlungsbewegung zwischen Beteiligten."],["Export","Verkauf von Gütern oder Dienstleistungen ins Ausland."]],"q":"Ein Betrieb zahlt Lohn an eine Mitarbeiterin. Welche Richtung hat der Geldstrom?","options":["Vom Haushalt zum Betrieb","Vom Betrieb zum Haushalt","Nur ins Ausland"],"answer":1,"feedback":"Die Arbeitsleistung geht zum Betrieb; die Lohnzahlung geht zum Haushalt.","mistake":"Ein Kreislaufbild vereinfacht reale Beziehungen. Nicht jede Zahlung hat unmittelbar einen entgegengesetzten Güterstrom."},"fa":{"title":"چرخه اقتصادی گسترده","goal":"جریان کالا و پول را بین خانواده‌ها، شرکت‌ها، دولت، بانک‌ها و خارج دنبال می‌کنی.","definition":"چرخه گسترده نشان می‌دهد خانوار، بنگاه، دولت، بانک و خارج چطور کالا و پول را عوض می‌کنند.","explanation":"چرخهٔ اقتصادی مدل ساده‌شدهٔ رابطه‌های اقتصادی است. خانواده نیروی کار در اختیار شرکت می‌گذارد و در مقابل حقوق می‌گیرد. بخشی از درآمد را برای خرید کالا مصرف می‌کند. شرکت از فروش درآمد دارد و با آن حقوق و هزینهٔ تأمین‌کننده را می‌پردازد. دولت مالیات می‌گیرد، خدمات عمومی ارائه می‌کند و سفارش می‌دهد. بانک‌ها پس‌انداز و تأمین مالی را مرتبط می‌کنند؛ سپرده می‌گیرند و وام می‌دهند. خارج نیز واردات و صادرات را اضافه می‌کند. هر پیکان را با یک رویداد دقیق مشخص کن: تحویل کالا و پرداخت پول جهت مخالف دارند. با این حال، هر جریان پول الزاماً مبادلهٔ مستقیم کالای هم‌ارزش ندارد؛ مثلاً بعضی پرداخت‌های انتقالی دولت.","example":"خانواده ۲۰۰۰ یورو حقوق می‌گیرد، بخشی را برای کالا مصرف و بخشی را در حساب پس‌انداز می‌کند. مدل، درآمد، مصرف و پس‌انداز را جریان‌های متفاوت نشان می‌دهد.","remember":["Haushalt: واحد اقتصادی مصرف‌کننده که مثلاً نیروی کار ارائه می‌کند.","Güterstrom: جریان کالا یا خدمات.","نمودار چرخه ساده‌سازی است؛ هر پرداخت الزاماً جریان کالای مستقیم در جهت عکس ندارد."],"summary":"چرخهٔ اقتصادی رابطهٔ طرف‌های اقتصاد را به شکل جریان کالا و پول نشان می‌دهد.","sections":[],"terms":[["Haushalt","واحد اقتصادی مصرف‌کننده که مثلاً نیروی کار ارائه می‌کند."],["Güterstrom","جریان کالا یا خدمات."],["Geldstrom","جریان پرداخت بین طرف‌ها."],["Export","فروش کالا یا خدمات به خارج."]],"q":"شرکت به کارمند حقوق می‌دهد؛ جریان پول به کدام جهت است؟","options":["از خانواده به شرکت","از شرکت به خانواده","فقط به خارج"],"answer":1,"feedback":"نیروی کار به شرکت ارائه می‌شود؛ حقوق به خانواده می‌رود.","mistake":"نمودار چرخه ساده‌سازی است؛ هر پرداخت الزاماً جریان کالای مستقیم در جهت عکس ندارد."},"minutes":9,"editorial":true,"source":["bpb · Wirtschaftskreislauf","https://www.bpb.de/kurz-knapp/lexika/lexikon-der-wirtschaft/21174/wirtschaftskreislauf/"]},"k10-bgwp/marktformen":{"de":{"title":"Marktformen","goal":"Du ordnest Polypol, Oligopol und Monopol anhand von Anbieter- und Nachfragerzahlen ein.","definition":"Die Marktform beschreibt, wie viele Anbieter einer gleichen Leistung gegenüberstehen.","explanation":"Ein Markt besteht aus einem Angebot und einer Nachfrage für vergleichbare Leistungen in einem bestimmten Gebiet. Die Marktform beschreibt die Anzahl der Beteiligten, nicht die Qualität ihres Angebots. Viele Anbieter heißen auf der Angebotsseite Polypol; wenige Anbieter bilden ein Oligopol; ein einzelner Anbieter bildet ein Monopol. Auf der Nachfrageseite kannst du ebenfalls viele, wenige oder einen Nachfrager unterscheiden. Wichtig ist die Marktgrenze: Ein einzelner Laden im Dorf ist nicht automatisch ein Monopol, wenn Kundinnen online oder im Nachbarort gleichwertige Produkte kaufen können. Wenige Anbieter können auf Preisänderungen ihrer Konkurrenten stark reagieren. Aus der Marktform allein folgt jedoch noch keine sichere Aussage über jeden konkreten Preis.","example":"In einem vereinfachten, klar abgegrenzten Beispielmarkt gibt es drei Anbieter einer vergleichbaren Leistung. Auf der Angebotsseite liegt dann ein Oligopol vor.","remember":["Polypol: Marktseite mit vielen Beteiligten.","Oligopol: Marktseite mit wenigen Beteiligten.","Zähle Anbieter erst, nachdem Produkt und räumlicher Markt sinnvoll abgegrenzt sind."],"summary":"Nach sinnvoller Marktabgrenzung zeigen Polypol, Oligopol und Monopol viele, wenige oder einen Anbieter.","sections":[],"terms":[["Polypol","Marktseite mit vielen Beteiligten."],["Oligopol","Marktseite mit wenigen Beteiligten."],["Monopol","Angebotsseite mit genau einem Anbieter im betrachteten Markt."],["Nachfrage","Wunsch nach einer Leistung verbunden mit Kaufbereitschaft und Kaufkraft."]],"q":"In einem klar abgegrenzten Markt bieten drei Firmen eine Leistung an. Was liegt auf der Angebotsseite vor?","options":["Polypol","Oligopol","Monopol"],"answer":1,"feedback":"Drei Anbieter stehen für wenige Anbieter und damit für ein Angebotsoligopol.","mistake":"Zähle Anbieter erst, nachdem Produkt und räumlicher Markt sinnvoll abgegrenzt sind."},"fa":{"title":"شکل‌های بازار","goal":"Polypol، Oligopol و Monopol را با تعداد عرضه‌کننده و تقاضاکننده تشخیص می‌دهی.","definition":"شکل بازار توصیف می‌کند چند عرضه‌کننده برای یک خدمت یکسان روبه‌رو هستند.","explanation":"بازار شامل عرضه و تقاضای خدمات یا کالای قابل مقایسه در یک محدوده است. نوع بازار تعداد طرف‌ها را نشان می‌دهد، نه کیفیت کالا. عرضه‌کننده‌های زیاد Polypol، تعداد کم Oligopol و یک عرضه‌کننده Monopol است. سمت تقاضا نیز می‌تواند خریدار زیاد، کم یا یک خریدار داشته باشد. مرز بازار مهم است: یک فروشگاه در روستا خودکار انحصار نیست، اگر مشتری بتواند همان محصول را آنلاین یا از محل نزدیک بخرد. در بازاری با چند عرضه‌کننده، تغییر قیمت یک رقیب می‌تواند بر تصمیم بقیه اثر زیادی بگذارد. با این حال، فقط از نام نوع بازار نمی‌توان قیمت دقیق هر کالا را نتیجه گرفت.","example":"در مثال ساده با بازار مشخص، سه عرضه‌کنندهٔ خدمت قابل مقایسه وجود دارد؛ پس سمت عرضه Oligopol است.","remember":["Polypol: سمت بازار با تعداد زیاد طرف‌ها.","Oligopol: سمت بازار با تعداد کم طرف‌ها.","ابتدا نوع کالا و محدودهٔ بازار را مشخص کن، سپس عرضه‌کننده‌ها را بشمار."],"summary":"پس از تعیین بازار، Polypol، Oligopol و Monopol به‌ترتیب عرضه‌کنندهٔ زیاد، کم و یک عرضه‌کننده را نشان می‌دهند.","sections":[],"terms":[["Polypol","سمت بازار با تعداد زیاد طرف‌ها."],["Oligopol","سمت بازار با تعداد کم طرف‌ها."],["Monopol","یک عرضه‌کننده در بازار مورد نظر."],["Nachfrage","نیاز همراه تمایل و توان خرید."]],"q":"در بازار مشخص، سه شرکت خدمت را ارائه می‌کنند؛ سمت عرضه چه نوعی است؟","options":["Polypol","Oligopol","Monopol"],"answer":1,"feedback":"سه عرضه‌کننده یعنی تعداد کم و در نتیجه Oligopol عرضه.","mistake":"ابتدا نوع کالا و محدودهٔ بازار را مشخص کن، سپس عرضه‌کننده‌ها را بشمار."},"minutes":9,"editorial":true,"source":["bpb · Marktstruktur","https://www.bpb.de/kurz-knapp/lexika/lexikon-der-wirtschaft/20085/marktstruktur/"]},"k10-bgwp/gruendung":{"de":{"title":"Eine Firma gründen","goal":"Du erklärst die Schritte einer Gründung von der Kundenidee bis zur organisatorischen Umsetzung.","definition":"Eine Gründung ist die geordnete Folge von Idee, Rechtsform, Plan, Anmeldung und Start. Die Skriptseiten dazu waren Scans und sind hier nicht abgetippt.","explanation":"Eine Gründung beginnt mit einem Problem, das eine bestimmte Kundengruppe tatsächlich lösen möchte. Beschreibe deine Leistung, den Kundennutzen und mögliche Alternativen. Danach prüfst du Einnahmen und Kosten: Welche Ausgaben entstehen einmalig, welche monatlich? Wie viele Aufträge brauchst du, damit der Betrieb zahlungsfähig bleibt? Ein Businessplan verbindet Markt, Angebot, Organisation und Finanzierung. Die Rechtsform beeinflusst Haftung, Verwaltung und Startkapital. Danach prüfst du die erforderlichen Anmeldungen und Genehmigungen für die konkrete Tätigkeit. Bei einem Gewerbe kommt insbesondere die Gewerbeanmeldung in Betracht; freiberufliche Tätigkeiten können anders eingeordnet sein. Verträge, Versicherungen, Datenschutz und Buchführung müssen zum Geschäftsmodell passen. Eine Gründung ist deshalb ein geplanter Prozess mit wirtschaftlichen und rechtlichen Prüfungen.","example":"Wer einen PC-Service anmeldet, braucht nicht zuerst ein Logo, sondern Angebot, Rechtsform und die Anmeldung beim Amt.","remember":["Geschäftsidee: Beschreibung von Angebot und Nutzen für eine Zielgruppe.","Businessplan: Plan für Markt, Organisation und Finanzierung.","Umsatz ist nicht Gewinn und Gewinn ist nicht automatisch verfügbare Liquidität."],"summary":"Eine tragfähige Gründung verbindet Kundennutzen, Finanzierung, Organisation und die erforderlichen rechtlichen Schritte.","sections":[],"terms":[["Geschäftsidee","Beschreibung von Angebot und Nutzen für eine Zielgruppe."],["Businessplan","Plan für Markt, Organisation und Finanzierung."],["Liquidität","Fähigkeit, fällige Zahlungen rechtzeitig zu leisten."],["Fixkosten","Kosten, die im betrachteten Bereich nicht mit jeder zusätzlichen Leistung steigen."]],"q":"Was sollte vor teuren Anschaffungen zuerst geprüft werden?","options":["Ob eine Kundengruppe das Angebot benötigt","Nur die Farbe des Logos","Nur ein möglichst großer Büroraum"],"answer":0,"feedback":"Ohne nachvollziehbaren Bedarf und Finanzierung ist die Investition wirtschaftlich nicht begründet.","mistake":"Umsatz ist nicht Gewinn und Gewinn ist nicht automatisch verfügbare Liquidität."},"fa":{"title":"تأسیس یک شرکت","goal":"مرحله‌های شروع کسب‌وکار را از نیاز مشتری تا اجرای سازمانی توضیح می‌دهی.","definition":"تأسیس ترتیب منظم ایده، شکل حقوقی، طرح، ثبت و شروع است. صفحه‌های جزوه اسکن بودند و اینجا رونویسی نشده‌اند.","explanation":"شروع کسب‌وکار با مشکلی آغاز می‌شود که گروه مشخصی از مشتریان واقعاً می‌خواهند حل شود. خدمت، فایده برای مشتری و جایگزین‌ها را توضیح بده. سپس درآمد و هزینه را بررسی کن: چه هزینه‌ای یک‌باره و چه هزینه‌ای ماهانه است؟ چند سفارش لازم داری تا نقدینگی کافی بماند؟ Businessplan بازار، خدمت، سازمان و تأمین مالی را پیوند می‌دهد. شکل حقوقی بر مسئولیت، اداره و سرمایهٔ شروع اثر دارد. بعد ثبت‌ها و مجوزهای لازم برای همان فعالیت را بررسی کن. برای Gewerbe معمولاً ثبت تجاری لازم است؛ بعضی فعالیت‌های حرفه‌ای آزاد شرایط دیگری دارند. قرارداد، بیمه، حفاظت داده و حسابداری باید با مدل کسب‌وکار سازگار باشند. پس تأسیس یک فرایند برنامه‌ریزی‌شدهٔ اقتصادی و حقوقی است.","example":"کسی که خدمات رایانه ثبت می‌کند اول لوگو لازم ندارد، بلکه پیشنهاد، شکل حقوقی و ثبت در اداره.","remember":["Geschäftsidee: شرح خدمت و فایدهٔ آن برای گروه مشتری.","Businessplan: برنامهٔ بازار، سازمان و تأمین مالی.","درآمد فروش سود نیست و سود هم الزاماً پول نقد در دسترس نیست."],"summary":"تأسیس پایدار، فایدهٔ مشتری، تأمین مالی، سازمان و اقدام‌های حقوقی لازم را ترکیب می‌کند.","sections":[],"terms":[["Geschäftsidee","شرح خدمت و فایدهٔ آن برای گروه مشتری."],["Businessplan","برنامهٔ بازار، سازمان و تأمین مالی."],["Liquidität","توان پرداخت به‌موقع بدهی‌های سررسیدشده."],["Fixkosten","هزینه‌هایی که در محدودهٔ مورد نظر با هر خدمت اضافه تغییر نمی‌کنند."]],"q":"پیش از خریدهای گران ابتدا چه چیزی باید بررسی شود؟","options":["آیا مشتری مشخص به خدمت نیاز دارد","فقط رنگ لوگو","فقط بزرگ‌بودن دفتر"],"answer":0,"feedback":"بدون نیاز واقعی و تأمین مالی روشن، سرمایه‌گذاری توجیه اقتصادی ندارد.","mistake":"درآمد فروش سود نیست و سود هم الزاماً پول نقد در دسترس نیست."},"minutes":9,"editorial":true,"source":["Bund · Gründungswissen und Rechtsformen","https://www.existenzgruendungsportal.de/Navigation/DE/Gruendungswissen/Rechtsformen/rechtsformen"]},"k10-bgwp/rechtsformen":{"de":{"title":"Rechtsformen","goal":"Du vergleichst wichtige Rechtsformen anhand von Haftung, Kapital und Organisationsform.","definition":"Eine Rechtsform ist der rechtliche Rahmen eines Unternehmens. Sie beeinflusst Haftung, Leitung, Kapital und Gründung.","explanation":"Die Rechtsform ordnet, wer Träger des Unternehmens ist, wer entscheidet und welches Vermögen grundsätzlich für Schulden einsteht. Ein Einzelunternehmer haftet grundsätzlich auch persönlich. Bei Personengesellschaften sind die Regeln je Form und Gesellschafterrolle zu prüfen. In der KG haftet der Komplementär grundsätzlich unbeschränkt; beim Kommanditisten hängen Außenhaftung und deren Begrenzung insbesondere von Haftsumme und geleisteter Einlage ab. Bei einer eingetragenen GmbH haftet grundsätzlich das Gesellschaftsvermögen; ihr gesetzliches Mindeststammkapital beträgt 25.000 Euro. Die UG (haftungsbeschränkt) ist eine GmbH-Variante unterhalb dieser Grenze mit besonderen Kapital- und Rücklagenregeln. Bei der AG beträgt das Mindestgrundkapital 50.000 Euro. Kapitalhöhe und Haftungsvermögen sind verschiedene Größen: Auch eine GmbH kann später deutlich mehr Vermögen besitzen.","example":"Zwei Auszubildende reparieren nebenbei ohne Gesellschaftsvertrag PCs und teilen den Gewinn. Das ist eher eine GbR als eine GmbH. Die Haftung bleibt bei den Personen.","remember":["Einzelunternehmen: Unternehmen einer natürlichen Person mit grundsätzlich persönlicher Haftung.","GmbH: Kapitalgesellschaft mit eigenem Vermögen und grundsätzlich eigener Haftung.","Bei der GmbH ist die Haftung grundsätzlich nicht auf genau 25.000 Euro begrenzt; das Gesellschaftsvermögen steht ein."],"summary":"Rechtsformen ordnen insbesondere Verantwortung, Haftung, Leitung und Kapitalanforderungen eines Unternehmens.","sections":[],"terms":[["Einzelunternehmen","Unternehmen einer natürlichen Person mit grundsätzlich persönlicher Haftung."],["GmbH","Kapitalgesellschaft mit eigenem Vermögen und grundsätzlich eigener Haftung."],["Stammkapital","Im Gesellschaftsvertrag festgelegtes Kapital einer GmbH."],["Kommanditist","Gesellschafter einer KG mit gesetzlich begrenzbarer Außenhaftung."]],"q":"Wie hoch ist das gesetzliche Mindeststammkapital einer GmbH?","options":["1 Euro","25.000 Euro","50.000 Euro"],"answer":1,"feedback":"25.000 Euro ist die gesetzliche Mindesthöhe des Stammkapitals. Die Einzahlung bei Anmeldung folgt zusätzlichen Regeln.","mistake":"Bei der GmbH ist die Haftung grundsätzlich nicht auf genau 25.000 Euro begrenzt; das Gesellschaftsvermögen steht ein."},"fa":{"title":"شکل‌های حقوقی","goal":"شکل‌های حقوقی مهم را از نظر مسئولیت، سرمایه و ساختار مقایسه می‌کنی.","definition":"شکل حقوقی چارچوب قانونی کسب‌وکار است و بر مسئولیت، مدیریت، سرمایه و تأسیس اثر دارد.","explanation":"شکل حقوقی مشخص می‌کند صاحب حقوقی شرکت کیست، چه کسی تصمیم می‌گیرد و کدام دارایی اصولاً پاسخ‌گوی بدهی است. صاحب کسب‌وکار انفرادی معمولاً شخصاً هم مسئول است. در شرکت‌های اشخاص، قانون به نوع شرکت و نقش شریک بستگی دارد. در KG شریک Komplementär معمولاً مسئولیت نامحدود دارد؛ مسئولیت بیرونی Kommanditist به‌ویژه به مبلغ ثبت‌شدهٔ مسئولیت و سرمایهٔ پرداخت‌شده مرتبط است. در GmbH ثبت‌شده، اصولاً دارایی خود شرکت مسئول بدهی است و حداقل سرمایهٔ اسمی آن ۲۵۰۰۰ یوروست. UG (haftungsbeschränkt) نوعی GmbH با سرمایهٔ کمتر و قواعد ویژهٔ سرمایه و ذخیره است. حداقل سرمایهٔ AG برابر ۵۰۰۰۰ یوروست. مبلغ سرمایه و داراییِ پاسخ‌گوی بدهی یکی نیستند؛ GmbH ممکن است بعداً دارایی بسیار بیشتری داشته باشد.","example":"دو کارآموز کنار کار بدون اساسنامه رایانه تعمیر می‌کنند و سود را تقسیم می‌کنند. این بیشتر GbR است تا GmbH. مسئولیت پیش اشخاص می‌ماند.","remember":["Einzelunternehmen: کسب‌وکار یک شخص حقیقی با مسئولیت اصولاً شخصی.","GmbH: شرکت سرمایه‌ای با دارایی و مسئولیت اصولاً مستقل.","مسئولیت GmbH اصولاً دقیقاً به ۲۵۰۰۰ یورو محدود نیست؛ دارایی شرکت پاسخ‌گوست."],"summary":"شکل حقوقی مسئولیت، پاسخ‌گویی بدهی، مدیریت و سرمایهٔ لازم شرکت را مشخص می‌کند.","sections":[],"terms":[["Einzelunternehmen","کسب‌وکار یک شخص حقیقی با مسئولیت اصولاً شخصی."],["GmbH","شرکت سرمایه‌ای با دارایی و مسئولیت اصولاً مستقل."],["Stammkapital","سرمایهٔ اسمی تعیین‌شده در قرارداد GmbH."],["Kommanditist","شریک KG که مسئولیت بیرونی او طبق قانون قابل محدودشدن است."]],"q":"حداقل سرمایهٔ اسمی GmbH طبق قانون چقدر است؟","options":["۱ یورو","۲۵۰۰۰ یورو","۵۰۰۰۰ یورو"],"answer":1,"feedback":"حداقل سرمایهٔ اسمی ۲۵۰۰۰ یوروست؛ پرداخت هنگام ثبت قواعد تکمیلی جدا دارد.","mistake":"مسئولیت GmbH اصولاً دقیقاً به ۲۵۰۰۰ یورو محدود نیست؛ دارایی شرکت پاسخ‌گوست."},"minutes":9,"editorial":true,"source":["GmbHG · Stammkapital","https://www.gesetze-im-internet.de/gmbhg/__5.html"]},"k10-bgwp/vollmacht":{"de":{"title":"Prokura und Handlungsvollmacht","goal":"Du unterscheidest Prokura und Handlungsvollmacht und prüfst, ob ein Geschäft von der Vollmacht gedeckt ist.","definition":"Beide ermächtigen, für ein Handelsgeschäft zu handeln. Die Prokura ist weit und wird ins Handelsregister eingetragen. Die Handlungsvollmacht ist enger und wird nicht eingetragen.","explanation":"Eine Vollmacht erlaubt einer Person, Rechtsgeschäfte für eine andere Person oder ein Unternehmen vorzunehmen. Prokura besitzt einen gesetzlich weit bestimmten Umfang und muss ausdrücklich erteilt werden. Ihre Erteilung und ihr Erlöschen sind zum Handelsregister anzumelden; die Eintragung macht die Erteilung erkennbar, begründet sie aber nicht erst. Interne Betragsgrenzen beschränken den gesetzlichen Umfang gegenüber Dritten grundsätzlich nicht; Missbrauch und besondere Ausnahmefälle sind gesondert zu beurteilen. Handlungsvollmacht bezieht sich auf gewöhnliche Geschäfte des übertragenen Aufgabenbereichs. Für bestimmte besondere Handlungen, etwa Darlehensaufnahme, reicht sie ohne besondere Ermächtigung nicht. Prüfe deshalb Art der Vollmacht, konkretes Geschäft und gesetzliche Sonderregeln getrennt.","example":"Die Büroleitung mit Handlungsvollmacht bestellt Ware für den laufenden Verkauf. Den Verkauf des Firmengrundstücks darf sie damit nicht unterschreiben.","remember":["Vollmacht: Erlaubnis zum rechtsgeschäftlichen Handeln für eine andere Person.","Prokura: Ausdrücklich erteilte handelsrechtliche Vollmacht mit gesetzlichem Umfang.","Die Eintragung der Prokura ist deklaratorisch: Sie macht eine bereits erteilte Prokura bekannt."],"summary":"Prokura hat einen gesetzlich weiten Umfang, Handlungsvollmacht deckt gewöhnliche Geschäfte des übertragenen Bereichs.","sections":[],"terms":[["Vollmacht","Erlaubnis zum rechtsgeschäftlichen Handeln für eine andere Person."],["Prokura","Ausdrücklich erteilte handelsrechtliche Vollmacht mit gesetzlichem Umfang."],["Handlungsvollmacht","Vollmacht für gewöhnliche Geschäfte eines Aufgabenbereichs."],["Handelsregister","Öffentliches Register mit gesetzlich vorgesehenen Unternehmensangaben."]],"q":"Welche Vollmacht muss ausdrücklich erteilt werden und ist zum Handelsregister anzumelden?","options":["Prokura","Jede Erlaubnis zum Telefonieren","Jede einzelne Bestellung"],"answer":0,"feedback":"Für Prokura gelten die besonderen Regeln der §§ 48 ff. HGB.","mistake":"Die Eintragung der Prokura ist deklaratorisch: Sie macht eine bereits erteilte Prokura bekannt."},"fa":{"title":"پروکورا و اختیار تجاری","goal":"Prokura و Handlungsvollmacht را جدا می‌کنی و بررسی می‌کنی یک معامله داخل اختیار هست یا نه.","definition":"هر دو اجازه می‌دهند کسی برای یک کسب تجاری عمل کند. پروکورا گسترده است و در ثبت تجاری نوشته می‌شود. اختیار تجاری باریک‌تر است و ثبت نمی‌شود.","explanation":"وکالت به یک فرد اجازه می‌دهد معاملهٔ حقوقی را برای شخص یا شرکت دیگری انجام دهد. Prokura اختیار قانونی گسترده دارد و باید صریح داده شود. اعطا و پایان آن باید برای ثبت در Handelsregister اعلام شود؛ ثبت، اختیار را قابل مشاهده می‌کند، اما اختیار فقط با ثبت به وجود نمی‌آید. محدودیت مبلغ داخلی معمولاً دامنهٔ قانونی Prokura را در برابر دیگران کم نمی‌کند؛ سوءاستفاده و استثناهای خاص بررسی جدا می‌خواهند. Handlungsvollmacht معامله‌های معمول حوزهٔ کاری واگذارشده را پوشش می‌دهد. برای بعضی کارهای ویژه مثل گرفتن وام، اختیار خاص لازم است. پس نوع وکالت، خود معامله و استثناهای قانونی را جدا بررسی کن.","example":"مسئول دفتر با اختیار تجاری کالا برای فروش جاری سفارش می‌دهد. فروش زمین شرکت را با همان اختیار نمی‌تواند امضا کند.","remember":["Vollmacht: اجازهٔ انجام معاملهٔ حقوقی برای شخص دیگر.","Prokura: اختیار تجاری صریح با دامنهٔ تعیین‌شده در قانون.","ثبت Prokura جنبهٔ اعلامی دارد؛ اختیار قبلاً اعطاشده را عمومی می‌کند."],"summary":"Prokura دامنهٔ قانونی گسترده دارد و Handlungsvollmacht کارهای معمول حوزهٔ واگذارشده را پوشش می‌دهد.","sections":[],"terms":[["Vollmacht","اجازهٔ انجام معاملهٔ حقوقی برای شخص دیگر."],["Prokura","اختیار تجاری صریح با دامنهٔ تعیین‌شده در قانون."],["Handlungsvollmacht","اختیار معامله‌های معمول در حوزهٔ کاری مشخص."],["Handelsregister","دفتر عمومی اطلاعات قانونی شرکت‌ها."]],"q":"کدام اختیار باید صریح داده و برای ثبت تجاری اعلام شود؟","options":["Prokura","هر اجازهٔ تلفن‌کردن","هر سفارش تکی"],"answer":0,"feedback":"برای Prokura قواعد ویژهٔ ماده‌های ۴۸ به بعد HGB اجرا می‌شود.","mistake":"ثبت Prokura جنبهٔ اعلامی دارد؛ اختیار قبلاً اعطاشده را عمومی می‌کند."},"minutes":9,"editorial":true,"source":["HGB · §§ 48–54","https://www.gesetze-im-internet.de/hgb/__54.html"]},"k10-ittechnik/entwicklung":{"de":{"title":"Vom Relais zum Mikroprozessor","goal":"Du beschreibst die Entwicklung elektronischer Schalter und erklärst, warum Integration kleinere Rechner ermöglicht.","definition":"Rechner wurden kleiner und dichter: von elektromechanischen Teilen über Röhren und Transistoren zu integrierten Schaltungen und zum Mikroprozessor.","explanation":"Frühe Rechner nutzten je nach Bauweise Relais oder Elektronenröhren als Schaltelemente. Ein Transistor konnte viele Aufgaben einer Röhre kleiner, robuster und mit geringerem Energiebedarf übernehmen. Integrierte Schaltungen vereinen viele Bauteile auf einem Halbleiterchip. Mit dem Mikroprozessor wurden wesentliche CPU-Funktionen auf einem Chip zusammengefasst. Heute enthalten Prozessoren sehr viele Transistoren und mehrere Rechenkerne. Mehr Transistoren bedeuten jedoch nicht automatisch die gleiche Steigerung der Leistung: Architektur, Takt, Speicherzugriff, Kühlung und Software wirken ebenfalls mit. Die Entwicklung erklärt, warum Rechenleistung heute in Notebooks, Mobiltelefonen und eingebetteten Systemen verfügbar ist. Ordne die Stufen nach dem technischen Prinzip, statt nur Jahreszahlen auswendig zu lernen.","example":"Ein Mikrocontroller integriert CPU, Speicher und weitere Funktionen für eine konkrete Steuerungsaufgabe auf einem Chip. Das zeigt die Wirkung hoher Integration.","remember":["Relais: Elektromechanischer Schalter.","Transistor: Halbleiterbauteil, unter anderem als elektronischer Schalter.","Mehr Transistoren allein garantieren keine proportional höhere Anwendungsleistung."],"summary":"Die Integration elektronischer Schalter ermöglichte kompaktere und vielseitigere Rechensysteme.","sections":[],"terms":[["Relais","Elektromechanischer Schalter."],["Transistor","Halbleiterbauteil, unter anderem als elektronischer Schalter."],["Integrierte Schaltung","Viele Bauelemente auf einem Chip."],["Mikroprozessor","Prozessor, dessen zentrale Funktionen auf einem Chip integriert sind."]],"q":"Was beschreibt Integration in der Elektronik?","options":["Viele Bauteile auf einem Chip zusammenfassen","Nur ein größeres Gehäuse bauen","Alle Programme entfernen"],"answer":0,"feedback":"Integration erhöht die Funktionsdichte und verkürzt viele interne Verbindungen.","mistake":"Mehr Transistoren allein garantieren keine proportional höhere Anwendungsleistung."},"fa":{"title":"از رله تا ریزپردازنده","goal":"روند پیشرفت کلیدهای الکترونیکی و تأثیر یکپارچه‌سازی بر کوچک‌شدن کامپیوتر را توضیح می‌دهی.","definition":"رایانه کوچک‌تر و فشرده‌تر شد: از قطعه الکترومکانیکی، از لامپ و ترانزیستور تا مدار مجتمع و ریزپردازنده.","explanation":"کامپیوترهای اولیه بسته به ساختار از رله یا لامپ الکترونی به عنوان کلید استفاده می‌کردند. ترانزیستور بسیاری از کارهای لامپ را با اندازه و مصرف کمتر و پایداری بیشتر انجام داد. مدار مجتمع چندین قطعه را روی یک تراشهٔ نیمه‌هادی ترکیب می‌کند. با ریزپردازنده، بخش‌های اصلی CPU روی یک تراشه جمع شدند. پردازنده‌های امروزی ترانزیستورهای بسیار زیاد و چند هسته دارند. ولی افزایش ترانزیستور لزوماً به همان نسبت سرعت را بالا نمی‌برد؛ معماری، فرکانس، حافظه، خنک‌کاری و نرم‌افزار هم مهم‌اند. این پیشرفت توضیح می‌دهد چرا قدرت محاسبه اکنون در لپ‌تاپ، موبایل و سیستم تعبیه‌شده وجود دارد. مرحله‌ها را بر اساس اصل فنی مرتب کن، نه فقط حفظ تاریخ.","example":"میکروکنترلر CPU، حافظه و قابلیت‌های دیگر را برای کنترل روی یک تراشه جمع می‌کند؛ این اثر یکپارچه‌سازی زیاد را نشان می‌دهد.","remember":["Relais: کلید الکترومکانیکی.","Transistor: قطعهٔ نیمه‌هادی که از جمله نقش کلید الکترونیکی دارد.","تعداد ترانزیستور بیشتر به‌تنهایی افزایش متناسب کارایی برنامه را تضمین نمی‌کند."],"summary":"یکپارچه‌سازی کلیدهای الکترونیکی سیستم‌های کوچک‌تر و چندکاره‌تر را ممکن کرد.","sections":[],"terms":[["Relais","کلید الکترومکانیکی."],["Transistor","قطعهٔ نیمه‌هادی که از جمله نقش کلید الکترونیکی دارد."],["Integrierte Schaltung","چندین جزء الکترونیکی روی یک تراشه."],["Mikroprozessor","پردازنده با عملکردهای اصلی یکپارچه روی یک تراشه."]],"q":"یکپارچه‌سازی در الکترونیک یعنی چه؟","options":["ترکیب چندین قطعه روی یک تراشه","فقط بزرگ‌کردن بدنه","حذف همهٔ برنامه‌ها"],"answer":0,"feedback":"یکپارچه‌سازی تراکم عملکرد را بالا می‌برد و بسیاری از اتصال‌های داخلی را کوتاه می‌کند.","mistake":"تعداد ترانزیستور بیشتر به‌تنهایی افزایش متناسب کارایی برنامه را تضمین نمی‌کند."},"minutes":9,"editorial":true,"source":["Intel · PC platform specifications","https://www.intel.com/content/www/us/en/products/sku/218827/intel-q670-chipset/specifications.html"]},"k10-ittechnik/eva":{"de":{"title":"EVA und Bauformen","goal":"Du ordnest ein praktisches Beispiel den Schritten Eingabe, Verarbeitung, Ausgabe und Speicherung zu.","definition":"Ein Rechner nimmt Daten auf, verarbeitet sie und gibt ein Ergebnis aus. Der Speicher hält Daten zwischen diesen Schritten. Die Bauform ist nur das Gehäuse.","explanation":"Das EVA-Prinzip beschreibt eine grundlegende Sicht auf Datenverarbeitung. Bei der Eingabe gelangen Daten in das System, beispielsweise durch Tastatur, Scanner oder Sensor. Bei der Verarbeitung führt der Prozessor mit einem Programm Berechnungen und Entscheidungen aus. Bei der Ausgabe wird das Ergebnis sichtbar oder wirksam: auf einem Bildschirm, als Ausdruck oder als Steuersignal. Speicher hält Programme, Eingaben und Ergebnisse bereit. Arbeitsspeicher dient dem schnellen aktuellen Zugriff; Massenspeicher bewahrt Daten längerfristig. Ein Gerät kann mehrere Rollen kombinieren: Ein Touchscreen zeigt ein Ergebnis und nimmt gleichzeitig Berührungen entgegen. Die Gehäuseform, etwa Notebook oder Tower, verändert diese grundlegenden Aufgaben nicht.","example":"Der Scanner ist Eingabe, die Bearbeitung des Scans ist Verarbeitung, die Datei auf dem Bildschirm ist Ausgabe, die Festplatte ist Speicher.","remember":["Eingabe: Übernahme von Daten in das System.","Verarbeitung: Berechnung und Bearbeitung von Daten nach Programmregeln.","Ein Touchscreen ist sowohl Eingabe- als auch Ausgabegerät. Eine Einteilung kann mehrere Rollen enthalten."],"summary":"Eingabe, Verarbeitung, Ausgabe und Speicherung beschreiben zusammen den grundlegenden Weg der Daten im Rechner.","sections":[],"terms":[["Eingabe","Übernahme von Daten in das System."],["Verarbeitung","Berechnung und Bearbeitung von Daten nach Programmregeln."],["Ausgabe","Bereitstellung eines Ergebnisses nach außen."],["Arbeitsspeicher","Schneller Speicher für aktuell verwendete Programme und Daten."]],"q":"Ein Barcode wird gescannt. Welcher EVA-Schritt ist das zunächst?","options":["Ausgabe","Eingabe","Gehäusewahl"],"answer":1,"feedback":"Der Scanner führt die erfassten Daten dem System zu. Die Preisermittlung wäre Verarbeitung.","mistake":"Ein Touchscreen ist sowohl Eingabe- als auch Ausgabegerät. Eine Einteilung kann mehrere Rollen enthalten."},"fa":{"title":"ورودی، پردازش، خروجی و شکل","goal":"یک مثال عملی را به ورودی، پردازش، خروجی و ذخیره‌سازی تقسیم می‌کنی.","definition":"رایانه داده را می‌گیرد، پردازش می‌کند و نتیجه را بیرون می‌دهد. حافظه داده را بین این گام‌ها نگه می‌دارد. شکل فقط جعبه است.","explanation":"اصل EVA یک نگاه پایه به پردازش داده است. در ورودی، داده از صفحه‌کلید، اسکنر یا سنسور وارد سیستم می‌شود. در پردازش، پردازنده با برنامه محاسبه و تصمیم‌گیری انجام می‌دهد. در خروجی، نتیجه قابل مشاهده یا مؤثر می‌شود؛ مثلاً روی مانیتور، روی کاغذ یا به شکل سیگنال کنترلی. حافظه برنامه‌ها، ورودی و نتیجه‌ها را نگه می‌دارد. RAM برای دسترسی سریع فعلی و حافظهٔ ذخیره‌سازی برای نگهداری طولانی‌تر است. یک وسیله ممکن است چند نقش داشته باشد: نمایشگر لمسی نتیجه را نشان می‌دهد و هم‌زمان لمس را دریافت می‌کند. شکل بدنه مثل لپ‌تاپ یا Tower، این وظیفه‌های اصلی را تغییر نمی‌دهد.","example":"اسکنر ورودی است، ویرایش اسکن پردازش است، فایل روی صفحه خروجی است، دیسک حافظه است.","remember":["Eingabe: ورود داده به سیستم.","Verarbeitung: محاسبه و تغییر داده طبق دستور برنامه.","نمایشگر لمسی هم ورودی و هم خروجی است؛ یک وسیله می‌تواند چند نقش داشته باشد."],"summary":"ورودی، پردازش، خروجی و ذخیره‌سازی مسیر پایهٔ داده در کامپیوتر را نشان می‌دهند.","sections":[],"terms":[["Eingabe","ورود داده به سیستم."],["Verarbeitung","محاسبه و تغییر داده طبق دستور برنامه."],["Ausgabe","ارائهٔ نتیجه به بیرون."],["Arbeitsspeicher","حافظهٔ سریع برنامه‌ها و داده‌های در حال استفاده."]],"q":"اسکن‌کردن بارکد در ابتدا کدام مرحلهٔ EVA است؟","options":["خروجی","ورودی","انتخاب بدنه"],"answer":1,"feedback":"اسکنر داده را وارد سیستم می‌کند؛ پیدا یا محاسبه‌کردن قیمت، پردازش است.","mistake":"نمایشگر لمسی هم ورودی و هم خروجی است؛ یک وسیله می‌تواند چند نقش داشته باشد."},"minutes":9,"editorial":true,"source":["Intel · PC platform specifications","https://www.intel.com/content/www/us/en/products/sku/218827/intel-q670-chipset/specifications.html"]},"k10-ittechnik/mainboard":{"de":{"title":"Mainboard","goal":"Du benennst zentrale Mainboard-Komponenten und prüfst ihre Kompatibilität beim Zusammenbau.","definition":"Das Mainboard ist die Hauptplatine, die zentrale Komponenten mechanisch, elektrisch und über Datenverbindungen zusammenführt.","explanation":"Das Mainboard ist die zentrale Platine eines Computers. Der CPU-Sockel nimmt einen kompatiblen Prozessor auf; die Spannungsversorgung auf dem Board bereitet benötigte Spannungen auf. DIMM-Steckplätze nehmen Arbeitsspeicher auf. PCIe-Steckplätze verbinden Erweiterungskarten. M.2-Anschlüsse können etwa eine NVMe-SSD aufnehmen, abhängig von der elektrischen Anbindung. Firmware wie UEFI startet die Hardwareinitialisierung und übergibt später an den Bootvorgang. Vor einem Austausch prüfst du Formfaktor, CPU-Unterstützung, RAM-Generation, Anschlüsse und Stromversorgung anhand der Herstellerangaben. Ein mechanisch passender Stecker garantiert nicht jede Funktion. Ein M.2-Steckplatz kann beispielsweise unterschiedliche Protokolle und Baugrößen unterstützen.","example":"Grafikkarte, SSD und USB-Buchse sitzen am oder auf dem Mainboard. Ohne Board hätten sie keine gemeinsame Verbindung.","remember":["CPU-Sockel: Mechanische und elektrische Aufnahme für den Prozessor.","DIMM-Steckplatz: Steckplatz für ein passendes Arbeitsspeichermodul.","Mechanische Passform reicht für Kompatibilität nicht aus. Elektrische Anbindung und Firmware müssen ebenfalls passen."],"summary":"Das Mainboard verbindet die Komponenten; Kompatibilität verlangt passende mechanische, elektrische und Firmware-Eigenschaften.","sections":[],"terms":[["CPU-Sockel","Mechanische und elektrische Aufnahme für den Prozessor."],["DIMM-Steckplatz","Steckplatz für ein passendes Arbeitsspeichermodul."],["Formfaktor","Baugröße und Anordnungsvorgaben, etwa ATX."],["UEFI","Firmware-Schnittstelle für Initialisierung und Systemstart."]],"q":"Welche Information ist beim CPU-Tausch besonders wichtig?","options":["Nur die Gehäusefarbe","Sockel und CPU-Unterstützung des Mainboards","Nur die Bildschirmgröße"],"answer":1,"feedback":"Sockel, Chipsatz und gegebenenfalls Firmware müssen den Prozessor unterstützen.","mistake":"Mechanische Passform reicht für Kompatibilität nicht aus. Elektrische Anbindung und Firmware müssen ebenfalls passen."},"fa":{"title":"برد اصلی","goal":"بخش‌های اصلی Mainboard را نام می‌بری و سازگاری آن‌ها را هنگام نصب بررسی می‌کنی.","definition":"Mainboard برد اصلی است که اجزای مرکزی را از نظر مکانیکی، برق و مسیر داده به هم وصل می‌کند.","explanation":"Mainboard برد مرکزی کامپیوتر است. سوکت CPU پردازندهٔ سازگار را نگه می‌دارد و بخش تغذیهٔ روی برد ولتاژهای لازم را آماده می‌کند. شکاف‌های DIMM برای RAM و PCIe برای کارت توسعه‌اند. اتصال M.2 بسته به ارتباط الکتریکی می‌تواند مثلاً SSD نوع NVMe را بپذیرد. Firmware مثل UEFI سخت‌افزار را آماده می‌کند و سپس کنترل را به فرایند Boot می‌دهد. پیش از تعویض، شکل برد، پردازندهٔ پشتیبانی‌شده، نسل RAM، اتصال‌ها و برق را در اطلاعات سازنده بررسی کن. جاخوردن ظاهری یک کانکتور، همهٔ قابلیت‌ها را تضمین نمی‌کند؛ مثلاً M.2 ممکن است فقط بعضی پروتکل‌ها و اندازه‌ها را پشتیبانی کند.","example":"کارت گرافیک، SSD و سوکت USB روی برد یا کنار آن نشسته‌اند. بدون برد پیوند مشترک ندارند.","remember":["CPU-Sockel: جایگاه مکانیکی و الکتریکی پردازنده.","DIMM-Steckplatz: شکاف نصب ماژول RAM سازگار.","جاخوردن ظاهری برای سازگاری کافی نیست؛ اتصال الکتریکی و Firmware هم باید مناسب باشند."],"summary":"Mainboard اجزا را متصل می‌کند؛ سازگاری به ویژگی مکانیکی، الکتریکی و Firmware مناسب نیاز دارد.","sections":[],"terms":[["CPU-Sockel","جایگاه مکانیکی و الکتریکی پردازنده."],["DIMM-Steckplatz","شکاف نصب ماژول RAM سازگار."],["Formfaktor","اندازه و قواعد چیدمان، مثل ATX."],["UEFI","رابط Firmware برای آماده‌سازی و شروع سیستم."]],"q":"برای تعویض CPU کدام اطلاعات مهم است؟","options":["فقط رنگ بدنه","سوکت و پشتیبانی پردازنده در Mainboard","فقط اندازهٔ مانیتور"],"answer":1,"feedback":"سوکت، چیپ‌ست و در صورت نیاز Firmware باید پردازنده را پشتیبانی کنند.","mistake":"جاخوردن ظاهری برای سازگاری کافی نیست؛ اتصال الکتریکی و Firmware هم باید مناسب باشند."},"minutes":9,"editorial":true,"source":["Intel · PC platform specifications","https://www.intel.com/content/www/us/en/products/sku/218827/intel-q670-chipset/specifications.html"]},"k10-ittechnik/chipsatz":{"de":{"title":"Chipsatz","goal":"Du erklärst die Aufgabe des Chipsatzes und unterscheidest historische und moderne Anbindungen.","definition":"Der Chipsatz ergänzt die Verbindungen zwischen CPU und weiteren Geräten. Welche Funktionen in der CPU oder im Chipsatz liegen, hängt von der Plattform ab.","explanation":"Ein Chipsatz stellt zusätzliche Verbindungen zwischen Prozessor und Peripherie bereit. In älteren PC-Architekturen trennte man häufig Northbridge und Southbridge: Die Northbridge band schnelle Komponenten wie Speicher an, die Southbridge weitere Ein- und Ausgabefunktionen. Moderne CPUs enthalten typischerweise bereits den Speichercontroller und direkte PCIe-Verbindungen. Ein verbleibender Chipsatz, je nach Plattform etwa PCH genannt, ergänzt weitere USB-, SATA- oder PCIe-Anschlüsse. Er kommuniziert über eine eigene Verbindung mit der CPU. Mehr Anschlüsse am Board bedeuten daher nicht unbegrenzt unabhängige Bandbreite: Manche Geräte teilen Anbindung und Ressourcen. Für eine Erweiterung prüfst du das Blockdiagramm und die Hinweise des Mainboardherstellers.","example":"Bei einer bestimmten Plattform sind einige USB-Ports am Chipsatz und andere direkt an der CPU angebunden. Das Mainboard-Blockdiagramm zeigt die tatsächlichen Wege.","remember":["Chipsatz: Ergänzt die Anbindung von Ein- und Ausgabegeräten an die CPU.","Northbridge: Historische Komponente für schnelle Anbindungen.","Moderne CPUs besitzen oft direkte Speicher- und PCIe-Anbindungen. Nicht jede Verbindung läuft über den Chipsatz."],"summary":"CPU und Chipsatz teilen sich je nach Plattform die Anbindung von Speicher und Peripherie.","sections":[],"terms":[["Chipsatz","Ergänzt die Anbindung von Ein- und Ausgabegeräten an die CPU."],["Northbridge","Historische Komponente für schnelle Anbindungen."],["Southbridge","Historische Komponente für weitere Ein-/Ausgabefunktionen."],["Speichercontroller","Steuert den Zugriff auf den Arbeitsspeicher."]],"q":"Wo befindet sich der Speichercontroller bei vielen modernen PC-Prozessoren?","options":["Im Prozessor","Im Monitor","Im USB-Kabel"],"answer":0,"feedback":"Viele Aufgaben der früheren Northbridge wurden in die CPU integriert.","mistake":"Moderne CPUs besitzen oft direkte Speicher- und PCIe-Anbindungen. Nicht jede Verbindung läuft über den Chipsatz."},"fa":{"title":"چیپ‌ست","goal":"وظیفهٔ چیپ‌ست را توضیح می‌دهی و ارتباط قدیمی و امروزی اجزا را جدا می‌کنی.","definition":"چیپ‌ست ارتباط CPU با تجهیزات دیگر را تکمیل می‌کند؛ محل وظیفه‌ها در CPU یا چیپ‌ست به پلتفرم بستگی دارد.","explanation":"چیپ‌ست ارتباط‌های اضافی پردازنده با تجهیزات جانبی را فراهم می‌کند. در معماری قدیمی PC معمولاً Northbridge بخش‌های سریع مثل حافظه را متصل می‌کرد و Southbridge ورودی و خروجی‌های دیگر را مدیریت می‌کرد. در CPUهای جدید، کنترلر حافظه و بعضی مسیرهای PCIe معمولاً داخل خود پردازنده هستند. چیپ‌ست باقی‌مانده که در برخی پلتفرم‌ها PCH نام دارد، USB، SATA یا PCIe بیشتری اضافه می‌کند. این بخش با مسیر مخصوص به CPU وصل است. پس داشتن اتصال‌های بیشتر روی برد به معنی پهنای باند کاملاً مستقل و نامحدود نیست؛ بعضی دستگاه‌ها مسیر و منابع مشترک دارند. برای توسعهٔ سیستم، نمودار و راهنمای سازنده را بررسی کن.","example":"در یک پلتفرم مشخص، بعضی USBها از چیپ‌ست و بعضی مستقیم از CPU می‌آیند؛ نمودار Mainboard مسیر واقعی را نشان می‌دهد.","remember":["Chipsatz: ارتباط تجهیزات ورودی و خروجی با CPU را تکمیل می‌کند.","Northbridge: بخش قدیمی ارتباط با اجزای سریع.","CPU جدید معمولاً اتصال مستقیم حافظه و PCIe دارد؛ همهٔ مسیرها از چیپ‌ست نمی‌گذرند."],"summary":"CPU و چیپ‌ست بسته به پلتفرم ارتباط حافظه و تجهیزات جانبی را بین خود تقسیم می‌کنند.","sections":[],"terms":[["Chipsatz","ارتباط تجهیزات ورودی و خروجی با CPU را تکمیل می‌کند."],["Northbridge","بخش قدیمی ارتباط با اجزای سریع."],["Southbridge","بخش قدیمی برای ورودی و خروجی‌های دیگر."],["Speichercontroller","دسترسی به RAM را کنترل می‌کند."]],"q":"کنترلر RAM در بسیاری از پردازنده‌های جدید کجاست؟","options":["داخل پردازنده","داخل مانیتور","در کابل USB"],"answer":0,"feedback":"بسیاری از وظیفه‌های Northbridge قدیمی داخل CPU یکپارچه شده‌اند.","mistake":"CPU جدید معمولاً اتصال مستقیم حافظه و PCIe دارد؛ همهٔ مسیرها از چیپ‌ست نمی‌گذرند."},"minutes":9,"editorial":true,"source":["Intel · PC platform specifications","https://www.intel.com/content/www/us/en/products/sku/218827/intel-q670-chipset/specifications.html"]},"k10-ittechnik/schnittstellen":{"de":{"title":"PCIe und USB","goal":"Du erklärst PCIe-Lanes und unterscheidest USB-Steckerform von Übertragungseigenschaften.","definition":"PCIe verbindet schnelle Karten punktgenau mit Lanes. USB verbindet Geräte am Rand des Rechners. Die Form der Buchse sagt nicht automatisch die Geschwindigkeit.","explanation":"PCI Express verbindet Komponenten über serielle Punkt-zu-Punkt-Verbindungen. Eine Lane besitzt Sende- und Empfangswege; x1, x4 oder x16 beschreibt die Anzahl gebündelter Lanes. Generation und Lanezahl beeinflussen die mögliche Datenrate. Ein mechanischer x16-Steckplatz kann elektrisch weniger Lanes bereitstellen. USB verbindet externe Geräte und organisiert deren Kommunikation über einen Host und gegebenenfalls Hubs. USB-A und USB-C beschreiben zunächst Steckformen. Welche Geschwindigkeit, Ladeleistung oder Bildausgabe verfügbar ist, hängt von Port, Gerät, Kabel und unterstütztem Standard ab. Für einen Anschluss vergleichst du daher vier Dinge: physische Form, Protokoll, Leistung und benötigte Funktion. Ein passendes USB-C-Kabel kann sich von einem anderen funktional deutlich unterscheiden.","example":"Eine Grafikkarte sitzt in PCIe x16. Ein USB-Stick steckt außen in USB. Beides sind Anschlüsse, aber nicht dieselbe Busart.","remember":["PCIe-Lane: Serieller Sende- und Empfangspfad einer PCIe-Verbindung.","USB-Host: Steuert die Kommunikation mit USB-Geräten.","USB-C ist eine Steckform. Daraus lassen sich nicht automatisch maximale Geschwindigkeit oder Videoausgabe ableiten."],"summary":"PCIe verbindet über Lanes, USB über eine Hoststruktur; die Steckerform allein bestimmt nicht alle Funktionen.","sections":[],"terms":[["PCIe-Lane","Serieller Sende- und Empfangspfad einer PCIe-Verbindung."],["USB-Host","Steuert die Kommunikation mit USB-Geräten."],["USB-C","Bezeichnung einer Stecker- und Buchsenform."],["Bandbreite","Mögliche Datenmenge pro Zeit auf einer Verbindung."]],"q":"Ein Port hat USB-C-Form. Was weißt du sicher?","options":["Er liefert immer jede Videoausgabe","Er hat eine bestimmte Steckerform","Er ist immer gleich schnell"],"answer":1,"feedback":"Die Form allein legt Geschwindigkeit, Video und Ladeleistung nicht vollständig fest.","mistake":"USB-C ist eine Steckform. Daraus lassen sich nicht automatisch maximale Geschwindigkeit oder Videoausgabe ableiten."},"fa":{"title":"PCIe و USB","goal":"Laneهای PCIe را توضیح می‌دهی و شکل کانکتور USB را از قابلیت انتقال آن جدا می‌کنی.","definition":"PCIe کارت سریع را نقطه‌به‌نقطه با خط وصل می‌کند. USB دستگاه را در لبه رایانه وصل می‌کند. شکل سوکت خودکار سرعت را نمی‌گوید.","explanation":"PCI Express اجزا را با ارتباط سریال نقطه‌به‌نقطه وصل می‌کند. هر Lane مسیر ارسال و دریافت دارد؛ x1، x4 و x16 تعداد Laneهای کنار هم را نشان می‌دهند. نسل و تعداد Lane بر نرخ داده اثر دارند. شکاف با اندازهٔ فیزیکی x16 ممکن است از نظر الکتریکی Lane کمتری داشته باشد. USB وسیله‌های خارجی را وصل می‌کند و ارتباط را از طریق Host و در صورت نیاز Hub سازمان می‌دهد. USB-A و USB-C ابتدا شکل کانکتور را بیان می‌کنند. سرعت، توان شارژ یا خروجی تصویر به پورت، دستگاه، کابل و استاندارد پشتیبانی‌شده بستگی دارد. پس شکل، پروتکل، توان و قابلیت لازم را جدا بررسی کن. دو کابل USB-C با ظاهر مشابه ممکن است کارکرد متفاوتی داشته باشند.","example":"کارت گرافیک در PCIe x16 می‌نشیند. یک USB در USB بیرون فرو می‌رود. هر دو اتصال‌اند، ولی یک نوع گذرگاه نیستند.","remember":["PCIe-Lane: مسیر سریال ارسال و دریافت در PCIe.","USB-Host: ارتباط دستگاه‌های USB را کنترل می‌کند.","USB-C شکل کانکتور است؛ به‌تنهایی سرعت حداکثر یا خروجی تصویر را تضمین نمی‌کند."],"summary":"PCIe با Lane و USB با ساختار Host ارتباط می‌دهد؛ شکل کانکتور همهٔ قابلیت‌ها را تعیین نمی‌کند.","sections":[],"terms":[["PCIe-Lane","مسیر سریال ارسال و دریافت در PCIe."],["USB-Host","ارتباط دستگاه‌های USB را کنترل می‌کند."],["USB-C","نام شکل کانکتور و درگاه USB."],["Bandbreite","حجم دادهٔ قابل انتقال در واحد زمان."]],"q":"اگر درگاه شکل USB-C داشته باشد، چه چیزی قطعی است؟","options":["همیشه همهٔ خروجی‌های تصویر را دارد","شکل کانکتور آن مشخص است","همیشه سرعت یکسان دارد"],"answer":1,"feedback":"شکل به‌تنهایی سرعت، تصویر و توان شارژ را کامل مشخص نمی‌کند.","mistake":"USB-C شکل کانکتور است؛ به‌تنهایی سرعت حداکثر یا خروجی تصویر را تضمین نمی‌کند."},"minutes":9,"editorial":true,"source":["USB-IF · Type-C capabilities","https://www.usb.org/usb-type-cr-cable-and-connector-specification"]},"k10-fuit/geraete":{"de":{"title":"Geräte und Server","goal":"Du ordnest Switch, Router, Access Point und Serverrollen anhand ihrer Aufgaben ein.","definition":"Ein Switch verbindet Geräte im lokalen Netz. Ein Access Point hängt WLAN-Geräte an dieses Netz. Ein Router verbindet verschiedene IP-Netze.","explanation":"Ein Arbeitsplatz ist per Kabel am Switch angeschlossen. Der Switch verbindet die Geräte innerhalb desselben Ethernet-Netzes. Ein Notebook erreicht dieses Netz drahtlos über einen Access Point. Soll eine Verbindung in ein anderes IP-Netz gehen, übernimmt ein Router die Weiterleitung. Ein Server stellt einen bestimmten Dienst bereit: DNS liefert Informationen zu Namen, DHCP vergibt Netzwerkkonfigurationen, ein Dateiserver verwaltet gemeinsame Dateien. Der Begriff Server bezeichnet dabei zunächst eine Rolle; mehrere Dienste können auf derselben Maschine oder auf virtuellen Systemen laufen. Bei der Fehlersuche trennst du deshalb Verbindung und Dienst: Ein funktionierender WLAN-Link sagt noch nicht, ob die Anmeldung am Dateiserver funktioniert.","example":"Der Access Point im Klassenraum gibt WLAN. Der Router am Standort verbindet dieses LAN mit einem anderen Netz. Der DHCP-Server verteilt die Adressen, der Access Point tut das nicht von allein.","remember":["Switch: Verbindet Geräte in einem lokalen Ethernet-Netz.","Router: Leitet IP-Pakete zwischen IP-Netzen weiter.","Ein Access Point stellt WLAN bereit. Ob dasselbe Gerät auch Routing oder DHCP anbietet, hängt von seiner Ausstattung ab."],"summary":"Switch, Access Point, Router und Serverdienst erfüllen unterschiedliche, kombinierbare Aufgaben im Netz.","sections":[],"terms":[["Switch","Verbindet Geräte in einem lokalen Ethernet-Netz."],["Router","Leitet IP-Pakete zwischen IP-Netzen weiter."],["Access Point","Stellt den drahtlosen Zugang zum Netz bereit."],["Serverdienst","Funktion, die ein System anderen Systemen anbietet."],["DHCP","Protokoll zur automatischen Vergabe von Netzwerkkonfiguration."]],"q":"Welches Gerät verbindet normalerweise unterschiedliche IP-Netze?","options":["Switch ohne Routing","Router","USB-Hub"],"answer":1,"feedback":"Der Router entscheidet anhand der Ziel-IP und seiner Routingtabelle über den nächsten Weg.","mistake":"Ein Access Point stellt WLAN bereit. Ob dasselbe Gerät auch Routing oder DHCP anbietet, hängt von seiner Ausstattung ab."},"fa":{"title":"دستگاه و سرور","goal":"سوئیچ، روتر، Access Point و نقش‌های سرور را بر اساس وظیفه تشخیص می‌دهی.","definition":"سوئیچ دستگاه‌ها را در شبکه محلی وصل می‌کند. نقطه دسترسی دستگاه‌های WLAN را به همان شبکه می‌آورد. مسیریاب شبکه‌های IP متفاوت را وصل می‌کند.","explanation":"یک کامپیوتر با کابل به سوئیچ وصل است. سوئیچ دستگاه‌های داخل یک شبکهٔ Ethernet را به هم متصل می‌کند. لپ‌تاپ با ارتباط بی‌سیم از طریق Access Point وارد همین شبکه می‌شود. اگر مقصد در شبکهٔ IP دیگری باشد، روتر داده را به آن مسیر می‌دهد. سرور یک خدمت مشخص ارائه می‌کند: DNS اطلاعات نام‌ها را می‌دهد، DHCP تنظیمات شبکه را توزیع می‌کند و فایل‌سرور فایل‌های مشترک را مدیریت می‌کند. Server ابتدا نام یک نقش است؛ چند سرویس می‌توانند روی یک دستگاه یا سیستم مجازی اجرا شوند. در عیب‌یابی، اتصال را از سرویس جدا کن: وصل‌بودن WLAN هنوز به معنای موفق‌بودن ورود به فایل‌سرور نیست.","example":"نقطه دسترسی در کلاس WLAN می‌دهد. مسیریاب محل این LAN را به شبکه دیگری وصل می‌کند. سرور DHCP نشانی را پخش می‌کند. نقطه دسترسی خودش این کار را نمی‌کند.","remember":["Switch: دستگاه‌های شبکهٔ محلی Ethernet را به هم وصل می‌کند.","Router: بسته‌های IP را بین شبکه‌ها هدایت می‌کند.","Access Point دسترسی WLAN می‌دهد؛ Routing یا DHCP بودن همان دستگاه به قابلیت‌های آن بستگی دارد."],"summary":"سوئیچ، Access Point، روتر و سرویس سرور وظیفه‌های متفاوت و قابل ترکیب در شبکه دارند.","sections":[],"terms":[["Switch","دستگاه‌های شبکهٔ محلی Ethernet را به هم وصل می‌کند."],["Router","بسته‌های IP را بین شبکه‌ها هدایت می‌کند."],["Access Point","دسترسی بی‌سیم به شبکه را فراهم می‌کند."],["Serverdienst","قابلیتی که یک سیستم به سیستم‌های دیگر ارائه می‌کند."],["DHCP","پروتکل تنظیم خودکار شبکه."]],"q":"کدام دستگاه معمولاً شبکه‌های IP متفاوت را متصل می‌کند؟","options":["سوئیچ بدون Routing","روتر","USB Hub"],"answer":1,"feedback":"روتر با IP مقصد و جدول مسیریابی، مسیر بعدی را انتخاب می‌کند.","mistake":"Access Point دسترسی WLAN می‌دهد؛ Routing یا DHCP بودن همان دستگاه به قابلیت‌های آن بستگی دارد."},"minutes":9,"editorial":true,"source":["Cisco · TCP/IP overview","https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13769-5.pdf"]},"k10-fuit/netzarten":{"de":{"title":"Reichweite der Netze","goal":"Du unterscheidest Netzarten nach räumlicher Ausdehnung und wählst passende Beispiele.","definition":"Der Name eines Netzes sagt, welchen Raum es überspannt: Körper, Person, Raum, Gelände, Stadt, weit oder weltweit.","explanation":"PAN steht für Personal Area Network: Geräte rund um eine Person, zum Beispiel Telefon und Bluetooth-Kopfhörer. Ein LAN verbindet lokal Geräte in einem Haushalt, Büro oder Gebäude; WLAN bezeichnet eine drahtlose LAN-Technik. Ein Campusnetz verbindet mehrere Gebäude eines Standorts und wird im passenden Kontext als CAN bezeichnet. Ein MAN umfasst ein städtisches Gebiet, ein WAN verbindet entfernte Standorte über größere geografische Räume. Diese Namen sind Größenordnungen und keine exakten Metergrenzen. Im Unternehmen können sie zusammenarbeiten: Zwei Standorte besitzen je ein LAN; die Verbindung zwischen ihnen gehört zum WAN. Unterscheide zusätzlich den Zugang: Ein lokales Netz kann sowohl kabelgebundene als auch drahtlose Abschnitte haben.","example":"Ein Büronetz ist ein LAN. Mehrere Campusgebäude können ein gemeinsames Campusnetz bilden. Die Verbindung zu einer weit entfernten Niederlassung wird über ein WAN organisiert.","remember":["PAN: Netz im persönlichen Umfeld einer Person.","LAN: Lokales Netzwerk in einem begrenzten Gebiet.","LAN und WLAN unterscheiden sich nicht nur in der Größe: WLAN beschreibt den drahtlosen Zugang."],"summary":"Netzarten beschreiben Einsatzraum und Ausdehnung; die Zugangstechnik ist eine zusätzliche Eigenschaft.","sections":[],"terms":[["PAN","Netz im persönlichen Umfeld einer Person."],["LAN","Lokales Netzwerk in einem begrenzten Gebiet."],["WLAN","Drahtlose Vernetzung in einem lokalen Netz."],["WAN","Netzverbindung über große geografische Entfernungen."],["Campusnetz","Verbindet mehrere Gebäude eines Standorts."]],"q":"Zwei weit entfernte Firmenstandorte werden verbunden. Welche Bezeichnung passt?","options":["PAN","WAN","Nur USB"],"answer":1,"feedback":"Die standortübergreifende Verbindung ist ein typischer WAN-Einsatz.","mistake":"LAN und WLAN unterscheiden sich nicht nur in der Größe: WLAN beschreibt den drahtlosen Zugang."},"fa":{"title":"برد شبکه","goal":"نوع شبکه‌ها را بر اساس وسعت تشخیص می‌دهی و مثال مناسب می‌آوری.","definition":"نام شبکه می‌گوید کدام فضا را می‌پوشاند: بدن، شخص، اتاق، محوطه، شهر، فاصله دور یا جهان.","explanation":"PAN شبکهٔ اطراف یک فرد است؛ مثلاً موبایل و هدفون Bluetooth. LAN دستگاه‌های یک خانه، دفتر یا ساختمان را محلی متصل می‌کند. WLAN روش بی‌سیم برای LAN است. شبکهٔ Campus چند ساختمان یک محل را وصل می‌کند و در این معنا CAN گفته می‌شود. MAN محدودهٔ شهری را پوشش می‌دهد و WAN محل‌های دور را در منطقه‌های بزرگ‌تر متصل می‌کند. این نام‌ها اندازه‌های تقریبی‌اند، نه مرز متری دقیق. در یک شرکت، دو شعبه می‌توانند هر کدام LAN داشته باشند و ارتباط بین آن‌ها بخشی از WAN باشد. نوع دسترسی را هم جدا بررسی کن: یک شبکهٔ محلی می‌تواند قسمت کابلی و بی‌سیم داشته باشد.","example":"شبکهٔ دفتر LAN است. چند ساختمان یک Campus می‌توانند شبکهٔ Campus بسازند. ارتباط شعبهٔ دور از طریق WAN انجام می‌شود.","remember":["PAN: شبکهٔ محدودهٔ شخصی یک فرد.","LAN: شبکهٔ محلی در محدودهٔ محدود.","تفاوت LAN و WLAN فقط اندازه نیست؛ WLAN روش بی‌سیم دسترسی را بیان می‌کند."],"summary":"نوع شبکه محدوده و کاربرد را نشان می‌دهد؛ روش دسترسی ویژگی جداگانه است.","sections":[],"terms":[["PAN","شبکهٔ محدودهٔ شخصی یک فرد."],["LAN","شبکهٔ محلی در محدودهٔ محدود."],["WLAN","اتصال بی‌سیم در شبکهٔ محلی."],["WAN","شبکه برای فاصله‌های جغرافیایی زیاد."],["Campusnetz","شبکهٔ اتصال چند ساختمان در یک محل."]],"q":"دو شعبهٔ دور از هم متصل می‌شوند؛ کدام نام مناسب است؟","options":["PAN","WAN","فقط USB"],"answer":1,"feedback":"اتصال بین شعبه‌های دور، کاربرد معمول WAN است.","mistake":"تفاوت LAN و WLAN فقط اندازه نیست؛ WLAN روش بی‌سیم دسترسی را بیان می‌کند."},"minutes":9,"editorial":true,"source":["Cisco · TCP/IP overview","https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13769-5.pdf"]},"k10-fuit/osi":{"de":{"title":"OSI als Landkarte","goal":"Du nennst die sieben OSI-Schichten von 7 bis 1 und erklärst Aufgabe und Beispiel jeder Schicht.","definition":"Das OSI-Modell teilt die Kommunikation in sieben Schichten, damit jede Schicht nur ihre eigene Aufgabe hat.","explanation":"Das OSI-Modell ist ein Referenzmodell für Netzwerkkommunikation. Es teilt eine komplexe Übertragung in sieben Aufgabenbereiche. Jede Schicht nutzt Leistungen der darunterliegenden Schicht und bietet der darüberliegenden Schicht Leistungen an. Beim Senden kann man den Weg von Anwendung zu Signalen, also von 7 nach 1, verfolgen. Beim Empfangen wird die Information in umgekehrter Richtung verarbeitet. Das Modell hilft beim Lernen, beim Beschreiben von Schnittstellen und bei der Fehlersuche. Reale Internetprotokolle folgen meist dem TCP/IP-Modell; deshalb passt nicht jede konkrete Funktion eindeutig in genau eine OSI-Schicht. Die folgende Reihenfolge zeigt die Aufgaben von oben nach unten.","example":"Eine IP-Adresse gehört zur Vermittlung. Die MAC-Adresse gehört zur Sicherung. Das Kabel gehört zur Bitübertragung.","remember":["Sieben Schichten, jede mit einer Aufgabe.","IP sucht den Weg, MAC den nächsten Hop.","Das Modell ist eine Landkarte, kein Gerät."],"summary":"Sieben Schichten gliedern die Kommunikation von Anwendungsdiensten über Transport und Routing bis zu lokalen Rahmen und Signalen.","sections":[{"title":"7 · Anwendungsschicht – Application","body":"Stellt anwendungsnahe Netzwerkfunktionen bereit. HTTP beschreibt beispielsweise die Kommunikation für Webinhalte, DNS die Abfrage von Namensinformationen. Der Browser nutzt solche Dienste; seine gesamte Benutzeroberfläche ist nicht selbst die OSI-Schicht."},{"title":"6 · Darstellungsschicht – Presentation","body":"Beschäftigt sich mit der Darstellung der Daten: Wie werden Zeichen codiert, Daten formatiert oder komprimiert? Verschlüsselung ist ebenfalls eine typische Modellaufgabe. In realen Protokollstapeln können diese Funktionen an verschiedenen Stellen umgesetzt sein."},{"title":"5 · Sitzungsschicht – Session","body":"Organisiert den Dialog zwischen Kommunikationspartnern, zum Beispiel Aufbau, Verwaltung und geordneten Abschluss einer Sitzung. Eine Benutzersitzung in einer Webanwendung ist jedoch nicht automatisch dasselbe wie eine eigenständige OSI-Schicht-5-Implementierung."},{"title":"4 · Transportschicht – Transport","body":"Stellt die Kommunikation zwischen Endpunkten bereit. TCP bietet einen zuverlässigen, geordneten Bytestrom; UDP versendet Datagramme ohne diese eingebauten Zusicherungen. Ports helfen, Daten dem passenden Dienst oder Prozess zuzuordnen."},{"title":"3 · Vermittlungsschicht – Network","body":"Adressiert und leitet Pakete über Netzgrenzen weiter. Bei IP betrachtet ein Router die Zieladresse und wählt mit seiner Routingtabelle den nächsten Weg. Er kann mehrere lokale Netze miteinander verbinden."},{"title":"2 · Sicherungsschicht – Data Link","body":"Überträgt Rahmen über einen lokalen Verbindungsabschnitt. Ethernet verwendet unter anderem MAC-Adressen. Ein Layer-2-Switch lernt, an welchem Port eine MAC-Adresse erreichbar ist, und leitet entsprechende Rahmen weiter."},{"title":"1 · Bitübertragungsschicht – Physical","body":"Überträgt Bits als elektrische, optische oder Funksignale. Dazu gehören Eigenschaften von Medium, Steckern, Signalpegeln und Übertragungsrate. Ein nicht eingestecktes Kabel ist ein naheliegendes Problem dieses Bereichs."}],"terms":[["Application","Schicht 7: anwendungsnahe Netzwerkdienste, etwa HTTP oder DNS."],["Transport","Schicht 4: Kommunikation zwischen Endpunkten, etwa mit TCP oder UDP."],["Network","Schicht 3: logische Adressierung und Weiterleitung zwischen Netzen."],["Data Link","Schicht 2: lokale Übertragung von Rahmen, zum Beispiel Ethernet."],["Physical","Schicht 1: Übertragung von Bits als Signale."]],"q":"Welche Schicht übernimmt die Weiterleitung zwischen IP-Netzen?","options":["Schicht 7 – Anwendung","Schicht 3 – Vermittlung","Schicht 1 – Bitübertragung"],"answer":1,"feedback":"IP-Adressierung und Routing gehören zur Vermittlungsschicht.","mistake":"Das Modell beschreibt Aufgaben. Ein Gerät oder Protokoll kann Funktionen mehrerer Schichten erfüllen. Ein erfolgreicher Ping beweist nicht, dass jede höhere Schicht fehlerfrei ist."},"fa":{"title":"OSI به‌عنوان نقشه","goal":"هفت لایهٔ OSI را از ۷ تا ۱ نام می‌بری و وظیفه و مثال هر لایه را می‌فهمی.","definition":"مدل OSI ارتباط را به هفت لایه تقسیم می‌کند تا هر لایه فقط کار خودش را داشته باشد.","explanation":"مدل OSI یک مدل مرجع برای ارتباط شبکه است. انتقال پیچیدهٔ داده را به هفت حوزهٔ وظیفه تقسیم می‌کند. هر لایه از خدمات لایهٔ پایین‌تر استفاده می‌کند و به لایهٔ بالاتر خدمت می‌دهد. هنگام ارسال، مسیر از برنامه تا سیگنال یعنی از لایهٔ ۷ به ۱ است. هنگام دریافت، داده در جهت عکس پردازش می‌شود. این مدل برای یادگیری، توضیح رابط‌ها و عیب‌یابی مفید است. پروتکل‌های واقعی اینترنت بیشتر بر مدل TCP/IP تکیه دارند؛ پس هر قابلیت واقعی همیشه دقیقاً داخل یک لایهٔ OSI قرار نمی‌گیرد. ترتیب زیر وظیفه‌ها را از بالا به پایین نشان می‌دهد.","example":"نشانی IP مال لایه شبکه است. نشانی MAC مال پیوند داده است. کابل مال لایه فیزیکی است.","remember":["هفت لایه، هرکدام یک کار.","IP راه را پیدا می‌کند، MAC پرش بعدی را.","مدل نقشه است، نه دستگاه."],"summary":"هفت لایه ارتباط را از خدمات برنامه، انتقال و مسیریابی تا فریم محلی و سیگنال تقسیم می‌کنند.","sections":[{"title":"۷ · لایهٔ کاربرد – Application","body":"خدمات شبکهٔ نزدیک به برنامه را فراهم می‌کند. HTTP ارتباط محتوای وب و DNS پرس‌وجوی اطلاعات نام را مشخص می‌کند. مرورگر از این خدمات استفاده می‌کند؛ کل رابط ظاهری مرورگر خودِ این لایه نیست."},{"title":"۶ · لایهٔ نمایش – Presentation","body":"با شکل نمایش داده کار دارد: کاراکترها چگونه کدگذاری و داده‌ها چگونه قالب‌بندی یا فشرده می‌شوند؟ رمزگذاری نیز از وظیفه‌های معمول این لایه در مدل است. در پیاده‌سازی واقعی، این کارها ممکن است در بخش‌های مختلف انجام شوند."},{"title":"۵ · لایهٔ نشست – Session","body":"گفت‌وگو بین دو طرف ارتباط را سازمان می‌دهد؛ مثل ایجاد، مدیریت و پایان منظم نشست. هر نشست کاربری در یک وب‌سایت لزوماً به معنای وجود پیاده‌سازی مستقل لایهٔ ۵ نیست."},{"title":"۴ · لایهٔ انتقال – Transport","body":"ارتباط بین دو انتها را فراهم می‌کند. TCP جریان بایت مرتب و قابل اعتماد ارائه می‌دهد. UDP دیتاگرام را بدون این تضمین‌های داخلی می‌فرستد. Port کمک می‌کند داده به سرویس یا فرایند مناسب برسد."},{"title":"۳ · لایهٔ شبکه – Network","body":"بسته‌ها را آدرس‌دهی و از مرز شبکه‌ها عبور می‌دهد. در IP، روتر آدرس مقصد را بررسی می‌کند و با جدول مسیریابی مسیر بعدی را انتخاب می‌کند. به این شکل چند شبکهٔ محلی متصل می‌شوند."},{"title":"۲ · لایهٔ پیوند داده – Data Link","body":"فریم را در یک بخش ارتباط محلی منتقل می‌کند. Ethernet از MAC Address استفاده می‌کند. سوئیچ لایهٔ ۲ یاد می‌گیرد هر MAC از کدام Port قابل دسترس است و فریم را هدایت می‌کند."},{"title":"۱ · لایهٔ فیزیکی – Physical","body":"بیت‌ها را به شکل سیگنال الکتریکی، نوری یا رادیویی منتقل می‌کند. ویژگی رسانه، کانکتور، سطح سیگنال و نرخ انتقال به این بخش مربوط‌اند. کابل وصل‌نشده نمونهٔ سادهٔ مشکل این لایه است."}],"terms":[["Application","لایهٔ ۷؛ خدمات نزدیک به برنامه مثل HTTP و DNS."],["Transport","لایهٔ ۴؛ ارتباط بین دو انتها مثل TCP یا UDP."],["Network","لایهٔ ۳؛ آدرس‌دهی منطقی و هدایت بین شبکه‌ها."],["Data Link","لایهٔ ۲؛ انتقال فریم در ارتباط محلی مثل Ethernet."],["Physical","لایهٔ ۱؛ انتقال بیت‌ها به شکل سیگنال."]],"q":"هدایت بین شبکه‌های IP وظیفهٔ کدام لایه است؟","options":["لایهٔ ۷؛ کاربرد","لایهٔ ۳؛ شبکه","لایهٔ ۱؛ فیزیکی"],"answer":1,"feedback":"آدرس‌دهی IP و Routing به لایهٔ شبکه یا Vermittlung تعلق دارند.","mistake":"مدل وظیفه‌ها را نشان می‌دهد. یک دستگاه یا پروتکل ممکن است کار چند لایه را انجام دهد. موفق‌بودن Ping سالم‌بودن همهٔ لایه‌های بالاتر را ثابت نمی‌کند."},"minutes":14,"editorial":true,"source":["Cisco · TCP/IP und OSI","https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13769-5.pdf"]},"k10-fuit/kopplung":{"de":{"title":"Repeater, Hub, Bridge, Switch","goal":"Du unterscheidest Repeater, Hub, Bridge und Switch nach Signalverarbeitung und Weiterleitung.","definition":"Ein Repeater frischt das Signal auf. Ein Hub ist ein Repeater mit mehreren Ports. Eine Bridge trennt anhand der MAC-Adresse. Ein Switch ist eine Bridge mit vielen Ports.","explanation":"Repeater regenerieren Signale auf der Bitübertragungsebene. Ein klassischer Hub arbeitet ähnlich mit mehreren Anschlüssen und gibt eingehende Signale an andere Ports weiter. Eine Bridge verarbeitet dagegen Datenrahmen der Sicherungsschicht. Sie lernt aus der Quell-MAC-Adresse, über welchen Anschluss ein Gerät erreichbar ist. Ein Switch nutzt dieses Prinzip mit vielen Ports. Kennt er die Ziel-MAC, kann er einen Unicast-Rahmen gezielt an den passenden Port senden. Unbekannte Unicast-Rahmen und Broadcasts werden im jeweiligen VLAN an andere geeignete Ports weitergegeben. Das heißt nicht, dass jeder Rahmen immer an alle Ports geht. Für die Kommunikation zwischen verschiedenen IP-Subnetzen ist zusätzlich Routing erforderlich.","example":"Ein bekannter Unicast-Rahmen geht beim Switch an den gelernten Zielport. Ein Broadcast wird innerhalb des VLANs an die anderen geeigneten Ports weitergegeben.","remember":["Repeater: Regeneriert Signale auf Schicht 1.","Hub: Mehrport-Repeater für ein geteiltes Übertragungsmedium.","Ein Switch sendet nicht jeden Rahmen gezielt: Unbekannte Ziele und Broadcasts müssen passend weiterverteilt werden."],"summary":"Repeater und Hub arbeiten mit Signalen, Bridge und Switch treffen Weiterleitungsentscheidungen anhand von Rahmenadressen.","sections":[],"terms":[["Repeater","Regeneriert Signale auf Schicht 1."],["Hub","Mehrport-Repeater für ein geteiltes Übertragungsmedium."],["Bridge","Verbindet Segmente und entscheidet anhand von MAC-Adressen."],["MAC-Tabelle","Zuordnung gelernter MAC-Adressen zu Switchports."]],"q":"Woraus lernt ein Switch seine MAC-Tabelle?","options":["Aus der Quell-MAC eingehender Rahmen","Aus der Farbe des Kabels","Nur aus der Ziel-Portnummer von TCP"],"answer":0,"feedback":"Der Eingangsport und die Quell-MAC zeigen, wo der Sender erreichbar ist.","mistake":"Ein Switch sendet nicht jeden Rahmen gezielt: Unbekannte Ziele und Broadcasts müssen passend weiterverteilt werden."},"fa":{"title":"تکرارگر، هاب، پل، سوئیچ","goal":"Repeater، Hub، Bridge و Switch را از نظر سیگنال و هدایت داده جدا می‌کنی.","definition":"تکرارگر سیگنال را تازه می‌کند. هاب تکرارگری با چند درگاه است. پل ترافیک را با نشانی MAC جدا می‌کند. سوئیچ پلی با درگاه‌های زیاد است.","explanation":"Repeater سیگنال را در لایهٔ فیزیکی بازسازی می‌کند. Hub قدیمی همین کار را با چند پورت انجام می‌دهد و سیگنال ورودی را به پورت‌های دیگر می‌فرستد. Bridge در مقابل فریم لایهٔ پیوند داده را بررسی می‌کند. از MAC مبدأ یاد می‌گیرد یک دستگاه از کدام اتصال قابل دسترس است. Switch همین اصل را با پورت‌های بیشتر به کار می‌برد. اگر MAC مقصد را بشناسد، فریم Unicast را هدفمند به پورت مناسب می‌فرستد. فریم Unicast ناشناخته و Broadcast در همان VLAN به پورت‌های مناسب دیگر ارسال می‌شوند. پس هر فریم همیشه به همهٔ پورت‌ها نمی‌رود. برای ارتباط بین زیرشبکه‌های IP متفاوت، Routing هم لازم است.","example":"سوئیچ فریم Unicast با مقصد شناخته‌شده را به پورت یادگرفته‌شده می‌فرستد؛ Broadcast در همان VLAN به پورت‌های مناسب دیگر ارسال می‌شود.","remember":["Repeater: سیگنال لایهٔ ۱ را بازسازی می‌کند.","Hub: Repeater چندپورتی برای رسانهٔ اشتراکی.","سوئیچ همهٔ فریم‌ها را هدفمند نمی‌فرستد؛ مقصد ناشناخته و Broadcast باید مناسب پخش شوند."],"summary":"Repeater و Hub با سیگنال کار می‌کنند؛ Bridge و Switch با آدرس فریم دربارهٔ هدایت تصمیم می‌گیرند.","sections":[],"terms":[["Repeater","سیگنال لایهٔ ۱ را بازسازی می‌کند."],["Hub","Repeater چندپورتی برای رسانهٔ اشتراکی."],["Bridge","بخش‌ها را با تصمیم بر اساس MAC وصل می‌کند."],["MAC-Tabelle","جدول ارتباط MACهای یادگرفته‌شده با پورت‌های سوئیچ."]],"q":"سوئیچ جدول MAC را از چه چیزی یاد می‌گیرد؟","options":["MAC مبدأ فریم‌های ورودی","رنگ کابل","فقط شمارهٔ Port پروتکل TCP"],"answer":0,"feedback":"پورت ورودی و MAC مبدأ نشان می‌دهند فرستنده از کجا قابل دسترس است.","mistake":"سوئیچ همهٔ فریم‌ها را هدفمند نمی‌فرستد؛ مقصد ناشناخته و Broadcast باید مناسب پخش شوند."},"minutes":9,"editorial":true,"source":["Cisco · TCP/IP overview","https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13769-5.pdf"]},"k10-fuit/verkabelung":{"de":{"title":"Kupfer, Glas und Struktur","goal":"Du erklärst Kupfer und Glasfaser und ordnest Primär-, Sekundär- und Tertiärverkabelung zu.","definition":"Kupferkabel tragen elektrische Signale auf der Etage. Glasfasern tragen Licht über längere Strecken. Die Verkabelung eines Geländes ist in drei Ebenen gegliedert.","explanation":"Eine strukturierte Verkabelung organisiert Leitungswege unabhängig von einem einzelnen Arbeitsplatz. Die Primärebene verbindet Gebäude auf einem Gelände. Die Sekundärebene verbindet Verteiler innerhalb eines Gebäudes, etwa zwischen Etagen. Die Tertiärebene führt vom Etagenverteiler zur Anschlussdose am Arbeitsplatz. Kupfer überträgt elektrische Signale und ist in der Arbeitsplatzverkabelung verbreitet. Glasfaser überträgt Licht und ist gegen elektromagnetische Störungen unempfindlich. Singlemode und Multimode unterscheiden sich durch Faseraufbau und unterstützte Übertragungsarten. Eine Reichweite lässt sich nur zusammen mit Faserklasse, Transceiver, Datenrate und Norm sinnvoll angeben. Für die Planung prüfst du daher nicht nur die Entfernung, sondern auch Dämpfung, Stecker und benötigte Geschwindigkeit.","example":"Vom Etagenverteiler zur Dose im Raum liegt Tertiär, oft Kupfer. Zwischen zwei Gebäuden auf dem Gelände liegt Primär, oft Glas.","remember":["Primärverkabelung: Verbindet Gebäude eines Geländes.","Sekundärverkabelung: Verbindet Verteiler innerhalb eines Gebäudes.","Glasfaser besitzt keine allgemeingültige feste Reichweite; Faser, Optik, Datenrate und Dämpfung gehören zusammen."],"summary":"Strukturierte Verkabelung trennt Gelände, Gebäude und Etage und wählt das Medium nach den technischen Anforderungen.","sections":[],"terms":[["Primärverkabelung","Verbindet Gebäude eines Geländes."],["Sekundärverkabelung","Verbindet Verteiler innerhalb eines Gebäudes."],["Tertiärverkabelung","Verbindung vom Etagenverteiler zum Arbeitsplatzanschluss."],["Dämpfung","Abschwächung eines Signals auf dem Übertragungsweg."]],"q":"Welche Ebene führt vom Etagenverteiler zur Arbeitsplatzdose?","options":["Primär","Sekundär","Tertiär"],"answer":2,"feedback":"Die Tertiärebene verteilt die Anschlüsse innerhalb der Etage.","mistake":"Glasfaser besitzt keine allgemeingültige feste Reichweite; Faser, Optik, Datenrate und Dämpfung gehören zusammen."},"fa":{"title":"مس، فیبر و ساختار","goal":"کابل مسی و فیبر نوری را توضیح می‌دهی و سه سطح کابل‌کشی را تشخیص می‌دهی.","definition":"کابل مس سیگنال الکتریکی را در طبقه می‌برد. فیبر نور را در فاصله بلندتر می‌برد. کابل‌کشی یک محوطه به سه سطح تقسیم می‌شود.","explanation":"کابل‌کشی ساختاریافته مسیرها را مستقل از یک میز کار مشخص سازمان می‌دهد. سطح اول یا Primär ساختمان‌های یک محوطه را وصل می‌کند. سطح دوم یا Sekundär توزیع‌کننده‌های داخل ساختمان، مثلاً طبقه‌ها را به هم وصل می‌کند. سطح سوم یا Tertiär از توزیع‌کنندهٔ طبقه به پریز محل کار می‌رود. مس سیگنال الکتریکی منتقل می‌کند و برای محل کار رایج است. فیبر نوری نور منتقل می‌کند و از اختلال الکترومغناطیسی تأثیر نمی‌گیرد. Singlemode و Multimode در ساختار فیبر و روش انتقال فرق دارند. برد را فقط همراه نوع فیبر، فرستنده‌گیرنده، سرعت و استاندارد می‌توان درست گفت. پس در طراحی، علاوه بر فاصله، افت سیگنال، کانکتور و سرعت لازم را هم بررسی کن.","example":"از توزیع‌کننده طبقه تا پریز اتاق سطح سوم است، اغلب مس. بین دو ساختمان در محوطه سطح اول است، اغلب فیبر.","remember":["Primärverkabelung: کابل‌کشی بین ساختمان‌های یک محوطه.","Sekundärverkabelung: اتصال توزیع‌کننده‌ها در داخل ساختمان.","فیبر برد ثابت همگانی ندارد؛ نوع فیبر، تجهیزات نوری، سرعت و افت سیگنال مهم‌اند."],"summary":"کابل‌کشی ساختاریافته محوطه، ساختمان و طبقه را جدا و رسانه را با نیاز فنی انتخاب می‌کند.","sections":[],"terms":[["Primärverkabelung","کابل‌کشی بین ساختمان‌های یک محوطه."],["Sekundärverkabelung","اتصال توزیع‌کننده‌ها در داخل ساختمان."],["Tertiärverkabelung","اتصال توزیع‌کنندهٔ طبقه به پریز محل کار."],["Dämpfung","کاهش قدرت سیگنال در مسیر انتقال."]],"q":"اتصال توزیع‌کنندهٔ طبقه به پریز میز کار کدام سطح است؟","options":["Primär","Sekundär","Tertiär"],"answer":2,"feedback":"سطح Tertiär اتصال‌ها را در همان طبقه توزیع می‌کند.","mistake":"فیبر برد ثابت همگانی ندارد؛ نوع فیبر، تجهیزات نوری، سرعت و افت سیگنال مهم‌اند."},"minutes":9,"editorial":true,"source":["Cisco · TCP/IP overview","https://www.cisco.com/c/en/us/support/docs/ip/routing-information-protocol-rip/13769-5.pdf"]},"k10-englisch/ausbildung":{"de":{"title":"Wörter der Ausbildung","goal":"Du stellst deine Ausbildung mit passenden englischen Begriffen in vollständigen Sätzen vor.","definition":"Diese Wörter beschreiben das duale System auf Englisch: Betrieb, Schule, Vertrag und die Personen.","explanation":"Einzelne Übersetzungen helfen erst, wenn du sie in einer Situation verwenden kannst. Beginne mit deiner Rolle: I am an apprentice in IT systems integration. Danach beschreibst du die Lernorte: I work at a company and attend vocational school. Nenne anschließend eine Aufgabe, zum Beispiel I help configure computers and support users. Apprentice bezeichnet eine Person in einer geregelten Ausbildung; trainee kann je nach Kontext auch andere Einarbeitungs- oder Ausbildungsrollen meinen. Trainer ist die ausbildende Person, training contract der Ausbildungsvertrag. Übe eine Vorstellung mit vier Sätzen: Person, Ausbildung, Lernorte und typische Aufgabe. Wähle verständliche Begriffe, statt die deutsche Berufsbezeichnung ohne Erklärung Wort für Wort zu übersetzen.","example":"“The trainee works a morning shift in the workshop and goes to vocational school on Tuesday.”","remember":["Apprentice: Person in einer geregelten Berufsausbildung.","Vocational school: Berufsschule.","Trainee und apprentice sind je nach Kontext nicht vollständig austauschbar."],"summary":"Mit passenden englischen Ausbildungsbegriffen kannst du Rolle, Lernorte und Aufgaben verständlich vorstellen.","sections":[],"terms":[["Apprentice","Person in einer geregelten Berufsausbildung."],["Vocational school","Berufsschule."],["Training contract","Ausbildungsvertrag."],["Department","Abteilung eines Unternehmens."]],"q":"Was bedeutet vocational school?","options":["Berufsschule","Lager","Urlaubsreise"],"answer":0,"feedback":"Vocational bezeichnet den Bezug zu einem Beruf; vocational school ist die Berufsschule.","mistake":"Trainee und apprentice sind je nach Kontext nicht vollständig austauschbar."},"fa":{"title":"واژه‌های کارآموزی","goal":"آموزش حرفه‌ای خودت را با واژه‌های انگلیسی و جمله‌های کامل معرفی می‌کنی.","definition":"این واژه‌ها نظام دوگانه را به انگلیسی توصیف می‌کنند: شرکت، مدرسه، قرارداد و اشخاص.","explanation":"ترجمهٔ تکی وقتی مفید است که در موقعیت واقعی از آن استفاده کنی. اول نقش خود را بگو: I am an apprentice in IT systems integration. بعد محل‌های یادگیری را توضیح بده: I work at a company and attend vocational school. سپس یک وظیفه بگو: I help configure computers and support users. واژهٔ apprentice فرد در آموزش حرفه‌ای رسمی را می‌رساند؛ trainee بسته به زمینه می‌تواند نقش‌های آموزشی دیگری هم باشد. Trainer مربی و training contract قرارداد آموزش است. معرفی چهار جمله‌ای تمرین کن: شخص، حرفه، محل‌های یادگیری و کار معمول. به‌جای ترجمهٔ کلمه‌به‌کلمهٔ عنوان آلمانی، واژهٔ روشن انتخاب کن.","example":"“The trainee works a morning shift in the workshop and goes to vocational school on Tuesday.”","remember":["Apprentice: فرد در آموزش حرفه‌ای رسمی.","Vocational school: مدرسهٔ حرفه‌ای یا Berufsschule.","Trainee و Apprentice بسته به زمینه همیشه قابل جایگزینی کامل نیستند."],"summary":"با واژه‌های مناسب انگلیسی می‌توانی نقش، محل آموزش و کارها را روشن معرفی کنی.","sections":[],"terms":[["Apprentice","فرد در آموزش حرفه‌ای رسمی."],["Vocational school","مدرسهٔ حرفه‌ای یا Berufsschule."],["Training contract","قرارداد آموزش حرفه‌ای."],["Department","بخش یک شرکت."]],"q":"Vocational school یعنی چه؟","options":["مدرسهٔ حرفه‌ای","انبار","سفر تفریحی"],"answer":0,"feedback":"Vocational به حرفه مربوط است؛ vocational school همان Berufsschule است.","mistake":"Trainee و Apprentice بسته به زمینه همیشه قابل جایگزینی کامل نیستند."},"minutes":9,"editorial":true,"source":["British Council · English learning","https://learnenglish.britishcouncil.org/"]},"k10-englisch/abteilungen":{"de":{"title":"Abteilungen","goal":"Du ordnest englische Abteilungsnamen Aufgaben zu und leitest Anfragen passend weiter.","definition":"Englische Abteilungsnamen sagen, wohin eine Mail oder ein Anruf gehört.","explanation":"Ein Abteilungsname wird verständlich, wenn du die zugehörige Aufgabe kennst. Purchasing kauft Material und Leistungen ein. Goods-in nimmt eingehende Ware an und prüft sie. Warehouse lagert Waren, shipping organisiert den Versand. Sales kümmert sich um Verkauf und Kundenangebote; order processing bearbeitet eingegangene Aufträge. Accounting erfasst Geschäftsvorgänge und Zahlungen. Human resources betreut Personalthemen. IT support unterstützt bei technischen Störungen und Anfragen. Eine Anfrage kann mehrere Stationen berühren: Bei einem defekten neuen Laptop prüft IT den technischen Fehler; purchasing klärt gegebenenfalls die Bestellung oder Rückgabe. Begründe bei einer Zuordnungsaufgabe deshalb die Aufgabe der Abteilung, nicht nur ihre Übersetzung.","example":"Eine beschädigte Lieferung geht an goods-in, nicht an marketing. Eine Bewerbung geht an human resources.","remember":["Purchasing: Einkauf von Waren und Dienstleistungen.","Warehouse: Lager zur Aufbewahrung von Waren.","Purchasing kauft ein; shipping verschickt. Die Richtung der Warenbewegung hilft bei der Zuordnung."],"summary":"Abteilungsnamen werden sicher verständlich, wenn du sie mit ihrer konkreten Aufgabe verknüpfst.","sections":[],"terms":[["Purchasing","Einkauf von Waren und Dienstleistungen."],["Warehouse","Lager zur Aufbewahrung von Waren."],["Accounting","Buchhaltung und Erfassung finanzieller Geschäftsvorgänge."],["Human resources","Personalabteilung."],["Shipping","Versand und Organisation ausgehender Lieferungen."]],"q":"Welche Abteilung ist normalerweise für den Einkauf zuständig?","options":["Purchasing","Shipping","Human resources"],"answer":0,"feedback":"Purchasing beschafft Leistungen und Waren; shipping versendet sie.","mistake":"Purchasing kauft ein; shipping verschickt. Die Richtung der Warenbewegung hilft bei der Zuordnung."},"fa":{"title":"بخش‌ها","goal":"نام انگلیسی بخش‌ها را با وظیفه تطبیق می‌دهی و درخواست را درست ارجاع می‌دهی.","definition":"نام انگلیسی بخش‌ها می‌گوید ایمیل یا تماس کجا می‌رود.","explanation":"وقتی وظیفهٔ بخش را بدانی، نام آن معنی پیدا می‌کند. Purchasing مواد و خدمات را خریداری می‌کند. Goods-in کالای ورودی را تحویل می‌گیرد و بررسی می‌کند. Warehouse انبار و Shipping ارسال را مدیریت می‌کنند. Sales فروش و پیشنهاد به مشتری را انجام می‌دهد و Order processing سفارش ثبت‌شده را رسیدگی می‌کند. Accounting رویدادهای مالی و پرداخت‌ها را ثبت می‌کند. Human resources موضوع‌های کارکنان را مدیریت می‌کند. IT support برای مشکل و درخواست فنی کمک می‌کند. یک درخواست ممکن است چند بخش را درگیر کند: برای لپ‌تاپ تازهٔ خراب، IT مشکل فنی را بررسی می‌کند و Purchasing در صورت نیاز سفارش یا برگشت را پیگیری می‌کند. پس در تمرین، وظیفهٔ بخش را هم دلیل بیاور.","example":"یک تحویل آسیب‌دیده به goods-in می‌رود، نه به marketing. یک درخواست کار به human resources می‌رود.","remember":["Purchasing: خرید کالا و خدمات.","Warehouse: انبار نگهداری کالا.","Purchasing خرید می‌کند و Shipping ارسال می‌کند؛ جهت حرکت کالا به تشخیص کمک می‌کند."],"summary":"وقتی نام بخش را با وظیفهٔ واقعی پیوند بدهی، آن را درست می‌فهمی.","sections":[],"terms":[["Purchasing","خرید کالا و خدمات."],["Warehouse","انبار نگهداری کالا."],["Accounting","حسابداری و ثبت رویدادهای مالی."],["Human resources","بخش منابع انسانی."],["Shipping","ارسال و سازمان‌دهی محموله‌های خروجی."]],"q":"کدام بخش معمولاً مسئول خرید است؟","options":["Purchasing","Shipping","Human resources"],"answer":0,"feedback":"Purchasing خرید می‌کند و Shipping ارسال را انجام می‌دهد.","mistake":"Purchasing خرید می‌کند و Shipping ارسال می‌کند؛ جهت حرکت کالا به تشخیص کمک می‌کند."},"minutes":9,"editorial":true,"source":["British Council · English learning","https://learnenglish.britishcouncil.org/"]},"k10-englisch/modal":{"de":{"title":"Modalverben","goal":"Du unterscheidest Fähigkeit, Erlaubnis, Verpflichtung, Verbot und fehlende Notwendigkeit.","definition":"Ein Modalverb sagt, ob etwas möglich, erlaubt, nötig oder ein Rat ist. Es steht vor dem Verb in der Grundform.","explanation":"Modalverben verändern die Bedeutung eines Vollverbs. Can beschreibt zum Beispiel Fähigkeit: I can configure the router. May kann eine förmliche Erlaubnis ausdrücken: You may use this computer. Must und have to können eine Verpflichtung ausdrücken, etwa die Pflicht, vertrauliche Daten zu schützen. Should gibt meist einen Rat: You should check the cable first. Entscheidend sind die Verneinungen: You must not share your password bedeutet, dass Teilen verboten ist. You do not have to restart bedeutet, dass ein Neustart nicht notwendig ist. Nach can, may, must und should folgt die Grundform ohne to. Bei have to ändern sich Formen: she has to, they had to. Übersetze deshalb die ganze Aussage und nicht nur ein einzelnes Wort.","example":"“You must wear safety shoes in the workshop.” Das ist ein Verbot, sie wegzulassen. “You don’t have to stay after 16:00.” Das ist keine Pflicht, kein Verbot.","remember":["Can: Drückt unter anderem Fähigkeit oder Erlaubnis aus.","Should: Drückt häufig eine Empfehlung aus.","Must not bedeutet verboten; do not have to bedeutet nicht nötig."],"summary":"Modalformen unterscheiden unter anderem Können, Erlaubnis, Pflicht, Verbot und fehlende Notwendigkeit.","sections":[],"terms":[["Can","Drückt unter anderem Fähigkeit oder Erlaubnis aus."],["Should","Drückt häufig eine Empfehlung aus."],["Must not","Bedeutet ein Verbot."],["Do not have to","Bedeutet fehlende Notwendigkeit."]],"q":"Was bedeutet You do not have to restart?","options":["Ein Neustart ist verboten","Ein Neustart ist nicht nötig","Ein Neustart ist immer Pflicht"],"answer":1,"feedback":"Nicht nötig und verboten sind verschiedene Aussagen.","mistake":"Must not bedeutet verboten; do not have to bedeutet nicht nötig."},"fa":{"title":"فعل‌های وجهی","goal":"توانایی، اجازه، الزام، ممنوعیت و لازم‌نبودن را از هم جدا می‌کنی.","definition":"فعل وجهی می‌گوید چیزی ممکن، مجاز، لازم یا توصیه است. پیش از فعل در شکل پایه می‌آید.","explanation":"فعل کمکی معنای فعل اصلی را تغییر می‌دهد. Can مثلاً توانایی را بیان می‌کند: I can configure the router. May می‌تواند اجازهٔ رسمی باشد: You may use this computer. Must و Have to الزام را بیان می‌کنند؛ مثلاً حفاظت از دادهٔ محرمانه. Should معمولاً توصیه است: You should check the cable first. منفی‌ها بسیار مهم‌اند: You must not share your password یعنی دادن رمز ممنوع است. You do not have to restart یعنی راه‌اندازی دوباره لازم نیست. پس از can، may، must و should فعل ساده بدون to می‌آید. Have to شکل‌های متغیر دارد: she has to و they had to. بنابراین معنای کل جمله را ترجمه کن، نه فقط یک واژه را.","example":"“You must wear safety shoes in the workshop.” این ممنوعیت درآوردن آن‌هاست. “You don’t have to stay after 16:00.” این وظیفه نیست، ممنوعیت نیست.","remember":["Can: از جمله توانایی یا اجازه را بیان می‌کند.","Should: معمولاً توصیه را بیان می‌کند.","Must not یعنی ممنوع؛ Do not have to یعنی لازم نیست."],"summary":"ساختارهای Modal توانایی، اجازه، الزام، ممنوعیت و لازم‌نبودن را جدا می‌کنند.","sections":[],"terms":[["Can","از جمله توانایی یا اجازه را بیان می‌کند."],["Should","معمولاً توصیه را بیان می‌کند."],["Must not","یعنی ممنوع‌بودن."],["Do not have to","یعنی لازم‌نبودن."]],"q":"You do not have to restart یعنی چه؟","options":["Restart ممنوع است","Restart لازم نیست","Restart همیشه اجباری است"],"answer":1,"feedback":"لازم‌نبودن و ممنوع‌بودن دو معنای متفاوت‌اند.","mistake":"Must not یعنی ممنوع؛ Do not have to یعنی لازم نیست."},"minutes":9,"editorial":true,"source":["British Council · Permission and obligation","https://learnenglish.britishcouncil.org/free-resources/grammar/b1-b2/modals-permission-obligation"]},"k10-englisch/mails":{"de":{"title":"E-Mails","goal":"Du schreibst eine verständliche englische Support-Mail mit Anliegen, nötigen Angaben und höflichem Abschluss.","definition":"Eine förmliche Mail nennt Anrede, Anliegen und Gruß. Eine lockere Mail ist kürzer und nur für Menschen, die du duzt.","explanation":"Eine gute geschäftliche E-Mail hilft der empfangenden Person, den nächsten Schritt zu erkennen. Der Betreff nennt Thema oder Ticketnummer, beispielsweise VPN connection fails – Ticket 1042. Die Anrede richtet sich nach Beziehung und Kontext. Beschreibe im Hauptteil kurz Problem, Beginn, betroffene Geräte und bereits versuchte Schritte. Formuliere danach die gewünschte Aktion oder Frage. Eine passende Schlussformel und dein Name schließen die Nachricht ab. Prüfe Anhänge und entferne unnötige vertrauliche Daten. Ein realistischer Satz lautet: Could you please check the VPN access for my account? Ton und Detailtiefe können sich je nach Empfänger unterscheiden. Klarheit, höfliche Sprache und ein nachvollziehbares Anliegen sind wichtiger als möglichst komplizierte Formulierungen.","example":"Subject: Damaged delivery 14 March. Dear Mr Braun, the monitor arrived with a broken screen. Could you send a replacement? Kind regards, Lea Hoffmann.","remember":["Subject: Betreff einer E-Mail.","Attachment: Angehängte Datei.","Ein langer Text ist nicht automatisch professionell. Anliegen, Angaben und gewünschter nächster Schritt müssen erkennbar sein."],"summary":"Eine gute Support-Mail benennt Thema, relevante Angaben und den gewünschten nächsten Schritt höflich und klar.","sections":[],"terms":[["Subject","Betreff einer E-Mail."],["Attachment","Angehängte Datei."],["Request","Anfrage oder Bitte um eine Handlung."],["Kind regards","Übliche höfliche Schlussformel."]],"q":"Welcher Betreff ist für eine Supportanfrage klarer?","options":["Hello","Question","VPN connection fails – Ticket 1042"],"answer":2,"feedback":"Der konkrete Betreff nennt Problem und Zuordnung, bevor die Mail geöffnet wird.","mistake":"Ein langer Text ist nicht automatisch professionell. Anliegen, Angaben und gewünschter nächster Schritt müssen erkennbar sein."},"fa":{"title":"ایمیل","goal":"ایمیل پشتیبانی انگلیسی با درخواست روشن، اطلاعات لازم و پایان مؤدبانه می‌نویسی.","definition":"ایمیل رسمی خطاب، درخواست و پایان دارد. ایمیل خودمانی کوتاه‌تر است و فقط برای کسی که خوب می‌شناسی.","explanation":"ایمیل کاری خوب کمک می‌کند گیرنده قدم بعدی را بفهمد. عنوان باید موضوع یا شمارهٔ تیکت را بگوید؛ مثلاً VPN connection fails – Ticket 1042. خطاب با رابطه و موقعیت هماهنگ باشد. در متن، مشکل، زمان شروع، دستگاه درگیر و کارهای امتحان‌شده را کوتاه توضیح بده. سپس اقدام یا سؤال مورد نظر را روشن بنویس. پایان مناسب و نام خود را اضافه کن. پیوست‌ها را بررسی و دادهٔ محرمانهٔ غیرضروری را حذف کن. جملهٔ نمونه: Could you please check the VPN access for my account? لحن و جزئیات بسته به مخاطب فرق می‌کنند. روشن‌بودن، ادب و درخواست قابل فهم از عبارت‌های پیچیده مهم‌ترند.","example":"Subject: Damaged delivery 14 March. Dear Mr Braun, the monitor arrived with a broken screen. Could you send a replacement? Kind regards, Lea Hoffmann.","remember":["Subject: عنوان ایمیل.","Attachment: فایل پیوست.","متن طولانی خودکار حرفه‌ای نیست؛ درخواست، اطلاعات و قدم بعدی باید روشن باشند."],"summary":"ایمیل پشتیبانی خوب موضوع، اطلاعات لازم و قدم بعدی را مؤدبانه و روشن بیان می‌کند.","sections":[],"terms":[["Subject","عنوان ایمیل."],["Attachment","فایل پیوست."],["Request","درخواست انجام کار."],["Kind regards","عبارت مؤدبانهٔ رایج برای پایان."]],"q":"کدام عنوان برای درخواست پشتیبانی روشن‌تر است؟","options":["Hello","Question","VPN connection fails – Ticket 1042"],"answer":2,"feedback":"عنوان دقیق پیش از بازکردن ایمیل، مشکل و شناسهٔ آن را نشان می‌دهد.","mistake":"متن طولانی خودکار حرفه‌ای نیست؛ درخواست، اطلاعات و قدم بعدی باید روشن باشند."},"minutes":9,"editorial":true,"source":["British Council · English learning","https://learnenglish.britishcouncil.org/"]},"k10-englisch/nato":{"de":{"title":"Buchstabieren","goal":"Du buchstabierst Namen und Kennungen mit dem internationalen Buchstabieralphabet eindeutig.","definition":"Das NATO-Alphabet macht Buchstaben am Telefon eindeutig. Jeder Buchstabe hat ein festes Wort.","explanation":"Am Telefon können B, D oder P leicht verwechselt werden. Das internationale Buchstabieralphabet ordnet jedem Buchstaben ein eindeutiges Wort zu. Du sagst deshalb nicht nur B, sondern Bravo. Für eine Kennung AJ4 sagst du Alfa – Juliett – four. Die Ziffer wird hier einzeln als Zahl gesprochen. Offizielle Schreibungen wie Alfa und Juliett sind absichtlich so festgelegt. Beginne mit einer kurzen Ankündigung: I will spell that for you. Sprich langsam, trenne die Wörter und bitte bei wichtigen Daten um Wiederholung. Eine wiederholte Kennung prüft, ob beide Seiten dasselbe verstanden haben. Buchstabiere keine Passwörter vor unberechtigten Zuhörenden; sichere Identitätsprüfung und Vertraulichkeit bleiben wichtig.","example":"Der Name Keller ist Kilo, Echo, Lima, Lima, Echo, Romeo.","remember":["Alfa: Codewort für A.","Bravo: Codewort für B.","Das Codewort für A lautet Alfa, für J Juliett. Freie Ersatzwörter schwächen die Eindeutigkeit."],"summary":"Standardisierte Codewörter machen einzelne Buchstaben bei mündlicher Übertragung eindeutig.","sections":[{"title":"Alle 26 Codewörter von A bis Z","body":"A Alfa · B Bravo · C Charlie · D Delta · E Echo · F Foxtrot · G Golf · H Hotel · I India · J Juliett · K Kilo · L Lima · M Mike · N November · O Oscar · P Papa · Q Quebec · R Romeo · S Sierra · T Tango · U Uniform · V Victor · W Whiskey · X X-ray · Y Yankee · Z Zulu"}],"terms":[["Alfa","Codewort für A."],["Bravo","Codewort für B."],["Juliett","Codewort für J."],["Whiskey","Codewort für W."],["Zulu","Codewort für Z."]],"q":"Welches Wort steht im internationalen Buchstabieralphabet für J?","options":["Juliett","January","Joker"],"answer":0,"feedback":"Das standardisierte Wort lautet Juliett mit zwei t.","mistake":"Das Codewort für A lautet Alfa, für J Juliett. Freie Ersatzwörter schwächen die Eindeutigkeit."},"fa":{"title":"هجی","goal":"نام و شناسه را با الفبای بین‌المللی واضح هجی می‌کنی.","definition":"الفبای ناتو حرف را در تلفن روشن می‌کند. هر حرف یک واژه ثابت دارد.","explanation":"در تلفن B، D یا P ممکن است اشتباه شنیده شوند. الفبای بین‌المللی برای هر حرف یک واژهٔ روشن دارد. پس به‌جای فقط B می‌گویی Bravo. شناسهٔ AJ4 را Alfa – Juliett – four می‌خوانی؛ رقم جداگانه گفته می‌شود. نوشتار رسمی Alfa و Juliett عمداً چنین تعیین شده است. ابتدا بگو: I will spell that for you. آهسته بخوان، واژه‌ها را جدا کن و برای دادهٔ مهم درخواست تکرار کن. تکرار شناسه بررسی می‌کند هر دو طرف یک چیز فهمیده‌اند. رمز را مقابل شنوندهٔ غیرمجاز هجی نکن؛ بررسی هویت و محرمانگی همچنان مهم‌اند.","example":"نام Keller می‌شود Kilo, Echo, Lima, Lima, Echo, Romeo.","remember":["Alfa: واژهٔ حرف A.","Bravo: واژهٔ حرف B.","واژهٔ A برابر Alfa و J برابر Juliett است؛ جایگزین دلخواه وضوح را کم می‌کند."],"summary":"واژه‌های استاندارد هنگام انتقال شفاهی، حرف‌ها را واضح می‌کنند.","sections":[{"title":"هر ۲۶ واژه از A تا Z","body":"A Alfa · B Bravo · C Charlie · D Delta · E Echo · F Foxtrot · G Golf · H Hotel · I India · J Juliett · K Kilo · L Lima · M Mike · N November · O Oscar · P Papa · Q Quebec · R Romeo · S Sierra · T Tango · U Uniform · V Victor · W Whiskey · X X-ray · Y Yankee · Z Zulu"}],"terms":[["Alfa","واژهٔ حرف A."],["Bravo","واژهٔ حرف B."],["Juliett","واژهٔ حرف J."],["Whiskey","واژهٔ حرف W."],["Zulu","واژهٔ حرف Z."]],"q":"در الفبای بین‌المللی کدام واژه برای J است؟","options":["Juliett","January","Joker"],"answer":0,"feedback":"واژهٔ استاندارد Juliett با دو حرف t است.","mistake":"واژهٔ A برابر Alfa و J برابر Juliett است؛ جایگزین دلخواه وضوح را کم می‌کند."},"minutes":9,"editorial":true,"source":["NATO · Phonetic alphabet","https://www.nato.int/content/dam/nato/webready/news/2010-2019/2017/12/21/20180111_nato-alphabet-sign-signal.pdf"]},"k10-englisch/telefon":{"de":{"title":"Telefonieren","goal":"Du führst einen kurzen Supportanruf mit Begrüßung, Rückfragen, Zusammenfassung und nächstem Schritt.","definition":"Am Telefon nennst du Firma und Namen, leitest weiter oder nimmst eine Nachricht auf und verschiebst Termine klar.","explanation":"Beginne mit einer klaren Vorstellung: Good morning, Lernova IT support, Mina speaking. How can I help you? Höre zu und stelle gezielte Fragen: When did the problem start? What error message do you see? Wiederhole das Anliegen, damit Missverständnisse sichtbar werden. Wenn du weiterleitest, kündige es an: I will put you through to the network team. Ist niemand verfügbar, frage: May I take a message? Notiere Name, Rückrufmöglichkeit, Anliegen und Zeitpunkt; prüfe Nummern durch Wiederholen. Zum Abschluss nennst du den vereinbarten nächsten Schritt und einen realistischen Rückmeldezeitpunkt. Versprich keine sofortige Lösung, wenn du sie noch nicht zusagen kannst. Freundliche Sprache und klare Notizen helfen dem gesamten Supportteam.","example":"Ein Anrufer will die Buchhaltung. Du sagst den Satz zum Weiterleiten und den Namen der Abteilung, nicht nur “wait”.","remember":["Put someone through: Einen Anruf an eine andere Stelle weiterleiten.","Take a message: Eine Nachricht für eine andere Person aufnehmen.","Eine Weiterleitung ohne Ankündigung kann verwirren. Sage zuerst, an welche Stelle du verbindest."],"summary":"Ein strukturierter Supportanruf klärt das Anliegen, hält nötige Angaben fest und vereinbart den nächsten Schritt.","sections":[],"terms":[["Put someone through","Einen Anruf an eine andere Stelle weiterleiten."],["Take a message","Eine Nachricht für eine andere Person aufnehmen."],["Call back","Zurückrufen."],["Available","Erreichbar oder verfügbar."],["Error message","Fehlermeldung eines Systems."]],"q":"Was bedeutet May I take a message?","options":["Darf ich eine Nachricht aufnehmen?","Ich lösche alle Nachrichten","Sie müssen sofort auflegen"],"answer":0,"feedback":"Die Frage bietet an, ein Anliegen für eine nicht erreichbare Person zu notieren.","mistake":"Eine Weiterleitung ohne Ankündigung kann verwirren. Sage zuerst, an welche Stelle du verbindest."},"fa":{"title":"تلفن","goal":"تماس کوتاه پشتیبانی را با سلام، سؤال، جمع‌بندی و قدم بعدی انجام می‌دهی.","definition":"در تلفن شرکت و نام را می‌گویی، وصل می‌کنی یا پیام می‌گیری و قرار را روشن جابه‌جا می‌کنی.","explanation":"با معرفی روشن شروع کن: Good morning, Lernova IT support, Mina speaking. How can I help you? گوش بده و سؤال دقیق بپرس: When did the problem start? What error message do you see? مشکل را تکرار کن تا سوءتفاهم روشن شود. هنگام انتقال بگو: I will put you through to the network team. اگر کسی در دسترس نیست، بپرس: May I take a message? نام، راه تماس، درخواست و زمان را ثبت کن و شماره را با تکرار بررسی کن. در پایان قدم بعدی توافق‌شده و زمان واقع‌بینانهٔ پاسخ را بگو. اگر هنوز نمی‌دانی حل فوری ممکن است، چنین قولی نده. زبان دوستانه و یادداشت روشن به کل تیم کمک می‌کند.","example":"تماس‌گیرنده حسابداری را می‌خواهد. جمله وصل کردن و نام بخش را می‌گویی، نه فقط wait.","remember":["Put someone through: تماس را به بخش دیگر وصل‌کردن.","Take a message: پیام برای شخص دیگر گرفتن.","انتقال بی‌خبر تماس گیج‌کننده است؛ ابتدا بگو به کدام بخش وصل می‌کنی."],"summary":"تماس منظم پشتیبانی درخواست را روشن، اطلاعات را ثبت و قدم بعدی را توافق می‌کند.","sections":[],"terms":[["Put someone through","تماس را به بخش دیگر وصل‌کردن."],["Take a message","پیام برای شخص دیگر گرفتن."],["Call back","دوباره تماس‌گرفتن."],["Available","در دسترس بودن."],["Error message","پیام خطای سیستم."]],"q":"May I take a message? یعنی چه؟","options":["می‌توانم پیامتان را بگیرم؟","همهٔ پیام‌ها را حذف می‌کنم","باید فوراً قطع کنید"],"answer":0,"feedback":"این سؤال پیشنهاد می‌دهد پیام برای فردی که در دسترس نیست ثبت شود.","mistake":"انتقال بی‌خبر تماس گیج‌کننده است؛ ابتدا بگو به کدام بخش وصل می‌کنی."},"minutes":9,"editorial":true,"source":["British Council · English learning","https://learnenglish.britishcouncil.org/"]},"it-systeme/osi":{"de":{"title":"OSI-Modell: sieben Aufgaben, ein Datenaustausch","goal":"Du benennst die sieben OSI-Schichten von 7 bis 1 und erklärst, welche Aufgabe jede Schicht beim Senden übernimmt.","definition":"Das OSI-Modell ordnet die Aufgaben der Netzwerkkommunikation in sieben Schichten. Es hilft, Geräte, Protokolle und Fehler systematisch einzuordnen. Es ist ein Referenzmodell; reale Internetprotokolle lassen sich nicht immer exakt einer einzigen Schicht zuweisen.","explanation":"Beim Sender werden Daten gedanklich von oben nach unten verarbeitet: von der Anwendung zur Übertragung der Signale. Dabei ergänzen Protokolle Steuerinformationen, zum Beispiel Ports, IP-Adressen und Ethernet-Adressen. Dies heißt Kapselung. Beim Empfänger läuft die Verarbeitung in umgekehrter Richtung; passende Steuerinformationen werden ausgewertet und entfernt.\n\nDie Schichten 5 bis 7 sind im TCP/IP-Alltag häufig gemeinsam durch Anwendungen und Bibliotheken umgesetzt. Der Browser selbst ist keine einzelne OSI-Schicht: Er nutzt mehrere Dienste. Für die Fehlersuche kannst du je nach Symptom unten beginnen, oben beginnen oder die Strecke gezielt eingrenzen.","example":"Du öffnest eine Website: HTTP beschreibt die Anfrage auf Anwendungsebene. Die Daten werden für die Übertragung aufbereitet. Bei HTTPS sorgt TLS für geschützte Kommunikation. TCP verwendet Ports und eine zuverlässige Übertragung. IP bringt Pakete zum Zielnetz. Ethernet oder WLAN übertragen Frames auf dem lokalen Abschnitt. Kabel oder Funk tragen die Signale. Am Ziel wird die Information wieder zusammengesetzt.","remember":["7 Anwendung, 6 Darstellung, 5 Sitzung, 4 Transport, 3 Vermittlung, 2 Sicherung, 1 Bitübertragung.","Senden: gedanklich 7 → 1. Empfangen: 1 → 7.","Ports, IP-Adressen und MAC-Adressen erfüllen unterschiedliche Aufgaben."],"summary":"7 Anwendung, 6 Darstellung, 5 Sitzung, 4 Transport, 3 Vermittlung, 2 Sicherung, 1 Bitübertragung.","mistake":"Ein erfolgreicher Ping beweist nicht, dass HTTP oder jede Anwendung funktioniert. Er prüft nur einen Teil der Kommunikation.","terms":[["Application","Anwendungsprotokolle stellen Netzwerkfunktionen für Programme bereit."],["Presentation","Aufbereitung und gemeinsame Darstellung von Daten."],["Session","Organisation eines Kommunikationsdialogs."],["Transport","Übertragung zwischen Prozessen, etwa über TCP oder UDP."],["Network","Logische Adressierung und Weiterleitung mit IP."],["Data Link","Frames und Adressierung auf einem lokalen Netzabschnitt."],["Physical","Übertragung von Bits als elektrische, optische oder Funksignale."]],"q":"Welche Schicht übernimmt die logische IP-Adressierung?","options":["Schicht 3: Vermittlung","Schicht 1: Bitübertragung","Schicht 6: Darstellung"],"answer":0,"feedback":"IP-Adressen und Routing gehören zur Vermittlungsschicht. MAC-Adressen werden auf der Sicherungsschicht verwendet.","sections":[{"title":"7 · Anwendungsschicht — Application","body":"Sie stellt Protokolle für die Kommunikation von Anwendungen bereit. HTTP regelt etwa Webanfragen, SMTP den Transport von E-Mails. Hier wird festgelegt, welche Nachricht ein Dienst erhält."},{"title":"6 · Darstellungsschicht — Presentation","body":"Sie beschreibt die gemeinsame Darstellung der Daten: zum Beispiel Zeichencodierung, Datenformate, Kompression und Verschlüsselungsfunktionen. Die konkrete Zuordnung von TLS im realen TCP/IP-System ist vereinfacht und nicht eindeutig."},{"title":"5 · Sitzungsschicht — Session","body":"Sie organisiert den Dialog zwischen Kommunikationspartnern, beispielsweise Aufbau, Verwaltung und Abschluss einer Sitzung. Eine Sitzung ist eine geordnete zusammengehörige Kommunikation und nicht einfach ein einzelnes Kabel."},{"title":"4 · Transportschicht — Transport","body":"Sie verbindet Prozesse auf Endgeräten. TCP bietet unter anderem Reihenfolge, Bestätigung und erneute Übertragung. UDP überträgt Datagramme ohne diese Zuverlässigkeitsmechanismen. Ports helfen bei der Zuordnung zu Anwendungen."},{"title":"3 · Vermittlungsschicht — Network","body":"Sie adressiert Geräte logisch und leitet Pakete zwischen Netzen weiter. IP-Adressen kennzeichnen die Netzschnittstellen, Router wählen anhand ihrer Routingtabelle den nächsten Weg."},{"title":"2 · Sicherungsschicht — Data Link","body":"Sie überträgt Frames über einen lokalen Netzabschnitt. Ethernet nutzt MAC-Adressen; Switches lernen, an welchem Port eine MAC-Adresse erreichbar ist. VLANs trennen logische Layer-2-Netze."},{"title":"1 · Bitübertragungsschicht — Physical","body":"Sie überträgt die Bits als Signale. Hierzu gehören elektrische Pegel, Lichtimpulse, Funk, Stecker und Übertragungsmedien. Ein beschädigtes Kabel kann bereits auf dieser Ebene die Verbindung verhindern."}]},"fa":{"title":"مدل OSI؛ هفت وظیفه برای تبادل داده","goal":"هفت لایهٔ OSI را از ۷ تا ۱ نام ببری و وظیفهٔ هرکدام را هنگام ارسال داده توضیح بدهی.","definition":"مدل OSI وظایف ارتباط شبکه را در هفت لایه دسته‌بندی می‌کند. با آن می‌توان نقش تجهیزات، پروتکل‌ها و محل احتمالی خطا را بهتر فهمید. این مدل یک چارچوب مفهومی است؛ پروتکل‌های واقعی اینترنت همیشه دقیقاً در یک لایه جا نمی‌گیرند.","explanation":"در فرستنده، پردازش را از بالا به پایین تصور می‌کنیم: از درخواست برنامه تا ارسال سیگنال. پروتکل‌ها اطلاعات کنترلی مانند شمارهٔ پورت، آدرس IP و آدرس Ethernet اضافه می‌کنند. این کار Kapselung یا کپسوله‌سازی نام دارد. گیرنده اطلاعات را از پایین به بالا بررسی می‌کند و اطلاعات کنترلی مربوط به هر مرحله را کنار می‌گذارد.\n\nدر شبکه‌های TCP/IP، وظایف لایه‌های ۵ تا ۷ اغلب در برنامه‌ها و کتابخانه‌ها با هم اجرا می‌شوند. خود مرورگر تنها یک لایه نیست؛ از چند سرویس استفاده می‌کند. برای عیب‌یابی نیز بسته به نشانه‌ها می‌توان از پایین، از بالا یا از یک نقطهٔ مشخص شروع کرد.","example":"یک وب‌سایت را باز می‌کنی: HTTP درخواست برنامه را توصیف می‌کند. داده برای انتقال آماده می‌شود؛ در HTTPS، پروتکل TLS ارتباط را محافظت می‌کند. TCP با پورت‌ها و انتقال قابل‌اعتماد کار می‌کند. IP بسته را به شبکهٔ مقصد می‌رساند. Ethernet یا WLAN فریم‌ها را در بخش محلی منتقل می‌کند و کابل یا امواج رادیویی سیگنال را حمل می‌کنند. مقصد دوباره اطلاعات را بازسازی می‌کند.","remember":["۷ کاربرد، ۶ نمایش، ۵ نشست، ۴ انتقال، ۳ شبکه، ۲ پیوند داده، ۱ فیزیکی.","ارسال را از ۷ به ۱ و دریافت را از ۱ به ۷ دنبال کن.","پورت، IP و MAC سه وظیفهٔ متفاوت دارند."],"summary":"۷ کاربرد، ۶ نمایش، ۵ نشست، ۴ انتقال، ۳ شبکه، ۲ پیوند داده، ۱ فیزیکی.","mistake":"موفقیت Ping ثابت نمی‌کند که HTTP یا تمام برنامه‌ها درست کار می‌کنند؛ فقط بخشی از ارتباط را می‌آزماید.","terms":[["Application","پروتکل‌های کاربردی خدمات شبکه را برای برنامه‌ها فراهم می‌کنند."],["Presentation","آماده‌سازی و نمایش سازگار داده‌ها."],["Session","سازمان‌دهی گفت‌وگوی ارتباطی."],["Transport","انتقال بین فرایندها، مثلاً با TCP یا UDP."],["Network","آدرس‌دهی منطقی و هدایت بسته با IP."],["Data Link","فریم و آدرس‌دهی در یک بخش شبکهٔ محلی."],["Physical","حمل بیت‌ها با سیگنال الکتریکی، نوری یا رادیویی."]],"q":"آدرس‌دهی منطقی IP وظیفهٔ کدام لایه است؟","options":["لایهٔ ۳: شبکه","لایهٔ ۱: فیزیکی","لایهٔ ۶: نمایش"],"answer":0,"feedback":"آدرس IP و مسیریابی به لایهٔ شبکه مربوط‌اند؛ MAC در لایهٔ پیوند داده به کار می‌رود.","sections":[{"title":"۷ · لایهٔ کاربرد — Anwendung / Application","body":"پروتکل‌هایی برای ارتباط برنامه‌ها فراهم می‌کند؛ مثلاً HTTP برای درخواست وب و SMTP برای انتقال ایمیل. اینجا مشخص می‌شود سرویس چه پیامی دریافت می‌کند."},{"title":"۶ · لایهٔ نمایش — Darstellung / Presentation","body":"نمایش مشترک داده را توصیف می‌کند: کدگذاری حروف، قالب فایل، فشرده‌سازی و وظایف رمزنگاری. جای‌دادن دقیق TLS در مدل واقعی TCP/IP ساده و یکسان نیست."},{"title":"۵ · لایهٔ نشست — Sitzung / Session","body":"گفت‌وگوی دو طرف را سازمان می‌دهد؛ مثل ایجاد، مدیریت و پایان نشست. نشست مجموعه‌ای از ارتباط‌های مرتبط است، نه صرفاً یک کابل یا اتصال فیزیکی."},{"title":"۴ · لایهٔ انتقال — Transport","body":"ارتباط فرایندهای دو دستگاه را فراهم می‌کند. TCP ترتیب، تأیید و ارسال دوباره دارد. UDP دیتاگرام را بدون همین سازوکارهای اطمینان انتقال می‌دهد. پورت‌ها ارتباط را به برنامهٔ مناسب وصل می‌کنند."},{"title":"۳ · لایهٔ شبکه — Vermittlung / Network","body":"آدرس‌دهی منطقی و انتقال بسته بین شبکه‌ها را بر عهده دارد. IP رابط‌های شبکه را مشخص می‌کند؛ روتر از جدول مسیریابی، مسیر بعدی را انتخاب می‌کند."},{"title":"۲ · لایهٔ پیوند داده — Sicherung / Data Link","body":"فریم را در یک بخش محلی شبکه منتقل می‌کند. Ethernet از MAC استفاده می‌کند. سوئیچ یاد می‌گیرد هر MAC از کدام پورت قابل دسترسی است. VLAN شبکه‌های منطقی لایهٔ ۲ را جدا می‌کند."},{"title":"۱ · لایهٔ فیزیکی — Bitübertragung / Physical","body":"بیت‌ها را به شکل سیگنال حمل می‌کند؛ مانند ولتاژ، نور یا امواج رادیویی. کابل، کانکتور و محیط انتقال در این بخش مطرح‌اند. کابل خراب می‌تواند همین‌جا ارتباط را متوقف کند."}]},"minutes":12,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"it-systeme/vlan":{"de":{"title":"VLAN: ein Switch, getrennte Netze","goal":"Du erklärst Access-Port, Trunk und Inter-VLAN-Routing und planst eine Trennung zwischen Mitarbeitern und Gästen.","definition":"Ein Virtual Local Area Network ist ein logisch getrenntes Layer-2-Netz. Mehrere VLANs können dieselben Switches nutzen, gehören aber zu unterschiedlichen Broadcastdomänen. Damit lassen sich Geräte nach Aufgaben oder Sicherheitsanforderungen gruppieren.","explanation":"Ein Access-Port gehört für gewöhnliche Endgeräte einem VLAN an. Der PC muss dabei meist keine VLAN-Tags verarbeiten. Ein Trunk transportiert mehrere VLANs zwischen Netzwerkgeräten; IEEE 802.1Q kennzeichnet die Zugehörigkeit mit Tags. Für die Kommunikation zwischen unterschiedlichen VLANs wird Routing benötigt, etwa durch einen Router oder Layer-3-Switch.\n\nIm üblichen Netzplan bekommt jedes VLAN ein eigenes IP-Subnetz. Ein VLAN allein definiert noch keine vollständige Sicherheitsregel: Sobald Routing erlaubt ist, entscheiden Zugriffsregeln beziehungsweise eine Firewall, welche Verbindungen zwischen den Bereichen zulässig sind.","example":"VLAN 10 enthält Firmen-PCs mit 192.168.10.0/24. VLAN 20 enthält Gäste mit 192.168.20.0/24. Die Access-Ports ordnen Geräte zu, ein Trunk verbindet zwei Switches. Der Router stellt für beide Netze ein Gateway bereit. Eine Firewallregel erlaubt Gästen Internetzugriff, aber keinen Zugriff auf den internen Dateiserver.","remember":["VLAN trennt Broadcastdomänen auf Layer 2.","Trunk transportiert mehrere VLANs, Access bindet ein Endgerät an.","Zwischen VLANs braucht es Routing und passende Zugriffsregeln."],"summary":"VLAN trennt Broadcastdomänen auf Layer 2.","mistake":"Zwei VLANs sind nicht allein durch ähnliche IP-Adressen miteinander verbunden. Die Layer-2-Trennung bleibt bestehen.","terms":[["VLAN","Logisch getrenntes Layer-2-Netz."],["Access-Port","Port für ein bestimmtes VLAN und gewöhnliche Endgeräte."],["Trunk","Verbindung, die mehrere VLANs transportiert."],["802.1Q","Standard zur Kennzeichnung von VLANs in Ethernet-Frames."],["Inter-VLAN-Routing","Weiterleitung zwischen VLANs."]],"q":"Was braucht ein PC in VLAN 10 für die Kommunikation mit VLAN 20?","options":["Einen Router oder Layer-3-Switch mit passender Konfiguration","Nur ein neues Patchkabel","Nur dieselbe MAC-Adresse"],"answer":0,"feedback":"Verschiedene VLANs sind getrennte Layer-2-Netze. Routing verbindet sie, sofern Regeln die Verbindung erlauben.","sections":[]},"fa":{"title":"VLAN؛ یک سوئیچ، چند شبکهٔ جدا","goal":"نقش Access، Trunk و مسیریابی بین VLANها را توضیح بدهی و شبکهٔ کارمندان و مهمانان را جدا کنی.","definition":"VLAN یک شبکهٔ منطقی جدا در لایهٔ ۲ است. چند VLAN می‌توانند روی یک سوئیچ باشند، ولی Broadcastdomain جدا داشته باشند. به این ترتیب دستگاه‌ها را بر اساس وظیفه یا نیاز امنیتی دسته‌بندی می‌کنیم.","explanation":"پورت Access برای دستگاه معمولی به یک VLAN تعلق دارد و کامپیوتر معمولاً نیازی به پردازش برچسب VLAN ندارد. پورت Trunk چند VLAN را بین تجهیزات شبکه جابه‌جا می‌کند؛ برچسب IEEE 802.1Q تعلق فریم را نشان می‌دهد. برای ارتباط دو VLAN به مسیریابی، مثلاً روتر یا سوئیچ لایهٔ ۳ نیاز داریم.\n\nدر طراحی معمول، هر VLAN یک زیرشبکهٔ IP جدا دارد. VLAN به‌تنهایی همهٔ امنیت را تأمین نمی‌کند؛ اگر مسیریابی فعال شود، قوانین دسترسی و فایروال تعیین می‌کنند کدام ارتباط بین بخش‌ها مجاز است.","example":"VLAN 10 برای کامپیوترهای شرکت با شبکهٔ 192.168.10.0/24 و VLAN 20 برای مهمان‌ها با شبکهٔ 192.168.20.0/24 است. پورت‌های Access دستگاه‌ها را دسته‌بندی می‌کنند و Trunk دو سوئیچ را وصل می‌کند. روتر برای هر شبکه Gateway دارد؛ فایروال به مهمان اینترنت می‌دهد، ولی دسترسی به فایل‌سرور داخلی را نمی‌دهد.","remember":["VLAN محدوده‌های Broadcast را در لایهٔ ۲ جدا می‌کند.","Trunk چند VLAN را حمل می‌کند و Access دستگاه را عضو شبکه می‌کند.","بین VLANها مسیریابی و قوانین دسترسی لازم است."],"summary":"VLAN محدوده‌های Broadcast را در لایهٔ ۲ جدا می‌کند.","mistake":"شبیه‌بودن IPها دو VLAN را به هم وصل نمی‌کند؛ جداسازی لایهٔ ۲ همچنان وجود دارد.","terms":[["VLAN","شبکهٔ منطقی جدا در لایهٔ ۲."],["Access-Port","پورت مربوط به VLAN مشخص برای دستگاه معمولی."],["Trunk","اتصالی که چند VLAN را حمل می‌کند."],["802.1Q","استاندارد برچسب‌گذاری VLAN در فریم Ethernet."],["Inter-VLAN-Routing","مسیریابی بین VLANها."]],"q":"برای ارتباط دستگاه VLAN 10 با VLAN 20 چه نیاز است؟","options":["روتر یا سوئیچ لایهٔ ۳ با تنظیم درست","فقط یک کابل جدید","فقط MAC یکسان"],"answer":0,"feedback":"VLANهای متفاوت شبکه‌های لایهٔ ۲ جدا هستند؛ مسیریابی در صورت مجازبودن قوانین، آن‌ها را وصل می‌کند.","sections":[]},"minutes":7,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"it-systeme/dhcp":{"de":{"title":"DHCP: Netzwerkeinstellungen automatisch erhalten","goal":"Du erklärst DORA, Lease und Adressbereich und erkennst den Bedarf an einem DHCP-Relay.","definition":"DHCP ist ein Protokoll zur automatischen Konfiguration von Geräten. Bei IPv4 kann ein Server zum Beispiel IP-Adresse, Subnetzmaske, Standardgateway und DNS-Server bereitstellen. Dadurch müssen diese Werte nicht an jedem Arbeitsplatz einzeln eingetragen werden.","explanation":"Der erste IPv4-Ablauf heißt DORA: Discover sucht verfügbare Server; Offer bietet eine Konfiguration an; Request fordert das ausgewählte Angebot an; Acknowledge bestätigt die Zuteilung. Die Adresse wird normalerweise zeitlich befristet als Lease vergeben und kann erneuert werden.\n\nDer Pool enthält die vergebbaren Adressen. Statische Router- und Serveradressen sollten nicht unkontrolliert aus diesem Pool vergeben werden. Eine Reservierung bindet eine Adresse an einen identifizierten Client. Weil anfängliche DHCP-Broadcasts nicht einfach geroutet werden, kann ein Relay Anfragen aus einem anderen Subnetz an den Server weiterleiten.","example":"Im Netz 192.168.10.0/24 nutzt der Router .1. Der Pool reicht von .100 bis .200. Ein PC erhält .105, Maske /24, Gateway .1 und den vorgesehenen DNS-Server. Nach der Anmeldung prüfst du mit ipconfig /all, ob die Konfiguration zum Netz passt. Eine erhaltene Adresse beweist noch keine Internetverbindung.","remember":["DORA beschreibt die erste übliche DHCPv4-Zuteilung.","Lease bedeutet zeitlich begrenzte Zuteilung.","Für andere Subnetze kann ein DHCP-Relay erforderlich sein."],"summary":"DORA beschreibt die erste übliche DHCPv4-Zuteilung.","mistake":"DHCP und DNS sind unterschiedliche Dienste: Konfiguration erhalten und Namen auflösen sind zwei Aufgaben.","terms":[["Discover","Client sucht DHCP-Server."],["Offer","Server bietet Konfigurationsdaten an."],["Request","Client fordert ein Angebot an."],["Acknowledge","Server bestätigt die Zuteilung."],["Lease","Zeitspanne der Adresszuteilung."],["DHCP-Relay","Leitet DHCP-Anfragen zwischen Subnetz und Server weiter."]],"q":"Welche Reihenfolge passt zur ersten üblichen DHCPv4-Zuteilung?","options":["Offer → Discover → ACK → Request","Discover → Offer → Request → ACK","Request → ACK → Discover → Offer"],"answer":1,"feedback":"Der Client sucht zuerst, erhält Angebote, wählt eines und erhält die Bestätigung.","sections":[]},"fa":{"title":"DHCP؛ دریافت خودکار تنظیمات شبکه","goal":"DORA، مدت اجاره و محدودهٔ آدرس را بفهمی و نیاز به DHCP Relay را تشخیص بدهی.","definition":"DHCP پروتکلی برای تنظیم خودکار دستگاه‌هاست. در IPv4، سرور می‌تواند IP، ماسک شبکه، Gateway و DNS بدهد. بنابراین لازم نیست این تنظیمات را جداگانه در هر کامپیوتر وارد کنیم.","explanation":"شروع معمول DHCPv4 با DORA توصیف می‌شود: Discover جست‌وجوی سرور است؛ Offer پیشنهاد تنظیمات است؛ Request درخواست پیشنهاد انتخاب‌شده و Acknowledge تأیید تخصیص است. آدرس معمولاً با مدت اجاره یا Lease داده می‌شود و امکان تمدید دارد.\n\nPool محدودهٔ آدرس‌های قابل واگذاری است. آدرس ثابت روتر و سرورها نباید بدون کنترل از همین محدوده به دیگران داده شود. Reservation یک IP را برای یک کاربر شناسایی‌شده نگه می‌دارد. چون Broadcast اولیه معمولاً از روتر عبور نمی‌کند، Relay درخواست زیرشبکهٔ دیگر را به سرور می‌رساند.","example":"در شبکهٔ 192.168.10.0/24 روتر .1 است و Pool از .100 تا .200. کامپیوتر .105، ماسک /24، Gateway .1 و DNS مناسب می‌گیرد. با ipconfig /all تنظیمات را بررسی می‌کنی؛ دریافت IP به‌تنهایی اتصال اینترنت را ثابت نمی‌کند.","remember":["DORA تخصیص اولیهٔ معمول DHCPv4 را توضیح می‌دهد.","Lease یعنی واگذاری زمان‌دار آدرس.","برای زیرشبکهٔ دیگر ممکن است DHCP Relay لازم باشد."],"summary":"DORA تخصیص اولیهٔ معمول DHCPv4 را توضیح می‌دهد.","mistake":"DHCP و DNS دو سرویس متفاوت‌اند: دریافت تنظیمات و تبدیل نام دو وظیفهٔ جدا هستند.","terms":[["Discover","کاربر سرور DHCP را پیدا می‌کند."],["Offer","سرور تنظیمات را پیشنهاد می‌دهد."],["Request","کاربر پیشنهاد را درخواست می‌کند."],["Acknowledge","سرور تخصیص را تأیید می‌کند."],["Lease","مدت واگذاری آدرس."],["DHCP-Relay","درخواست را بین زیرشبکه و سرور منتقل می‌کند."]],"q":"ترتیب تخصیص اولیهٔ معمول DHCPv4 چیست؟","options":["Offer → Discover → ACK → Request","Discover → Offer → Request → ACK","Request → ACK → Discover → Offer"],"answer":1,"feedback":"کاربر اول جست‌وجو می‌کند، پیشنهاد می‌گیرد، یکی را انتخاب می‌کند و تأیید می‌گیرد.","sections":[]},"minutes":7,"source":["RFC 2131 · DHCP","https://www.rfc-editor.org/rfc/rfc2131.html"],"editorial":true},"it-systeme/routing":{"de":{"title":"Routing: den nächsten Weg auswählen","goal":"Du liest Zielnetz, Präfix und Next Hop und erklärst die Auswahl der spezifischsten passenden Route.","definition":"Routing ist die Auswahl eines Weges für IP-Pakete zwischen Netzen. Ein Router entscheidet anhand seiner Routingtabelle, über welche Schnittstelle oder welchen nächsten Router er ein Paket weiterleitet.","explanation":"Ein Eintrag enthält typischerweise Zielnetz und Präfix, nächsten Router beziehungsweise Ausgangsschnittstelle und weitere Auswahlwerte. Zuerst zählt die spezifischste passende Netzroute: Ein /24 passt genauer als ein /16. Die Standardroute /0 ist die allgemeinste Möglichkeit, falls keine spezifischere Route greift.\n\nDirekt angeschlossene Netze kennt der Router durch seine Schnittstellenkonfiguration. Statische Routen trägt ein Administrator ein; dynamische Routingprotokolle tauschen Erreichbarkeitsinformationen aus. Für eine erfolgreiche Verbindung braucht auch die Antwort einen Rückweg. Ein erlaubter Hinweg allein genügt deshalb nicht. Firewalls können die Kommunikation zusätzlich beschränken.","example":"Ein Router hat 192.168.20.0/24 über 10.0.0.2 und eine Standardroute über 10.0.0.1. Das Ziel 192.168.20.50 passt zur /24-Route, also wird 10.0.0.2 verwendet. Ein Paket zu 203.0.113.10 nutzt mangels genauerer Route die Standardroute. Die Adressen dienen hier nur als Übungsbeispiel.","remember":["Die längste passende Präfixlänge gewinnt.","Auch die Antwort braucht eine Route.","Eine Standardroute ersetzt keine gezielte Netzplanung."],"summary":"Die längste passende Präfixlänge gewinnt.","mistake":"Eine Route erlaubt technisch einen Weg. Ob Verkehr zugelassen ist, entscheiden zusätzlich Firewall- und Sicherheitsregeln.","terms":[["Routingtabelle","Liste bekannter Zielnetze und Wege."],["Next Hop","Nächster Router auf einem Weg."],["Standardroute","Allgemeine Route für sonst nicht genauer passende Ziele."],["Statische Route","Manuell eingerichteter Routingeintrag."],["Longest Prefix Match","Auswahl der spezifischsten passenden Route."]],"q":"Für ein Ziel passen /16 und /24. Welche Route ist spezifischer?","options":["/16","/24","Beide sind immer gleich"],"answer":1,"feedback":"/24 beschreibt einen kleineren, genauer passenden Adressbereich als /16.","sections":[]},"fa":{"title":"مسیریابی؛ انتخاب مسیر بعدی","goal":"شبکهٔ مقصد، پیشوند و Next Hop را بخوانی و انتخاب دقیق‌ترین مسیر را توضیح بدهی.","definition":"Routing انتخاب مسیر بستهٔ IP بین شبکه‌هاست. روتر با جدول مسیریابی تصمیم می‌گیرد بسته را از کدام رابط یا به کدام روتر بعدی بفرستد.","explanation":"هر رکورد معمولاً شبکهٔ مقصد و پیشوند، روتر بعدی یا رابط خروجی و مقادیر انتخاب مسیر را دارد. ابتدا دقیق‌ترین شبکهٔ منطبق انتخاب می‌شود: /24 از /16 دقیق‌تر است. مسیر پیش‌فرض /0 زمانی کاربرد دارد که مسیر دقیق‌تری منطبق نباشد.\n\nروتر شبکه‌های مستقیم را از تنظیمات رابط خودش می‌شناسد. مسیر Static را مدیر وارد می‌کند و پروتکل‌های Dynamic اطلاعات دسترسی را مبادله می‌کنند. برای ارتباط موفق، پاسخ هم به مسیر بازگشت نیاز دارد؛ تنها مسیر رفت کافی نیست. فایروال نیز ممکن است ارتباط را محدود کند.","example":"روتر برای 192.168.20.0/24 مسیر از 10.0.0.2 و برای سایر مقصدها مسیر پیش‌فرض از 10.0.0.1 دارد. مقصد 192.168.20.50 با /24 منطبق است و به .2 فرستاده می‌شود؛ 203.0.113.10 بدون مسیر دقیق‌تر از مسیر پیش‌فرض می‌رود. آدرس‌ها صرفاً مثال آموزشی‌اند.","remember":["بلندترین پیشوند منطبق انتخاب می‌شود.","پاسخ هم مسیر لازم دارد.","مسیر پیش‌فرض جای طراحی دقیق شبکه را نمی‌گیرد."],"summary":"بلندترین پیشوند منطبق انتخاب می‌شود.","mistake":"وجود مسیر به معنی مجازبودن همهٔ ترافیک نیست؛ فایروال و قوانین امنیتی هم تعیین‌کننده‌اند.","terms":[["Routingtabelle","فهرست شبکه‌های مقصد و مسیرهای شناخته‌شده."],["Next Hop","روتر بعدی در مسیر."],["Standardroute","مسیر عمومی وقتی مسیر دقیق‌تر نداریم."],["Statische Route","مسیر واردشده به دست مدیر."],["Longest Prefix Match","انتخاب دقیق‌ترین مسیر منطبق."]],"q":"برای یک مقصد /16 و /24 منطبق‌اند؛ کدام دقیق‌تر است؟","options":["/16","/24","همیشه برابرند"],"answer":1,"feedback":"/24 محدودهٔ کوچک‌تر و دقیق‌تری از /16 مشخص می‌کند.","sections":[]},"minutes":7,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"it-systeme/nat":{"de":{"title":"NAT und PAT: Adressen am Übergang übersetzen","goal":"Du unterscheidest Adressübersetzung von Portübersetzung und erklärst einen typischen Internetzugang.","definition":"NAT verändert IP-Adressen beim Durchgang durch ein Netzwerkgerät. Bei der verbreiteten Portübersetzung PAT teilen sich viele interne Verbindungen eine öffentliche IPv4-Adresse; Portnummern helfen bei der Zuordnung der Antworten.","explanation":"Private IPv4-Adressen wie 192.168.0.0/16 werden im öffentlichen Internet nicht als globale Zieladressen geroutet. Am Internetrouter kann die Quelladresse eines ausgehenden Pakets durch eine öffentliche Adresse ersetzt werden. Das Gerät speichert die Zuordnung, damit die Antwort wieder zum richtigen internen Client gelangt.\n\nStatisches NAT bildet Adressen fest ab. Dynamisches NAT verwendet einen Pool. PAT übersetzt zusätzlich Ports und ermöglicht vielen gleichzeitigen Verbindungen die gemeinsame Nutzung einer Adresse. Portweiterleitung ordnet einen gewünschten eingehenden Dienst gezielt einem internen System zu. NAT ersetzt weder Firewallregeln noch Verschlüsselung.","example":"PC A sendet von 192.168.10.10:51000. PC B sendet von 192.168.10.20:51000. Der Router übersetzt etwa auf 203.0.113.5:61001 und :61002. Antworten auf diese Ports können damit unterschieden werden. 203.0.113.5 ist eine Dokumentationsadresse und dient hier als Beispiel für die Außenseite.","remember":["NAT übersetzt IP-Adressen.","PAT berücksichtigt zusätzlich Ports.","NAT ist keine vollständige Sicherheitslösung."],"summary":"NAT übersetzt IP-Adressen.","mistake":"NAT löst keine Domainnamen auf. Für die Zuordnung von Namen zu Informationen ist DNS zuständig.","terms":[["NAT","Network Address Translation, Übersetzung von IP-Adressen."],["PAT","Übersetzung mit zusätzlicher Portzuordnung."],["Private Adresse","Für interne Netze reservierte Adresse."],["Portweiterleitung","Gezielte Zuordnung eines eingehenden Ports."],["Zuordnungstabelle","Gespeicherte Abbildung interner und externer Verbindungen."]],"q":"Warum kann PAT viele Clients über eine öffentliche Adresse anbinden?","options":["Weil jeder Client dieselbe MAC bekommt","Weil Ports die Zuordnung unterscheiden","Weil DNS alle Pakete speichert"],"answer":1,"feedback":"Unterschiedliche externe Portzuordnungen machen Antworten den internen Verbindungen zuordenbar.","sections":[]},"fa":{"title":"NAT و PAT؛ ترجمهٔ آدرس در مرز شبکه","goal":"تفاوت ترجمهٔ آدرس و پورت را بفهمی و اتصال معمول اینترنت را توضیح بدهی.","definition":"NAT هنگام عبور داده از دستگاه شبکه، آدرس IP را تغییر می‌دهد. در روش رایج PAT چند اتصال داخلی از یک IPv4 عمومی استفاده می‌کنند و شمارهٔ پورت پاسخ‌ها را تفکیک می‌کند.","explanation":"آدرس‌های خصوصی مانند 192.168.0.0/16 در اینترنت عمومی به‌عنوان مقصد جهانی مسیریابی نمی‌شوند. روتر اینترنت می‌تواند آدرس مبدأ بستهٔ خروجی را با آدرس عمومی عوض کند. دستگاه این نگاشت را نگه می‌دارد تا پاسخ را به کاربر داخلی درست برگرداند.\n\nStatic NAT نگاشت ثابت دارد؛ Dynamic NAT از مجموعهٔ آدرس استفاده می‌کند. PAT علاوه بر IP، پورت را هم ترجمه می‌کند تا چندین ارتباط از یک آدرس استفاده کنند. Port Forwarding یک سرویس ورودی مشخص را به دستگاه داخلی می‌رساند. NAT جای فایروال یا رمزنگاری نیست.","example":"کامپیوتر A از 192.168.10.10:51000 و B از 192.168.10.20:51000 می‌فرستند. روتر آن‌ها را مثلاً به 203.0.113.5:61001 و :61002 ترجمه می‌کند؛ بنابراین پاسخ‌ها جدا می‌شوند. آدرس 203.0.113.5 برای مستندات است و اینجا نقش سمت بیرونی را نشان می‌دهد.","remember":["NAT آدرس IP را ترجمه می‌کند.","PAT پورت را هم در نظر می‌گیرد.","NAT راهکار امنیتی کامل نیست."],"summary":"NAT آدرس IP را ترجمه می‌کند.","mistake":"NAT نام دامنه را تبدیل نمی‌کند؛ این وظیفه به DNS مربوط است.","terms":[["NAT","ترجمهٔ آدرس IP."],["PAT","ترجمه همراه با نگاشت پورت."],["Private Adresse","آدرس رزروشده برای شبکهٔ داخلی."],["Portweiterleitung","هدایت یک پورت ورودی به مقصد داخلی."],["Zuordnungstabelle","جدول نگاشت ارتباط داخلی و بیرونی."]],"q":"چرا PAT چند کاربر را با یک IP عمومی متصل می‌کند؟","options":["چون همه یک MAC می‌گیرند","چون پورت‌ها نگاشت را جدا می‌کنند","چون DNS بسته‌ها را ذخیره می‌کند"],"answer":1,"feedback":"پورت‌های متفاوت بیرونی کمک می‌کنند پاسخ به ارتباط داخلی درست برگردد.","sections":[]},"minutes":7,"source":["RFC 3022 · Traditional NAT","https://www.rfc-editor.org/rfc/rfc3022.html"],"editorial":true},"it-systeme/ipv6":{"de":{"title":"IPv6: Aufbau und Schreibweise verstehen","goal":"Du liest IPv6-Adressen, kürzt Nullgruppen korrekt und unterscheidest wichtige Adressarten.","definition":"IPv6 ist die Version des Internetprotokolls mit 128-Bit-Adressen. Der große Adressraum erlaubt deutlich mehr eindeutige Adressen als IPv4. IPv6 verändert außerdem Teile der Adresskonfiguration und der Kommunikation im lokalen Netz.","explanation":"Eine volle Adresse besteht aus acht Gruppen mit je vier hexadezimalen Zeichen. Führende Nullen innerhalb einer Gruppe dürfen entfallen. Eine zusammenhängende Folge von Nullgruppen darf einmal pro Adresse durch :: ersetzt werden. Zweimal :: wäre mehrdeutig. Der Präfix bezeichnet den Netzanteil; /64 ist bei vielen lokalen IPv6-Netzen üblich.\n\nGlobal-Unicast-Adressen können global geroutet werden. Link-Local-Adressen aus fe80::/10 dienen dem lokalen Link und werden nicht über Router weitergeleitet. ::1 ist Loopback. IPv6 nutzt Multicast anstelle des IPv4-Broadcasts. Neighbor Discovery übernimmt unter anderem die Nachbarauflösung; ARP wird dafür nicht eingesetzt.","example":"2001:0db8:0000:0000:0000:0000:0000:0010 wird zu 2001:db8::10. Die zwei sichtbaren Gruppen vor :: und die Gruppe danach belegen zusammen drei Gruppen; :: steht somit für fünf Nullgruppen. 2001:db8::/32 ist ausschließlich für Dokumentationsbeispiele reserviert.","remember":["IPv6 hat 128 Bit.",":: ist höchstens einmal pro Adresse erlaubt.","Link-Local bleibt auf dem lokalen Link."],"summary":"IPv6 hat 128 Bit.","mistake":"Eine längere Adresse ist nicht automatisch sicherer. Firewallregeln, sichere Konfiguration und Updates bleiben notwendig.","terms":[["Hexadezimal","Zahlensystem mit 0–9 und a–f."],["Nullkompression","Abkürzung zusammenhängender Nullgruppen mit ::."],["Link-Local","Nur auf dem lokalen Link gültige Adresse."],["Global Unicast","Global adressierbarer IPv6-Adressbereich."],["Loopback","Adresse für die Kommunikation des Geräts mit sich selbst."]],"q":"Wie oft darf :: in einer IPv6-Adresse vorkommen?","options":["Beliebig oft","Genau zweimal","Höchstens einmal"],"answer":2,"feedback":"Mehrere Abkürzungen mit :: ließen offen, wie viele Nullgruppen an welcher Stelle fehlen.","sections":[]},"fa":{"title":"IPv6؛ ساختار و نوشتن آدرس","goal":"آدرس IPv6 را بخوانی، گروه‌های صفر را درست کوتاه کنی و نوع‌های مهم را بشناسی.","definition":"IPv6 نسخه‌ای از پروتکل اینترنت با آدرس‌های ۱۲۸ بیتی است. فضای بزرگ آن آدرس‌های یکتای بسیار بیشتری از IPv4 دارد و بخشی از تنظیمات آدرس و ارتباط محلی نیز در آن متفاوت است.","explanation":"آدرس کامل هشت گروه دارد و هر گروه چهار رقم شانزدهی دارد. صفرهای ابتدای هر گروه را می‌توان حذف کرد. یک زنجیرهٔ پیوسته از گروه‌های صفر را فقط یک بار با :: جایگزین می‌کنیم؛ دو بار استفاده مبهم است. پیشوند بخش شبکه را مشخص می‌کند و /64 در بسیاری از شبکه‌های محلی رایج است.\n\nGlobal Unicast می‌تواند به‌صورت جهانی مسیریابی شود. Link-Local در fe80::/10 فقط روی همان لینک کاربرد دارد و روتر آن را عبور نمی‌دهد. ::1 آدرس Loopback است. IPv6 به جای Broadcast نوع IPv4، از Multicast استفاده می‌کند؛ Neighbor Discovery همسایه‌ها را پیدا می‌کند و ARP برای این کار استفاده نمی‌شود.","example":"آدرس 2001:0db8:0000:0000:0000:0000:0000:0010 به 2001:db8::10 کوتاه می‌شود. سه گروه نوشته شده‌اند؛ پس :: جای پنج گروه صفر را می‌گیرد. پیشوند 2001:db8::/32 فقط برای مثال‌های مستندات رزرو شده است.","remember":["IPv6 دارای ۱۲۸ بیت است.",":: در هر آدرس حداکثر یک بار می‌آید.","Link-Local روی همان لینک باقی می‌ماند."],"summary":"IPv6 دارای ۱۲۸ بیت است.","mistake":"طولانی‌تر بودن آدرس خودبه‌خود امنیت نمی‌دهد؛ فایروال، تنظیم درست و به‌روزرسانی همچنان لازم‌اند.","terms":[["Hexadezimal","سیستم اعداد با ۰ تا ۹ و a تا f."],["Nullkompression","کوتاه‌کردن گروه‌های پیوستهٔ صفر با ::."],["Link-Local","آدرس معتبر فقط در همان لینک."],["Global Unicast","آدرس‌دهی جهانی IPv6."],["Loopback","آدرس ارتباط دستگاه با خودش."]],"q":":: چند بار در یک آدرس IPv6 مجاز است؟","options":["هرچند بار","دقیقاً دو بار","حداکثر یک بار"],"answer":2,"feedback":"چند :: مشخص نمی‌کند در هر قسمت چند گروه صفر حذف شده است.","sections":[]},"minutes":7,"source":["RFC 8200 · IPv6","https://www.rfc-editor.org/rfc/rfc8200.html"],"editorial":true},"it-systeme/topo":{"de":{"title":"Netztopologien: Wer ist mit wem verbunden?","goal":"Du vergleichst Stern, Bus, Ring und Mesh nach Aufbau, Ausfallverhalten und Aufwand.","definition":"Eine Topologie beschreibt die Anordnung der Verbindungen in einem Netz. Die physische Topologie zeigt Kabel und Geräte. Die logische Topologie beschreibt, wie die Kommunikation tatsächlich organisiert ist.","explanation":"Beim Stern verbindet sich jedes Endgerät mit einem zentralen Gerät, meist einem Switch. Ein defektes Anschlusskabel betrifft normalerweise nur den zugehörigen Rechner; der Ausfall des einzigen zentralen Switches betrifft viele. Ein Bus nutzt einen gemeinsamen Übertragungsweg. Ein Ring verbindet Nachbarn zu einer geschlossenen Struktur; die Ausfallsicherheit hängt vom eingesetzten Verfahren ab.\n\nEin Mesh enthält mehrere Verbindungen zwischen Knoten. Voll vermascht bedeutet: Jeder Knoten ist direkt mit jedem anderen verbunden. Teilvermascht bedeutet: Nur ausgewählte Knoten besitzen zusätzliche Verbindungen. Redundanz kann die Verfügbarkeit erhöhen, verlangt aber geeignete Protokolle und Planung, damit zum Beispiel Ethernet-Schleifen vermieden werden.","example":"Ein Büro besitzt 20 PCs an einem Switch: physisch ein Stern. Für einen wichtigen Standort werden zwei Verteiler und passende redundante Wege geplant. Damit entsteht zusätzliche Verfügbarkeit nur dann, wenn Stromversorgung, Umschaltung und Schleifenschutz ebenfalls berücksichtigt werden. Zwei Kabel allein garantieren noch keinen unterbrechungsfreien Betrieb.","remember":["Physisch beschreibt Verbindungen, logisch den Kommunikationsaufbau.","Ein Stern hat häufig einen zentralen Ausfallpunkt.","Redundanz braucht zusätzlich ein funktionierendes Umschaltkonzept."],"summary":"Physisch beschreibt Verbindungen, logisch den Kommunikationsaufbau.","mistake":"Mehr Verbindungen verbessern nicht automatisch jedes Netz. Ungeplante Schleifen können den Betrieb stören.","terms":[["Stern","Endgeräte sind mit einem zentralen Knoten verbunden."],["Bus","Mehrere Teilnehmer teilen einen Übertragungsweg."],["Ring","Nachbarn bilden eine geschlossene Verbindungskette."],["Mesh","Knoten besitzen mehrere untereinander vermaschte Verbindungen."],["Redundanz","Zusätzliche Ressourcen oder Wege für den Ausfallfall."]],"q":"Was ist beim einfachen Stern ein zentraler Ausfallpunkt?","options":["Der einzige zentrale Switch","Jede Maus","Der DNS-Name eines PCs"],"answer":0,"feedback":"Fällt der einzige zentrale Switch aus, können die dort angeschlossenen Geräte gewöhnlich nicht mehr miteinander kommunizieren.","sections":[]},"fa":{"title":"توپولوژی شبکه؛ چه کسی به چه کسی وصل است؟","goal":"ستاره، باس، حلقه و مش را از نظر ساختار، خرابی و هزینه مقایسه کنی.","definition":"توپولوژی آرایش اتصال‌های شبکه را توصیف می‌کند. نوع فیزیکی، کابل‌ها و تجهیزات را نشان می‌دهد؛ نوع منطقی مشخص می‌کند ارتباط واقعاً چگونه سازمان‌دهی شده است.","explanation":"در ستاره، هر دستگاه به یک مرکز، معمولاً سوئیچ، وصل است. خرابی کابل یک کامپیوتر معمولاً فقط همان دستگاه را قطع می‌کند؛ ولی خرابی تنها سوئیچ مرکزی تعداد زیادی را قطع می‌کند. باس از مسیر مشترک استفاده می‌کند. حلقه، همسایه‌ها را در ساختار بسته وصل می‌کند و مقاومت آن به روش پیاده‌سازی وابسته است.\n\nدر مش، بین گره‌ها چند اتصال وجود دارد. در مش کامل هر گره مستقیماً به همه وصل است؛ در مش جزئی فقط بعضی گره‌ها مسیر اضافه دارند. افزونگی می‌تواند دسترس‌پذیری را بهتر کند، ولی طراحی و پروتکل مناسب لازم است تا مثلاً حلقهٔ مخرب Ethernet ایجاد نشود.","example":"۲۰ کامپیوتر یک دفتر به یک سوئیچ وصل‌اند؛ این ستارهٔ فیزیکی است. برای محل مهم، دو توزیع‌کننده و مسیر افزونه طراحی می‌کنیم. افزایش دسترس‌پذیری زمانی واقعی است که برق، جابه‌جایی مسیر و جلوگیری از حلقه هم بررسی شوند؛ دو کابل به‌تنهایی کار بدون وقفه را تضمین نمی‌کند.","remember":["فیزیکی اتصال‌ها و منطقی روش ارتباط را توضیح می‌دهد.","ستاره اغلب نقطهٔ خرابی مرکزی دارد.","افزونگی به روش تعویض مسیر درست نیاز دارد."],"summary":"فیزیکی اتصال‌ها و منطقی روش ارتباط را توضیح می‌دهد.","mistake":"اتصال بیشتر همیشه شبکه را بهتر نمی‌کند؛ حلقهٔ برنامه‌ریزی‌نشده می‌تواند شبکه را مختل کند.","terms":[["Stern","دستگاه‌ها به مرکز متصل‌اند."],["Bus","چند کاربر مسیر انتقال مشترک دارند."],["Ring","اتصال همسایه‌ها یک حلقه می‌سازد."],["Mesh","گره‌ها چند اتصال به یکدیگر دارند."],["Redundanz","منبع یا مسیر اضافه برای زمان خرابی."]],"q":"در ستارهٔ ساده، نقطهٔ خرابی مرکزی چیست؟","options":["تنها سوئیچ مرکزی","هر ماوس","نام DNS کامپیوتر"],"answer":0,"feedback":"وقتی تنها سوئیچ مرکزی خراب شود، دستگاه‌های متصل معمولاً دیگر با هم ارتباط ندارند.","sections":[]},"minutes":8,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"it-systeme/troubleshoot":{"de":{"title":"Fehlersuche: Vermutung durch Tests eingrenzen","goal":"Du prüfst Link, IP-Konfiguration, Route und Namensauflösung getrennt und dokumentierst Ergebnisse.","definition":"Netzwerk-Fehlersuche ist das systematische Eingrenzen einer Störung. Du beschreibst zuerst das genaue Symptom, prüfst anschließend eine begründete Vermutung und veränderst möglichst nur eine Sache pro Test.","explanation":"Frage zuerst: Seit wann besteht der Fehler, welche Nutzer sind betroffen, und was hat sich geändert? Bei fehlender Verbindung ist ein Beginn an der physischen Ebene sinnvoll: Kabel, WLAN-Anmeldung und Linkzustand. Danach prüfst du IP-Adresse, Maske, Gateway und DNS-Server. Ein falsches Subnetz kann lokale und entfernte Ziele unterschiedlich betreffen.\n\nPrüfe anschließend geeignete lokale und entfernte Ziele sowie DNS mit einer gezielten Namensabfrage. Ping nutzt ICMP; fehlende Antworten können auch durch Filter entstehen. Eine erfolgreiche Namensauflösung beweist umgekehrt nicht, dass der Webdienst erreichbar ist. Bei einem klaren Anwendungsfehler darf die Untersuchung direkt an der Anwendung beginnen.","example":"Ein PC erreicht interne Server, aber eine Website nicht. Du notierst IP-Konfiguration und Fehlermeldung. nslookup liefert die erwartete Adresse. Danach prüfst du Verbindung und Dienstport mit einem geeigneten Werkzeug. So unterscheidest du DNS, Routing, Filter und Dienstfehler, anstatt wahllos mehrere Einstellungen zu ändern.","remember":["Symptom → Vermutung → Test → Ergebnis → nächster Schritt.","Ping und DNS testen unterschiedliche Aspekte.","Änderungen und Ergebnisse dokumentieren."],"summary":"Symptom → Vermutung → Test → Ergebnis → nächster Schritt.","mistake":"Nicht gleichzeitig Router, DNS, IP und Firewall ändern. Danach ist unklar, welche Änderung geholfen oder geschadet hat.","terms":[["Link","Zustand der lokalen physischen oder Funkverbindung."],["ICMP","Protokoll für Kontroll- und Fehlermeldungen, von Ping genutzt."],["Namensauflösung","Abfrage der zu einem Namen gehörenden Informationen."],["Hypothese","Prüfbare Vermutung über die Ursache."],["Fehlerprotokoll","Dokumentation von Symptom, Tests und Ergebnissen."]],"q":"Ein Ping antwortet nicht. Was folgt daraus sicher?","options":["Der DNS-Server ist immer defekt","Das Gerät ist sicher ausgeschaltet","Für diesen Test kam keine ICMP-Antwort an"],"answer":2,"feedback":"Es sind weitere Tests nötig, weil Filter, Verbindungsprobleme oder der Zielhost die fehlende Antwort erklären können.","sections":[]},"fa":{"title":"عیب‌یابی؛ محدودکردن احتمال‌ها با آزمایش","goal":"لینک، تنظیم IP، مسیر و DNS را جدا آزمایش کنی و نتیجه‌ها را ثبت کنی.","definition":"عیب‌یابی شبکه یعنی محدودکردن منظم علت خرابی. ابتدا نشانهٔ دقیق را توصیف می‌کنی، سپس یک احتمال منطقی را آزمایش می‌کنی و در هر آزمایش ترجیحاً فقط یک مورد را تغییر می‌دهی.","explanation":"اول بپرس خطا از چه زمانی است، چه کسانی درگیرند و چه چیزی تغییر کرده است. اگر هیچ ارتباطی نیست، شروع از کابل، ورود WLAN و Link منطقی است. سپس IP، ماسک، Gateway و DNS را بررسی کن. زیرشبکهٔ اشتباه ممکن است روی مقصدهای محلی و دور متفاوت اثر بگذارد.\n\nبعد مقصد محلی و بیرونی مناسب را آزمایش کن و DNS را با پرس‌وجوی نام جدا بررسی کن. Ping از ICMP استفاده می‌کند و ممکن است فیلتر شود؛ بی‌پاسخ‌بودن آن خرابی قطعی مقصد نیست. پاسخ درست DNS هم فعال‌بودن وب‌سرویس را ثابت نمی‌کند. اگر خطا روشن و مربوط به برنامه باشد، می‌توان از همان برنامه شروع کرد.","example":"کامپیوتر به سرور داخلی می‌رسد ولی سایت باز نمی‌شود. تنظیم IP و پیام خطا را ثبت می‌کنی. nslookup آدرس مورد انتظار را می‌دهد. سپس اتصال و پورت سرویس را با ابزار مناسب بررسی می‌کنی؛ به این ترتیب DNS، مسیریابی، فیلتر و خطای سرویس را جدا می‌کنی.","remember":["نشانه ← احتمال ← آزمایش ← نتیجه ← قدم بعدی.","Ping و DNS موضوع‌های متفاوت را آزمایش می‌کنند.","تغییر و نتیجه را ثبت کن."],"summary":"نشانه ← احتمال ← آزمایش ← نتیجه ← قدم بعدی.","mistake":"هم‌زمان روتر، DNS، IP و فایروال را تغییر نده؛ بعد معلوم نمی‌شود کدام تغییر مؤثر بوده است.","terms":[["Link","وضعیت اتصال فیزیکی یا بی‌سیم محلی."],["ICMP","پروتکل پیام‌های کنترلی که Ping از آن استفاده می‌کند."],["Namensauflösung","پرس‌وجوی اطلاعات مرتبط با نام."],["Hypothese","احتمال قابل‌آزمایش دربارهٔ علت."],["Fehlerprotokoll","ثبت نشانه، آزمایش و نتیجه."]],"q":"Ping پاسخ نمی‌دهد؛ کدام نتیجه قطعی است؟","options":["DNS حتماً خراب است","دستگاه حتماً خاموش است","در این آزمایش پاسخ ICMP دریافت نشده است"],"answer":2,"feedback":"آزمایش بیشتر لازم است؛ فیلتر، مشکل مسیر یا خود مقصد می‌تواند علت باشد.","sections":[]},"minutes":8,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"it-systeme/security":{"de":{"title":"Netzwerksicherheit: Schutz in mehreren Schichten","goal":"Du begründest Netztrennung, minimale Rechte, Updates und getestete Backups an einem Beispiel.","definition":"Netzwerksicherheit schützt Vertraulichkeit, Integrität und Verfügbarkeit. Daten sollen nur berechtigte Personen lesen, Änderungen sollen kontrolliert sein und wichtige Dienste sollen zuverlässig zur Verfügung stehen.","explanation":"Beginne mit der Frage, welche Systeme und Daten geschützt werden müssen. Trenne Geräte mit unterschiedlichen Risiken, zum Beispiel Gäste, Verwaltung und Server. Regeln erlauben nur erforderliche Verbindungen. Nach dem Prinzip der minimalen Rechte erhält ein Konto nur die für seine Aufgabe nötigen Befugnisse.\n\nAktualisierungen schließen bekannte Schwachstellen; sichere Passwörter und Mehrfaktor-Anmeldung schützen Konten. Protokolle und Monitoring helfen, Auffälligkeiten zu erkennen. Backups werden getrennt geschützt und regelmäßig durch Wiederherstellung getestet. Diese Maßnahmen ergänzen sich: Ein Backup verhindert keinen Datenabfluss und ein VLAN ersetzt keine Zugriffskontrolle.","example":"Ein Gast darf über WLAN ins Internet, aber nicht auf den Personalserver. Du nutzt ein Gast-VLAN, eine klare Firewallregel und getrennte Zugangsdaten. Der Personalserver erhält Updates und gesicherte Backups. Du prüfst mit einem Gastgerät, dass Internet funktioniert und der interne Zugriff tatsächlich gesperrt ist.","remember":["Schutzmaßnahmen müssen zum Risiko passen.","Minimale Rechte begrenzen mögliche Schäden.","Backups sind erst nach geprüftem Restore belastbar."],"summary":"Schutzmaßnahmen müssen zum Risiko passen.","mistake":"Eine offene Verbindung ist nicht allein deshalb sicher, weil die Anwendung damit funktioniert.","terms":[["Vertraulichkeit","Informationen bleiben nur für Berechtigte lesbar."],["Integrität","Daten bleiben korrekt und Änderungen nachvollziehbar."],["Verfügbarkeit","Dienste und Daten sind bei Bedarf nutzbar."],["Least Privilege","Nur die für eine Aufgabe nötigen Rechte."],["Restore","Wiederherstellung von Daten aus einer Sicherung."]],"q":"Welche Maßnahme prüft, ob ein Backup im Ernstfall nutzbar ist?","options":["Eine testweise Wiederherstellung","Nur den Dateinamen ansehen","Nur den Server neu starten"],"answer":0,"feedback":"Erst ein Restore-Test zeigt, ob Sicherung, Zugriff und Wiederherstellungsverfahren zusammen funktionieren.","sections":[]},"fa":{"title":"امنیت شبکه؛ محافظت در چند سطح","goal":"جداسازی شبکه، حداقل دسترسی، به‌روزرسانی و پشتیبان آزمایش‌شده را با مثال توضیح بدهی.","definition":"امنیت شبکه از محرمانگی، یکپارچگی و دسترس‌پذیری محافظت می‌کند؛ فقط افراد مجاز داده را بخوانند، تغییرها کنترل شوند و سرویس‌های مهم قابل استفاده باشند.","explanation":"اول مشخص کن چه سیستم و داده‌ای باید محافظت شود. دستگاه‌های با ریسک متفاوت مثل مهمان، مدیریت و سرور را جدا کن. قوانین فقط ارتباط ضروری را اجازه دهند. طبق اصل حداقل دسترسی، هر حساب فقط مجوز لازم برای کارش را داشته باشد.\n\nبه‌روزرسانی آسیب‌پذیری شناخته‌شده را رفع می‌کند؛ رمز مناسب و ورود چندمرحله‌ای حساب را محافظت می‌کند. Log و Monitoring رفتار غیرعادی را آشکار می‌کنند. پشتیبان باید جدا محافظت شود و بازیابی آن مرتب آزمایش شود. این کارها مکمل‌اند: پشتیبان جلوی افشای اطلاعات را نمی‌گیرد و VLAN جای کنترل دسترسی نیست.","example":"مهمان باید اینترنت داشته باشد ولی به سرور منابع انسانی نرسد. VLAN مهمان، قانون فایروال و اطلاعات ورود جدا تنظیم می‌کنی. سرور به‌روزرسانی و پشتیبان محافظت‌شده دارد. با دستگاه مهمان بررسی می‌کنی اینترنت کار کند ولی دسترسی داخلی واقعاً بسته باشد.","remember":["محافظت باید متناسب با ریسک باشد.","حداقل دسترسی خسارت احتمالی را محدود می‌کند.","پشتیبان با آزمایش بازیابی قابل اتکا می‌شود."],"summary":"محافظت باید متناسب با ریسک باشد.","mistake":"کارکردن برنامه با یک اتصال باز، امن‌بودن آن را ثابت نمی‌کند.","terms":[["Vertraulichkeit","خواندن اطلاعات فقط توسط افراد مجاز."],["Integrität","درستی داده و قابل‌پیگیری‌بودن تغییر."],["Verfügbarkeit","قابل‌استفاده‌بودن داده و سرویس هنگام نیاز."],["Least Privilege","فقط دسترسی لازم برای وظیفه."],["Restore","بازیابی داده از پشتیبان."]],"q":"چه کاری نشان می‌دهد پشتیبان هنگام نیاز قابل استفاده است؟","options":["بازیابی آزمایشی","فقط نگاه‌کردن نام فایل","فقط راه‌اندازی مجدد سرور"],"answer":0,"feedback":"آزمایش بازیابی نشان می‌دهد فایل، مجوز و روش بازگردانی با هم درست کار می‌کنند.","sections":[]},"minutes":7,"source":["BSI · IT-Grundschutz","https://www.bsi.bund.de/DE/Themen/Unternehmen-und-Organisationen/Standards-und-Zertifizierung/IT-Grundschutz/it-grundschutz_node.html"],"editorial":true},"it-technik/iotcps":{"de":{"title":"IoT und CPS: messen, vernetzen, handeln","goal":"Du unterscheidest vernetzte Geräte von einem rückgekoppelten cyber-physischen System.","definition":"Das Internet of Things vernetzt physische Gegenstände, damit sie Daten austauschen können. Ein cyber-physisches System verbindet physische Vorgänge mit digitaler Verarbeitung; Sensoren und Aktoren koppeln beide Bereiche miteinander.","explanation":"Der Sensor erfasst einen Zustand, etwa Temperatur oder Position. Ein Mikrocontroller verarbeitet den Messwert und führt das Programm aus. Über ein Netzwerk können Daten an einen Server oder eine App gelangen. Ein Aktor verändert die Umgebung, beispielsweise durch Einschalten eines Lüfters. Wird der neue Zustand wieder gemessen und bei der Entscheidung berücksichtigt, entsteht eine Rückkopplung.\n\nNicht jedes IoT-Gerät braucht einen Aktor oder eine Cloud. Ein vernetzter Temperaturlogger kann nur messen. Ein CPS kann hingegen auch lokal arbeiten. Bei der Planung zählen Messgenauigkeit, Reaktionszeit, Ausfallsicherheit und Schutz vor unberechtigter Steuerung.","example":"Ein Gewächshaus misst 30 °C. Der Controller vergleicht mit dem Sollwert von 25 °C und schaltet über eine geeignete Treiberstufe einen Lüfter ein. Der Sensor misst erneut. Sinkt die Temperatur unter eine festgelegte Abschaltgrenze, wird der Lüfter ausgeschaltet. Eine Hysterese verhindert zu häufiges Umschalten.","remember":["Sensor misst, Controller verarbeitet, Aktor verändert.","Vernetzung und Rückkopplung sind unterschiedliche Eigenschaften.","Cloud ist eine Möglichkeit, keine Pflicht."],"summary":"Sensor misst, Controller verarbeitet, Aktor verändert.","mistake":"Ein Mikrocontroller-Ausgang darf einen leistungsstarken Motor nicht ohne passende elektrische Ansteuerung versorgen.","terms":[["IoT","Vernetzung physischer Gegenstände für Datenaustausch."],["CPS","Kopplung physischer Vorgänge und digitaler Verarbeitung."],["Sensor","Erfasst eine physische Größe."],["Aktor","Setzt ein Steuersignal in eine physische Wirkung um."],["Rückkopplung","Ein Ergebnis wird erneut gemessen und berücksichtigt."]],"q":"Welches Bauteil verändert die physische Umgebung?","options":["Sensor","Aktor","Messprotokoll"],"answer":1,"feedback":"Der Aktor führt eine Wirkung aus, zum Beispiel Bewegung oder Kühlung. Der Sensor misst.","sections":[]},"fa":{"title":"IoT و CPS؛ اندازه‌گیری، اتصال و عمل","goal":"دستگاه متصل را از سیستم سایبرفیزیکی دارای بازخورد تشخیص بدهی.","definition":"اینترنت اشیا دستگاه‌های واقعی را برای تبادل داده متصل می‌کند. سیستم سایبرفیزیکی یا CPS فرایند فیزیکی و پردازش دیجیتال را به هم پیوند می‌دهد؛ سنسور و عملگر پل بین این دو هستند.","explanation":"سنسور وضعیتی مثل دما یا موقعیت را اندازه می‌گیرد. میکروکنترلر داده را پردازش و برنامه را اجرا می‌کند. شبکه می‌تواند مقدار را به سرور یا برنامه بفرستد. عملگر مثل فن، محیط را تغییر می‌دهد. اگر وضعیت تازه دوباره اندازه‌گیری و در تصمیم استفاده شود، بازخورد داریم.\n\nهر دستگاه IoT به عملگر یا Cloud نیاز ندارد؛ ثبت‌کنندهٔ دمای متصل ممکن است فقط اندازه بگیرد. CPS هم می‌تواند محلی کار کند. در طراحی باید دقت، زمان واکنش، رفتار هنگام خرابی و جلوگیری از کنترل غیرمجاز بررسی شود.","example":"گلخانه ۳۰ درجه است؛ کنترلر آن را با هدف ۲۵ درجه مقایسه می‌کند و فن را با مدار راه‌انداز مناسب روشن می‌کند. سنسور دوباره اندازه می‌گیرد. با پایین‌رفتن از حد خاموشی، فن خاموش می‌شود. فاصلهٔ حد روشن و خاموش از قطع‌و‌وصل زیاد جلوگیری می‌کند.","remember":["سنسور می‌سنجد، کنترلر پردازش می‌کند، عملگر تغییر می‌دهد.","اتصال شبکه و بازخورد دو ویژگی متفاوت‌اند.","Cloud یک امکان است، نه الزام."],"summary":"سنسور می‌سنجد، کنترلر پردازش می‌کند، عملگر تغییر می‌دهد.","mistake":"پایهٔ میکروکنترلر نباید موتور پرقدرت را بدون مدار راه‌انداز مناسب تغذیه کند.","terms":[["IoT","اتصال اشیای واقعی برای تبادل داده."],["CPS","پیوند فرایند فیزیکی و پردازش دیجیتال."],["Sensor","اندازه‌گیری کمیت فیزیکی."],["Aktor","تبدیل فرمان به اثر فیزیکی."],["Rückkopplung","اندازه‌گیری دوبارهٔ نتیجه و استفاده از آن."]],"q":"کدام جزء محیط فیزیکی را تغییر می‌دهد؟","options":["سنسور","عملگر","گزارش اندازه‌گیری"],"answer":1,"feedback":"عملگر اثر ایجاد می‌کند، مثل حرکت یا خنک‌کردن؛ سنسور اندازه می‌گیرد.","sections":[]},"minutes":8,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/sensor":{"de":{"title":"Sensor und Aktor: Ein- und Ausgabe der realen Welt","goal":"Du ordnest Messung und Wirkung zu und unterscheidest analoge und digitale Signale.","definition":"Ein Sensor wandelt eine physische Größe in ein auswertbares Signal um. Ein Aktor wandelt ein elektrisches Steuersignal in eine physische Wirkung um. Gemeinsam ermöglichen sie einem Controller, die Umgebung zu beobachten und zu beeinflussen.","explanation":"Ein analoger Sensor liefert einen veränderlichen Messwert, etwa eine Spannung. Ein Analog-Digital-Wandler macht daraus einen Zahlenwert. Ein digitaler Sensor überträgt Werte als digitale Informationen, häufig über eine definierte Schnittstelle wie I²C. Digital bedeutet nicht automatisch, dass nur die Zustände an und aus gemessen werden.\n\nBei einem Aktor muss zwischen Steuerung und Leistungsversorgung unterschieden werden. Eine LED braucht geeignete Strombegrenzung. Motoren oder Relais benötigen oft eine Treiberschaltung und gegebenenfalls Schutz vor induktiven Spannungsspitzen. Prüfe Messbereich, Genauigkeit, Versorgung und zulässige Anschlüsse immer anhand des Datenblatts.","example":"Ein Helligkeitssensor misst die Beleuchtung. Das Programm vergleicht den Wert mit einem Schwellwert. Bei Dunkelheit schaltet ein geeigneter Ausgang eine LED ein. Eine zweite Messung zeigt, ob sich die Umgebung geändert hat. Für eine aussagekräftige Prüfung dokumentierst du Messwert, Grenzwert und Zustand der LED.","remember":["Sensor: Umwelt → Daten. Aktor: Steuerung → Wirkung.","Digitale Sensoren können viele Zahlenwerte übertragen.","Elektrische Grenzwerte gehören zum Aufbau."],"summary":"Sensor: Umwelt → Daten. Aktor: Steuerung → Wirkung.","mistake":"Die Versorgungsspannung eines Sensors und die zulässige Signalspannung am GPIO sind nicht automatisch gleich.","terms":[["Analogsignal","Kontinuierlich veränderliches Signal."],["Digitalsignal","Signal mit diskreten Zuständen beziehungsweise codierten Werten."],["ADC","Wandler von analoger Messgröße zu digitalem Zahlenwert."],["Messbereich","Bereich, in dem ein Sensor spezifiziert misst."],["Treiberstufe","Schaltung zwischen Steuersignal und leistungsstarkem Verbraucher."]],"q":"Was macht ein ADC?","options":["Er übersetzt IP-Adressen","Er wandelt ein analoges Signal in einen digitalen Zahlenwert","Er speichert WLAN-Passwörter"],"answer":1,"feedback":"Der Controller kann den digitalen Zahlenwert anschließend im Programm verarbeiten.","sections":[]},"fa":{"title":"سنسور و عملگر؛ ورودی و خروجی دنیای واقعی","goal":"اندازه‌گیری و اثرگذاری را جدا کنی و سیگنال آنالوگ و دیجیتال را بشناسی.","definition":"سنسور یک کمیت فیزیکی را به سیگنال قابل پردازش تبدیل می‌کند. عملگر فرمان الکتریکی را به اثر فیزیکی تبدیل می‌کند. این دو به کنترلر امکان مشاهده و تغییر محیط را می‌دهند.","explanation":"سنسور آنالوگ مقدار متغیری مانند ولتاژ می‌دهد؛ مبدل ADC آن را به عدد تبدیل می‌کند. سنسور دیجیتال مقدار را به شکل اطلاعات دیجیتال، مثلاً از طریق I²C، می‌فرستد. دیجیتال الزاماً به معنی اندازه‌گیری فقط روشن و خاموش نیست.\n\nدر عملگر، فرمان و تأمین توان را جدا کن. LED به محدودکردن جریان نیاز دارد. موتور یا رله اغلب مدار راه‌انداز و گاهی محافظت در برابر ولتاژ القایی لازم دارد. محدودهٔ اندازه‌گیری، دقت، ولتاژ و اتصالات مجاز را از دیتاشیت بررسی کن.","example":"سنسور روشنایی مقدار نور را می‌سنجد. برنامه آن را با حد مشخص مقایسه می‌کند. در تاریکی، خروجی مناسب LED را روشن می‌کند. اندازه‌گیری بعدی وضعیت تازه را نشان می‌دهد. برای آزمایش، مقدار، حد و وضعیت LED را ثبت می‌کنی.","remember":["سنسور: محیط به داده؛ عملگر: فرمان به اثر.","سنسور دیجیتال می‌تواند مقدارهای عددی زیادی بفرستد.","حدود الکتریکی بخش مهم ساخت مدارند."],"summary":"سنسور: محیط به داده؛ عملگر: فرمان به اثر.","mistake":"ولتاژ تغذیهٔ سنسور و ولتاژ مجاز سیگنال GPIO الزاماً یکسان نیستند.","terms":[["Analogsignal","سیگنال با تغییر پیوسته."],["Digitalsignal","سیگنال با وضعیت گسسته یا مقدار کدگذاری‌شده."],["ADC","تبدیل مقدار آنالوگ به عدد دیجیتال."],["Messbereich","محدودهٔ مجاز اندازه‌گیری سنسور."],["Treiberstufe","مدار بین فرمان و مصرف‌کنندهٔ پرقدرت."]],"q":"ADC چه می‌کند؟","options":["IP را ترجمه می‌کند","سیگنال آنالوگ را به عدد دیجیتال تبدیل می‌کند","رمز WLAN را ذخیره می‌کند"],"answer":1,"feedback":"کنترلر می‌تواند عدد دیجیتال را در برنامه پردازش کند.","sections":[]},"minutes":7,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/esp32":{"de":{"title":"ESP32: ein kleiner Rechner für Steuerungsaufgaben","goal":"Du beschreibst Programm, GPIO und Versorgung und prüfst die Pinbelegung vor dem Anschluss.","definition":"Der ESP32 ist eine Mikrocontroller-Familie. Ein Mikrocontroller führt ein gespeichertes Programm aus und besitzt Anschlüsse für Ein- und Ausgaben. Viele Varianten bieten WLAN und Bluetooth; Funktionen und Pins unterscheiden sich je nach Modell.","explanation":"Auf einem Entwicklungsboard ergänzen USB-Anschluss, Spannungsregler und weitere Bauteile den eigentlichen Chip. GPIO-Pins können je nach Pin und Konfiguration digitale Signale lesen oder ausgeben. Manche Pins besitzen zusätzliche Funktionen, etwa ADC, I²C oder UART. Nicht jeder Pin ist für jede Aufgabe geeignet.\n\nIm Arduino-Umfeld wird setup() einmal nach dem Start ausgeführt. loop() läuft anschließend wiederholt. Du initialisierst zuerst Anschlüsse und Schnittstellen, liest dann Eingänge und steuerst Ausgänge. Übliche ESP32-Logik arbeitet mit 3,3 V; zulässige Pegel, Stromgrenzen und Boot-Pins müssen für das konkrete Board geprüft werden.","example":"Du willst eine Taste lesen und eine LED schalten. Prüfe zuerst die Board-Pinbelegung, definiere einen geeigneten Eingang mit stabilem Ruhepegel und einen geeigneten Ausgang. Gib den Tasterzustand testweise im seriellen Monitor aus. Erst wenn das Lesen stimmt, ergänzt du die LED-Steuerung. So bleibt die Fehlersuche übersichtlich.","remember":["Board und Chip sind nicht identisch.","GPIO-Funktionen hängen vom konkreten Pin und Modell ab.","Erst einfach testen, dann Sensoren und Netzwerk ergänzen."],"summary":"Board und Chip sind nicht identisch.","mistake":"Ein mit 5 V versorgtes Entwicklungsboard bedeutet nicht, dass jeder GPIO ein 5-V-Signal verträgt.","terms":[["Mikrocontroller","Chip mit Recheneinheit, Speicher und Ein-/Ausgabefunktionen."],["GPIO","Allgemein nutzbarer digitaler Ein-/Ausgang."],["Pinout","Übersicht der Pinbelegung."],["setup()","Einmalige Initialisierung im Arduino-Programm."],["loop()","Wiederholt ausgeführter Programmteil."]],"q":"Wo initialisierst du im Arduino-Programm normalerweise die GPIO-Modi?","options":["In setup()","Im WLAN-Passwort","Nur im Dateinamen"],"answer":0,"feedback":"setup() läuft einmal beim Start und eignet sich für die Initialisierung.","sections":[]},"fa":{"title":"ESP32؛ رایانهٔ کوچک برای کنترل","goal":"برنامه، GPIO و تغذیه را بشناسی و پیش از اتصال، پایه‌ها را بررسی کنی.","definition":"ESP32 خانواده‌ای از میکروکنترلرهاست. میکروکنترلر برنامهٔ ذخیره‌شده را اجرا می‌کند و برای ورودی و خروجی پایه دارد. بسیاری از مدل‌ها WLAN و Bluetooth دارند، ولی امکانات و پایه‌ها به مدل وابسته‌اند.","explanation":"روی برد توسعه، USB، تنظیم‌کنندهٔ ولتاژ و قطعات دیگر کنار تراشه قرار دارند. GPIO بسته به پایه و تنظیم، سیگنال دیجیتال را می‌خواند یا می‌فرستد. بعضی پایه‌ها ADC، I²C یا UART هم دارند؛ هر پایه برای هر کار مناسب نیست.\n\nدر محیط Arduino، تابع setup() پس از روشن‌شدن یک بار و loop() مرتب تکرار می‌شود. ابتدا پایه و رابط‌ها را تنظیم می‌کنی، سپس ورودی را می‌خوانی و خروجی را کنترل می‌کنی. منطق معمول ESP32 با ۳٫۳ ولت کار می‌کند؛ حد جریان، ولتاژ مجاز و پایه‌های Boot را برای مدل مشخص بررسی کن.","example":"می‌خواهی کلید را بخوانی و LED را کنترل کنی. ابتدا Pinout را بررسی و ورودی با حالت پایدار و خروجی مناسب انتخاب می‌کنی. وضعیت کلید را در Serial Monitor چاپ می‌کنی. وقتی خواندن درست شد، کنترل LED را اضافه می‌کنی تا عیب‌یابی ساده بماند.","remember":["برد و تراشه یک چیز نیستند.","قابلیت GPIO به پایه و مدل بستگی دارد.","اول ساده آزمایش کن، بعد سنسور و شبکه را اضافه کن."],"summary":"برد و تراشه یک چیز نیستند.","mistake":"تغذیهٔ ۵ ولتی برد به معنی تحمل سیگنال ۵ ولت توسط GPIO نیست.","terms":[["Mikrocontroller","تراشه با پردازنده، حافظه و ورودی‌خروجی."],["GPIO","پایهٔ ورودی یا خروجی دیجیتال عمومی."],["Pinout","نقشهٔ عملکرد پایه‌ها."],["setup()","راه‌اندازی یک‌باره در برنامهٔ Arduino."],["loop()","بخش تکرارشوندهٔ برنامه."]],"q":"حالت GPIO معمولاً کجا تنظیم می‌شود؟","options":["در setup()","داخل رمز WLAN","فقط نام فایل"],"answer":0,"feedback":"setup() هنگام شروع یک بار اجرا و برای تنظیم اولیه استفاده می‌شود.","sections":[]},"minutes":7,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/pull":{"de":{"title":"Pull-up und Pull-down: einen Eingang stabil halten","goal":"Du erklärst den Ruhepegel eines Tasters und liest ein aktiv-low-Signal richtig.","definition":"Ein Pull-Widerstand hält einen digitalen Eingang auf einem definierten Pegel, wenn kein anderes Bauteil ihn aktiv steuert. Ohne diesen Bezug kann ein hochohmiger Eingang schweben und scheinbar zufällige Werte liefern.","explanation":"Ein Pull-up verbindet den Eingang über einen Widerstand mit der positiven Logikversorgung. Ist ein Taster zwischen Eingang und Masse angeschlossen, wird ohne Tastendruck HIGH gelesen. Beim Drücken liegt der Eingang an Masse und wird LOW. Das Signal heißt aktiv-low. Der Widerstand begrenzt dabei den Strom.\n\nEin Pull-down verbindet den Eingang über einen Widerstand mit Masse. Ein passend angeschlossener Taster zieht den Eingang beim Drücken auf HIGH. Manche Mikrocontroller-Pins bieten interne Pull-Widerstände. Ob sie vorhanden und geeignet sind, hängt vom konkreten Pin und Modell ab. Pull-Widerstände sorgen für einen Ruhepegel; sie entfernen mechanisches Prellen nicht automatisch.","example":"Bei INPUT_PULLUP ist der Taster passend zwischen GPIO und GND angeschlossen. Das Programm behandelt digitalRead(pin) == LOW als gedrückt. Im Test protokollierst du zunächst 1 ohne Druck und 0 beim Druck. Wenn das Signal trotz Pull mehrfach wechselt, prüfst du zusätzlich die Entprellung.","remember":["Pull-up: Ruhe HIGH, Taste nach GND ergibt LOW.","Pull-down: Ruhe LOW.","Stabiler Ruhepegel und Entprellung sind verschiedene Aufgaben."],"summary":"Pull-up: Ruhe HIGH, Taste nach GND ergibt LOW.","mistake":"HIGH bedeutet nicht grundsätzlich gedrückt. Bei aktiv-low bedeutet gerade LOW den aktiven Zustand.","terms":[["Pull-up","Widerstand für definierten HIGH-Ruhepegel."],["Pull-down","Widerstand für definierten LOW-Ruhepegel."],["Floating","Eingang ohne stabilen Bezug."],["Aktiv-low","Die aktive Funktion wird durch LOW angezeigt."],["GND","Gemeinsamer elektrischer Massebezug."]],"q":"Ein Taster liegt zwischen INPUT_PULLUP-Pin und GND. Was bedeutet LOW?","options":["Taste gedrückt","Taste sicher offen","WLAN verbunden"],"answer":0,"feedback":"Beim Drücken zieht der Taster den Eingang gegen Masse.","sections":[]},"fa":{"title":"Pull-up و Pull-down؛ پایدارکردن ورودی","goal":"وضعیت عادی کلید را توضیح بدهی و سیگنال Active Low را درست بخوانی.","definition":"مقاومت Pull زمانی که هیچ قطعه‌ای ورودی را فعال کنترل نمی‌کند، آن را در وضعیت مشخص نگه می‌دارد. ورودی با مقاومت بالا بدون این مرجع ممکن است شناور شود و مقدارهای نامطمئن بدهد.","explanation":"Pull-up ورودی را با مقاومت به ولتاژ مثبت منطق وصل می‌کند. اگر کلید بین ورودی و GND باشد، بدون فشردن HIGH و با فشردن LOW خوانده می‌شود. این روش Active Low است. مقاومت جریان را محدود می‌کند.\n\nPull-down ورودی را با مقاومت به زمین می‌برد. کلید مناسب هنگام فشردن ورودی را HIGH می‌کند. برخی پایه‌ها مقاومت Pull داخلی دارند؛ وجود و مناسب‌بودن آن به مدل و پایه بستگی دارد. Pull فقط وضعیت عادی را پایدار می‌کند و پرش مکانیکی کلید را خودبه‌خود حذف نمی‌کند.","example":"در INPUT_PULLUP کلید به‌درستی بین GPIO و GND وصل است. برنامه digitalRead(pin) == LOW را فشرده‌شدن می‌داند. ابتدا ثبت می‌کنی بدون فشار ۱ و با فشار ۰ دریافت شود. اگر تغییر چندباره وجود داشت، Entprellung را هم بررسی می‌کنی.","remember":["Pull-up: حالت عادی HIGH؛ کلید به زمین LOW می‌دهد.","Pull-down: حالت عادی LOW.","پایداری ورودی و حذف پرش کلید دو کار جدا هستند."],"summary":"Pull-up: حالت عادی HIGH؛ کلید به زمین LOW می‌دهد.","mistake":"HIGH همیشه به معنی فشرده‌شدن نیست؛ در Active Low، LOW حالت فعال است.","terms":[["Pull-up","مقاومت برای وضعیت عادی HIGH."],["Pull-down","مقاومت برای وضعیت عادی LOW."],["Floating","ورودی بدون مرجع پایدار."],["Aktiv-low","فعال‌شدن با وضعیت LOW."],["GND","مرجع زمین مشترک مدار."]],"q":"کلید بین INPUT_PULLUP و GND است؛ LOW چه معنی دارد؟","options":["کلید فشرده است","کلید حتماً باز است","WLAN وصل است"],"answer":0,"feedback":"هنگام فشار، کلید ورودی را به زمین می‌برد.","sections":[]},"minutes":8,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/prellen":{"de":{"title":"Taster entprellen: ein Druck, ein Ereignis","goal":"Du beschreibst mechanisches Prellen und setzt eine zeitliche Stabilitätsprüfung in eigenen Worten um.","definition":"Prellen bedeutet, dass ein mechanischer Kontakt beim Betätigen kurz mehrmals öffnet und schließt. Ein schneller Mikrocontroller kann diese Wechsel als mehrere Tastendrücke zählen. Entprellung macht daraus ein verlässlich auswertbares Ereignis.","explanation":"Eine einfache Softwarelösung merkt sich den zuletzt gelesenen Rohzustand und den Zeitpunkt einer Änderung. Erst wenn der Zustand für eine festgelegte Zeit stabil bleibt, übernimmt das Programm ihn als gültigen Zustand. Danach kann eine Flankenerkennung nur den Übergang von nicht gedrückt zu gedrückt zählen. Die Entprellzeit wird passend zu Taster und Anwendung gewählt, beispielsweise zunächst einige zehn Millisekunden und anschließend gemessen.\n\nEin langes blockierendes delay() ist zwar leicht verständlich, hält aber auch andere Aufgaben auf. Mit einer Zeitabfrage, etwa über millis(), kann das Programm während der Wartezeit weiterhin Sensoren oder Netzwerkereignisse bearbeiten. Auch Hardware kann entprellen, muss aber passend ausgelegt werden.","example":"Ein Zähler soll bei jedem Druck um eins steigen. Du liest den Eingang fortlaufend, wartest nach jeder Rohänderung auf einen stabilen Zustand und zählst erst die bestätigte Druckflanke. Gedrückthalten erzeugt dann kein ständiges Hochzählen, solange keine bewusste Wiederholfunktion programmiert ist.","remember":["Prellen ist ein physischer Kontaktfehler beim Umschalten.","Entprellung bestätigt einen stabilen Zustand.","Flankenerkennung unterscheidet Drücken von Gedrückthalten."],"summary":"Prellen ist ein physischer Kontaktfehler beim Umschalten.","mistake":"Ein Pull-up verhindert einen schwebenden Eingang, beseitigt aber nicht jedes mechanische Prellen.","terms":[["Prellen","Kurze mehrfache Kontaktwechsel bei einer Betätigung."],["Entprellzeit","Geforderte Dauer eines stabilen Zustands."],["Rohzustand","Ungefiltert gelesener Eingangspegel."],["Flanke","Übergang zwischen zwei Signalzuständen."],["Nicht blockierend","Andere Aufgaben können während einer Wartephase weiterlaufen."]],"q":"Was verhindert das Zählen vieler Ereignisse beim Gedrückthalten?","options":["Nur den Pin umbenennen","Bestätigte Druckflanke statt jeden LOW-Wert zählen","Den Bildschirm ausschalten"],"answer":1,"feedback":"Ein Ereignis entsteht beim Zustandsübergang, nicht bei jeder Programmschleife mit gedrückter Taste.","sections":[]},"fa":{"title":"حذف پرش کلید؛ یک فشار، یک رویداد","goal":"پرش مکانیکی کلید و بررسی پایداری زمانی را توضیح بدهی.","definition":"Prellen یعنی تماس مکانیکی کلید هنگام حرکت، برای مدت کوتاه چند بار باز و بسته شود. میکروکنترلر سریع ممکن است آن را چند فشار حساب کند. Entprellung این تغییرها را به رویداد قابل اعتماد تبدیل می‌کند.","explanation":"روش سادهٔ نرم‌افزاری، آخرین مقدار خام و زمان تغییر آن را نگه می‌دارد. وقتی مقدار برای مدت مشخص ثابت بماند، برنامه آن را معتبر می‌پذیرد. سپس تشخیص لبه فقط تغییر از «آزاد» به «فشرده» را می‌شمارد. زمان حذف پرش باید با کلید و کاربرد تنظیم شود؛ مثلاً با چند ده میلی‌ثانیه شروع و سپس اندازه‌گیری شود.\n\nدستور delay() طولانی ساده است، ولی کارهای دیگر را هم متوقف می‌کند. با بررسی زمان مثل millis()، برنامه هنگام انتظار می‌تواند سنسور و شبکه را هم رسیدگی کند. حذف پرش سخت‌افزاری نیز ممکن است، ولی باید درست طراحی شود.","example":"شمارنده باید با هر فشار یکی زیاد شود. ورودی مرتب خوانده می‌شود؛ پس از تغییر خام، برنامه منتظر پایداری می‌ماند و فقط لبهٔ تأییدشدهٔ فشار را می‌شمارد. نگه‌داشتن کلید، بدون برنامه‌ریزی تکرار، نباید شمارنده را پیوسته افزایش دهد.","remember":["پرش هنگام تغییر تماس مکانیکی ایجاد می‌شود.","Entprellung وضعیت پایدار را تأیید می‌کند.","تشخیص لبه فشار جدید را از نگه‌داشتن جدا می‌کند."],"summary":"پرش هنگام تغییر تماس مکانیکی ایجاد می‌شود.","mistake":"Pull-up ورودی شناور را رفع می‌کند، ولی الزاماً پرش مکانیکی را حذف نمی‌کند.","terms":[["Prellen","تغییر چندبارهٔ کوتاه تماس با یک فشار."],["Entprellzeit","زمان لازم برای معتبرشدن حالت پایدار."],["Rohzustand","مقدار خام ورودی."],["Flanke","لحظهٔ تغییر بین دو وضعیت."],["Nicht blockierend","امکان ادامهٔ کارهای دیگر هنگام انتظار."]],"q":"چه چیزی شمارش زیاد هنگام نگه‌داشتن کلید را متوقف می‌کند؟","options":["فقط تغییر نام پایه","شمردن لبهٔ فشار معتبر به جای هر LOW","خاموش‌کردن نمایشگر"],"answer":1,"feedback":"رویداد هنگام تغییر حالت ایجاد می‌شود، نه در هر دور برنامه با کلید فشرده.","sections":[]},"minutes":8,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/baud":{"de":{"title":"Baudrate: serielle Daten richtig lesen","goal":"Du erklärst Baudrate und Bitrate und erkennst unpassende Einstellungen im seriellen Monitor.","definition":"Die Baudrate gibt an, wie viele Symbole pro Sekunde übertragen werden. Die Bitrate zählt dagegen Bits pro Sekunde. Bei einer einfachen binären UART-Verbindung steht ein Symbol für ein Bit; bei anderen Übertragungsverfahren muss das nicht so sein.","explanation":"Eine UART-Verbindung überträgt Daten nacheinander über eine serielle Leitung. Sender und Empfänger müssen unter anderem passende Geschwindigkeit, Datenbits, Parität und Stoppbits verwenden. 8N1 bedeutet acht Datenbits, keine Parität und ein Stoppbit. Zusätzlich beginnt ein üblicher Rahmen mit einem Startbit.\n\nDeshalb entsprechen 9600 Bit/s bei 8N1 nicht 9600 Nutzzeichen pro Sekunde: Ein Zeichen benötigt hier typischerweise zehn übertragene Bits. Für einen Test müssen außerdem TX und RX passend verbunden sein und ein gemeinsamer Massebezug bestehen. Zulässige elektrische Pegel werden separat geprüft; UART-Logik ist nicht automatisch RS-232.","example":"Das Programm nutzt Serial.begin(115200). Im Monitor sind 9600 eingestellt: Zeichen erscheinen unlesbar. Du stellst den Monitor ebenfalls auf 115200 und prüfst eine bekannte Testzeile. Bleibt der Fehler, untersuchst du Rahmenparameter, Verdrahtung, gemeinsame Masse und Pegel.","remember":["Baud zählt Symbole, Bitrate zählt Bits.","Bei einfachem binärem UART sind beide Zahlen oft gleich.","Nutzdatenrate berücksichtigt Start- und Stoppbits."],"summary":"Baud zählt Symbole, Bitrate zählt Bits.","mistake":"Unlesbare Zeichen beweisen keinen defekten Controller; oft passen die Übertragungsparameter nicht.","terms":[["Baudrate","Symbole pro Sekunde."],["Bitrate","Übertragene Bits pro Sekunde."],["UART","Asynchrone serielle Schnittstelle."],["8N1","Acht Datenbits, keine Parität, ein Stoppbit."],["TX / RX","Sende- und Empfangsleitung."]],"q":"Was bedeutet das N in 8N1?","options":["Keine Parität","Kein Startbit","Keine Daten"],"answer":0,"feedback":"8N1 enthält acht Datenbits, keine Paritätsprüfung und ein Stoppbit.","sections":[]},"fa":{"title":"Baudrate؛ خواندن درست دادهٔ سریال","goal":"Baudrate و Bitrate را توضیح بدهی و تنظیم ناسازگار Serial Monitor را بشناسی.","definition":"Baudrate تعداد نمادهای ارسالی در ثانیه را می‌گوید؛ Bitrate تعداد بیت‌ها در ثانیه است. در UART سادهٔ دودویی، هر نماد یک بیت است؛ در روش‌های دیگر این برابری الزامی نیست.","explanation":"UART داده را بیت‌به‌بیت روی مسیر سریال می‌فرستد. سرعت، تعداد بیت داده، Parität و Stoppbit در دو طرف باید سازگار باشد. 8N1 یعنی هشت بیت داده، بدون Parität و یک بیت پایان؛ قاب معمول یک بیت شروع هم دارد.\n\nپس در 8N1، سرعت ۹۶۰۰ بیت بر ثانیه معادل ۹۶۰۰ نویسه نیست؛ هر نویسه معمولاً ده بیت انتقال می‌خواهد. TX و RX باید درست متصل و زمین مشترک برقرار باشد. سطح ولتاژ را جدا بررسی کن؛ منطق UART خودبه‌خود همان RS-232 نیست.","example":"برنامه Serial.begin(115200) دارد ولی مانیتور روی 9600 است و متن نامفهوم دیده می‌شود. مانیتور را هم 115200 می‌کنی و یک خط مشخص می‌فرستی. اگر مشکل باقی ماند، قالب قاب، سیم‌کشی، زمین مشترک و ولتاژ را بررسی می‌کنی.","remember":["Baud نماد و Bitrate بیت را می‌شمارد.","در UART دودویی ساده معمولاً عددشان برابر است.","سرعت دادهٔ مفید باید بیت شروع و پایان را هم حساب کند."],"summary":"Baud نماد و Bitrate بیت را می‌شمارد.","mistake":"متن نامفهوم خرابی کنترلر را ثابت نمی‌کند؛ اغلب تنظیم انتقال سازگار نیست.","terms":[["Baudrate","نماد در ثانیه."],["Bitrate","بیت انتقال‌یافته در ثانیه."],["UART","رابط سریال ناهم‌زمان."],["8N1","هشت بیت داده، بدون Parität و یک پایان."],["TX / RX","مسیر ارسال و دریافت."]],"q":"N در 8N1 چه معنی دارد؟","options":["بدون Parität","بدون بیت شروع","بدون داده"],"answer":0,"feedback":"8N1 هشت بیت داده، بدون بررسی Parität و یک بیت پایان دارد.","sections":[]},"minutes":7,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/wlan":{"de":{"title":"ESP32 im WLAN: Verbindung und Datendienst trennen","goal":"Du unterscheidest WLAN-Anmeldung, IP-Konfiguration und Erreichbarkeit eines Dienstes.","definition":"WLAN verbindet Geräte per Funk mit einem lokalen Netzwerk. Ein ESP32 kann je nach Betriebsart als Station einem Access Point beitreten oder selbst einen Access Point bereitstellen. Eine Funkverbindung allein beweist noch keinen erfolgreichen Datenaustausch mit einem Server.","explanation":"Im Station-Modus wählt das Programm eine SSID und verwendet die dafür vorgesehenen Zugangsdaten. Nach der erfolgreichen Anmeldung benötigt das Gerät eine passende IP-Konfiguration, häufig über DHCP. Erst danach kann es einen Broker, Webserver oder anderen Dienst erreichen. Prüfe nacheinander Funkstatus, IP-Adresse, Gateway, DNS und Zielport.\n\nViele klassische ESP32-Varianten verwenden 2,4-GHz-WLAN; prüfe die Funkfähigkeiten des konkreten Modells statt von jedem ESP32 dieselben Bänder zu erwarten. Zugangsdaten gehören nicht in öffentliche Repositories. Plane auch den Fehlerfall: zeitlich begrenzte Verbindungsversuche, verständliche Statusausgabe und eine kontrollierte Wiederverbindung.","example":"Der Monitor meldet WLAN verbunden, der MQTT-Broker ist aber nicht erreichbar. Du prüfst, ob eine gültige IP vorliegt, ob Brokername aufgelöst wird und ob der Brokerport erreichbar und freigegeben ist. Die WLAN-Zugangsdaten immer wieder zu ändern würde diese Ebenen vermischen.","remember":["WLAN-Anmeldung, IP und Dienstverbindung sind drei Prüfungen.","Funkband und Sicherheit müssen zum Gerät passen.","Wiederverbindung und Schutz der Zugangsdaten mitplanen."],"summary":"WLAN-Anmeldung, IP und Dienstverbindung sind drei Prüfungen.","mistake":"WLAN verbunden heißt nicht automatisch Internet oder MQTT verbunden.","terms":[["SSID","Name eines WLANs."],["Station","WLAN-Client, der einem Access Point beitritt."],["Access Point","Gerät oder Betriebsart für den WLAN-Zugang."],["RSSI","Hinweis auf die empfangene Signalstärke."],["Reconnect","Kontrollierter erneuter Verbindungsaufbau."]],"q":"WLAN ist verbunden, aber ein Servername funktioniert nicht. Was prüfst du gezielt?","options":["DNS-Auflösung und Serveradresse","Nur die Farbe des Boards","Nur die Bildschirmhelligkeit"],"answer":0,"feedback":"Nach der WLAN-Anmeldung können IP-, DNS- oder Dienstprobleme bestehen bleiben.","sections":[]},"fa":{"title":"WLAN در ESP32؛ اتصال و سرویس داده","goal":"ورود WLAN، تنظیم IP و دسترسی به سرویس را از هم جدا کنی.","definition":"WLAN دستگاه را بی‌سیم به شبکهٔ محلی وصل می‌کند. ESP32 بسته به حالت می‌تواند Station باشد و به Access Point وصل شود یا خودش Access Point ایجاد کند. اتصال رادیویی به‌تنهایی موفقیت ارتباط با سرور را ثابت نمی‌کند.","explanation":"در حالت Station برنامه SSID و اطلاعات ورود مربوط را استفاده می‌کند. پس از ورود موفق، دستگاه به تنظیم IP مناسب، معمولاً با DHCP، نیاز دارد. سپس می‌تواند به Broker، وب‌سرور یا سرویس دیگر برسد. به ترتیب وضعیت رادیویی، IP، Gateway، DNS و پورت مقصد را بررسی کن.\n\nبسیاری از مدل‌های کلاسیک ESP32 با ۲٫۴ گیگاهرتز کار می‌کنند؛ توانایی مدل مشخص را بررسی کن. اطلاعات ورود نباید در مخزن عمومی باشد. برای خطا هم برنامه داشته باش: تلاش اتصال محدود، نمایش وضعیت روشن و اتصال دوبارهٔ کنترل‌شده.","example":"مانیتور می‌گوید WLAN وصل است، ولی Broker MQTT در دسترس نیست. IP معتبر، تبدیل نام Broker و مجازبودن پورت را بررسی می‌کنی. تغییر پی‌درپی رمز WLAN موضوع‌های مختلف را مخلوط می‌کند.","remember":["ورود WLAN، تنظیم IP و اتصال سرویس سه بررسی جدا هستند.","باند و امنیت باید با دستگاه سازگار باشد.","اتصال مجدد و محافظت اطلاعات ورود را طراحی کن."],"summary":"ورود WLAN، تنظیم IP و اتصال سرویس سه بررسی جدا هستند.","mistake":"WLAN وصل به معنی اینترنت یا MQTT وصل نیست.","terms":[["SSID","نام شبکهٔ WLAN."],["Station","کاربری که به Access Point می‌پیوندد."],["Access Point","تجهیز یا حالت فراهم‌کنندهٔ WLAN."],["RSSI","نشانهٔ قدرت سیگنال دریافتی."],["Reconnect","برقراری دوبارهٔ کنترل‌شدهٔ اتصال."]],"q":"WLAN وصل است ولی نام سرور کار نمی‌کند؛ چه را بررسی می‌کنی؟","options":["تبدیل نام DNS و آدرس سرور","فقط رنگ برد","فقط نور نمایشگر"],"answer":0,"feedback":"پس از ورود WLAN هنوز ممکن است مشکل IP، DNS یا سرویس وجود داشته باشد.","sections":[]},"minutes":7,"source":["Espressif · GPIO","https://docs.espressif.com/projects/arduino-esp32/en/latest/api/gpio.html"],"editorial":true},"it-technik/mqtt":{"de":{"title":"MQTT: Nachrichten über einen Broker verteilen","goal":"Du erklärst Publisher, Subscriber, Topic und QoS und planst eine einfache Sensornachricht.","definition":"MQTT ist ein Nachrichtenprotokoll nach dem Publish/Subscribe-Prinzip. Clients senden Nachrichten an einen Broker. Dieser verteilt sie anhand von Topics an die Clients, die passende Topics abonniert haben. Sender und Empfänger müssen einander nicht direkt kennen.","explanation":"Der Publisher veröffentlicht einen Payload, zum Beispiel einen Temperaturwert, unter einem Topic wie lager/temperatur. Ein Subscriber meldet Interesse an diesem Topic an. Der Broker vermittelt die Nachricht und kann Zugriffsrechte prüfen. Topics bilden eine Hierarchie; passende Filter können mehrere Topics abdecken.\n\nQoS 0 bietet höchstens einmalige Zustellung ohne Protokollbestätigung. QoS 1 kann bei Wiederholung Duplikate erzeugen. QoS 2 verwendet einen aufwendigeren Ablauf für genau einmalige Zustellung innerhalb des jeweiligen MQTT-Protokollaustauschs. Retained-Nachrichten speichern den letzten Wert eines Topics für neue Abonnenten. Für Schutz sind TLS, Authentifizierung und gezielte Topic-Rechte sinnvoll.","example":"Ein ESP32 veröffentlicht 24.5 unter lager/temperatur. Die Anzeige hat dieses Topic abonniert und zeigt den Wert an. Für einen Alarm nutzt du eine passende QoS-Stufe und eine Nachrichten-ID zur Behandlung möglicher Duplikate. Ein gespeicherter retained-Wert braucht außerdem einen Zeitstempel, damit alte Messungen erkennbar bleiben.","remember":["Publisher sendet, Subscriber abonniert, Broker verteilt.","QoS 1 kann Duplikate liefern.","Retained ist ein letzter gespeicherter Wert, keine vollständige Historie."],"summary":"Publisher sendet, Subscriber abonniert, Broker verteilt.","mistake":"QoS ersetzt weder Berechtigungen noch Verschlüsselung und garantiert keine erfolgreiche physische Aktion eines Aktors.","terms":[["Broker","Zentrale Vermittlungsstelle für MQTT-Nachrichten."],["Publisher","Client, der eine Nachricht veröffentlicht."],["Subscriber","Client mit einem Topic-Abonnement."],["Topic","Name beziehungsweise Pfad für die Zuordnung einer Nachricht."],["QoS","Stufe der protokollseitigen Zustellbehandlung."],["Retained","Vom Broker gespeicherte letzte Nachricht eines Topics."]],"q":"Welche Aussage zu QoS 1 stimmt?","options":["Duplikate sind möglich","Jeder Aktor führt sicher genau eine Aktion aus","Es verschlüsselt automatisch"],"answer":0,"feedback":"QoS 1 arbeitet mit Bestätigungen und Wiederholungen; dabei kann eine Nachricht mehrfach empfangen werden.","sections":[]},"fa":{"title":"MQTT؛ توزیع پیام با Broker","goal":"Publisher، Subscriber، Topic و QoS را توضیح بدهی و یک پیام سنسور طراحی کنی.","definition":"MQTT پروتکل پیام‌رسانی با روش انتشار و اشتراک است. کاربران پیام را به Broker می‌دهند و Broker بر اساس Topic به مشترکان مربوط می‌رساند. فرستنده و گیرنده لازم نیست مستقیم یکدیگر را بشناسند.","explanation":"Publisher محتوایی مثل دما را زیر Topic مانند lager/temperatur منتشر می‌کند. Subscriber همان Topic را مشترک می‌شود. Broker پیام را واسطه‌گری و دسترسی را بررسی می‌کند. Topic ساختار سلسله‌مراتبی دارد و فیلتر می‌تواند چند Topic را پوشش دهد.\n\nQoS 0 حداکثر یک بار و بدون تأیید پروتکلی است. QoS 1 ممکن است پیام تکراری ایجاد کند. QoS 2 فرایند پیچیده‌تری برای تحویل دقیقاً یک‌باره در همان تبادل پروتکل MQTT دارد. Retained آخرین مقدار Topic را برای مشترک جدید نگه می‌دارد. TLS، احراز هویت و محدودکردن Topicها برای محافظت مهم‌اند.","example":"ESP32 مقدار 24.5 را زیر lager/temperatur منتشر می‌کند. نمایشگر این Topic را مشترک است و مقدار را نشان می‌دهد. برای هشدار QoS مناسب و شناسهٔ پیام برای کنترل تکرار در نظر می‌گیری. مقدار Retained باید زمان داشته باشد تا اندازه‌گیری قدیمی مشخص شود.","remember":["Publisher می‌فرستد، Subscriber مشترک می‌شود، Broker توزیع می‌کند.","QoS 1 می‌تواند پیام تکراری بدهد.","Retained آخرین مقدار است، نه تاریخچهٔ کامل."],"summary":"Publisher می‌فرستد، Subscriber مشترک می‌شود، Broker توزیع می‌کند.","mistake":"QoS جای مجوز و رمزنگاری را نمی‌گیرد و انجام فیزیکی عملگر را تضمین نمی‌کند.","terms":[["Broker","واسطهٔ مرکزی پیام‌های MQTT."],["Publisher","کاربر منتشرکنندهٔ پیام."],["Subscriber","کاربر مشترک Topic."],["Topic","نام یا مسیر دسته‌بندی پیام."],["QoS","سطح روش تحویل پروتکلی."],["Retained","آخرین پیام ذخیره‌شدهٔ یک Topic."]],"q":"کدام دربارهٔ QoS 1 درست است؟","options":["تکرار پیام ممکن است","هر عملگر حتماً دقیقاً یک بار عمل می‌کند","خودکار رمزنگاری می‌کند"],"answer":0,"feedback":"QoS 1 تأیید و ارسال مجدد دارد؛ بنابراین یک پیام ممکن است چند بار دریافت شود.","sections":[]},"minutes":8,"source":["OASIS · MQTT 5.0","https://docs.oasis-open.org/mqtt/mqtt/v5.0/mqtt-v5.0.html"],"editorial":true},"bgwp/itsm":{"de":{"title":"IT-Servicemanagement: vom Bedarf zum verlässlichen Dienst","goal":"Du erklärst einen IT-Service und beschreibst einen nachvollziehbaren Bearbeitungsablauf für eine Anfrage.","definition":"IT-Servicemanagement organisiert, wie IT-Leistungen geplant, bereitgestellt, unterstützt und verbessert werden. Im Mittelpunkt steht der Nutzen für Anwender und Organisation, etwa zuverlässig drucken, kommunizieren oder auf Unternehmensdaten zugreifen zu können.","explanation":"Ein Service besteht nicht nur aus einem Gerät. Er umfasst zum Beispiel Technik, Zuständigkeiten, vereinbarte Leistungen und einen Unterstützungsweg. Ein Service Desk kann als zentrale Anlaufstelle Meldungen aufnehmen. Im Ticket stehen betroffene Person, Dienst, Symptom, Zeitpunkt, Auswirkungen und bereits bekannte Informationen.\n\nDanach wird die Meldung eingeordnet: Liegt eine Störung vor oder eine planbare Standardanfrage? Aus Auswirkung und Dringlichkeit ergibt sich die Priorität nach den Regeln des Betriebs. Die zuständige Stelle bearbeitet oder eskaliert den Fall, informiert den Nutzer und dokumentiert die Lösung. Erst eine nachvollziehbare Abschlussprüfung macht aus einer vermuteten Lösung einen belastbaren Abschluss.","example":"Eine Mitarbeiterin kann seit 08:00 nicht drucken. Du erfasst Drucker und Standort und prüfst, ob nur sie oder eine ganze Abteilung betroffen ist. Nach der passenden Priorisierung behebst du die Ursache oder gibst das Ticket mit Tests und Ergebnissen weiter. Ein bestätigter Testdruck und eine Lösungsnotiz schließen den Fall ab.","remember":["Ein IT-Service liefert einen nutzbaren Beitrag zum Arbeitsablauf.","Aufnahme, Einordnung, Bearbeitung, Kommunikation und Abschluss gehören zusammen.","Priorität richtet sich nach vereinbarten Kriterien."],"summary":"Ein IT-Service liefert einen nutzbaren Beitrag zum Arbeitsablauf.","mistake":"Die lauteste Beschwerde ist nicht automatisch der wichtigste Ausfall. Auswirkungen und Dringlichkeit müssen bewertet werden.","terms":[["IT-Service","IT-Leistung mit einem Nutzen für Anwender oder Organisation."],["Service Desk","Zentrale Anlaufstelle für IT-Anliegen."],["Ticket","Nachverfolgbarer Datensatz einer Meldung."],["Auswirkung","Umfang des Schadens oder betroffener Arbeit."],["Dringlichkeit","Zeitlicher Druck bis zu relevanten Folgen."],["Eskalation","Gezielte Weitergabe oder Einbeziehung weiterer Verantwortung."]],"q":"Was ist vor einer sinnvollen Priorisierung wichtig?","options":["Auswirkung und Dringlichkeit verstehen","Das Ticket sofort löschen","Den Benutzer ignorieren"],"answer":0,"feedback":"Nur mit dem Umfang der Störung und dem zeitlichen Bedarf lässt sich eine nachvollziehbare Priorität bestimmen.","sections":[]},"fa":{"title":"مدیریت خدمات IT؛ از نیاز تا سرویس قابل اتکا","goal":"سرویس IT را تعریف و مراحل رسیدگی قابل‌پیگیری به درخواست را توضیح بدهی.","definition":"مدیریت خدمات IT برنامه‌ریزی، ارائه، پشتیبانی و بهبود خدمات فناوری را سازمان می‌دهد. هدف، منفعت برای کاربر و سازمان است؛ مثل چاپ قابل اعتماد، ارتباط و دسترسی به اطلاعات شرکت.","explanation":"سرویس فقط یک دستگاه نیست؛ فناوری، مسئولیت، کیفیت توافق‌شده و راه پشتیبانی هم دارد. Service Desk می‌تواند نقطهٔ مرکزی دریافت درخواست باشد. تیکت باید کاربر، سرویس، نشانه، زمان، اثر و اطلاعات موجود را ثبت کند.\n\nسپس نوع درخواست روشن می‌شود: خرابی است یا درخواست استاندارد قابل برنامه‌ریزی؟ اثر و فوریت طبق قانون شرکت، اولویت را تعیین می‌کند. بخش مسئول حل می‌کند یا موضوع را ارجاع می‌دهد، به کاربر اطلاع می‌دهد و راه‌حل را ثبت می‌کند. در پایان باید نتیجه آزمایش شود؛ حدس دربارهٔ رفع مشکل برای بستن پرونده کافی نیست.","example":"کارمند از ساعت ۸ نمی‌تواند چاپ کند. نام چاپگر و محل را ثبت و بررسی می‌کنی آیا فقط او یا یک بخش کامل درگیر است. پس از اولویت‌بندی، حل می‌کنی یا تیکت را همراه آزمایش‌ها ارجاع می‌دهی. چاپ آزمایشی تأییدشده و توضیح راه‌حل، کار را تمام می‌کند.","remember":["سرویس IT به انجام کار کمک قابل استفاده می‌کند.","ثبت، دسته‌بندی، رسیدگی، اطلاع‌رسانی و پایان به هم مربوط‌اند.","اولویت بر پایهٔ معیار توافق‌شده است."],"summary":"سرویس IT به انجام کار کمک قابل استفاده می‌کند.","mistake":"بلندترین شکایت الزاماً مهم‌ترین خرابی نیست؛ اثر و فوریت باید ارزیابی شود.","terms":[["IT-Service","خدمت IT با منفعت برای کاربر یا سازمان."],["Service Desk","مرکز دریافت درخواست IT."],["Ticket","پروندهٔ قابل‌پیگیری درخواست."],["Auswirkung","اندازهٔ اثر بر کار یا خسارت."],["Dringlichkeit","فشار زمانی تا پیامد مهم."],["Eskalation","ارجاع هدفمند یا اضافه‌کردن مسئول دیگر."]],"q":"پیش از اولویت‌بندی درست چه مهم است؟","options":["فهم اثر و فوریت","حذف فوری تیکت","نادیده‌گرفتن کاربر"],"answer":0,"feedback":"با دانستن گسترهٔ خرابی و نیاز زمانی می‌توان اولویت قابل توجیه تعیین کرد.","sections":[]},"minutes":8,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"bgwp/org":{"de":{"title":"Aufbau und Ablauf: Zuständigkeit und Reihenfolge","goal":"Du unterscheidest Organigramm und Prozess und erkennst Linien-, Stab- und Matrixorganisation.","definition":"Die Aufbauorganisation legt fest, welche Stellen und Abteilungen existieren und wer wem zugeordnet ist. Die Ablauforganisation beschreibt, wie Aufgaben in welcher Reihenfolge und mit welchen Übergaben bearbeitet werden.","explanation":"Ein Organigramm zeigt beispielsweise IT-Leitung, Service Desk, Technik und Vertrieb. Im Einliniensystem erhält eine Stelle Weisungen grundsätzlich über einen direkten Vorgesetzten. Ein Stab unterstützt eine Leitung mit Fachberatung; aus der Stabsrolle folgt für sich allein keine allgemeine Weisungsbefugnis gegenüber der Linie. In einer Matrix wirken zwei Verantwortungsrichtungen zusammen, etwa Fachabteilung und Projekt. Das braucht klare Regeln bei Zielkonflikten.\n\nEin Prozess zeigt dagegen Ereignisse, Tätigkeiten, Entscheidungen und Übergaben. Derselbe Supportmitarbeiter kann in mehreren Prozessen mitwirken. Für eine gute Beschreibung werden nicht nur Schritte, sondern auch Eingang, Ergebnis und Verantwortung je Schritt festgelegt.","example":"Das Organigramm ordnet den Service Desk der IT-Leitung zu. Im Störungsprozess nimmt der Service Desk eine Meldung auf, die Technik untersucht den Fehler und der Service Desk informiert den Nutzer. Die hierarchische Zuordnung erklärt die Verantwortung; der Prozess erklärt die Zusammenarbeit über die Zeit.","remember":["Aufbau fragt: Wer ist wofür zuständig?","Ablauf fragt: Was passiert wann und mit welcher Übergabe?","Matrixorganisation braucht abgestimmte Prioritäten."],"summary":"Aufbau fragt: Wer ist wofür zuständig?","mistake":"Eine Linie im Organigramm beschreibt nicht automatisch die zeitliche Reihenfolge eines Tickets.","terms":[["Organigramm","Darstellung von Stellen und organisatorischen Beziehungen."],["Einliniensystem","Eine direkte Weisungslinie je Stelle."],["Stab","Beratende Unterstützung einer Leitungsstelle."],["Matrix","Überlagerung zweier organisatorischer Verantwortungsrichtungen."],["Prozess","Zusammenhängender Ablauf zur Erzeugung eines Ergebnisses."]],"q":"Was zeigt am besten die Reihenfolge der Ticketbearbeitung?","options":["Ein Prozessablauf","Nur eine Gehaltsliste","Nur der Firmenname"],"answer":0,"feedback":"Der Ablauf zeigt Schritte und Übergaben; das Organigramm zeigt Stellen und Hierarchie.","sections":[]},"fa":{"title":"ساختار و فرایند؛ مسئولیت و ترتیب کار","goal":"Organigramm و فرایند را جدا و ساختار خطی، ستادی و ماتریسی را بشناسی.","definition":"ساختار سازمانی مشخص می‌کند چه جایگاه و بخش‌هایی وجود دارند و هر فرد زیر نظر چه کسی است. سازمان‌دهی فرایند، ترتیب انجام کار و تحویل آن بین بخش‌ها را توضیح می‌دهد.","explanation":"Organigramm مثلاً مدیریت IT، Service Desk، بخش فنی و فروش را نشان می‌دهد. در ساختار تک‌خطی، هر جایگاه اصولاً از یک مدیر مستقیم دستور می‌گیرد. ستاد به مدیریت مشاورهٔ تخصصی می‌دهد؛ نقش ستادی به‌خودی‌خود اختیار عمومی فرمان‌دادن به واحدها ایجاد نمی‌کند. در ماتریس دو جهت مسئولیت، مثلاً بخش تخصصی و پروژه، هم‌زمان حضور دارند و برای تعارض هدف، قانون روشن لازم است.\n\nفرایند به جای سلسله‌مراتب، رویداد، فعالیت، تصمیم و تحویل کار را نشان می‌دهد. یک کارمند پشتیبانی می‌تواند در چند فرایند کار کند. شرح خوب علاوه بر مرحله‌ها، ورودی، خروجی و مسئول هر مرحله را هم مشخص می‌کند.","example":"در نمودار سازمانی، Service Desk زیر مدیریت IT است. در فرایند خرابی، درخواست را ثبت می‌کند، بخش فنی خطا را بررسی و Service Desk به کاربر خبر می‌دهد. ساختار مسئولیت را روشن می‌کند و فرایند همکاری در طول زمان را.","remember":["ساختار می‌پرسد چه کسی مسئول چیست؟","فرایند می‌پرسد چه کاری چه زمانی و با چه تحویلی انجام می‌شود؟","ماتریس به هماهنگی اولویت‌ها نیاز دارد."],"summary":"ساختار می‌پرسد چه کسی مسئول چیست؟","mistake":"خط در Organigramm ترتیب زمانی انجام تیکت را نشان نمی‌دهد.","terms":[["Organigramm","نمایش جایگاه‌ها و رابطهٔ سازمانی."],["Einliniensystem","یک مسیر مستقیم دستور برای هر جایگاه."],["Stab","پشتیبانی مشورتی از مدیر."],["Matrix","هم‌زمانی دو جهت مسئولیت سازمانی."],["Prozess","مراحل مرتبط برای رسیدن به نتیجه."]],"q":"چه چیزی ترتیب رسیدگی به تیکت را بهتر نشان می‌دهد؟","options":["فرایند کار","فقط فهرست حقوق","فقط نام شرکت"],"answer":0,"feedback":"فرایند مرحله و تحویل را نشان می‌دهد؛ Organigramm جایگاه و سلسله‌مراتب را.","sections":[]},"minutes":8,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"bgwp/eepk":{"de":{"title":"eEPK: einen Geschäftsprozess verständlich abbilden","goal":"Du unterscheidest Ereignis und Funktion und liest AND, OR und XOR an einer Verzweigung.","definition":"Eine ereignisgesteuerte Prozesskette beschreibt, wie Ereignisse Tätigkeiten auslösen und daraus neue Zustände entstehen. Die erweiterte EPK ergänzt beispielsweise Zuständigkeiten und Informationsobjekte, damit ein Geschäftsprozess nachvollziehbar wird.","explanation":"Ein Ereignis beschreibt einen eingetretenen Zustand, etwa Meldung eingegangen. Eine Funktion bezeichnet eine Tätigkeit, etwa Meldung erfassen. Im grundlegenden Ablauf wechseln beide Arten einander ab; Anfang und Ende werden als Ereignisse modelliert. Organisationseinheiten lassen sich Funktionen zuordnen, um die Verantwortung zu zeigen. Informationsobjekte zeigen, welche Daten benötigt oder erzeugt werden.\n\nKonnektoren steuern Verzweigungen: AND bedeutet, dass alle Zweige beteiligt sind. XOR wählt genau eine Alternative. OR erlaubt eine oder mehrere Alternativen. Eine Verzweigung und ihre Zusammenführung müssen logisch zusammenpassen. Ein Ereignis trifft selbst keine Entscheidung; die Entscheidung entsteht durch eine vorherige Funktion beziehungsweise eine definierte Regel.","example":"Ereignis: Meldung eingegangen. Funktion: Störung prüfen. Danach wird per XOR unterschieden: selbst lösbar oder Weitergabe nötig. Die passenden Funktionen lauten Störung beheben beziehungsweise Ticket weiterleiten. Nach einer dokumentierten Lösung endet der Prozess mit dem Ereignis Störung abgeschlossen.","remember":["Ereignis ist ein Zustand, Funktion ist eine Tätigkeit.","AND: alle; XOR: genau eine; OR: eine oder mehrere.","Erweiterungen zeigen Verantwortung und Informationsbedarf."],"summary":"Ereignis ist ein Zustand, Funktion ist eine Tätigkeit.","mistake":"AND und XOR sind nicht austauschbar: Gleichzeitig arbeiten und eine Alternative auswählen bedeuten unterschiedliche Abläufe.","terms":[["Ereignis","Eingetretener Zustand im Prozess."],["Funktion","Auszuführende Tätigkeit."],["AND","Alle verbundenen Zweige werden berücksichtigt."],["XOR","Genau eine Alternative wird gewählt."],["OR","Eine oder mehrere Alternativen sind möglich."],["Organisationseinheit","Für eine Funktion zuständige Stelle."]],"q":"Welcher Konnektor steht für genau eine Alternative?","options":["AND","XOR","OR"],"answer":1,"feedback":"XOR ist das ausschließende Oder: Von den Alternativen wird genau eine ausgewählt.","sections":[]},"fa":{"title":"eEPK؛ نمایش روشن فرایند کسب‌وکار","goal":"رویداد و فعالیت را جدا کنی و AND، OR و XOR را در انشعاب بخوانی.","definition":"زنجیرهٔ فرایند رویدادمحور نشان می‌دهد چه رویدادی فعالیت را آغاز می‌کند و چه وضعیت تازه‌ای ایجاد می‌شود. eEPK با افزودن مسئول و اطلاعات، فرایند را قابل فهم‌تر می‌کند.","explanation":"رویداد وضعیتی رخ‌داده است، مثل «گزارش دریافت شد». Function فعالیت است، مثل «گزارش را ثبت کن». در مسیر پایه این دو پشت سر هم می‌آیند و شروع و پایان رویداد است. واحد سازمانی به فعالیت وصل می‌شود تا مسئول مشخص باشد. شیء اطلاعاتی دادهٔ مورد نیاز یا تولیدشده را نشان می‌دهد.\n\nKonnektor انشعاب را کنترل می‌کند: AND همهٔ شاخه‌ها، XOR دقیقاً یک شاخه و OR یک یا چند شاخه را فعال می‌کند. تقسیم و جمع‌شدن مسیر باید منطقی سازگار باشد. خود رویداد تصمیم نمی‌گیرد؛ تصمیم حاصل فعالیت قبلی یا قانون مشخص است.","example":"رویداد: گزارش دریافت شد. فعالیت: خرابی را بررسی کن. سپس XOR دو حالت را جدا می‌کند: قابل حل در همین بخش یا نیازمند ارجاع. فعالیت بعدی «خرابی را رفع کن» یا «تیکت را ارجاع بده» است. پس از ثبت راه‌حل، رویداد «خرابی پایان یافت» فرایند را تمام می‌کند.","remember":["رویداد وضعیت است و Function فعالیت.","AND همه؛ XOR دقیقاً یکی؛ OR یک یا چند.","اجزای افزوده مسئول و اطلاعات را نشان می‌دهند."],"summary":"رویداد وضعیت است و Function فعالیت.","mistake":"AND و XOR قابل جایگزینی نیستند؛ کار هم‌زمان و انتخاب یک گزینه دو فرایند متفاوت‌اند.","terms":[["Ereignis","وضعیت رخ‌دادهٔ فرایند."],["Funktion","فعالیتی که انجام می‌شود."],["AND","همهٔ شاخه‌ها درگیرند."],["XOR","دقیقاً یک گزینه انتخاب می‌شود."],["OR","یک یا چند گزینه ممکن است."],["Organisationseinheit","بخش مسئول فعالیت."]],"q":"کدام برای انتخاب دقیقاً یک گزینه است؟","options":["AND","XOR","OR"],"answer":1,"feedback":"XOR یا انحصاری است؛ دقیقاً یک مسیر انتخاب می‌شود.","sections":[]},"minutes":8,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"bgwp/sla":{"de":{"title":"SLA: Servicequalität messbar vereinbaren","goal":"Du unterscheidest Reaktion, Wiederherstellung und Lösung und berücksichtigst vereinbarte Servicezeiten.","definition":"Ein Service Level Agreement beschreibt vereinbarte Leistungen und messbare Qualitätsziele zwischen Dienstleister und Kunde. Es kann zum Beispiel Verfügbarkeit, Servicezeiten, Reaktionsziele, Wiederherstellungsziele, Zuständigkeiten und Berichtswege festlegen.","explanation":"Die Reaktionszeit beschreibt einen vereinbarten ersten Bearbeitungs- oder Antwortschritt; was genau zählt, muss im SLA definiert sein. Wiederherstellung bedeutet, dass der Dienst wieder nutzbar ist, gegebenenfalls mit einer Übergangslösung. Eine dauerhafte Lösung kann später folgen. Diese Begriffe dürfen daher nicht unbemerkt gleichgesetzt werden.\n\nZeitziele gelten innerhalb der vereinbarten Bedingungen. Dazu gehören Servicekalender, Prioritätsklassen, Messbeginn, erlaubte Pausen und Ausnahmen. Verfügbarkeit muss ebenfalls mit einem Bezugszeitraum und einer Rechenregel definiert sein. Im Betrieb überwacht man die Ziele, informiert früh bei drohenden Überschreitungen und verbessert wiederkehrende Schwachstellen.","example":"Für eine hohe Priorität sind innerhalb der Servicezeit eine Reaktion in 30 Minuten und Wiederherstellung in vier Stunden vereinbart. Eine Meldung um 10:00 braucht dann den definierten Reaktionsschritt bis 10:30. Ein Ersatzdrucker kann den Dienst wiederherstellen, obwohl die Reparatur des ursprünglichen Geräts noch läuft.","remember":["SLA umfasst mehr als nur eine Zeitangabe.","Reaktion, Wiederherstellung und dauerhafte Lösung unterscheiden.","Ziele nur mit Servicekalender und Messregeln bewerten."],"summary":"SLA umfasst mehr als nur eine Zeitangabe.","mistake":"30 Minuten sind nur dann 30 Kalenderminuten, wenn der vereinbarte Servicekalender und die Messregel das so vorsehen.","terms":[["SLA","Vereinbarung zu Leistung und messbarer Servicequalität."],["Reaktionszeit","Zielzeit bis zum definierten ersten Reaktionsschritt."],["Wiederherstellung","Dienst wieder nutzbar machen."],["Servicezeit","Vereinbarter Zeitraum der Serviceleistung."],["Verfügbarkeit","Nutzbarkeit eines Dienstes im definierten Messzeitraum."]],"q":"Ein Ersatzgerät ermöglicht wieder das Drucken. Was ist damit erreicht?","options":["Möglicherweise die Wiederherstellung des Dienstes","Automatisch jede dauerhafte Fehlerursache beseitigt","Das SLA ist bedeutungslos"],"answer":0,"feedback":"Der Dienst kann durch eine Übergangslösung wieder nutzbar sein, während die dauerhafte Reparatur noch aussteht.","sections":[]},"fa":{"title":"SLA؛ توافق قابل اندازه‌گیری دربارهٔ کیفیت سرویس","goal":"واکنش، بازگردانی سرویس و حل را جدا کنی و ساعات توافق‌شده را در نظر بگیری.","definition":"SLA توافق ارائه‌دهنده و مشتری دربارهٔ خدمت و هدف‌های قابل اندازه‌گیری کیفیت است؛ مانند دسترس‌پذیری، ساعت خدمت، زمان واکنش، بازگردانی، مسئولیت و روش گزارش‌دهی.","explanation":"زمان واکنش یک قدم اولیهٔ پاسخ یا رسیدگی است؛ دقیقاً چه چیزی حساب می‌شود باید در SLA مشخص باشد. بازگردانی یعنی سرویس دوباره قابل استفاده شود، حتی با راه‌حل موقت؛ حل دائمی ممکن است بعداً انجام شود. بنابراین این زمان‌ها الزاماً یکسان نیستند.\n\nهدف زمانی در شرایط توافق‌شده اعتبار دارد: تقویم خدمت، اولویت، شروع اندازه‌گیری، توقف مجاز و استثناها. دسترس‌پذیری نیز دوره و فرمول روشن می‌خواهد. در کار واقعی هدف‌ها پایش می‌شوند، خطر تأخیر زود اعلام و ضعف تکراری اصلاح می‌شود.","example":"برای اولویت بالا در ساعت خدمت، واکنش ۳۰ دقیقه و بازگردانی چهار ساعت توافق شده است. درخواست ساعت ۱۰ باید تا ۱۰:۳۰ قدم واکنش تعریف‌شده را دریافت کند. چاپگر جایگزین می‌تواند سرویس را برگرداند، در حالی که تعمیر اصلی ادامه دارد.","remember":["SLA بیش از یک عدد زمان است.","واکنش، بازگردانی و حل دائمی متفاوت‌اند.","هدف با ساعت خدمت و قانون اندازه‌گیری ارزیابی می‌شود."],"summary":"SLA بیش از یک عدد زمان است.","mistake":"۳۰ دقیقه فقط وقتی زمان تقویمی است که تقویم خدمت و قانون اندازه‌گیری همین را بگوید.","terms":[["SLA","توافق خدمت و کیفیت قابل اندازه‌گیری."],["Reaktionszeit","زمان هدف تا قدم اولیهٔ تعریف‌شده."],["Wiederherstellung","قابل استفاده‌کردن دوبارهٔ سرویس."],["Servicezeit","بازهٔ توافق‌شدهٔ خدمت."],["Verfügbarkeit","قابل‌استفاده‌بودن سرویس در دورهٔ اندازه‌گیری."]],"q":"دستگاه جایگزین دوباره چاپ را ممکن می‌کند؛ چه حاصل شده؟","options":["ممکن است سرویس بازگردانی شده باشد","حتماً علت اصلی برای همیشه رفع شده","SLA بی‌معنی شده است"],"answer":0,"feedback":"سرویس با راه موقت قابل استفاده می‌شود، حتی اگر تعمیر دائمی باقی باشد.","sections":[]},"minutes":7,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"bgwp/incident":{"de":{"title":"Incident und Problem: Dienst zurück, Ursache klären","goal":"Du unterscheidest Störung, Ursachenuntersuchung und geplante Änderung an einem Druckerbeispiel.","definition":"Ein Incident ist eine ungeplante Unterbrechung oder Qualitätsminderung eines Dienstes. Ein Problem ist eine Ursache oder mögliche Ursache eines oder mehrerer Incidents. Die Ursache muss noch nicht bekannt sein und ein Incident muss sich nicht erst wiederholen, bevor ein Problem untersucht werden darf.","explanation":"Incident Management konzentriert sich darauf, den Dienst möglichst angemessen und schnell wieder nutzbar zu machen. Eine sichere Übergangslösung kann dafür genügen. Problem Management untersucht Ursachen, bewertet Risiken und sucht Möglichkeiten, weitere Störungen zu verhindern oder ihre Folgen zu mindern. Beide Arbeiten können zeitlich parallel laufen.\n\nEin Workaround vermindert Auswirkungen, ohne zwingend die Ursache zu beseitigen. Ein Known Error beschreibt ein analysiertes, noch nicht behobenes Problem. Für eine dauerhafte technische Änderung werden die betrieblichen Änderungsregeln verwendet. Dokumentierte Zusammenhänge zwischen Tickets, Problem und Änderung helfen späteren Bearbeitern.","example":"Ein Druckdienst fällt aus. Der Service Desk stellt Drucken über ein Ersatzgerät bereit: Incident-Wiederherstellung. Die Technik untersucht Speicherfehler des ursprünglichen Geräts: Problem-Untersuchung. Ein geprüftes Firmware-Update kann anschließend als kontrollierte Änderung die Ursache beheben. Nicht jede Störung benötigt dabei einen eigenen großen Problemfall.","remember":["Incident: den gestörten Dienst wieder nutzbar machen.","Problem: Ursache oder mögliche Ursache untersuchen.","Workaround kann vor der dauerhaften Lösung helfen."],"summary":"Incident: den gestörten Dienst wieder nutzbar machen.","mistake":"Problem bedeutet nicht einfach besonders schwerer Incident. Es beschreibt die Ursachenperspektive.","terms":[["Incident","Ungeplante Störung oder Qualitätsminderung."],["Problem","Ursache oder mögliche Ursache von Incidents."],["Workaround","Übergangslösung zur Verringerung der Auswirkungen."],["Known Error","Analysiertes, noch nicht beseitigtes Problem."],["Change","Kontrollierte Änderung an einem Dienst oder System."]],"q":"Was ist ein Workaround?","options":["Immer eine endgültige Reparatur","Eine Maßnahme, die Auswirkungen reduziert","Ein neues Passwort für jeden Nutzer"],"answer":1,"feedback":"Ein Workaround macht Arbeit wieder möglich oder vermindert Folgen, auch wenn die Ursache noch besteht.","sections":[]},"fa":{"title":"Incident و Problem؛ بازگردانی سرویس و یافتن علت","goal":"خرابی، بررسی علت و تغییر برنامه‌ریزی‌شده را با مثال چاپگر جدا کنی.","definition":"Incident قطع ناخواسته یا کاهش کیفیت سرویس است. Problem علت یا علت احتمالی یک یا چند Incident است. علت ممکن است هنوز معلوم نباشد و برای بررسی Problem لازم نیست خرابی حتماً چند بار تکرار شده باشد.","explanation":"Incident Management می‌خواهد سرویس را با سرعت مناسب و به‌شکل قابل قبول دوباره قابل استفاده کند؛ راه‌حل موقت امن هم می‌تواند کافی باشد. Problem Management علت و ریسک را بررسی می‌کند تا خرابی بعدی یا اثر آن کمتر شود. این دو کار می‌توانند هم‌زمان پیش بروند.\n\nWorkaround اثر خرابی را کم می‌کند ولی الزاماً علت را رفع نمی‌کند. Known Error یک Problem بررسی‌شده و هنوز رفع‌نشده است. برای تغییر دائمی فناوری باید قواعد تغییر شرکت رعایت شود. ارتباط ثبت‌شده بین تیکت، Problem و Change به افراد بعدی کمک می‌کند.","example":"سرویس چاپ قطع است. پشتیبانی چاپگر جایگزین می‌دهد؛ این بازگردانی Incident است. بخش فنی خطای حافظهٔ دستگاه اصلی را بررسی می‌کند؛ این بررسی Problem است. به‌روزرسانی آزمایش‌شدهٔ Firmware می‌تواند بعداً با Change کنترل‌شده علت را رفع کند.","remember":["Incident: سرویس مختل را برگردان.","Problem: علت یا علت احتمالی را بررسی کن.","Workaround می‌تواند پیش از حل دائمی کمک کند."],"summary":"Incident: سرویس مختل را برگردان.","mistake":"Problem صرفاً Incident سخت‌تر نیست؛ نگاه به علت را توصیف می‌کند.","terms":[["Incident","قطع یا افت کیفیت ناخواستهٔ سرویس."],["Problem","علت یا علت احتمالی خرابی‌ها."],["Workaround","راه موقت کاهش اثر."],["Known Error","مشکل بررسی‌شده و هنوز رفع‌نشده."],["Change","تغییر کنترل‌شدهٔ سیستم یا سرویس."]],"q":"Workaround چیست؟","options":["همیشه تعمیر دائمی","اقدامی برای کاهش اثر خرابی","رمز تازه برای همه"],"answer":1,"feedback":"راه موقت کار را ممکن یا اثر را کم می‌کند، حتی اگر علت باقی باشد.","sections":[]},"minutes":7,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"bgwp/support":{"de":{"title":"Support-Level: Wissen und Verantwortung passend einsetzen","goal":"Du erklärst drei typische Supportstufen und bereitest eine sinnvolle Eskalation vor.","definition":"Support-Level organisieren die Bearbeitung von IT-Anliegen nach Wissen, Werkzeugen und Zuständigkeit. Die genaue Aufteilung bestimmt der Betrieb. Ein Level ist keine allgemeingültige Rangliste des Werts der Mitarbeitenden.","explanation":"Im First Level werden Anfragen aufgenommen, eingeordnet und mit bekannten Verfahren bearbeitet. Dazu können Identitätsprüfung, Standardhilfe und ein dokumentierter Passwort-Reset gehören. Der Second Level besitzt vertieftes Fachwissen für bestimmte Systeme, etwa Netzwerke oder Server, und analysiert komplexere Fälle. Der Third Level liefert besonders tiefes Produkt- oder Entwicklungswissen; das kann ein internes Entwicklungsteam oder ein Hersteller sein.\n\nEine fachliche Eskalation gibt den Fall an passende Spezialisten weiter. Eine hierarchische Eskalation bezieht Verantwortung oder Entscheidungen der Leitung ein. Vor der Übergabe werden Symptom, Auswirkungen, Umgebung, Tests, Ergebnisse und relevante Protokolle zusammengestellt. Ein klarer Ansprechpartner hält den Nutzer weiter informiert.","example":"Ein VPN-Login schlägt trotz geprüfter Zugangsdaten fehl. First Level dokumentiert Fehlermeldung, Zeitpunkt und Clientversion sowie bereits ausgeführte Tests. Second Level untersucht Gateway und Authentifizierung. Zeigen Protokolle einen Softwarefehler, wird mit diesen Daten das zuständige Entwicklungs- oder Herstellerteam einbezogen.","remember":["Level-Aufteilung ist betriebsspezifisch.","Third Level kann intern oder extern sein.","Eine gute Übergabe enthält überprüfbare Informationen."],"summary":"Level-Aufteilung ist betriebsspezifisch.","mistake":"Ein Ticket nur mit funktioniert nicht weiterzugeben verlagert die Arbeit, ohne die Untersuchung voranzubringen.","terms":[["First Level","Erste Aufnahme und standardisierte Unterstützung."],["Second Level","Vertiefte fachliche Fehleranalyse."],["Third Level","Sehr tiefes Produkt- oder Entwicklungswissen."],["Fachliche Eskalation","Übergabe an passende Spezialisten."],["Hierarchische Eskalation","Einbeziehung höherer Entscheidungsverantwortung."]],"q":"Welche Information hilft bei einer Eskalation besonders?","options":["Genaue Fehlermeldung und bisherige Testergebnisse","Nur dringend hinschreiben","Nur den Namen der Firma"],"answer":0,"feedback":"Damit kann das nächste Team die Untersuchung gezielt fortsetzen und doppelte Tests vermeiden.","sections":[]},"fa":{"title":"سطح پشتیبانی؛ استفادهٔ درست از تخصص","goal":"سه سطح معمول پشتیبانی را توضیح بدهی و ارجاع مفید آماده کنی.","definition":"سطح‌های پشتیبانی، درخواست IT را بر پایهٔ دانش، ابزار و مسئولیت تقسیم می‌کنند. جزئیات را شرکت تعیین می‌کند؛ سطح، ارزش شخصی کارکنان را رتبه‌بندی نمی‌کند.","explanation":"First Level درخواست را ثبت، دسته‌بندی و با روش‌های شناخته‌شده بررسی می‌کند؛ مثلاً تأیید هویت، کمک استاندارد و بازنشانی رمز ثبت‌شده. Second Level تخصص عمیق‌تر در سیستم‌هایی مانند شبکه یا سرور دارد و مورد پیچیده را تحلیل می‌کند. Third Level دانش خیلی عمیق محصول یا توسعه دارد؛ ممکن است تیم داخلی یا سازنده باشد.\n\nارجاع تخصصی موضوع را به متخصص مناسب می‌دهد. ارجاع مدیریتی مسئولیت یا تصمیم مدیر را وارد می‌کند. قبل از تحویل باید نشانه، اثر، محیط، آزمایش، نتیجه و Log لازم ثبت شود. مسئول ارتباط باید کاربر را همچنان مطلع نگه دارد.","example":"ورود VPN با وجود اطلاعات بررسی‌شده شکست می‌خورد. First Level پیام، زمان، نسخهٔ Client و آزمایش‌ها را ثبت می‌کند. Second Level Gateway و احراز هویت را بررسی می‌کند. اگر Log خطای نرم‌افزار نشان دهد، تیم توسعه یا سازنده با همین اطلاعات وارد می‌شود.","remember":["تقسیم سطح به شرکت بستگی دارد.","Third Level می‌تواند داخلی یا بیرونی باشد.","تحویل خوب اطلاعات قابل بررسی دارد."],"summary":"تقسیم سطح به شرکت بستگی دارد.","mistake":"ارجاع فقط با «کار نمی‌کند» کار را جابه‌جا می‌کند ولی بررسی را جلو نمی‌برد.","terms":[["First Level","ثبت اولیه و پشتیبانی استاندارد."],["Second Level","تحلیل تخصصی عمیق‌تر."],["Third Level","دانش بسیار عمیق محصول یا توسعه."],["Fachliche Eskalation","ارجاع به متخصص مناسب."],["Hierarchische Eskalation","واردکردن مسئول تصمیم‌گیری بالاتر."]],"q":"چه اطلاعاتی در ارجاع بیشتر کمک می‌کند؟","options":["پیام دقیق خطا و نتیجهٔ آزمایش‌ها","فقط نوشتن فوری","فقط نام شرکت"],"answer":0,"feedback":"تیم بعدی می‌تواند بررسی را هدفمند ادامه دهد و آزمایش تکراری را کم کند.","sections":[]},"minutes":8,"source":["PeopleCert · ITIL practices","https://www.peoplecert.org/browse-certifications/it-governance-and-service-management/ITIL-1"],"editorial":true},"aeup/welt":{"de":{"title":"Datenarten: Inhalt und Verwendung unterscheiden","goal":"Du ordnest Daten nach Struktur und Verwendung ein und begründest deine Entscheidung.","definition":"Daten sind gespeicherte oder übertragene Informationen in einer verarbeitbaren Darstellung. Man kann sie nach mehreren unabhängigen Gesichtspunkten einteilen: etwa strukturiert oder unstrukturiert sowie Stamm-, Bewegungs- oder Bestandsdaten.","explanation":"Strukturierte Daten folgen einem festen Schema, etwa Kundennummer, Name und E-Mail in einer Tabelle. Semistrukturierte Daten enthalten erkennbare Schlüssel und Hierarchien, zum Beispiel JSON, müssen aber nicht alle dieselben Felder besitzen. Unstrukturierte Inhalte wie freie Texte oder Bilder folgen nicht dem passenden fachlichen Tabellenschema.\n\nStammdaten beschreiben relativ dauerhafte Objekte, zum Beispiel einen Kunden oder Artikel. Bewegungsdaten entstehen durch Vorgänge wie Bestellung oder Zahlung. Bestandsdaten geben einen Zustand zu einem Zeitpunkt an, etwa den Lagerbestand. Diese Kategorien können sich mit der Struktur-Einteilung überschneiden: Eine Bestellposition kann zugleich strukturiert und eine Bewegungsinformation sein.","example":"Artikel A hat eine Artikelnummer und Bezeichnung: Stammdaten. Eine Lieferung von zehn Stück ist Bewegungsinformation. Der Vorrat von 80 Stück nach der Lieferung ist eine Bestandsinformation. Werden diese Angaben in festen Tabellenspalten gespeichert, sind sie gleichzeitig strukturiert. Die Bedeutung entscheidet, nicht nur der Dateiname.","remember":["Struktur und betriebliche Verwendung sind verschiedene Einteilungen.","Stammdaten beschreiben Objekte, Bewegungsdaten Vorgänge.","Bestandsdaten zeigen einen Zustand zu einem Zeitpunkt."],"summary":"Struktur und betriebliche Verwendung sind verschiedene Einteilungen.","mistake":"Stammdaten und Bestandsdaten werden nicht in jedem Fachmaterial gleich verwendet. Die vereinbarte Definition im konkreten Kontext muss klar sein.","terms":[["Strukturierte Daten","Daten mit festem Schema und definierten Feldern."],["Semistrukturierte Daten","Daten mit Schlüsseln oder Hierarchien, etwa JSON."],["Stammdaten","Relativ dauerhafte Beschreibung betrieblicher Objekte."],["Bewegungsdaten","Daten eines Geschäftsvorgangs."],["Bestandsdaten","Zustandswerte zu einem bestimmten Zeitpunkt."]],"q":"Welche Angabe ist eine Bewegungsinformation?","options":["Die Menge einer einzelnen Bestellung","Die dauerhafte Artikelbezeichnung","Die Kundennummer allein"],"answer":0,"feedback":"Die Bestellmenge gehört zu einem konkreten Vorgang und entsteht mit dieser Bestellung.","sections":[]},"fa":{"title":"نوع داده؛ محتوا و کاربرد را جدا کن","goal":"داده را بر اساس ساختار و کاربرد دسته‌بندی کنی و دلیل بیاوری.","definition":"داده اطلاعات ذخیره یا منتقل‌شده با شکل قابل پردازش است. می‌توان آن را از چند دید مستقل دسته‌بندی کرد؛ مثلاً ساختاریافته یا بدون ساختار و همچنین Stammdaten، Bewegungsdaten یا Bestandsdaten.","explanation":"دادهٔ ساختاریافته از الگوی ثابت پیروی می‌کند؛ مثل شماره، نام و ایمیل مشتری در جدول. نیمه‌ساختاریافته مثل JSON کلید و سلسله‌مراتب دارد، ولی همهٔ موارد الزاماً فیلد یکسان ندارند. متن آزاد یا تصویر ساختار جدول تخصصی مورد نظر را ندارند.\n\nStammdaten چیز نسبتاً پایدار مانند مشتری یا کالا را توصیف می‌کند. Bewegungsdaten از رویداد مثل سفارش یا پرداخت ایجاد می‌شود. Bestandsdaten وضعیت در یک زمان، مثل موجودی انبار، را می‌گوید. این دسته‌بندی با ساختار هم‌پوشانی دارد؛ ردیف سفارش می‌تواند هم ساختاریافته و هم دادهٔ رویدادی باشد.","example":"کالای A شماره و نام دارد؛ Stammdaten است. تحویل ده عدد رویداد و Bewegungsdaten است. موجودی ۸۰ عدد پس از تحویل، Bestandsdaten است. اگر در ستون‌های ثابت ذخیره شوند، هم‌زمان ساختاریافته هم هستند؛ معنی داده مهم است، نه فقط نام فایل.","remember":["ساختار و کاربرد دو دسته‌بندی متفاوت‌اند.","Stammdaten شیء و Bewegungsdaten رویداد را می‌گوید.","Bestandsdaten وضعیت در یک زمان است."],"summary":"ساختار و کاربرد دو دسته‌بندی متفاوت‌اند.","mistake":"Stammdaten و Bestandsdaten در همهٔ منابع دقیقاً یکسان استفاده نمی‌شوند؛ تعریف منبع و مسئله را روشن کن.","terms":[["Strukturierte Daten","داده با الگو و فیلد ثابت."],["Semistrukturierte Daten","داده دارای کلید یا سلسله‌مراتب مثل JSON."],["Stammdaten","شرح نسبتاً پایدار شیء کاری."],["Bewegungsdaten","دادهٔ یک رویداد کاری."],["Bestandsdaten","مقدار وضعیت در زمان مشخص."]],"q":"کدام داده رویدادی است؟","options":["تعداد یک سفارش مشخص","نام پایدار کالا","تنها شمارهٔ مشتری"],"answer":0,"feedback":"تعداد سفارش به رویداد مشخص مربوط و با همان سفارش ایجاد می‌شود.","sections":[]},"minutes":8,"source":["PostgreSQL · Data definition","https://www.postgresql.org/docs/current/ddl.html"],"editorial":true},"aeup/modelle":{"de":{"title":"Datenmodell: die Regeln vor den Tabellen klären","goal":"Du entwickelst aus einem Auftrag Objekte, Attribute und Beziehungen und trennst drei Modellebenen.","definition":"Ein Datenmodell beschreibt, welche Informationen ein System benötigt und nach welchen Regeln sie zusammenhängen. Es verhindert, dass Tabellen nur aus spontanen Ideen entstehen und wichtige Beziehungen später fehlen.","explanation":"Beginne mit dem fachlichen Bedarf: Welche Fragen soll das System beantworten, wer arbeitet damit und welche Vorgänge werden gespeichert? Sammle dann Objekttypen wie Kunde und Auftrag, deren Eigenschaften und die erlaubten Beziehungen. Kläre Eindeutigkeit, Pflichtangaben und Löschregeln mit den Beteiligten.\n\nDas konzeptionelle Modell beschreibt die fachliche Sicht unabhängig von einer Datenbanktechnik. Das logische Modell überträgt sie beispielsweise auf Tabellen, Schlüssel und Beziehungen. Das physische Modell konkretisiert Datentypen, Indizes und technische Speicherung für ein bestimmtes System. Diese Ebenen helfen, fachliche Entscheidungen von technischen Optimierungen zu trennen.","example":"Ein Ticketsystem soll zeigen, welcher Kunde welches Ticket gemeldet hat. Fachlich gibt es Kunde und Ticket; ein Kunde kann mehrere Tickets melden. Logisch erhält Ticket einen Fremdschlüssel auf Kunde. Physisch werden Datentypen und ein geeigneter Index gewählt. Vor der Umsetzung klärst du, ob ein Ticket auch ohne Kundenkonto entstehen darf.","remember":["Erst Anforderungen verstehen, dann modellieren.","Konzeptionell, logisch und physisch beantworten verschiedene Fragen.","Geschäftsregeln müssen ausdrücklich geklärt werden."],"summary":"Erst Anforderungen verstehen, dann modellieren.","mistake":"Eine Tabelle mit vielen Spalten ist noch kein vollständiges Datenmodell. Beziehungen und Regeln gehören ebenfalls dazu.","terms":[["Anforderung","Benötigte Funktion oder Eigenschaft des Systems."],["Konzeptionelles Modell","Fachliche Beschreibung der Informationen."],["Logisches Modell","Darstellung in einer Datenmodell-Art wie Tabellen."],["Physisches Modell","Technische Umsetzung in einem konkreten System."],["Geschäftsregel","Fachliche Bedingung, die Daten erfüllen müssen."]],"q":"Welche Frage gehört zuerst in die fachliche Klärung?","options":["Welche Informationen werden für den Auftrag gebraucht?","Welche Festplattenfarbe passt?","Wie heißt die erste SQL-Datei?"],"answer":0,"feedback":"Das Modell muss die benötigten Informationen und Regeln abbilden, bevor die technische Umsetzung festgelegt wird.","sections":[]},"fa":{"title":"مدل داده؛ اول قانون، بعد جدول","goal":"از نیاز، موجودیت، ویژگی و رابطه استخراج و سه سطح مدل را جدا کنی.","definition":"مدل داده مشخص می‌کند سیستم چه اطلاعاتی نیاز دارد و رابطهٔ آن‌ها از چه قانونی پیروی می‌کند. این کار کمک می‌کند جدول‌ها تصادفی ساخته نشوند و رابطهٔ مهم جا نماند.","explanation":"از نیاز کاری شروع کن: سیستم باید به چه سؤال‌هایی جواب بدهد، چه کسی استفاده می‌کند و چه رویدادی ذخیره می‌شود؟ نوع‌هایی مثل مشتری و سفارش، ویژگی‌ها و رابطهٔ مجاز را جمع کن. یکتایی، مقدار اجباری و قانون حذف را با مسئولان روشن کن.\n\nمدل مفهومی نگاه کسب‌وکار را مستقل از فناوری توضیح می‌دهد. مدل منطقی آن را مثلاً به جدول، کلید و رابطه تبدیل می‌کند. مدل فیزیکی نوع داده، Index و ذخیره‌سازی یک سیستم مشخص را تعیین می‌کند. این سطح‌ها تصمیم کاری را از بهینه‌سازی فنی جدا می‌کنند.","example":"سیستم تیکت باید مشتری هر تیکت را نشان دهد. مفهومی: مشتری و تیکت؛ یک مشتری چند تیکت دارد. منطقی: جدول تیکت کلید خارجی مشتری دارد. فیزیکی: نوع داده و Index مناسب تعیین می‌شود. قبل از پیاده‌سازی روشن کن تیکت بدون حساب مشتری مجاز است یا نه.","remember":["اول نیاز را بفهم، بعد مدل بساز.","مفهومی، منطقی و فیزیکی سؤال متفاوت دارند.","قانون کسب‌وکار باید روشن شود."],"summary":"اول نیاز را بفهم، بعد مدل بساز.","mistake":"جدول پرستون، مدل کامل نیست؛ رابطه و قانون هم لازم است.","terms":[["Anforderung","نیاز عملکرد یا ویژگی سیستم."],["Konzeptionelles Modell","شرح مفهومی اطلاعات."],["Logisches Modell","نمایش در نوع مدل، مثلاً جدول."],["Physisches Modell","پیاده‌سازی فنی در سیستم مشخص."],["Geschäftsregel","شرط کاری که داده باید رعایت کند."]],"q":"کدام سؤال ابتدا باید از نظر کاری روشن شود؟","options":["چه اطلاعاتی برای نیاز لازم است؟","رنگ دیسک چیست؟","نام فایل SQL اول چیست؟"],"answer":0,"feedback":"مدل باید اطلاعات و قانون مورد نیاز را پیش از انتخاب اجرای فنی مشخص کند.","sections":[]},"minutes":8,"source":["PostgreSQL · Data definition","https://www.postgresql.org/docs/current/ddl.html"],"editorial":true},"aeup/rel":{"de":{"title":"Relationales Modell: Daten in verbundenen Tabellen","goal":"Du erklärst Primär- und Fremdschlüssel und setzt eine 1:n-Beziehung in Tabellen um.","definition":"Das relationale Modell organisiert Daten in Tabellen. Eine Zeile beschreibt einen Datensatz, eine Spalte ein Attribut. Schlüssel identifizieren Datensätze eindeutig und verbinden Informationen, ohne dieselben Stammdaten unnötig oft zu speichern.","explanation":"Der Primärschlüssel ist der ausgewählte eindeutige Identifikator einer Tabelle. Er kann aus einer oder mehreren Spalten bestehen. Ein Fremdschlüssel verweist auf einen passenden eindeutigen Schlüssel einer referenzierten Tabelle; dadurch lassen sich Beziehungen technisch absichern. Bei einer üblichen 1:n-Beziehung steht der Fremdschlüssel auf der n-Seite.\n\nEine n:m-Beziehung wird meist durch eine zusätzliche Zuordnungstabelle mit beiden Verweisen umgesetzt. Datenbankbedingungen prüfen beispielsweise Eindeutigkeit, Pflichtwerte und gültige Referenzen. Normalisierung hilft, Wiederholungen und widersprüchliche Änderungen zu vermeiden. Ein JOIN führt bei einer Abfrage passende Datensätze wieder zusammen; er ändert die Tabellenstruktur nicht.","example":"Kunde(KundenID, Name) und Auftrag(AuftragsID, KundenID, Datum) bilden eine 1:n-Beziehung. KundenID in Auftrag verweist auf Kunde. Ein Auftrag mit KundenID 99 ist nur gültig, wenn die referenzierte Kundennummer existiert oder die Regeln eine andere Behandlung vorsehen. Der Kundenname muss nicht bei jedem Auftrag neu gespeichert werden.","remember":["Zeile = Datensatz; Spalte = Attribut.","Primärschlüssel identifiziert, Fremdschlüssel verknüpft.","1:n: Fremdschlüssel gewöhnlich auf der n-Seite."],"summary":"Zeile = Datensatz; Spalte = Attribut.","mistake":"Ein Fremdschlüssel muss nicht selbst eindeutig sein: Viele Aufträge können denselben Kunden referenzieren.","terms":[["Relation","Tabelle im relationalen Modell."],["Tupel","Ein Datensatz beziehungsweise eine Tabellenzeile."],["Primärschlüssel","Ausgewählter eindeutiger Identifikator."],["Fremdschlüssel","Verweis auf einen referenzierten Schlüssel."],["Referenzielle Integrität","Gültigkeit der Beziehungen zwischen Datensätzen."],["JOIN","Verknüpfung passender Zeilen in einer Abfrage."]],"q":"Ein Kunde hat viele Aufträge. Wo steht gewöhnlich der Kunden-Fremdschlüssel?","options":["In der Tabelle Auftrag","Nur im Dateinamen","In jeder Bildschirmtaste"],"answer":0,"feedback":"Jeder Auftrag speichert die Zuordnung zu seinem Kunden; derselbe Kundenwert darf in vielen Aufträgen vorkommen.","sections":[]},"fa":{"title":"مدل رابطه‌ای؛ داده در جدول‌های مرتبط","goal":"کلید اصلی و خارجی را توضیح و رابطهٔ 1:n را به جدول تبدیل کنی.","definition":"مدل رابطه‌ای داده را در جدول سازمان می‌دهد. هر ردیف یک رکورد و هر ستون یک ویژگی است. کلید رکورد را یکتا و اطلاعات مرتبط را به هم وصل می‌کند تا دادهٔ ثابت بی‌دلیل تکرار نشود.","explanation":"کلید اصلی شناسهٔ یکتای انتخاب‌شدهٔ جدول است و می‌تواند یک یا چند ستون باشد. کلید خارجی به کلید یکتای مناسب در جدول مرجع اشاره می‌کند و رابطه را قابل کنترل می‌سازد. در رابطهٔ معمول 1:n، کلید خارجی در سمت n قرار می‌گیرد.\n\nرابطهٔ n:m معمولاً با جدول واسط دارای هر دو ارجاع ساخته می‌شود. شرط‌های پایگاه داده یکتایی، مقدار اجباری و مرجع معتبر را بررسی می‌کنند. نرمال‌سازی تکرار و تغییر ناسازگار را کم می‌کند. JOIN هنگام پرس‌وجو ردیف‌های مرتبط را کنار هم می‌آورد و ساختار جدول را تغییر نمی‌دهد.","example":"جدول Kunde با KundenID و Name و جدول Auftrag با AuftragsID، KundenID و Datum رابطهٔ 1:n دارند. KundenID در سفارش به مشتری اشاره می‌کند. اگر شمارهٔ ۹۹ وجود نداشته باشد، ارجاع طبق قانون باید رد یا مدیریت شود. نام مشتری لازم نیست در هر سفارش تکرار شود.","remember":["ردیف رکورد و ستون ویژگی است.","کلید اصلی شناسایی و کلید خارجی ارتباط برقرار می‌کند.","در 1:n، کلید خارجی معمولاً سمت n است."],"summary":"ردیف رکورد و ستون ویژگی است.","mistake":"کلید خارجی الزاماً یکتا نیست؛ چند سفارش می‌توانند به یک مشتری اشاره کنند.","terms":[["Relation","جدول در مدل رابطه‌ای."],["Tupel","رکورد یا ردیف جدول."],["Primärschlüssel","شناسهٔ یکتای انتخاب‌شده."],["Fremdschlüssel","ارجاع به کلید مرجع."],["Referenzielle Integrität","معتبرماندن ارتباط بین رکوردها."],["JOIN","کنارهم‌آوردن ردیف مرتبط در پرس‌وجو."]],"q":"یک مشتری چند سفارش دارد؛ کلید خارجی مشتری معمولاً کجاست؟","options":["جدول سفارش","فقط نام فایل","هر دکمهٔ صفحه"],"answer":0,"feedback":"هر سفارش مشتری خود را ذخیره می‌کند و همان مشتری می‌تواند در چند سفارش باشد.","sections":[]},"minutes":7,"source":["PostgreSQL · Data definition","https://www.postgresql.org/docs/current/ddl.html"],"editorial":true},"aeup/json":{"de":{"title":"JSON und API: Daten zwischen Systemen austauschen","goal":"Du liest ein JSON-Objekt und unterscheidest Datenformat, Schnittstelle und HTTP-Status.","definition":"Eine API ist eine definierte Schnittstelle, über die Programme Funktionen oder Daten eines anderen Systems nutzen. JSON ist ein textbasiertes Datenformat, das dabei häufig verwendet wird. Eine API kann JSON verwenden, muss es aber nicht.","explanation":"JSON-Objekte bestehen aus Schlüssel-Wert-Paaren in geschweiften Klammern. Schlüssel und Zeichenketten stehen in doppelten Anführungszeichen. Werte dürfen unter anderem Zahlen, Zeichenketten, true, false, null, Objekte oder Arrays sein. Arrays sind geordnete Listen in eckigen Klammern. Kommentare und ein abschließendes überflüssiges Komma sind in normalem JSON nicht erlaubt.\n\nBei einer HTTP-API beschreiben Methode und Adresse den Aufruf: GET liest häufig eine Ressource, POST übermittelt Daten zur Verarbeitung. Der Status beschreibt das Ergebnis, etwa 200 für einen erfolgreichen Aufruf und 404 für eine nicht gefundene Ressource. 401 betrifft fehlende gültige Authentifizierung; 403 eine verweigerte Ausführung. Das konkrete API-Schema erklärt Pflichtfelder und Bedeutung.","example":"GET /tickets/5 liefert {\"id\":5,\"title\":\"VPN-Störung\",\"open\":true}. id ist eine Zahl, title eine Zeichenkette und open ein boolescher Wert. Dein Programm prüft zuerst Status und Antwortformat, liest danach die Felder und behandelt fehlende Werte kontrolliert. Zugangstoken werden geschützt und nicht öffentlich in Beispielcode gespeichert.","remember":["API ist die Schnittstelle, JSON das Datenformat.","Objekt enthält Schlüssel-Werte, Array eine geordnete Liste.","Status, Schema und Berechtigungen getrennt prüfen."],"summary":"API ist die Schnittstelle, JSON das Datenformat.","mistake":"Die Zeichenkette \"5\" und die Zahl 5 sind im JSON-Modell unterschiedliche Wertearten.","terms":[["API","Definierte Programmierschnittstelle."],["JSON-Objekt","Sammlung von Schlüssel-Wert-Paaren."],["Array","Geordnete Liste von Werten."],["Boolean","Logischer Wert true oder false."],["HTTP-Status","Kennzeichnung des Ergebnisses einer HTTP-Anfrage."],["Schema","Beschreibung der erwarteten Datenstruktur."]],"q":"Welcher JSON-Wert ist ein boolescher Wert?","options":["true","\"true\"","\"5\""],"answer":0,"feedback":"true ohne Anführungszeichen ist ein Boolean. \"true\" ist eine Zeichenkette.","sections":[]},"fa":{"title":"JSON و API؛ تبادل داده بین سیستم‌ها","goal":"یک شیء JSON را بخوانی و قالب داده، رابط و وضعیت HTTP را جدا کنی.","definition":"API رابط تعریف‌شده‌ای است که برنامه با آن از داده یا قابلیت سیستم دیگر استفاده می‌کند. JSON قالب متنی داده است که زیاد در API استفاده می‌شود؛ ولی هر API الزاماً JSON ندارد.","explanation":"شیء JSON از جفت کلید و مقدار داخل آکولاد ساخته می‌شود. کلید و متن با کوتیشن دوتایی نوشته می‌شوند. مقدار می‌تواند عدد، متن، true، false، null، شیء یا آرایه باشد. آرایه فهرست مرتب داخل براکت است. JSON معمولی توضیح کامنت و کامای اضافی آخر را نمی‌پذیرد.\n\nدر API مبتنی بر HTTP، متد و آدرس درخواست را مشخص می‌کنند؛ GET معمولاً منبع را می‌خواند و POST داده را برای پردازش می‌فرستد. وضعیت نتیجه را می‌گوید؛ 200 موفق و 404 منبع پیدا نشده است. 401 به احراز هویت معتبر نداشتن و 403 به رد اجرای درخواست مربوط است. Schema همان API فیلد اجباری و معنی داده را مشخص می‌کند.","example":"GET /tickets/5 مقدار {\"id\":5,\"title\":\"VPN-Störung\",\"open\":true} می‌دهد. id عدد، title متن و open منطقی است. برنامه اول Status و قالب پاسخ را بررسی، سپس فیلدها را می‌خواند و مقدار غایب را کنترل می‌کند. Token نباید در کد عمومی باشد.","remember":["API رابط و JSON قالب داده است.","شیء جفت کلید‌مقدار و آرایه فهرست مرتب دارد.","وضعیت، Schema و مجوز را جدا بررسی کن."],"summary":"API رابط و JSON قالب داده است.","mistake":"متن \"5\" و عدد 5 در مدل JSON نوع متفاوت دارند.","terms":[["API","رابط تعریف‌شدهٔ برنامه."],["JSON-Objekt","مجموعهٔ کلید و مقدار."],["Array","فهرست مرتب مقدارها."],["Boolean","مقدار منطقی true یا false."],["HTTP-Status","نشانهٔ نتیجهٔ درخواست HTTP."],["Schema","شرح ساختار مورد انتظار داده."]],"q":"کدام مقدار JSON منطقی است؟","options":["true","\"true\"","\"5\""],"answer":0,"feedback":"true بدون کوتیشن منطقی است؛ \"true\" متن است.","sections":[]},"minutes":8,"source":["RFC 8259 · JSON","https://www.rfc-editor.org/rfc/rfc8259.html"],"editorial":true},"fachpraxis/szenario":{"de":{"title":"Netzwerkauftrag: vom Bedarf zum prüfbaren Plan","goal":"Du leitest aus einem Kundenauftrag einen kleinen Netzplan mit klaren Abnahmekriterien ab.","definition":"Ein Netzwerkszenario beschreibt eine betriebliche Ausgangslage und ein gewünschtes Ergebnis. Bevor Geräte konfiguriert werden, müssen Nutzer, Dienste, Sicherheitsanforderungen und technische Randbedingungen verstanden sein.","explanation":"Erfasse zuerst Gerätezahl, Standorte, benötigte Dienste und erlaubte Verbindungen. Frage nach vorhandener Verkabelung, Internetanschluss, Adressbereichen und wichtigen Betriebszeiten. Daraus entstehen ein physischer Plan für Geräte und Leitungen und ein logischer Plan für VLANs, Subnetze, Gateways und Dienste.\n\nDefiniere danach prüfbare Ziele: Ein Arbeitsplatz erhält die richtige IP-Konfiguration, interne Namen werden korrekt aufgelöst und Gäste erreichen keine internen Server. Plane die Reihenfolge der Umsetzung und einen Rückweg bei Fehlern. Dokumentiere Änderungen, damit ein anderer Techniker den Aufbau nachvollziehen kann. Erfolg bedeutet, dass die Anforderungen nachweisbar erfüllt sind, nicht nur dass einige LEDs leuchten.","example":"Ein Büro braucht Mitarbeiter- und Gastnetz. Du planst VLAN 10 und VLAN 20 mit getrennten Subnetzen. Der Plan nennt Switchports, Gatewayadressen und DHCP-Bereiche. Zur Abnahme testest du je ein Gerät beider Gruppen, dokumentierst die erhaltenen Einstellungen und prüfst erlaubte sowie verbotene Verbindungen.","remember":["Anforderungen vor Konfiguration klären.","Physischer und logischer Plan ergänzen sich.","Abnahme prüft konkrete vereinbarte Ergebnisse."],"summary":"Anforderungen vor Konfiguration klären.","mistake":"Ein erfolgreicher Internetzugriff beweist nicht, dass die Trennung zum internen Netz korrekt ist.","terms":[["Istzustand","Vorhandene Situation vor der Änderung."],["Sollzustand","Gewünschtes Ergebnis des Auftrags."],["Physischer Netzplan","Geräte, Standorte und Verbindungen."],["Logischer Netzplan","VLANs, IP-Netze und Dienste."],["Abnahmekriterium","Prüfbare Bedingung für den erfolgreichen Abschluss."]],"q":"Was ist ein gutes Abnahmekriterium?","options":["Das Netzwerk soll schön sein","Ein Gastgerät erreicht Internet, aber keinen internen Server","Viele Kabel sind angeschlossen"],"answer":1,"feedback":"Die Bedingung beschreibt zwei konkret überprüfbare Ergebnisse.","sections":[]},"fa":{"title":"درخواست شبکه؛ از نیاز تا طرح قابل آزمایش","goal":"از نیاز مشتری، نقشهٔ شبکه و معیار پذیرش روشن بسازی.","definition":"سناریوی شبکه وضعیت فعلی و نتیجهٔ مورد نیاز سازمان را توصیف می‌کند. پیش از تنظیم تجهیزات باید کاربر، سرویس، امنیت و محدودیت فنی روشن باشد.","explanation":"اول تعداد دستگاه، محل، سرویس و ارتباط مجاز را ثبت کن. کابل موجود، اینترنت، محدودهٔ آدرس و ساعات مهم کار را بپرس. سپس نقشهٔ فیزیکی برای تجهیزات و کابل و نقشهٔ منطقی برای VLAN، زیرشبکه، Gateway و سرویس می‌سازی.\n\nبعد هدف قابل‌آزمایش تعریف کن: کاربر IP درست بگیرد، نام داخلی درست تبدیل شود و مهمان به سرور داخلی نرسد. ترتیب اجرا و راه بازگشت هنگام خطا را طراحی کن. تغییرها را طوری ثبت کن که تکنسین دیگر بتواند بفهمد. روشن‌شدن چراغ‌ها کافی نیست؛ نیاز باید با آزمایش تأیید شود.","example":"دفتر به شبکهٔ کارمند و مهمان نیاز دارد. VLAN 10 و 20 با زیرشبکهٔ جدا می‌سازی. نقشه پورت، Gateway و Pool DHCP را نشان می‌دهد. برای پذیرش از هر گروه یک دستگاه، تنظیم دریافتی و ارتباط مجاز و ممنوع را آزمایش می‌کنی.","remember":["نیاز را پیش از تنظیم روشن کن.","نقشهٔ فیزیکی و منطقی مکمل‌اند.","پذیرش نتیجهٔ مشخص توافق‌شده را می‌آزماید."],"summary":"نیاز را پیش از تنظیم روشن کن.","mistake":"اینترنت کارکردن ثابت نمی‌کند جداسازی شبکهٔ داخلی درست است.","terms":[["Istzustand","وضعیت موجود پیش از تغییر."],["Sollzustand","نتیجهٔ مورد نیاز."],["Physischer Netzplan","تجهیز، محل و اتصال."],["Logischer Netzplan","VLAN، شبکهٔ IP و سرویس."],["Abnahmekriterium","شرط قابل‌آزمایش پایان موفق."]],"q":"کدام معیار پذیرش خوب است؟","options":["شبکه زیبا باشد","مهمان اینترنت داشته باشد ولی به سرور داخلی نرسد","کابل زیاد وصل باشد"],"answer":1,"feedback":"این شرط دو نتیجهٔ مشخص قابل آزمایش دارد.","sections":[]},"minutes":8,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"fachpraxis/switch":{"de":{"title":"Switch einrichten: Ports und VLANs bewusst zuordnen","goal":"Du planst Access- und Trunkports und prüfst Managementzugang sowie Portzuordnung.","definition":"Ein Ethernet-Switch verbindet Geräte innerhalb von Layer-2-Netzen. Er lernt Quell-MAC-Adressen an Ports und nutzt diese Zuordnung für die Weiterleitung von Frames. Bei einem verwaltbaren Switch lassen sich unter anderem VLANs und Portfunktionen konfigurieren.","explanation":"Prüfe vor der Änderung Modell, vorhandene Konfiguration und einen sicheren Managementzugang. Lege die benötigten VLANs an und ordne Endgeräteports als Access-Ports dem passenden VLAN zu. Für eine Verbindung zu einem anderen VLAN-fähigen Gerät kann ein Trunk mit einer bewusst begrenzten Liste erlaubter VLANs erforderlich sein. Beide Seiten müssen zusammenpassen.\n\nEine Management-IP dient der Verwaltung des Switches und macht einen reinen Layer-2-Switch nicht automatisch zum Router. Dokumentiere Portnummer, angeschlossenes Gerät und VLAN. Speichere die Konfiguration nach dem vorgesehenen Verfahren, damit sie einen Neustart übersteht. Teste zuerst einen Port, bevor dieselbe Änderung auf viele Anschlüsse übertragen wird.","example":"Port 1 verbindet einen Firmen-PC in VLAN 10, Port 2 einen Gast in VLAN 20. Port 24 verbindet den Router als Trunk für beide VLANs. Du prüfst, ob der PC seine vorgesehenen Dienste erreicht und der Gast auf das Internet beschränkt bleibt. Bei fehlender Verbindung kontrollierst du zuerst Portmodus und VLAN-Zuordnung.","remember":["Access-Ports ordnen Endgeräte zu.","Trunks transportieren bewusst erlaubte VLANs.","Management-IP ist keine automatische Routingfunktion."],"summary":"Access-Ports ordnen Endgeräte zu.","mistake":"Eine VLAN-ID nur auf einer Trunkseite zuzulassen reicht nicht für eine funktionierende durchgehende Verbindung.","terms":[["MAC-Tabelle","Zuordnung gelernter MAC-Adressen zu Ports."],["Access-Port","Endgeräteport mit VLAN-Zuordnung."],["Trunk","Verbindung für mehrere VLANs."],["Management-IP","Adresse für die Verwaltung eines Geräts."],["Konfigurationssicherung","Gespeicherter Stand zur Wiederherstellung."]],"q":"Was macht die Management-IP eines Layer-2-Switches?","options":["Sie ermöglicht die Verwaltung","Sie routet automatisch alle VLANs","Sie ersetzt jede Firewall"],"answer":0,"feedback":"Für Inter-VLAN-Routing ist eine passende Layer-3-Funktion nötig.","sections":[]},"fa":{"title":"تنظیم سوئیچ؛ تخصیص آگاهانهٔ پورت و VLAN","goal":"Access و Trunk را طراحی و دسترسی مدیریت و عضویت پورت را بررسی کنی.","definition":"سوئیچ Ethernet دستگاه‌ها را در شبکه‌های لایهٔ ۲ وصل می‌کند. MAC مبدأ را روی پورت یاد می‌گیرد و از جدول برای هدایت فریم استفاده می‌کند. سوئیچ مدیریتی امکان تنظیم VLAN و نقش پورت دارد.","explanation":"پیش از تغییر مدل، تنظیم موجود و راه مدیریت امن را بررسی کن. VLAN لازم را بساز و پورت دستگاه را به‌عنوان Access عضو شبکهٔ درست کن. اتصال به تجهیز VLANدار دیگر ممکن است Trunk با فهرست محدود VLAN مجاز بخواهد؛ دو سمت باید سازگار باشند.\n\nIP مدیریت برای تنظیم سوئیچ است و سوئیچ لایهٔ ۲ را خودکار روتر نمی‌کند. شمارهٔ پورت، دستگاه و VLAN را ثبت کن. تنظیم را با روش مناسب ذخیره کن تا پس از روشن‌شدن مجدد باقی بماند. اول یک پورت را آزمایش کن، سپس تغییر را گسترش بده.","example":"پورت ۱ کارمند VLAN 10، پورت ۲ مهمان VLAN 20 و پورت ۲۴ Trunk روتر برای هر دو است. خدمات لازم کارمند و محدودشدن مهمان به اینترنت را می‌آزمایی. اگر ارتباط نبود، ابتدا حالت پورت و VLAN را بررسی می‌کنی.","remember":["Access دستگاه را عضو شبکه می‌کند.","Trunk VLANهای مجاز را حمل می‌کند.","IP مدیریت خودکار مسیریابی نمی‌دهد."],"summary":"Access دستگاه را عضو شبکه می‌کند.","mistake":"مجازکردن VLAN فقط در یک سمت Trunk برای اتصال کامل کافی نیست.","terms":[["MAC-Tabelle","جدول MACهای آموخته‌شده و پورت."],["Access-Port","پورت دستگاه با عضویت VLAN."],["Trunk","اتصال چند VLAN."],["Management-IP","آدرس مدیریت تجهیز."],["Konfigurationssicherung","نسخهٔ تنظیم برای بازیابی."]],"q":"IP مدیریت سوئیچ لایهٔ ۲ چه می‌کند؟","options":["مدیریت را ممکن می‌کند","همهٔ VLANها را خودکار مسیریابی می‌کند","جای همهٔ فایروال‌ها را می‌گیرد"],"answer":0,"feedback":"برای مسیریابی بین VLAN به قابلیت مناسب لایهٔ ۳ نیاز است.","sections":[]},"minutes":8,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"fachpraxis/router":{"de":{"title":"Router einrichten: Schnittstellen, Wege und Regeln","goal":"Du planst Gatewayadressen und unterscheidest Routing, NAT und Zugriffskontrolle.","definition":"Ein Router verbindet unterschiedliche IP-Netze. Seine Schnittstellen oder logischen Unterschnittstellen sind die erreichbaren Übergänge für die jeweiligen Netze. Die Routingtabelle bestimmt den nächsten Weg für ein Paket.","explanation":"Lege zuerst für jedes direkt angebundene Subnetz eine passende Routeradresse und Maske fest. Bei mehreren VLANs kann ein Router mit VLAN-Unterschnittstellen oder ein Layer-3-Switch eingesetzt werden. Die Endgeräte tragen die tatsächlich konfigurierte Routeradresse ihres eigenen Subnetzes als Standardgateway ein, sofern diese Standardroute vorgesehen ist.\n\nDirekt angeschlossene Netze werden anhand aktiver Schnittstellen bekannt. Entfernte Netze benötigen passende Routen; für übrige Ziele kann eine Standardroute dienen. Routing allein übersetzt keine Adressen. Ein typischer IPv4-Internetzugang benötigt gegebenenfalls zusätzlich NAT/PAT. Firewallregeln legen fest, welche Verbindungen zulässig sind. Prüfe auch den Rückweg und sichere den Managementzugang.","example":"VLAN 10 nutzt 192.168.10.0/24 mit Gateway .1. VLAN 20 nutzt 192.168.20.0/24 mit Gateway .1 im jeweils eigenen Netz. Du richtest 192.168.10.1/24 und 192.168.20.1/24 am Router ein. Erst danach testest du lokale Gateways, erlaubte netzübergreifende Ziele und den Internetpfad getrennt.","remember":["Gatewayadresse muss zum lokalen Subnetz passen.","Routing, NAT und Firewall erfüllen verschiedene Aufgaben.","Für jede Verbindung Hin- und Rückweg beachten."],"summary":"Gatewayadresse muss zum lokalen Subnetz passen.","mistake":"Ein beliebiger erreichbarer Server ist kein Gateway, solange er keine entsprechende Routingfunktion bereitstellt.","terms":[["Routerschnittstelle","Anschluss oder logischer Zugang zu einem Netz."],["Gateway","Nächster Router für eine Route vom Endgerät."],["Subinterface","Logisch unterteilte Netzschnittstelle, etwa je VLAN."],["Standardroute","Route für nicht spezifischer bekannte Ziele."],["Firewallregel","Vorgabe für erlaubten oder gesperrten Verkehr."]],"q":"Welche Funktion wählt den Weg zwischen IP-Netzen?","options":["Routing","Nur DNS","Nur Dateikompression"],"answer":0,"feedback":"Routing bestimmt den nächsten Weg. DNS löst Namen auf, NAT verändert Adressinformationen.","sections":[]},"fa":{"title":"تنظیم روتر؛ رابط، مسیر و قانون","goal":"Gateway را طراحی و Routing، NAT و کنترل دسترسی را جدا کنی.","definition":"روتر شبکه‌های IP متفاوت را وصل می‌کند. رابط فیزیکی یا منطقی آن نقطهٔ عبور قابل‌دسترسی هر شبکه است. جدول مسیریابی مسیر بعدی بسته را تعیین می‌کند.","explanation":"ابتدا برای هر زیرشبکهٔ مستقیم، آدرس و ماسک مناسب روتر را تعیین کن. چند VLAN می‌توانند از Subinterface روتر یا سوئیچ لایهٔ ۳ استفاده کنند. دستگاه‌ها در صورت نیاز به مسیر پیش‌فرض، آدرس واقعی رابط روتر در زیرشبکهٔ خود را به‌عنوان Gateway می‌گیرند.\n\nشبکهٔ مستقیم از رابط فعال شناخته می‌شود؛ شبکهٔ دور مسیر مناسب می‌خواهد و برای بقیه مقصدها می‌توان مسیر پیش‌فرض داشت. Routing خود آدرس را ترجمه نمی‌کند. اینترنت معمول IPv4 ممکن است علاوه بر آن NAT/PAT بخواهد. فایروال ارتباط مجاز را مشخص می‌کند. مسیر بازگشت و مدیریت امن را هم بررسی کن.","example":"VLAN 10 شبکهٔ 192.168.10.0/24 و VLAN 20 شبکهٔ 192.168.20.0/24 دارد؛ Gateway هرکدام .1 در شبکهٔ خودش است. روی روتر 192.168.10.1/24 و 192.168.20.1/24 می‌گذاری. سپس Gateway محلی، ارتباط بین شبکهٔ مجاز و اینترنت را جدا می‌آزمایی.","remember":["Gateway باید با زیرشبکهٔ محلی سازگار باشد.","Routing، NAT و فایروال کار متفاوت دارند.","مسیر رفت و برگشت هر دو مهم‌اند."],"summary":"Gateway باید با زیرشبکهٔ محلی سازگار باشد.","mistake":"هر سرور قابل دسترس Gateway نیست؛ باید وظیفهٔ مسیریابی مناسب را انجام دهد.","terms":[["Routerschnittstelle","رابط فیزیکی یا منطقی یک شبکه."],["Gateway","روتر بعدی مسیر از دستگاه."],["Subinterface","بخش منطقی رابط، مثلاً برای هر VLAN."],["Standardroute","مسیر مقصد بدون راه دقیق‌تر."],["Firewallregel","قانون ترافیک مجاز یا ممنوع."]],"q":"کدام وظیفه مسیر بین شبکهٔ IP را انتخاب می‌کند؟","options":["مسیریابی","فقط DNS","فقط فشرده‌سازی فایل"],"answer":0,"feedback":"Routing راه بعدی را تعیین می‌کند؛ DNS نام را تبدیل و NAT آدرس را تغییر می‌دهد.","sections":[]},"minutes":7,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"fachpraxis/dhcp":{"de":{"title":"DHCP je VLAN: den richtigen Bereich vergeben","goal":"Du planst je Subnetz einen Scope und erklärst, wann ein Relay benötigt wird.","definition":"Ein DHCP-Scope ist eine zusammengehörige Konfiguration für einen IP-Adressbereich. In einem Netz mit mehreren VLANs müssen Pool und Optionen zum jeweiligen Subnetz des Clients passen, damit Geräte die richtigen Netzwerkeinstellungen erhalten.","explanation":"Für jeden Bereich legst du Netzadresse und Maske, vergebbaren Pool, ausgeschlossene Adressen und passende Optionen fest. Die Gatewayoption verweist auf die Routeradresse in diesem Subnetz. Die DNS-Option nennt den vorgesehenen Resolver. Die Leasezeit beschreibt, wie lange die Zuteilung gilt. Statische Infrastrukturadressen werden bewusst ausgenommen oder gezielt reserviert.\n\nSteht der DHCP-Server in einem anderen Subnetz, kann ein Relay am Router Anfragen weiterleiten und die Herkunft kenntlich machen. Der Server wählt dadurch den passenden Bereich. Ohne Relay erreichen anfängliche lokale Broadcasts einen entfernten DHCP-Server normalerweise nicht. Teste jede VLAN-Gruppe einzeln; ein funktionierender Pool in VLAN 10 beweist nicht, dass VLAN 20 richtig versorgt wird.","example":"VLAN 10 erhält den Pool 192.168.10.100–200, Gateway 192.168.10.1 und /24. VLAN 20 erhält 192.168.20.100–200, Gateway 192.168.20.1 und /24. Ein Gastgerät mit einer Adresse aus 192.168.10.0/24 deutet auf eine falsche VLAN-Zuordnung oder DHCP-Konfiguration hin. Prüfe Port, Relay und Scope statt nur die Leasezeit zu verändern.","remember":["Ein Subnetz braucht passende DHCP-Optionen.","Ein Relay verbindet lokale Anfragen mit einem entfernten Server.","Erhaltene Adresse, Maske, Gateway und DNS je VLAN testen."],"summary":"Ein Subnetz braucht passende DHCP-Optionen.","mistake":"Adresspools für verschiedene Netze dürfen nicht mit demselben falschen Gateway kopiert werden.","terms":[["Scope","DHCP-Konfiguration für einen Adressbereich."],["Pool","Zur Vergabe vorgesehene IP-Adressen."],["Ausschluss","Adresse, die nicht dynamisch vergeben wird."],["Reservierung","Gezielte Adresszuordnung zu einem Client."],["Relay","Weiterleitung von DHCP-Anfragen aus einem anderen Subnetz."],["Option","Zusätzlicher Konfigurationswert wie Gateway oder DNS."]],"q":"Welches Gateway passt zu einem üblichen Client in 192.168.20.0/24?","options":["Die konfigurierte Routeradresse in diesem Subnetz","Immer 192.168.10.1","Beliebige Internetadresse"],"answer":0,"feedback":"Das Gateway muss im üblichen LAN-Aufbau direkt erreichbar und auf dem Router tatsächlich eingerichtet sein.","sections":[]},"fa":{"title":"DHCP برای هر VLAN؛ تخصیص محدودهٔ درست","goal":"برای هر زیرشبکه Scope طراحی و نیاز به Relay را توضیح بدهی.","definition":"Scope در DHCP مجموعهٔ تنظیمات یک محدودهٔ آدرس است. در شبکهٔ چند VLAN، Pool و گزینه‌ها باید با زیرشبکهٔ کاربر سازگار باشند تا تنظیم درست دریافت شود.","explanation":"برای هر محدوده، شبکه و ماسک، Pool، آدرس مستثنا و گزینه‌ها را مشخص کن. Gateway باید آدرس روتر همان زیرشبکه باشد. گزینهٔ DNS، Resolver مناسب و Lease مدت تخصیص را می‌گوید. آدرس زیرساخت ثابت را آگاهانه مستثنا یا رزرو کن.\n\nاگر سرور در زیرشبکهٔ دیگر است، Relay روتر درخواست را منتقل و مبدأ را مشخص می‌کند تا سرور محدودهٔ مناسب را انتخاب کند. بدون Relay، Broadcast اولیه معمولاً به سرور دور نمی‌رسد. هر VLAN را جدا آزمایش کن؛ کارکرد VLAN 10 ثابت نمی‌کند VLAN 20 هم تنظیم درست می‌گیرد.","example":"Pool VLAN 10 از 192.168.10.100 تا .200 با Gateway 192.168.10.1 و /24 است؛ VLAN 20 از 192.168.20.100 تا .200 با Gateway 192.168.20.1. اگر مهمان IP شبکهٔ کارمند بگیرد، عضویت VLAN یا DHCP را بررسی کن؛ فقط تغییر Lease راه‌حل نیست.","remember":["هر زیرشبکه گزینهٔ DHCP مناسب می‌خواهد.","Relay درخواست محلی را به سرور دور می‌رساند.","IP، ماسک، Gateway و DNS هر VLAN را بررسی کن."],"summary":"هر زیرشبکه گزینهٔ DHCP مناسب می‌خواهد.","mistake":"Pool شبکه‌های مختلف را با Gateway اشتباه یکسان کپی نکن.","terms":[["Scope","تنظیم DHCP یک محدوده."],["Pool","آدرس‌های قابل واگذاری."],["Ausschluss","آدرس مستثنا از تخصیص پویا."],["Reservierung","آدرس مشخص برای کاربر معین."],["Relay","انتقال درخواست DHCP از زیرشبکهٔ دیگر."],["Option","تنظیم اضافی مثل Gateway یا DNS."]],"q":"برای کاربر معمول شبکهٔ 192.168.20.0/24 کدام Gateway مناسب است؟","options":["آدرس تنظیم‌شدهٔ روتر در همین شبکه","همیشه 192.168.10.1","هر IP اینترنتی"],"answer":0,"feedback":"Gateway در LAN معمول باید مستقیم قابل دسترس و واقعاً روی روتر تنظیم باشد.","sections":[]},"minutes":8,"source":["RFC 2131 · DHCP","https://www.rfc-editor.org/rfc/rfc2131.html"],"editorial":true},"fachpraxis/test":{"de":{"title":"Netzwerk abnehmen: lokal, netzübergreifend, Anwendung","goal":"Du führst einen nachvollziehbaren Testplan aus und prüfst auch unerlaubte Verbindungen.","definition":"Eine Netzwerkabnahme vergleicht den aufgebauten Zustand mit den vereinbarten Anforderungen. Sie umfasst Konfiguration, Erreichbarkeit, Dienste und Sicherheitsgrenzen. Ein einzelner erfolgreicher Ping genügt dafür nicht.","explanation":"Stufe 1 prüft das lokale Netz: Linkzustand, VLAN-Zuordnung und erhaltene IP-Konfiguration. Danach testest du ein geeignetes lokales Ziel und das eigene Gateway. Stufe 2 untersucht den Weg zu anderen Netzen: passende Route, Rückweg und erlaubte beziehungsweise gesperrte Verbindungen. Ping ist dabei nur ein Werkzeug und kann durch ICMP-Filter begrenzt sein.\n\nStufe 3 prüft den eigentlichen Anwendungsfall. Ein Webdienst muss über seinen vorgesehenen Namen und Port funktionieren; ein Dateidienst benötigt eine gültige Anmeldung und die richtigen Rechte. Prüfe zusätzlich negative Fälle, etwa dass Gäste den Personalserver nicht erreichen. Protokolliere Testquelle, Ziel, erwartetes Ergebnis, tatsächliches Ergebnis und offene Abweichungen.","example":"Ein Mitarbeiter-PC erhält die richtige Adresse und erreicht sein Gateway. Der Servername wird korrekt aufgelöst, aber die Datei kann nicht geöffnet werden. Der Fehler liegt damit noch nicht automatisch im Kabel: Prüfe Dienst, Anmeldung und Dateiberechtigungen. Ein separater Gasttest bestätigt, dass dieser Server aus dem Gastnetz gesperrt bleibt.","remember":["Lokale Verbindung, Netzweg und Anwendung getrennt prüfen.","Erlaubte und verbotene Verbindungen testen.","Erwartung und tatsächliches Ergebnis dokumentieren."],"summary":"Lokale Verbindung, Netzweg und Anwendung getrennt prüfen.","mistake":"Ein offener Port beweist nicht, dass der Nutzer die erforderlichen Daten lesen darf. Erreichbarkeit und Berechtigung unterscheiden sich.","terms":[["Testfall","Definierter Aufbau mit Aktion und erwartetem Ergebnis."],["Positivtest","Prüfung eines erlaubten funktionierenden Vorgangs."],["Negativtest","Prüfung, dass Unerlaubtes oder Ungültiges verhindert wird."],["Abweichung","Unterschied zwischen Soll- und Ist-Ergebnis."],["Abnahmeprotokoll","Nachweis ausgeführter Tests und ihrer Ergebnisse."]],"q":"Warum gehört ein Gastzugriff auf interne Server in den Testplan?","options":["Um die geplante Sperre zu prüfen","Um alle Regeln auszuschalten","Weil Gäste immer Administratoren sind"],"answer":0,"feedback":"Ein Negativtest weist nach, dass die Sicherheitsgrenze die verbotene Verbindung tatsächlich verhindert.","sections":[]},"fa":{"title":"پذیرش شبکه؛ محلی، بین‌شبکه‌ای و کاربرد","goal":"برنامهٔ آزمایش قابل پیگیری اجرا و ارتباط غیرمجاز را هم بررسی کنی.","definition":"پذیرش شبکه وضعیت ساخته‌شده را با نیاز توافق‌شده مقایسه می‌کند. تنظیمات، دسترسی، سرویس و مرز امنیتی بررسی می‌شوند؛ یک Ping موفق کافی نیست.","explanation":"مرحلهٔ ۱ شبکهٔ محلی را بررسی می‌کند: Link، VLAN و IP دریافتی؛ سپس مقصد محلی و Gateway مناسب را آزمایش کن. مرحلهٔ ۲ مسیر به شبکهٔ دیگر، بازگشت و ارتباط مجاز و ممنوع را بررسی می‌کند. Ping تنها یک ابزار است و فیلتر ICMP می‌تواند پاسخ را محدود کند.\n\nمرحلهٔ ۳ خود کاربرد را می‌آزماید. وب‌سرویس باید با نام و پورت مقرر کار کند؛ فایل‌سرویس ورود معتبر و مجوز درست می‌خواهد. حالت منفی را هم بررسی کن، مثل نرسیدن مهمان به سرور منابع انسانی. مبدأ، مقصد، نتیجهٔ مورد انتظار، نتیجهٔ واقعی و اختلاف باقی‌مانده را ثبت کن.","example":"کامپیوتر کارمند IP درست و دسترسی Gateway دارد. نام سرور درست تبدیل می‌شود ولی فایل باز نمی‌شود. فوراً کابل را مقصر ندان؛ سرویس، ورود و مجوز فایل را بررسی کن. آزمایش جداگانهٔ مهمان باید ممنوع‌بودن دسترسی به همین سرور را تأیید کند.","remember":["اتصال محلی، مسیر شبکه و برنامه را جدا آزمایش کن.","ارتباط مجاز و ممنوع را هر دو امتحان کن.","انتظار و نتیجهٔ واقعی را ثبت کن."],"summary":"اتصال محلی، مسیر شبکه و برنامه را جدا آزمایش کن.","mistake":"پورت باز ثابت نمی‌کند کاربر حق خواندن داده دارد؛ دسترسی شبکه و مجوز متفاوت‌اند.","terms":[["Testfall","آزمایش تعریف‌شده با عمل و نتیجهٔ مورد انتظار."],["Positivtest","بررسی کار مجاز و صحیح."],["Negativtest","بررسی جلوگیری از کار نامجاز یا نامعتبر."],["Abweichung","تفاوت نتیجهٔ مطلوب و واقعی."],["Abnahmeprotokoll","ثبت آزمایش انجام‌شده و نتیجه."]],"q":"چرا دسترسی مهمان به سرور داخلی در برنامهٔ آزمایش است؟","options":["برای بررسی مسدودبودن برنامه‌ریزی‌شده","برای خاموش‌کردن همهٔ قوانین","چون مهمان همیشه مدیر است"],"answer":0,"feedback":"آزمایش منفی نشان می‌دهد مرز امنیتی واقعاً ارتباط ممنوع را متوقف می‌کند.","sections":[]},"minutes":8,"source":["Cisco · Network communication models","https://www.ciscopress.com/articles/article.asp?p=3192417&seqNum=6"],"editorial":true},"pug/struktur":{"de":{"title":"Artikel 20: die Grundordnung Deutschlands","goal":"Du erklärst die Staatsprinzipien aus Artikel 20 und ordnest ihnen verständliche Beispiele zu.","definition":"Artikel 20 des Grundgesetzes beschreibt zentrale Regeln für den deutschen Staat: woher seine Macht kommt, wie sie ausgeübt wird und woran staatliches Handeln gebunden ist.","explanation":"Der Staat ist kein einzelner Mensch, sondern besteht aus vielen Einrichtungen mit festgelegten Aufgaben. Artikel 20 verbindet diese Aufgaben mit Grundprinzipien. Du lernst ihn am besten in zwei Schritten: Zuerst die Staatsform und die politischen Ziele, dann die Regeln für Entscheidungen und Kontrolle. Die Regeln gelten auch dann, wenn eine Entscheidung politisch beliebt ist.","example":"Eine Gemeinde lehnt einen Antrag ab. Die betroffene Person kann prüfen lassen, ob die Behörde das geltende Recht richtig angewendet hat. Das zeigt den Rechtsstaat: Staatliche Entscheidungen brauchen eine rechtliche Grundlage und können überprüft werden.","remember":["Demokratie: Staatliche Macht wird auf die Bevölkerung zurückgeführt.","Bundesstaat: Bund und Länder teilen staatliche Aufgaben.","Rechtsstaat: Auch der Staat ist an Recht gebunden."],"summary":"Artikel 20 verbindet demokratische Legitimation, soziale Verantwortung, föderale Organisation und rechtliche Bindung.","mistake":"Eine Mehrheit kann nicht allein dadurch jede beliebige staatliche Maßnahme rechtmäßig machen. Mehrheitsentscheidungen müssen die Verfassung beachten.","terms":[["Grundgesetz","Verfassung der Bundesrepublik Deutschland."],["Demokratieprinzip","Staatliche Herrschaft muss demokratisch legitimiert sein."],["Sozialstaat","Der Staat trägt Verantwortung für soziale Sicherheit und Ausgleich."],["Bundesstaat","Staat mit Aufgaben und Zuständigkeiten für Bund und Länder."],["Republik","Staatsform ohne erbliches Staatsoberhaupt."],["Rechtsstaat","Staatliche Macht ist durch Recht gebunden und kontrollierbar."]],"q":"Welches Beispiel zeigt besonders das Bundesstaatsprinzip?","options":["Bund und Länder besitzen eigene Zuständigkeiten.","Eine Behörde darf jedes Gesetz ignorieren.","Ein Amt wird automatisch an ein Kind vererbt."],"answer":0,"feedback":"Föderalismus verteilt staatliche Aufgaben zwischen Bund und Ländern. Das ist das Bundesstaatsprinzip.","sections":[{"title":"Staatsform und Ziele","body":"Republik bedeutet: Das Staatsoberhaupt erhält sein Amt nicht durch Erbfolge. Demokratie bedeutet: Entscheidungen brauchen eine demokratische Legitimation. Sozialstaat bedeutet: Der Staat übernimmt Verantwortung für soziale Sicherheit und Ausgleich. Bundesstaat bedeutet: Bund und Länder haben eigene Zuständigkeiten."},{"title":"Entscheidung und Bindung","body":"Die Bevölkerung wirkt insbesondere durch Wahlen an der Staatsgewalt mit. Gesetzgebung, Regierung und Verwaltung sowie Gerichte erfüllen unterschiedliche Aufgaben. Gesetzgebung ist an die Verfassung gebunden; Verwaltung und Rechtsprechung sind an Gesetz und Recht gebunden."}]},"fa":{"title":"اصل ۲۰؛ نظم پایهٔ دولت آلمان","goal":"اصول اصلی دولت در مادهٔ ۲۰ را توضیح بدهی و برای هرکدام مثال مناسب پیدا کنی.","definition":"مادهٔ ۲۰ قانون اساسی قواعد اصلی دولت آلمان را مشخص می‌کند: قدرت از کجا می‌آید، چگونه اعمال می‌شود و دولت باید به چه قواعدی پایبند باشد.","explanation":"دولت یک شخص نیست؛ از نهادهای مختلف با وظایف مشخص تشکیل شده است. مادهٔ ۲۰ این وظایف را به چند اصل متصل می‌کند. برای فهم آن، اول شکل دولت و هدف‌های عمومی را بشناس؛ بعد ببین تصمیم‌ها چگونه گرفته و کنترل می‌شوند. محبوب‌بودن یک تصمیم باعث نمی‌شود قانون اساسی کنار گذاشته شود.","example":"یک اداره درخواست شخصی را رد می‌کند. آن شخص می‌تواند بررسی قانونی تصمیم را پیگیری کند. این مثالِ دولت قانون‌مدار است: تصمیم اداره باید مبنای قانونی داشته و قابل بررسی باشد.","remember":["دموکراسی: قدرت دولت باید از مردم مشروعیت بگیرد.","فدرالیسم: دولت مرکزی و ایالت‌ها وظایف را تقسیم می‌کنند.","دولت قانون‌مدار: خود دولت نیز به قانون پایبند است."],"summary":"اصل ۲۰ مشروعیت مردمی، مسئولیت اجتماعی، ساختار فدرال و پایبندی به قانون را به هم وصل می‌کند.","mistake":"اکثریت نمی‌تواند صرفاً با رأی خود هر اقدام دولتی را قانونی کند. تصمیم اکثریت هم باید با قانون اساسی سازگار باشد.","terms":[["Grundgesetz","قانون اساسی جمهوری فدرال آلمان."],["Demokratieprinzip","اصل مشروعیت مردمیِ قدرت دولت."],["Sozialstaat","مسئولیت دولت برای امنیت و تعادل اجتماعی."],["Bundesstaat","دولتی با وظایف و صلاحیت‌های تقسیم‌شده میان دولت مرکزی و ایالت‌ها."],["Republik","شکلی از دولت که رئیس کشور مقام خود را به ارث نمی‌برد."],["Rechtsstaat","دولتی که قدرت آن محدود به قانون و قابل کنترل است."]],"q":"کدام مثال بیشتر اصل فدرالیسم را نشان می‌دهد؟","options":["دولت مرکزی و ایالت‌ها صلاحیت‌های مشخص خود را دارند.","اداره می‌تواند هر قانونی را نادیده بگیرد.","مقام دولتی خودکار به فرزند صاحب مقام می‌رسد."],"answer":0,"feedback":"فدرالیسم وظایف دولت را میان دولت مرکزی و ایالت‌ها تقسیم می‌کند.","sections":[{"title":"شکل دولت و هدف‌های آن","body":"Republik یعنی رئیس کشور مقامش را به ارث نمی‌برد. Demokratie یعنی تصمیم‌ها به مشروعیت مردمی نیاز دارند. Sozialstaat یعنی دولت در برابر امنیت و تعادل اجتماعی مسئولیت دارد. Bundesstaat یعنی دولت مرکزی و ایالت‌ها صلاحیت‌های مشخص خود را دارند."},{"title":"تصمیم‌گیری و پایبندی به قانون","body":"مردم به‌ویژه از راه انتخابات در قدرت دولت نقش دارند. قانون‌گذاری، دولت و اداره‌ها، و دادگاه‌ها وظایف متفاوتی دارند. قانون‌گذار باید قانون اساسی را رعایت کند؛ اداره‌ها و دادگاه‌ها نیز به قانون و حقوق پایبندند."}]},"source":["Grundgesetz · Artikel 20","https://www.gesetze-im-internet.de/gg/art_20.html"],"minutes":8,"editorial":true},"pug/demo":{"de":{"title":"Demokratie: mitbestimmen und Macht kontrollieren","goal":"Du nennst zentrale Merkmale einer Demokratie und erklärst, warum Wahlen allein nicht ausreichen.","definition":"Demokratie ist eine Ordnung, in der politische Herrschaft vom Volk legitimiert wird. Bürgerinnen und Bürger können auf Entscheidungen Einfluss nehmen und politische Verantwortung kontrollieren.","explanation":"Eine Demokratie braucht Regeln für einen fairen Wettbewerb um politische Macht. Unterschiedliche Ansichten müssen öffentlich vertreten werden können. Entscheidungen werden nach festgelegten Verfahren getroffen und können politisch kritisiert werden. Wer heute in der Minderheit ist, muss auch morgen noch die Chance haben, für seine Position zu werben. Darum gehören Grundrechte und unabhängige Gerichte zur demokratischen Ordnung.","example":"Bei einer Klassenwahl treten mehrere Personen an. Alle Wahlberechtigten dürfen ohne Druck abstimmen; die Stimmen werden nach demselben Verfahren gezählt. Danach vertritt die gewählte Person auch die Anliegen derjenigen, die sie nicht gewählt haben. Dieses Schulbeispiel macht mehrere demokratische Prinzipien sichtbar.","remember":["Freie Wahlen erlauben echte Auswahl.","Mehrheit entscheidet innerhalb rechtlicher Grenzen.","Opposition und Kritik sind Teil demokratischer Kontrolle."],"summary":"Demokratie verbindet Beteiligung mit Grundrechten, fairen Verfahren und kontrollierbarer Macht.","mistake":"Eine Abstimmung ist nicht automatisch demokratisch, wenn Menschen bedroht werden, keine echte Auswahl haben oder Minderheiten ihre Rechte verlieren.","terms":[["Volkssouveränität","Politische Staatsgewalt geht vom Volk aus."],["Wahl","Verfahren zur Auswahl politischer Vertreterinnen und Vertreter."],["Mehrheitsprinzip","Entscheidung nach festgelegter Stimmenmehrheit."],["Minderheitenschutz","Schutz der Rechte auch der überstimmten Gruppe."],["Opposition","Politische Kräfte, die nicht die Regierung tragen und sie kontrollieren."],["Meinungsfreiheit","Grundrecht, Meinungen im rechtlichen Rahmen frei zu äußern."]],"q":"Warum ist eine Opposition in einer Demokratie wichtig?","options":["Sie darf jede Wahl nachträglich ändern.","Sie kontrolliert die Regierung und bietet politische Alternativen.","Sie ersetzt sämtliche Gerichte."],"answer":1,"feedback":"Die Opposition prüft und kritisiert Regierungshandeln. Sie macht außerdem andere politische Lösungen sichtbar.","sections":[{"title":"Beteiligung","body":"Wahlberechtigte wählen Vertreter. Menschen können sich außerdem in Parteien, Verbänden, Initiativen oder öffentlichen Diskussionen einbringen. Welche Rechte im Einzelnen gelten, hängt vom jeweiligen Verfahren ab."},{"title":"Freiheit und Kontrolle","body":"Freie Medien und öffentliche Kritik helfen, politische Entscheidungen zu prüfen. Unabhängige Gerichte schützen Rechte. Machtwechsel müssen möglich bleiben, damit eine Regierung ihre Macht nicht dauerhaft dem Wettbewerb entzieht."}]},"fa":{"title":"دموکراسی؛ مشارکت و کنترل قدرت","goal":"ویژگی‌های اصلی دموکراسی را نام ببری و توضیح بدهی چرا فقط رأی‌گیری کافی نیست.","definition":"دموکراسی نظمی است که قدرت سیاسی آن از مردم مشروعیت می‌گیرد. شهروندان می‌توانند بر تصمیم‌ها اثر بگذارند و مسئولان سیاسی را کنترل کنند.","explanation":"دموکراسی برای رقابت منصفانه بر سر قدرت به قواعد نیاز دارد. دیدگاه‌های مختلف باید بتوانند در فضای عمومی مطرح شوند. تصمیم‌ها با روش مشخص گرفته می‌شوند و نقد سیاسی آن‌ها ممکن است. کسی که امروز در اقلیت است، باید فردا هم فرصت دفاع از دیدگاه خود را داشته باشد. به همین دلیل حقوق اساسی و دادگاه مستقل بخشی از نظم دموکراتیک‌اند.","example":"در انتخابات نمایندهٔ کلاس چند نفر نامزد می‌شوند. افراد دارای حق رأی بدون فشار رأی می‌دهند و رأی‌ها با یک روش شمرده می‌شوند. شخص منتخب باید خواسته‌های کسانی را هم بشنود که به او رأی نداده‌اند. این مثال ساده چند اصل دموکراتیک را نشان می‌دهد.","remember":["انتخابات آزاد امکان انتخاب واقعی می‌دهد.","اکثریت در چارچوب قانون تصمیم می‌گیرد.","نقد و اپوزیسیون بخشی از کنترل دموکراتیک‌اند."],"summary":"دموکراسی، مشارکت را با حقوق اساسی، روش منصفانه و قدرت قابل‌کنترل ترکیب می‌کند.","mistake":"هر رأی‌گیری خودکار دموکراتیک نیست؛ تهدید رأی‌دهنده، نبود انتخاب واقعی و ازبین‌بردن حقوق اقلیت با آن سازگار نیست.","terms":[["Volkssouveränität","اصل اینکه قدرت دولت از مردم می‌آید."],["Wahl","روش انتخاب نمایندگان سیاسی."],["Mehrheitsprinzip","تصمیم‌گیری با اکثریتِ مشخص‌شده در قواعد."],["Minderheitenschutz","حفاظت از حقوق گروهی که رأی کمتری آورده است."],["Opposition","نیروهای سیاسیِ خارج از پشتیبانی دولت که آن را کنترل می‌کنند."],["Meinungsfreiheit","حق بیان آزاد نظر در چارچوب قانون."]],"q":"چرا وجود اپوزیسیون در دموکراسی مهم است؟","options":["می‌تواند نتیجهٔ هر انتخاباتی را عوض کند.","دولت را کنترل می‌کند و راه‌حل سیاسی دیگری پیشنهاد می‌دهد.","جای همهٔ دادگاه‌ها را می‌گیرد."],"answer":1,"feedback":"اپوزیسیون عملکرد دولت را بررسی و نقد می‌کند و راه‌حل‌های سیاسی دیگری را مطرح می‌سازد.","sections":[{"title":"مشارکت","body":"افراد دارای حق رأی نمایندگان را انتخاب می‌کنند. مشارکت در حزب، انجمن، ابتکارهای مردمی و بحث عمومی نیز ممکن است. قواعد و حقوق دقیق هر نوع مشارکت به همان روش بستگی دارد."},{"title":"آزادی و کنترل","body":"رسانهٔ آزاد و نقد عمومی به بررسی تصمیم‌های سیاسی کمک می‌کنند. دادگاه مستقل از حقوق حفاظت می‌کند. تغییر قدرت باید ممکن بماند تا دولت رقابت سیاسی را برای همیشه حذف نکند."}]},"source":["Deutscher Bundestag · Repräsentative Demokratie","https://www.bundestag.de/services/glossar/repraesentative-demokratie-869088"],"minutes":8,"editorial":true},"pug/direkt":{"de":{"title":"Direkte und repräsentative Demokratie","goal":"Du unterscheidest eine Sachabstimmung von einer Vertreterwahl und erklärst die Rolle beider Verfahren.","definition":"Bei direkter Demokratie stimmen Wahlberechtigte selbst über eine politische Sachfrage ab. Bei repräsentativer Demokratie wählen sie Personen, die politische Entscheidungen im Parlament treffen.","explanation":"Der Unterschied liegt darin, worüber abgestimmt wird: über eine konkrete Sache oder über Vertreter. Deutschland ist auf Bundesebene hauptsächlich repräsentativ organisiert. Der Bundestag ist ein gewähltes Parlament und beschließt Bundesgesetze unter Beteiligung weiterer dafür zuständiger Organe. In Ländern und Gemeinden gibt es zusätzlich direkte Verfahren nach den dortigen Regeln. Ein Bürgerbegehren ist dabei nicht schon die abschließende Abstimmung.","example":"Eine Klasse wählt zwei Klassensprecher: Sie überträgt Vertretungsaufgaben an Personen. Das ist ein Beispiel für Repräsentation. Wenn anschließend alle nach vereinbarten Regeln über das Ziel eines Klassenausflugs abstimmen, entscheiden sie direkt über eine Sache. Im Staat sind die Verfahren rechtlich genauer festgelegt als in diesem Schulbeispiel.","remember":["Personen wählen und Sachfragen abstimmen sind verschiedene Vorgänge.","Repräsentation ermöglicht laufende parlamentarische Arbeit.","Direkte Verfahren haben eigene Voraussetzungen und Zuständigkeiten."],"summary":"Direkt: selbst über die Sache entscheiden. Repräsentativ: Vertreter für politische Entscheidungen wählen.","mistake":"Nicht jedes politische Anliegen kann durch eine beliebige Online-Abstimmung verbindlich entschieden werden. Zuständigkeit und das gesetzlich geregelte Verfahren sind entscheidend.","terms":[["Repräsentation","Politische Vertretung durch gewählte Personen."],["Mandat","Amt beziehungsweise Auftrag einer gewählten Vertretung."],["Parlament","Gewählte Vertretung, die unter anderem Gesetze berät und beschließt."],["Sachabstimmung","Abstimmung über eine bestimmte politische Frage."],["Bürgerbegehren","Verfahren, mit dem eine kommunale Sachabstimmung beantragt werden kann."],["Volksentscheid","Direkte Entscheidung der Wahlberechtigten über eine Sachfrage nach geltendem Recht."]],"q":"Welche Situation ist ein Beispiel für repräsentative Demokratie?","options":["Wahlberechtigte entscheiden direkt über eine Vorlage.","Wahlberechtigte wählen Abgeordnete für ein Parlament.","Eine Person übernimmt ein Staatsamt durch Erbfolge."],"answer":1,"feedback":"Abgeordnete werden gewählt, damit sie im Parlament Entscheidungen treffen. Das ist politische Repräsentation.","sections":[{"title":"Repräsentativ: Personen auswählen","body":"Ein Parlament berät viele Themen dauerhaft und arbeitet mit Ausschüssen. Gewählte Abgeordnete müssen politische Entscheidungen begründen und stellen sich politischer Kontrolle."},{"title":"Direkt: über eine Sache entscheiden","body":"Bei einer direkten Abstimmung steht eine konkrete Vorlage zur Entscheidung. Wer teilnehmen darf, wie das Verfahren beginnt und welche Mehrheit erforderlich ist, bestimmen die jeweiligen Rechtsvorschriften."}]},"fa":{"title":"دموکراسی مستقیم و نمایندگی","goal":"رأی‌دادن به یک موضوع را از انتخاب نماینده تشخیص بدهی و نقش هر روش را توضیح بدهی.","definition":"در دموکراسی مستقیم، افراد دارای حق رأی خودشان دربارهٔ یک مسئلهٔ سیاسی رأی می‌دهند. در دموکراسی نمایندگی، اشخاصی را انتخاب می‌کنند تا در مجلس تصمیم سیاسی بگیرند.","explanation":"تفاوت این است که رأی دربارهٔ چیست: یک موضوع مشخص یا انتخاب نماینده. ساختار سیاسی آلمان در سطح فدرال عمدتاً نمایندگی است. بوندستاگ مجلس منتخب است و با مشارکت نهادهای مسئول دیگر قوانین فدرال را تصویب می‌کند. در ایالت‌ها و شهرها، روش‌های مستقیم هم طبق قواعد مربوط وجود دارند. Bürgerbegehren مرحلهٔ درخواست یک رأی‌گیری محلی است و خودِ رأی‌گیری نهایی محسوب نمی‌شود.","example":"کلاس دو نماینده انتخاب می‌کند؛ یعنی وظیفهٔ نمایندگی را به اشخاص می‌سپارد. این نمونهٔ نمایندگی است. اگر بعد همهٔ کلاس طبق قواعد توافق‌شده دربارهٔ مقصد گردش رأی بدهند، مستقیماً دربارهٔ یک موضوع تصمیم گرفته‌اند. در دولت، قواعد این روش‌ها دقیق‌تر و قانونی‌اند.","remember":["انتخاب اشخاص با رأی‌گیری دربارهٔ موضوع متفاوت است.","نمایندگی، کار مداوم مجلس را ممکن می‌کند.","روش‌های مستقیم، شرایط و صلاحیت‌های مشخص خود را دارند."],"summary":"مستقیم: خودت دربارهٔ موضوع رأی می‌دهی. نمایندگی: نماینده انتخاب می‌کنی تا تصمیم سیاسی بگیرد.","mistake":"هر خواسته‌ای با یک نظرسنجی اینترنتی به تصمیم الزام‌آور تبدیل نمی‌شود. صلاحیت نهاد و روش قانونی تعیین‌کننده‌اند.","terms":[["Repräsentation","نمایندگی سیاسی توسط اشخاص منتخب."],["Mandat","مقام یا مسئولیت نمایندگیِ انتخاب‌شده."],["Parlament","مجلس منتخب که از جمله قوانین را بررسی و تصویب می‌کند."],["Sachabstimmung","رأی‌گیری دربارهٔ یک موضوع سیاسی مشخص."],["Bürgerbegehren","فرآیند درخواست رأی‌گیری دربارهٔ موضوع محلی."],["Volksentscheid","تصمیم مستقیم رأی‌دهندگان دربارهٔ موضوعی طبق قانون مربوط."]],"q":"کدام وضعیت نمونهٔ دموکراسی نمایندگی است؟","options":["رأی‌دهندگان مستقیماً دربارهٔ یک پیشنهاد تصمیم می‌گیرند.","رأی‌دهندگان نمایندگان مجلس را انتخاب می‌کنند.","شخصی مقام دولتی را به ارث می‌برد."],"answer":1,"feedback":"نمایندگان انتخاب می‌شوند تا در مجلس تصمیم بگیرند؛ این همان نمایندگی سیاسی است.","sections":[{"title":"نمایندگی؛ انتخاب اشخاص","body":"مجلس به‌طور مداوم موضوع‌های زیادی را بررسی می‌کند و کمیسیون دارد. نمایندگان باید تصمیم‌هایشان را توضیح بدهند و تحت کنترل سیاسی قرار دارند."},{"title":"مستقیم؛ تصمیم دربارهٔ موضوع","body":"در رأی‌گیری مستقیم یک پیشنهاد مشخص مطرح است. قانون مربوط تعیین می‌کند چه کسی رأی می‌دهد، فرآیند چگونه شروع می‌شود و چه اکثریتی لازم است."}]},"source":["Bundeswahlleiterin · Demokratie","https://www.bundeswahlleiterin.de/service/glossar/d/demokratie.html"],"minutes":8,"editorial":true},"pug/gewalt":{"de":{"title":"Gewaltenteilung: drei Aufgaben, gegenseitige Kontrolle","goal":"Du benennst Legislative, Exekutive und Judikative und ordnest Parlament, Verwaltung und Gerichte richtig zu.","definition":"Gewaltenteilung verteilt staatliche Macht auf verschiedene Organe. Sie soll Machtmissbrauch begrenzen und ermöglichen, dass staatliche Entscheidungen kontrolliert werden.","explanation":"Mit Gewalt ist hier staatliche Entscheidungs- und Handlungsmacht gemeint. Die drei Bereiche haben unterschiedliche Kernaufgaben, stehen aber in Beziehung zueinander. In Deutschland gibt es deshalb sowohl Trennung als auch Zusammenarbeit und Kontrolle. Beispielsweise kontrolliert der Bundestag die Bundesregierung; zugleich stützt eine parlamentarische Mehrheit häufig die Regierung. Unabhängige Gerichte prüfen Streitfälle anhand des Rechts.","example":"Ein Gesetz legt Pflichten für eine Genehmigung fest. Eine zuständige Behörde prüft einen Antrag und erlässt einen Bescheid. Die betroffene Person hält die Ablehnung für rechtswidrig und nutzt die vorgesehenen Rechtsbehelfe. Ein Gericht kann die Rechtsfrage überprüfen. So erscheinen Gesetzgebung, Ausführung und Rechtsprechung in einem Ablauf.","remember":["Legislative macht Gesetze.","Exekutive führt Gesetze aus.","Judikative entscheidet Rechtsstreitigkeiten unabhängig."],"summary":"Gewaltenteilung verteilt Aufgaben und schafft Kontrolle. Keine einzelne Stelle soll alle staatlichen Entscheidungen ohne Gegenkontrolle beherrschen.","mistake":"Die Polizei gehört zur Exekutive. Sie ist kein Gericht. Welche Maßnahmen oder Sanktionen eine Behörde selbst vornehmen darf, richtet sich nach den jeweiligen Gesetzen.","terms":[["Legislative","Gesetzgebende Gewalt; auf Bundesebene insbesondere der Bundestag."],["Exekutive","Ausführende Gewalt, unter anderem Regierung und Verwaltung."],["Judikative","Rechtsprechende Gewalt; unabhängige Gerichte."],["Kontrolle","Prüfung, ob Entscheidungen und Handlungen zulässig und begründet sind."],["Verwaltung","Behörden, die öffentliche Aufgaben nach geltendem Recht erfüllen."],["Gewaltenverschränkung","Zusammenwirken der Gewalten bei gleichzeitiger Begrenzung und Kontrolle."]],"q":"Zu welchem Bereich gehört eine kommunale Behörde bei der Bearbeitung eines Antrags?","options":["Legislative","Exekutive","Judikative"],"answer":1,"feedback":"Die Behörde wendet geltendes Recht auf einen konkreten Antrag an. Das ist eine Aufgabe der ausführenden Gewalt.","sections":[{"title":"1 · Legislative","body":"Die gesetzgebende Gewalt berät und beschließt Gesetze. Auf Bundesebene arbeitet der Bundestag dabei je nach Verfahren mit dem Bundesrat zusammen."},{"title":"2 · Exekutive","body":"Regierung und Verwaltung führen staatliche Aufgaben aus. Eine Behörde wendet zum Beispiel ein Gesetz auf einen Antrag an. Sie muss dabei rechtliche Grenzen beachten."},{"title":"3 · Judikative","body":"Gerichte entscheiden über rechtliche Streitfragen und sind bei ihrer Rechtsprechung unabhängig. Sie sollen nicht einfach politische Anweisungen der Regierung umsetzen."}]},"fa":{"title":"تفکیک قوا؛ سه وظیفه و کنترل متقابل","goal":"نام سه قوه را بدانی و مجلس، اداره و دادگاه را به قوهٔ درست نسبت بدهی.","definition":"تفکیک قوا، قدرت دولت را میان نهادهای مختلف تقسیم می‌کند. هدف آن محدودکردن سوءاستفاده از قدرت و ممکن‌کردن کنترل تصمیم‌های دولتی است.","explanation":"واژهٔ Gewalt اینجا به معنای قدرت تصمیم‌گیری و اقدام دولت است. سه قوه وظایف اصلی متفاوت دارند، اما با یکدیگر نیز در ارتباط‌اند. بنابراین در آلمان هم جدایی وجود دارد و هم همکاری و کنترل. برای مثال بوندستاگ دولت فدرال را کنترل می‌کند؛ در عین حال اکثریت مجلس معمولاً از دولت حمایت می‌کند. دادگاه مستقل اختلاف را بر اساس قانون بررسی می‌کند.","example":"یک قانون شرایط صدور مجوز را تعیین می‌کند. ادارهٔ مسئول درخواست را بررسی و تصمیم صادر می‌کند. متقاضی فکر می‌کند رد درخواست قانونی نیست و از روش اعتراضِ پیش‌بینی‌شده استفاده می‌کند. دادگاه می‌تواند مسئلهٔ حقوقی را بررسی کند. اینجا قانون‌گذاری، اجرا و قضاوت را در یک مسیر می‌بینی.","remember":["Legislative قانون‌گذاری می‌کند.","Exekutive قانون را اجرا می‌کند.","Judikative اختلاف حقوقی را مستقل بررسی می‌کند."],"summary":"تفکیک قوا، وظایف را تقسیم و کنترل ایجاد می‌کند؛ یک نهاد نباید بدون نظارت همهٔ قدرت دولت را در دست داشته باشد.","mistake":"پلیس جزو قوهٔ مجریه است و دادگاه نیست. اینکه اداره چه اقدام یا جریمه‌ای می‌تواند انجام دهد، به قانون مربوط بستگی دارد.","terms":[["Legislative","قوهٔ قانون‌گذار؛ در سطح فدرال به‌ویژه بوندستاگ."],["Exekutive","قوهٔ مجریه، شامل دولت و اداره‌ها."],["Judikative","قوهٔ قضاییه؛ دادگاه‌های مستقل."],["Kontrolle","بررسی قانونی‌بودن و دلیل تصمیم یا اقدام."],["Verwaltung","اداره‌هایی که وظایف عمومی را طبق قانون انجام می‌دهند."],["Gewaltenverschränkung","همکاری قوا همراه با محدودیت و کنترل متقابل."]],"q":"ادارهٔ شهر هنگام بررسی یک درخواست جزو کدام قوه عمل می‌کند؟","options":["قانون‌گذار","مجریه","قضاییه"],"answer":1,"feedback":"اداره قانون موجود را روی درخواست مشخص اجرا می‌کند؛ این وظیفهٔ قوهٔ مجریه است.","sections":[{"title":"۱ · Legislative","body":"قوهٔ قانون‌گذار قانون‌ها را بررسی و تصویب می‌کند. در سطح فدرال، بوندستاگ بسته به فرآیند با بوندسرات همکاری دارد."},{"title":"۲ · Exekutive","body":"دولت و اداره‌ها وظایف دولتی را اجرا می‌کنند. مثلاً اداره قانونی را روی یک درخواست اعمال می‌کند و باید محدودیت‌های قانونی را رعایت کند."},{"title":"۳ · Judikative","body":"دادگاه‌ها دربارهٔ اختلاف حقوقی تصمیم می‌گیرند و در قضاوت مستقل‌اند. وظیفهٔ آن‌ها صرفاً اجرای دستور سیاسی دولت نیست."}]},"source":["Deutscher Bundestag · Prinzip der Gewaltenteilung","https://www.bundestag.de/parlament/aufgaben/rechtsgrundlagen/gewaltenteilung-246408"],"minutes":8,"editorial":true},"pug/bericht":{"de":{"title":"Ausbildungsnachweis: Lernen nachvollziehbar festhalten","goal":"Du schreibst einen sachlichen Ausbildungsnachweis und erklärst seine Bedeutung für Ausbildung und Prüfung.","definition":"Der Ausbildungsnachweis dokumentiert die Inhalte deiner Berufsausbildung. Er macht sichtbar, welche Tätigkeiten, Unterweisungen und Unterrichtsinhalte du bearbeitet hast.","explanation":"Du führst den Nachweis regelmäßig in der vorgesehenen schriftlichen oder elektronischen Form. Er hilft dir und dem Ausbildungsbetrieb, den Lernfortschritt mit dem Ausbildungsplan zu vergleichen. § 13 BBiG nennt das Führen als Pflicht der Auszubildenden. § 14 verpflichtet den Ausbildungsbetrieb, die Nachweise regelmäßig durchzusehen und Gelegenheit zum Führen am Arbeitsplatz zu geben. Die ordnungsgemäße Führung ist auch für die Zulassung zur Abschlussprüfung wichtig.","example":"Beispiel für einen Eintrag: „Netzwerkinfrastruktur: sechs Patchpanel-Ports nach Plan beschriftet, Verbindungen dokumentiert und Messergebnis mit dem Ausbilder besprochen; ungefähr drei Stunden.“ Der Eintrag sagt, was du getan hast und womit du dich fachlich beschäftigt hast. Er enthält keine Passwörter oder vertraulichen Kundendaten.","remember":["Regelmäßig und wahrheitsgemäß dokumentieren.","Betriebliche Tätigkeiten und Berufsschulinhalte berücksichtigen.","Vorgaben von Ausbildungsbetrieb und zuständiger Kammer beachten."],"summary":"Ein guter Ausbildungsnachweis ist konkret, fachlich und regelmäßig geführt. Er zeigt die tatsächlich bearbeiteten Ausbildungsinhalte.","mistake":"Nicht überall ist dieselbe Papierunterschrift vorgeschrieben. Bei elektronischen Verfahren kann die Bestätigung anders erfolgen; die Vorgaben der zuständigen Stelle sind maßgeblich.","terms":[["Ausbildungsnachweis","Dokumentation der bearbeiteten Ausbildungsinhalte."],["Berichtsheft","Gebräuchliche Bezeichnung für den Ausbildungsnachweis."],["Unterweisung","Geplante Erklärung oder Anleitung zu einer beruflichen Aufgabe."],["Ausbildungsplan","Plan der zeitlichen und fachlichen Ausbildungsinhalte."],["Elektronischer Nachweis","Digital geführte Dokumentation mit vorgesehenem Bestätigungsweg."],["Zulassung","Bestätigung, dass die Voraussetzungen für eine Prüfung erfüllt sind."]],"q":"Welcher Eintrag eignet sich am besten für den Ausbildungsnachweis?","options":["War heute irgendwie beschäftigt.","Drei Stunden Patchpanel-Ports beschriftet und die Verbindungen nach Plan dokumentiert.","Alle geheimen Zugangsdaten des Kunden."],"answer":1,"feedback":"Der zweite Eintrag nennt eine konkrete fachliche Tätigkeit und ihren Umfang, ohne vertrauliche Daten preiszugeben.","sections":[{"title":"1 · Inhalt sammeln","body":"Notiere kurz, welche Aufgaben und Unterrichtsthemen tatsächlich vorkamen. Halte wichtige neue Kenntnisse fest. Vertrauliche Informationen gehören nicht in den Nachweis."},{"title":"2 · Sachlich formulieren","body":"Beschreibe die Tätigkeit mit einem passenden Verb: eingerichtet, verglichen, dokumentiert oder getestet. Ergänze den zeitlichen Umfang, wenn deine Vorlage ihn verlangt."},{"title":"3 · Prüfen und bestätigen lassen","body":"Trage den Zeitraum richtig ein und lasse den Nachweis regelmäßig nach dem vorgesehenen Verfahren kontrollieren. Fehlende Inhalte klärst du rechtzeitig mit der ausbildenden Person."}]},"fa":{"title":"گزارش آموزش؛ ثبت قابل‌پیگیری یادگیری","goal":"یک گزارش آموزشی روشن بنویسی و اهمیت آن برای آموزش و امتحان را توضیح بدهی.","definition":"Ausbildungsnachweis محتوای آموزش حرفه‌ای تو را ثبت می‌کند. نشان می‌دهد چه کارها، آموزش‌های عملی و موضوع‌های مدرسه را انجام داده‌ای.","explanation":"گزارش را به‌طور منظم، در قالب کتبی یا الکترونیکیِ تعیین‌شده ثبت می‌کنی. این مدرک به تو و شرکت کمک می‌کند پیشرفت را با برنامهٔ آموزش مقایسه کنید. مادهٔ ۱۳ BBiG ثبت آن را از وظایف کارآموز می‌داند. مادهٔ ۱۴ شرکت را موظف می‌کند گزارش‌ها را منظم بررسی کند و در محل آموزش برای نوشتن آن فرصت بدهد. ثبت درست گزارش برای پذیرش در امتحان نهایی نیز اهمیت دارد.","example":"نمونهٔ یک نوشته: «زیرساخت شبکه: شش پورت پچ‌پنل را طبق نقشه برچسب زدم، ارتباط‌ها را مستند کردم و نتیجهٔ اندازه‌گیری را با مربی بررسی کردم؛ حدود سه ساعت.» این نوشته کار و موضوع فنی را مشخص می‌کند و رمز یا اطلاعات محرمانهٔ مشتری ندارد.","remember":["گزارش را منظم و مطابق واقعیت بنویس.","کارهای شرکت و موضوع‌های مدرسه را در نظر بگیر.","قواعد شرکت و اتاق مسئول آموزش را رعایت کن."],"summary":"گزارش خوب، مشخص، فنی و منظم است و محتوای واقعی آموزش را نشان می‌دهد.","mistake":"همه‌جا یک نوع امضای کاغذی لازم نیست. در روش الکترونیکی تأیید می‌تواند شکل دیگری داشته باشد؛ دستورالعمل مرجع مسئول تعیین‌کننده است.","terms":[["Ausbildungsnachweis","ثبت موضوع‌ها و کارهای انجام‌شده در آموزش حرفه‌ای."],["Berichtsheft","نام رایج دفتر یا سامانهٔ گزارش آموزش."],["Unterweisung","توضیح یا راهنمایی برنامه‌ریزی‌شده برای یک کار حرفه‌ای."],["Ausbildungsplan","برنامهٔ زمانی و محتوایی آموزش."],["Elektronischer Nachweis","گزارش دیجیتال با روش تأیید مشخص."],["Zulassung","تأیید اینکه شرایط لازم برای شرکت در امتحان فراهم است."]],"q":"کدام نوشته برای گزارش آموزش مناسب‌تر است؟","options":["امروز یک‌جوری مشغول بودم.","سه ساعت پورت‌های پچ‌پنل را برچسب زدم و ارتباط‌ها را طبق نقشه مستند کردم.","همهٔ رمزهای محرمانهٔ مشتری."],"answer":1,"feedback":"گزینهٔ دوم، کار تخصصی و مدت آن را روشن می‌کند و اطلاعات محرمانه را افشا نمی‌کند.","sections":[{"title":"۱ · جمع‌آوری محتوا","body":"خلاصه یادداشت کن چه کارها و موضوع‌های درسی واقعاً انجام شده‌اند. دانش تازهٔ مهم را ثبت کن. اطلاعات محرمانه نباید وارد گزارش شود."},{"title":"۲ · نوشتن روشن","body":"کار را با فعل مناسب مثل تنظیم کردم، مقایسه کردم، مستند کردم یا آزمایش کردم توضیح بده. اگر فرم مدت می‌خواهد، زمان تقریبی را هم اضافه کن."},{"title":"۳ · بررسی و تأیید","body":"بازهٔ زمانی را درست بنویس و گزارش را طبق روش تعیین‌شده منظم برای کنترل ارائه کن. قسمت‌های ناقص را زود با مربی روشن کن."}]},"source":["BBiG · §13, §14 und Ausbildungsnachweis","https://www.gesetze-im-internet.de/bbig_2005/__13.html"],"minutes":9,"editorial":true},"englisch/noten":{"de":{"title":"Englischleistungen und KMK-Zertifikat verstehen","goal":"Du unterscheidest schulische Leistungsbewertung und zusätzliche Sprachzertifizierung und planst passende Übungen.","definition":"Die Englischnote bewertet deine Leistungen im Unterricht nach den geltenden schulischen Vorgaben. Das KMK-Fremdsprachenzertifikat ist eine zusätzliche Prüfung für berufsbezogene Sprachkenntnisse.","explanation":"Welche Leistungsnachweise, Gewichtungen und Bewertungsmaßstäbe in deiner Klasse gelten, ergibt sich aus den schulischen Regeln und den verbindlichen Informationen der Lehrkraft. Eine pauschale Regel „drei Teile mit gleichem Gewicht“ lässt sich daraus nicht für alle Klassen ableiten. Für deine Vorbereitung brauchst du deshalb zuerst die konkreten Anforderungen. Teile danach deine Übungszeit nach den Fertigkeiten ein, bei denen du Unterstützung brauchst.","example":"Die Lehrkraft kündigt eine Aufgabe an: eine englische Störungsmeldung lesen und eine kurze Antwort schreiben. Du übst zuerst die wichtige Information herauszufinden, dann eine höfliche Antwort mit nächstem Schritt zu formulieren. Wenn du zusätzlich das KMK-Zertifikat machen möchtest, prüfst du die angebotene Stufe und das Anmeldeverfahren deiner Schule.","remember":["Bewertungskriterien der eigenen Klasse klären.","Sprachfertigkeiten getrennt und kombiniert üben.","KMK-Zertifikat und Zeugnisnote sind unterschiedliche Nachweise."],"summary":"Gute Vorbereitung beginnt mit klaren Anforderungen. Das freiwillige KMK-Zertifikat ergänzt die schulische Sprachbildung.","mistake":"Ein Modell mit drei gleich gewichteten Teilen ist keine allgemeingültige Regel für jede Englischnote. Verwende nur die tatsächlich geltende Bewertungsgrundlage.","terms":[["Assessment","Bewertung einer Leistung anhand festgelegter Kriterien."],["Criteria","Merkmale, nach denen eine Leistung beurteilt wird."],["Reception","Informationen aus gehörten oder gelesenen Texten verstehen."],["Production","Eigene mündliche oder schriftliche Texte erstellen."],["Mediation","Wichtige Inhalte zwischen Sprachen sinngemäß vermitteln."],["Interaction","Mit anderen sprachlich aufeinander bezogen kommunizieren."]],"q":"Was solltest du zuerst klären, wenn du deine Englischnote gezielt verbessern möchtest?","options":["Welche Leistungen und Kriterien in deiner Klasse gelten.","Welche zufällige Gewichtung im Internet steht.","Ob du jede unbekannte Vokabel vermeiden kannst."],"answer":0,"feedback":"Nur mit den tatsächlich geltenden Kriterien kannst du passende Fertigkeiten und Aufgaben gezielt üben.","sections":[{"title":"Die Fertigkeiten kennenlernen","body":"Rezeption umfasst Hör- und Leseverstehen. Produktion bedeutet selbst sprechen oder schreiben. Mediation überträgt wichtige Inhalte sinngemäß zwischen Sprachen. Interaktion ist das gemeinsame Gespräch oder der schriftliche Austausch."},{"title":"Zusatzqualifikation KMK","body":"Die KMK-Prüfung ist berufsbezogen und freiwillig. Angeboten werden unterschiedliche GER-Niveaus. Welche Stufen und Termine deine Schule anbietet, erfährst du dort; ein alter Unterrichtstermin ist keine aktuelle Prüfungsankündigung."}]},"fa":{"title":"نمرهٔ انگلیسی و گواهی KMK را بفهم","goal":"ارزیابی مدرسه را از گواهی زبانِ اضافه تشخیص بدهی و تمرین مناسب برنامه‌ریزی کنی.","definition":"نمرهٔ انگلیسی عملکرد تو را طبق قواعد مدرسه ارزیابی می‌کند. KMK-Fremdsprachenzertifikat امتحان اضافه‌ای برای اثبات توانایی زبان در محیط حرفه‌ای است.","explanation":"نوع نمره‌ها، وزن آن‌ها و معیار ارزیابی صنف تو را قواعد مدرسه و اطلاعات معتبر معلم مشخص می‌کند. قانون عمومی «سه بخش با وزن مساوی» برای همهٔ صنف‌ها درست نیست. بنابراین اول شرایط واقعی خودت را روشن کن؛ سپس زمان تمرین را با توجه به مهارتی تقسیم کن که بیشتر به آن نیاز داری.","example":"معلم می‌گوید باید یک گزارش خرابی انگلیسی را بخوانی و جواب کوتاه بنویسی. اول تمرین می‌کنی اطلاعات مهم را پیدا کنی؛ بعد جواب مؤدبانه با قدم بعدی می‌نویسی. اگر گواهی KMK هم می‌خواهی، سطح‌های ارائه‌شده و روش ثبت‌نام مدرسه‌ات را جداگانه بررسی می‌کنی.","remember":["معیارهای واقعی ارزیابی صنفت را روشن کن.","مهارت‌های زبان را هم جدا و هم ترکیبی تمرین کن.","گواهی KMK و نمرهٔ کارنامه دو مدرک متفاوت‌اند."],"summary":"آمادگی خوب از شناخت شرایط شروع می‌شود. گواهی داوطلبانهٔ KMK مکمل آموزش زبان مدرسه است.","mistake":"سه بخشِ هم‌وزن قانون عمومی همهٔ نمره‌های انگلیسی نیست. فقط از معیار معتبرِ مربوط به صنف خودت استفاده کن.","terms":[["Assessment","ارزیابی عملکرد بر اساس معیار مشخص."],["Criteria","معیارهایی که با آن‌ها عملکرد سنجیده می‌شود."],["Reception","فهم اطلاعات در متن خوانده‌شده یا شنیده‌شده."],["Production","ساختن متن گفتاری یا نوشتاری خودت."],["Mediation","انتقال معنای مهم میان دو زبان."],["Interaction","ارتباط زبانیِ رفت‌وبرگشتی با دیگران."]],"q":"برای بهترکردن هدفمند نمرهٔ انگلیسی، اول چه چیزی را باید روشن کنی؟","options":["کدام عملکردها و معیارها در صنفت حساب می‌شوند.","یک وزن‌دهی تصادفی در اینترنت چیست.","چطور از همهٔ واژه‌های ناشناس دوری کنی."],"answer":0,"feedback":"وقتی معیارهای واقعی را بدانی، می‌توانی مهارت و نوع سؤال مناسب را هدفمند تمرین کنی.","sections":[{"title":"مهارت‌ها را بشناس","body":"Reception شامل درک شنیداری و خواندن است. Production یعنی خودت صحبت کنی یا بنویسی. Mediation یعنی معنای مهم را میان زبان‌ها منتقل کنی. Interaction یعنی گفت‌وگو یا تبادل نوشتاری دوطرفه."},{"title":"گواهی تکمیلی KMK","body":"امتحان KMK مرتبط با شغل و داوطلبانه است و سطح‌های مختلف GER دارد. سطح و زمانِ ارائه‌شده را از مدرسه بپرس؛ تاریخ قدیمی یک جزوه، اعلان فعلی امتحان نیست."}]},"source":["KMK · Berufsbezogene Fremdsprachenkompetenzen","https://www.kmk.org/bildungsministerkonferenz/vertiefende-bildungsinhalte/berufliche-bildung/kmk-fremdsprachenzertifikat.html"],"minutes":8,"editorial":true},"englisch/machine":{"de":{"title":"Machine code, assembly und high-level language","goal":"Du erklärst die drei Sprachebenen mit englischen Fachwörtern und beschreibst ihren Zusammenhang.","definition":"Programmiersprachen beschreiben Anweisungen für die Verarbeitung von Daten. Machine code, assembly language und high-level language liegen dabei unterschiedlich nah an der Hardware.","explanation":"Ein Prozessor führt die Maschinenbefehle seiner Architektur aus. Menschen schreiben Programme meist in lesbarerem Quelltext. Übersetzungs- und Laufzeitwerkzeuge verbinden diesen Text mit der Ausführung auf dem Rechner. Für englische IT-Texte ist wichtig, Ebene und Werkzeug zu unterscheiden: Eine Sprache beschreibt etwas; ein Compiler oder Interpreter ist ein Programm, das bei der Umsetzung hilft.","example":"Im Satz „The compiler translates the source code“ ist compiler das Werkzeug, translates die Tätigkeit und source code die Eingabe. Ein C-Programm kann über mehrere Übersetzungsschritte zu einem ausführbaren Programm werden. Bei CPython wird Python-Quelltext zunächst in Bytecode übersetzt und durch eine virtuelle Maschine ausgeführt.","remember":["Machine code besteht aus Befehlen für eine bestimmte Prozessorarchitektur.","Assembly benutzt symbolische Befehlsnamen.","High-level languages ermöglichen abstraktere Programmbeschreibungen."],"summary":"Je höher die Sprachebene, desto weniger Hardwaredetails stehen gewöhnlich direkt im Quelltext. Ausführung benötigt passende Übersetzungs- und Laufzeitwerkzeuge.","mistake":"„Interpreter bedeutet, dass niemals übersetzt wird“ ist falsch. Übersetzung und Interpretation können in einer Implementierung kombiniert werden.","terms":[["Machine code","Binäre Darstellung von Prozessorbefehlen."],["Assembly language","Hardwarenahe Sprache mit symbolischen Befehlsnamen."],["High-level language","Sprache mit abstrakteren Mitteln wie Funktionen und Datenstrukturen."],["Source code","Von Menschen geschriebener Programmtext."],["Instruction set","Menge der Maschinenbefehle einer Prozessorarchitektur."],["Bytecode","Zwischendarstellung, die zum Beispiel eine virtuelle Maschine verarbeitet."]],"q":"Welche Aussage beschreibt assembly language am besten?","options":["Eine rein grafische Darstellung eines Netzwerks.","Eine hardwarenahe Sprache mit symbolischen Befehlsnamen.","Die natürliche Alltagssprache des Benutzers."],"answer":1,"feedback":"Assembly verwendet kurze Symbole für hardwarenahe Anweisungen und hängt von der Zielarchitektur ab.","sections":[{"title":"1 · Machine code","body":"Die CPU verarbeitet codierte Maschinenbefehle. Welche Befehle verfügbar sind und wie sie aussehen, hängt von der Prozessorarchitektur ab."},{"title":"2 · Assembly language","body":"Symbolische Namen wie MOV machen Befehle für Menschen lesbarer. Ein Assembler übersetzt sie in Objektcode. Nicht jede Assemblerzeile entspricht zwingend genau einer CPU-Anweisung, etwa bei Pseudobefehlen."},{"title":"3 · High-level language","body":"Sprachen wie C oder Python bieten Variablen, Funktionen und weitere Abstraktionen. Wie das Programm ausgeführt wird, hängt von Sprache, Implementierung und Werkzeugen ab."}]},"fa":{"title":"کد ماشین، اسمبلی و زبان سطح بالا","goal":"سه سطح زبان برنامه‌نویسی را با واژه‌های انگلیسی توضیح بدهی و رابطه‌شان را بفهمی.","definition":"زبان برنامه‌نویسی دستورهای پردازش داده را توصیف می‌کند. Machine code، Assembly language و High-level language از نظر نزدیکی به سخت‌افزار در سطح‌های متفاوتی قرار دارند.","explanation":"پردازنده دستورهای ماشینِ معماری خودش را اجرا می‌کند. انسان معمولاً برنامه را در کد منبعِ خواناتر می‌نویسد. ابزار ترجمه و محیط اجرا، این متن را به اجرای برنامه روی کامپیوتر وصل می‌کنند. در متن انگلیسی، سطح زبان را از ابزار تشخیص بده: زبان برای بیان برنامه است؛ کامپایلر یا مفسر برنامه‌ای است که در تبدیل یا اجرای آن کمک می‌کند.","example":"در جملهٔ «The compiler translates the source code»، کلمهٔ compiler ابزار، translates کار و source code ورودی را بیان می‌کند. برنامهٔ C می‌تواند با چند مرحله ترجمه به برنامهٔ اجرایی تبدیل شود. در CPython، کد پایتون ابتدا به Bytecode ترجمه و سپس با ماشین مجازی اجرا می‌شود.","remember":["Machine code نمایش دستورهای یک معماری پردازنده است.","Assembly از نام‌های نمادی برای دستورها استفاده می‌کند.","زبان سطح بالا بیان انتزاعی‌تر برنامه را ممکن می‌کند."],"summary":"هرچه سطح زبان بالاتر باشد، معمولاً جزئیات سخت‌افزار کمتر در کد دیده می‌شوند. اجرای آن به ابزار ترجمه و محیط اجرای مناسب نیاز دارد.","mistake":"این تصور که «مفسر یعنی هیچ ترجمه‌ای انجام نمی‌شود» درست نیست. یک پیاده‌سازی می‌تواند ترجمه و تفسیر را ترکیب کند.","terms":[["Machine code","نمایش دودویی دستورهای پردازنده."],["Assembly language","زبان نزدیک به سخت‌افزار با نام‌های نمادی دستورها."],["High-level language","زبان با امکانات انتزاعی‌تر مانند تابع و ساختار داده."],["Source code","متن برنامه که انسان می‌نویسد."],["Instruction set","مجموعهٔ دستورهای ماشین یک معماری پردازنده."],["Bytecode","نمایش میانی که مثلاً ماشین مجازی پردازش می‌کند."]],"q":"کدام توضیح برای Assembly language درست‌تر است؟","options":["نقشهٔ گرافیکی شبکه.","زبان نزدیک به سخت‌افزار با نام‌های نمادی دستورها.","زبان عادی روزمرهٔ کاربر."],"answer":1,"feedback":"اسمبلی برای دستورهای نزدیک به سخت‌افزار از نام‌های کوتاه استفاده می‌کند و به معماری مقصد وابسته است.","sections":[{"title":"۱ · Machine code","body":"CPU دستورهای ماشینِ کدگذاری‌شده را پردازش می‌کند. دستورهای موجود و شکل آن‌ها به معماری پردازنده بستگی دارند."},{"title":"۲ · Assembly language","body":"نام‌هایی مثل MOV خواندن دستور را برای انسان آسان‌تر می‌کنند. Assembler آن را به کد شیء تبدیل می‌کند. هر خط اسمبلی الزاماً یک دستور CPU نیست؛ مثلاً شبه‌دستورها ممکن است متفاوت باشند."},{"title":"۳ · High-level language","body":"زبان‌هایی مثل C و Python متغیر، تابع و امکانات انتزاعی دارند. شیوهٔ اجرای برنامه به زبان، پیاده‌سازی و ابزارها بستگی دارد."}]},"source":["Python · Glossary und Bytecode","https://docs.python.org/3/glossary.html"],"minutes":8,"editorial":true},"englisch/vocab":{"de":{"title":"Assemble, compile, link und execute","goal":"Du ordnest englische Verben und Werkzeuge den typischen Schritten vom Quelltext zur Ausführung zu.","definition":"Die Wörter assemble, compile, link und execute beschreiben unterschiedliche Arbeitsschritte bei der Erstellung und Ausführung von Software. Die genaue Werkzeugkette hängt von Sprache und Plattform ab.","explanation":"Bei einer typischen C-Werkzeugkette wird lesbarer Quelltext schrittweise verarbeitet. Nicht jeder Schritt muss als eigene Datei sichtbar bleiben: Werkzeuge können Zwischenergebnisse direkt weitergeben. Die Begriffe helfen dir, englische Fehlermeldungen einzuordnen. Ein syntax error deutet auf ein Problem beim Verarbeiten des Quelltexts hin; eine fehlende Bibliotheksfunktion kann beim Linken auffallen. Ein fertiges Programm kann später außerdem einen runtime error erzeugen.","example":"Beispiel: Eine Datei main.c nutzt eine Funktion aus einer Bibliothek. Der Compiler verarbeitet den C-Code, der Assembler erzeugt Objektcode, und der Linker verbindet diesen mit den benötigten Teilen der Bibliothek. Fehlt die Funktion, kann „undefined reference“ beim Linken erscheinen. Die Ursache ist dann nicht automatisch ein Tippfehler in der Assemblersyntax.","remember":["Compile und execute beschreiben unterschiedliche Tätigkeiten.","Object files können noch nicht allein lauffähig sein.","Linking verbindet benötigte Programmteile."],"summary":"Die typische Reihenfolge hilft beim Verständnis: source code verarbeiten, übersetzen, Objektcode erzeugen, verbinden und ausführen.","mistake":"Eine Datei wird nicht allein durch Umbenennen in .exe ausführbar. Format, Inhalt, Zielsystem und notwendige Laufzeitumgebung müssen passen.","terms":[["To compile","Quelltext in eine andere Darstellung übersetzen."],["To assemble","Assemblertext in Objekt- beziehungsweise Maschinencode umsetzen."],["To link","Objektdateien und benötigte Bibliotheksteile verbinden."],["Executable","Programmdatei, die vom vorgesehenen System gestartet werden kann."],["Object file","Zwischenergebnis mit Programmcode und Informationen zum weiteren Verbinden."],["Runtime error","Fehler, der während der Ausführung auftritt."]],"q":"Welches Werkzeug verbindet normalerweise Objektdateien zu einem Programm?","options":["Der Linker.","Der Texteditor.","Der Dateimanager durch Umbenennen."],"answer":0,"feedback":"Der Linker verbindet Objektdateien und benötigte Bibliotheksteile. Ein Dateiname allein erledigt diese Arbeit nicht.","sections":[{"title":"Compile und assemble","body":"Der Compiler übersetzt Quelltext, beispielsweise in Assemblertext. Der Assembler verarbeitet symbolische Maschinenanweisungen zu Objektcode. Der genaue Übergang hängt von der Werkzeugkette ab."},{"title":"Link und execute","body":"Der Linker löst Verweise zwischen Programmteilen auf und erzeugt beispielsweise ein ausführbares Programm. Beim Ausführen lädt das Betriebssystem das passende Programm; benötigte Laufzeitkomponenten müssen vorhanden sein."}]},"fa":{"title":"Assemble، Compile، Link و Execute","goal":"فعل‌ها و ابزارهای انگلیسی را به مراحل ساخت و اجرای برنامه نسبت بدهی.","definition":"واژه‌های Assemble، Compile، Link و Execute کارهای متفاوتی را در ساخت و اجرای نرم‌افزار بیان می‌کنند. زنجیرهٔ دقیق ابزارها به زبان و سیستم مقصد بستگی دارد.","explanation":"در زنجیرهٔ معمول زبان C، کد خوانا مرحله‌به‌مرحله پردازش می‌شود. لازم نیست نتیجهٔ هر مرحله در یک فایل جدا دیده شود؛ ابزار می‌تواند خروجی را مستقیم به مرحلهٔ بعد بدهد. این واژه‌ها به فهم پیام خطای انگلیسی کمک می‌کنند. Syntax error معمولاً به پردازش متن کد مربوط است؛ نبود یک تابع کتابخانه می‌تواند در مرحلهٔ Link مشخص شود. برنامهٔ ساخته‌شده هم ممکن است هنگام اجرا Runtime error بدهد.","example":"مثال: فایل main.c تابعی از یک کتابخانه را استفاده می‌کند. کامپایلر کد C را پردازش می‌کند، اسمبلر کد شیء می‌سازد و لینکِر آن را با قسمت‌های لازم کتابخانه متصل می‌کند. اگر تابع پیدا نشود، ممکن است هنگام Link پیام undefined reference بیاید. این پیام الزاماً خطای نوشتن یک دستور اسمبلی نیست.","remember":["Compile و Execute دو کار متفاوت‌اند.","فایل شیء ممکن است به‌تنهایی قابل اجرا نباشد.","Linking قسمت‌های لازم برنامه را به هم وصل می‌کند."],"summary":"ترتیب معمول برای فهم واژه‌ها: پردازش کد منبع، ترجمه، ساخت کد شیء، اتصال بخش‌ها و اجرای برنامه.","mistake":"با تغییر نام فایل به .exe، آن فایل واقعاً اجرایی نمی‌شود. قالب، محتوا، سیستم مقصد و محیط اجرای لازم باید مناسب باشند.","terms":[["To compile","ترجمهٔ کد منبع به نمایش دیگر."],["To assemble","تبدیل متن اسمبلی به کد شیء یا کد ماشین."],["To link","متصل‌کردن فایل‌های شیء و بخش‌های لازم کتابخانه."],["Executable","فایل برنامه که سیستم تعیین‌شده می‌تواند آن را اجرا کند."],["Object file","خروجی میانی دارای کد و اطلاعات لازم برای اتصال بعدی."],["Runtime error","خطایی که هنگام اجرای برنامه رخ می‌دهد."]],"q":"کدام ابزار معمولاً فایل‌های شیء را به یک برنامه متصل می‌کند؟","options":["Linker.","ویرایشگر متن.","مدیریت فایل با تغییر نام."],"answer":0,"feedback":"Linker فایل‌های شیء و بخش‌های لازم کتابخانه را متصل می‌کند؛ نام فایل به‌تنهایی این کار را انجام نمی‌دهد.","sections":[{"title":"Compile و Assemble","body":"کامپایلر کد منبع را مثلاً به متن اسمبلی ترجمه می‌کند. اسمبلر دستورهای نمادی ماشین را به کد شیء تبدیل می‌کند. جزئیات این مسیر به زنجیرهٔ ابزارها بستگی دارد."},{"title":"Link و Execute","body":"لینکر ارجاع میان بخش‌های برنامه را برقرار می‌کند و مثلاً برنامهٔ اجرایی می‌سازد. هنگام اجرا، سیستم‌عامل برنامهٔ مناسب را بار می‌کند؛ اجزای لازم محیط اجرا هم باید موجود باشند."}]},"source":["GCC · Overall Options","https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html"],"minutes":8,"editorial":true},"englisch/themen":{"de":{"title":"Englische IT-Texte hören, lesen und zusammenfassen","goal":"Du findest Kerninformationen in einem englischen IT-Text und schreibst eine kurze, sachliche Zusammenfassung.","definition":"Hör- und Leseverstehen bedeutet, Informationen aus einem Text passend zur Aufgabe zu erfassen. Eine Zusammenfassung gibt die wesentlichen Aussagen kurz in eigenen Worten wieder.","explanation":"Du musst nicht jedes Wort übersetzen, um einen Text richtig zu verstehen. Entscheidend sind die Fragestellung und die Textstruktur. Ein Titel zeigt oft das Thema. Signalwörter wie because, however oder therefore zeigen Gründe, Gegensätze und Folgen. Wenn eine Information im Text nicht steht, darf sie nicht als gesicherte Tatsache in deiner Antwort erscheinen. Besonders bei IT-Nachrichten müssen eine berichtete Behauptung und eine bestätigte Beobachtung auseinandergehalten werden.","example":"Übungstext: „The company paused the software update because some users reported connection failures. A corrected version is being tested.“\nKernaussage: Das Unternehmen hat das Update wegen gemeldeter Verbindungsprobleme angehalten; eine korrigierte Version wird getestet.\nNicht ableitbar: wann die neue Version erscheint oder ob alle Nutzer betroffen sind. Diese Angaben stehen nicht im Text.","remember":["Vor dem Lesen oder Hören die Aufgabe ansehen.","Wichtige Informationen mit Textstellen begründen.","Zusammenfassen bedeutet auswählen und in eigenen Worten formulieren."],"summary":"Arbeite vom Überblick zu den Details und kontrolliere am Ende, ob deine Antwort wirklich zur Frage passt.","mistake":"„Some users reported“ bedeutet nicht „alle Nutzer sind betroffen“. Wörter für Umfang und Sicherheit einer Aussage verändern die Bedeutung.","terms":[["Main idea","Zentrale Aussage eines Textes."],["Evidence","Information, die eine Aussage stützt."],["Because","Signalwort für einen Grund: weil."],["However","Signalwort für einen Gegensatz: jedoch."],["Therefore","Signalwort für eine Folge: deshalb."],["Summary","Kurze Wiedergabe der wichtigsten Aussagen in eigenen Worten."]],"q":"Was lässt sich aus „some users reported connection failures“ sicher wiedergeben?","options":["Alle Nutzer haben dauerhaft keinen Internetzugang.","Einige Nutzer meldeten Verbindungsfehler.","Die korrigierte Version erscheint morgen."],"answer":1,"feedback":"Some users bedeutet einige Nutzer. Die Aussage berichtet Meldungen; sie nennt weder alle Nutzer noch einen Veröffentlichungstermin.","sections":[{"title":"1 · Überblick gewinnen","body":"Lies zuerst die Aufgabe und den Titel. Beim ersten Hören oder Lesen suche Thema, Beteiligte und grobe Aussage. Notiere wenige Schlüsselwörter statt ganzer Übersetzungen."},{"title":"2 · Details gezielt finden","body":"Suche nach der Information, die eine konkrete Frage beantwortet. Achte auf Zahlen, Verneinungen und Signalwörter. Höre oder lies die entscheidende Stelle erneut."},{"title":"3 · Antwort prüfen","body":"Formuliere kurz und sachlich. Vergleiche deine Antwort mit dem Text: Ist sie vollständig, ist sie zu weitgehend oder enthält sie eine Vermutung? Korrigiere unbelegte Ergänzungen."}]},"fa":{"title":"شنیدن، خواندن و خلاصه‌کردن متن IT انگلیسی","goal":"اطلاعات اصلی متن IT انگلیسی را پیدا کنی و خلاصه‌ای کوتاه و دقیق بنویسی.","definition":"درک شنیداری و خواندن یعنی اطلاعات متن را متناسب با سؤال بفهمی. خلاصه، نکته‌های اصلی را کوتاه و با جمله‌های خودت بیان می‌کند.","explanation":"برای فهم متن لازم نیست تک‌تک واژه‌ها را ترجمه کنی. سؤال و ساختار متن تعیین‌کننده‌اند. عنوان معمولاً موضوع را نشان می‌دهد. واژه‌هایی مثل Because، However و Therefore علت، تضاد و نتیجه را مشخص می‌کنند. اطلاعاتی که در متن نیست نباید به‌عنوان واقعیت قطعی وارد پاسخ شود. به‌ویژه در خبر IT، گزارش یک ادعا با مشاهدهٔ تأییدشده یکسان نیست.","example":"متن تمرینی: «The company paused the software update because some users reported connection failures. A corrected version is being tested.»\nخلاصه: شرکت به‌دلیل گزارش مشکل اتصال از طرف بعضی کاربران، انتشار به‌روزرسانی را متوقف کرده و نسخهٔ اصلاح‌شده در حال آزمایش است.\nاز متن نمی‌توان زمان انتشار نسخهٔ تازه یا درگیرشدن همهٔ کاربران را نتیجه گرفت.","remember":["قبل از شنیدن یا خواندن، سؤال را ببین.","اطلاعات مهم را با بخش مربوط متن پشتیبانی کن.","خلاصه یعنی انتخاب نکته‌های اصلی و نوشتن با زبان خودت."],"summary":"از دید کلی به جزئیات برو و در آخر مطمئن شو پاسخت دقیقاً به سؤال مربوط است.","mistake":"عبارت Some users reported به معنی «همهٔ کاربران دچار مشکل‌اند» نیست. واژه‌های مقدار و میزان قطعیت، معنی جمله را عوض می‌کنند.","terms":[["Main idea","پیام یا نکتهٔ اصلی متن."],["Evidence","اطلاعاتی که از یک ادعا پشتیبانی می‌کند."],["Because","واژهٔ نشان‌دهندهٔ علت؛ چون یا زیرا."],["However","واژهٔ نشان‌دهندهٔ تضاد؛ بااین‌حال."],["Therefore","واژهٔ نشان‌دهندهٔ نتیجه؛ بنابراین."],["Summary","بیان کوتاه نکته‌های اصلی با زبان خودت."]],"q":"از جملهٔ Some users reported connection failures چه چیزی را می‌توان دقیق بیان کرد؟","options":["همهٔ کاربران برای همیشه اینترنت ندارند.","برخی کاربران خطای اتصال گزارش کردند.","نسخهٔ اصلاح‌شده فردا منتشر می‌شود."],"answer":1,"feedback":"Some users یعنی برخی کاربران. جمله گزارش مشکل را می‌گوید و نه درگیرشدن همهٔ کاربران یا زمان انتشار را.","sections":[{"title":"۱ · دید کلی بگیر","body":"اول سؤال و عنوان را بخوان. در دور اول موضوع، افراد یا نهادهای درگیر و پیام کلی را پیدا کن. به‌جای ترجمهٔ کامل، چند واژهٔ کلیدی یادداشت کن."},{"title":"۲ · جزئیات را هدفمند پیدا کن","body":"بخش پاسخ‌دهنده به سؤال را پیدا کن. به عددها، منفی‌بودن جمله و واژه‌های ربط دقت کن. قسمت تعیین‌کننده را دوباره بخوان یا گوش بده."},{"title":"۳ · پاسخ را کنترل کن","body":"کوتاه و دقیق بنویس. پاسخ را با متن مقایسه کن: کامل است؟ بیش از حد نتیجه گرفته‌ای؟ حدسی اضافه کرده‌ای؟ اطلاعات بدون پشتوانه را اصلاح کن."}]},"source":["KMK · Sprachkompetenzen Rezeption und Produktion","https://www.kmk.org/bildungsministerkonferenz/vertiefende-bildungsinhalte/berufliche-bildung/kmk-fremdsprachenzertifikat.html"],"minutes":8,"editorial":true},"k12-server/serverdienst":{"de":{"title":"Serverdienste planen und bereitstellen","goal":"Du leitest aus einem Kundenbedarf einen prüfbaren Serverdienst ab.","definition":"Ein Serverdienst stellt anderen Geräten eine bestimmte Funktion über ein Netzwerk bereit. Beispiele sind Dateizugriff, Namensauflösung oder eine Webanwendung. Server bezeichnet dabei eine Rolle; mehrere Dienste können auf derselben Hardware laufen.","explanation":"1. Anforderungen erheben: Kläre zuerst Benutzerzahl, Datenmenge, Zugriffszeiten und erlaubte Ausfälle. Beschreibe den Nutzen, beispielsweise gemeinsame Projektdateien. Ohne diese Angaben lässt sich die passende Plattform nicht begründet auswählen.\n\n2. Plattform und Konfiguration wählen: Vergleiche Betriebssystem, Ressourcen, unterstützte Protokolle und Lizenzbedingungen. Plane Dienstkonto, Netzwerkadresse, Freigaben und Firewallregeln. Ein Dienst benötigt nur die Berechtigungen, die seine Aufgabe erfordert.\n\n3. Testen und in Betrieb nehmen: Teste aus Sicht eines berechtigten Clients und zusätzlich mit einem unberechtigten Konto. Prüfe Neustart, Protokollierung und Wiederherstellung. Dokumentiere Zuständigkeit, Konfiguration und Wartungsfenster, damit der Dienst auch nach der Installation betreut werden kann.","sections":[{"title":"1. Anforderungen erheben","body":"Kläre zuerst Benutzerzahl, Datenmenge, Zugriffszeiten und erlaubte Ausfälle. Beschreibe den Nutzen, beispielsweise gemeinsame Projektdateien. Ohne diese Angaben lässt sich die passende Plattform nicht begründet auswählen."},{"title":"2. Plattform und Konfiguration wählen","body":"Vergleiche Betriebssystem, Ressourcen, unterstützte Protokolle und Lizenzbedingungen. Plane Dienstkonto, Netzwerkadresse, Freigaben und Firewallregeln. Ein Dienst benötigt nur die Berechtigungen, die seine Aufgabe erfordert."},{"title":"3. Testen und in Betrieb nehmen","body":"Teste aus Sicht eines berechtigten Clients und zusätzlich mit einem unberechtigten Konto. Prüfe Neustart, Protokollierung und Wiederherstellung. Dokumentiere Zuständigkeit, Konfiguration und Wartungsfenster, damit der Dienst auch nach der Installation betreut werden kann."}],"example":"Ein Büro benötigt gemeinsame Dateien für 25 Personen. Du vereinbarst Gruppenrechte, 2 TB nutzbaren Speicher und tägliche Sicherung. Danach prüfst du, ob ein Teammitglied Dateien bearbeiten kann und ein Gast keinen Zugriff erhält. Erst diese Ergebnisse zeigen, ob der Kundenbedarf erfüllt ist.","mistake":"Eine erfolgreiche Installation beweist noch nicht, dass Rechte, Datensicherung und Clientzugriff richtig funktionieren.","terms":[["Serverdienst","Netzwerkfunktion, die Clients nutzen können."],["Client","Gerät oder Programm, das einen Dienst anfordert."],["Dienstkonto","Identität, unter der ein Dienst ausgeführt wird."],["Wartungsfenster","Vereinbarter Zeitraum für geplante Arbeiten."],["Berechtigung","Erlaubte Aktion auf einer Ressource."],["Funktionstest","Prüfung einer vereinbarten Funktion."]],"q":"Was beschreibt eine prüfbare Anforderung an einen Dateidienst?","options":["Der Server soll modern sein.","25 Benutzer sollen ihre Teamdateien bearbeiten können.","Wir installieren irgendein Betriebssystem."],"answer":1,"feedback":"Benutzerzahl und erlaubte Aktion lassen sich mit Testkonten konkret prüfen.","remember":["Ein Serverdienst wird nach Nutzerbedarf ausgewählt.","Zugriffe mit berechtigten und unberechtigten Konten testen.","Betrieb braucht Verantwortliche, Wartung und Wiederherstellung."],"summary":"Ein Serverdienst ist erst sinnvoll bereitgestellt, wenn seine benötigte Funktion und sein weiterer Betrieb überprüfbar gesichert sind."},"fa":{"title":"برنامه‌ریزی و راه‌اندازی سرویس سرور","goal":"از نیاز مشتری یک سرویس قابل آزمایش طراحی کنی.","definition":"سرویس سرور یک قابلیت مشخص را از طریق شبکه در اختیار دستگاه‌ها می‌گذارد؛ مثل اشتراک فایل، DNS یا برنامهٔ وب. سرور در اینجا یک نقش است و یک دستگاه می‌تواند چند سرویس داشته باشد.","explanation":"۱. نیاز را بفهم: ابتدا تعداد کاربران، حجم داده، ساعت دسترسی و مدت قطعی مجاز را بپرس. کاربرد را مشخص کن؛ مثلاً دسترسی مشترک به فایل‌های پروژه. انتخاب سیستم بدون شناخت این نیازها دلیل روشنی ندارد.\n\n۲. سیستم و تنظیمات را انتخاب کن: سیستم‌عامل، منابع، پروتکل‌های مورد نیاز و مجوز نرم‌افزار را مقایسه کن. برای حساب سرویس، آدرس شبکه، پوشه‌های مشترک و قواعد فایروال برنامه داشته باش. سرویس فقط دسترسی لازم برای کار خودش را می‌گیرد.\n\n۳. آزمایش و تحویل: با حساب مجاز و حساب غیرمجاز آزمایش کن. راه‌اندازی دوباره، ثبت رویداد و بازیابی را هم بررسی کن. تنظیمات، مسئول نگهداری و زمان تعمیرات را ثبت کن تا سرویس پس از نصب هم قابل مدیریت باشد.","sections":[{"title":"۱. نیاز را بفهم","body":"ابتدا تعداد کاربران، حجم داده، ساعت دسترسی و مدت قطعی مجاز را بپرس. کاربرد را مشخص کن؛ مثلاً دسترسی مشترک به فایل‌های پروژه. انتخاب سیستم بدون شناخت این نیازها دلیل روشنی ندارد."},{"title":"۲. سیستم و تنظیمات را انتخاب کن","body":"سیستم‌عامل، منابع، پروتکل‌های مورد نیاز و مجوز نرم‌افزار را مقایسه کن. برای حساب سرویس، آدرس شبکه، پوشه‌های مشترک و قواعد فایروال برنامه داشته باش. سرویس فقط دسترسی لازم برای کار خودش را می‌گیرد."},{"title":"۳. آزمایش و تحویل","body":"با حساب مجاز و حساب غیرمجاز آزمایش کن. راه‌اندازی دوباره، ثبت رویداد و بازیابی را هم بررسی کن. تنظیمات، مسئول نگهداری و زمان تعمیرات را ثبت کن تا سرویس پس از نصب هم قابل مدیریت باشد."}],"example":"یک دفتر برای ۲۵ نفر فایل مشترک می‌خواهد. دسترسی گروه‌ها، ۲ ترابایت فضای قابل استفاده و پشتیبان روزانه را توافق می‌کنی. سپس بررسی می‌کنی عضو تیم بتواند فایل را ویرایش کند ولی مهمان دسترسی نداشته باشد. این نتیجه نشان می‌دهد نیاز مشتری برآورده شده است.","mistake":"نصب موفق به‌تنهایی ثابت نمی‌کند که دسترسی‌ها، پشتیبان‌گیری و اتصال کاربران درست کار می‌کنند.","terms":[["Serverdienst","قابلیتی که کلاینت‌ها در شبکه استفاده می‌کنند."],["Client","دستگاه یا برنامهٔ درخواست‌کنندهٔ سرویس."],["Dienstkonto","حسابی که سرویس با آن اجرا می‌شود."],["Wartungsfenster","زمان توافق‌شده برای کارهای نگهداری."],["Berechtigung","اجازهٔ یک عمل روی منبع."],["Funktionstest","آزمایش عملکرد توافق‌شده."]],"q":"کدام نیاز سرویس فایل قابل آزمایش است؟","options":["سرور مدرن باشد.","۲۵ کاربر بتوانند فایل‌های تیم خود را ویرایش کنند.","یک سیستم‌عامل دلخواه نصب کنیم."],"answer":1,"feedback":"تعداد کاربر و عمل مجاز را می‌توان با حساب‌های آزمایشی بررسی کرد.","remember":["سرویس بر پایهٔ نیاز کاربر انتخاب می‌شود.","با حساب مجاز و غیرمجاز دسترسی را آزمایش کن.","مسئول، نگهداری و بازیابی بخشی از بهره‌برداری‌اند."],"summary":"راه‌اندازی سرویس زمانی کامل است که عملکرد لازم و ادامهٔ نگهداری آن روشن و قابل بررسی باشد."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-server/virtualisierung":{"de":{"title":"Virtualisierung und Container unterscheiden","goal":"Du erklärst Hypervisor, virtuelle Maschine und Container und wählst passend zum Einsatz.","definition":"Virtualisierung teilt physische Rechenressourcen in voneinander getrennte virtuelle Systeme. So können mehrere Arbeitsumgebungen auf einem Host betrieben und Ressourcen gezielter genutzt werden.","explanation":"1. Host und Hypervisor: Der Host stellt CPU, RAM, Speicher und Netzwerk bereit. Ein Hypervisor verwaltet virtuelle Maschinen und teilt ihnen Ressourcen zu. Aus Sicht einer VM erscheinen diese Ressourcen wie eigene Hardware.\n\n2. Virtuelle Maschine: Eine VM besitzt gewöhnlich ein eigenes Gastbetriebssystem einschließlich Kernel. Dadurch lassen sich verschiedene Betriebssysteme getrennt betreiben. Jede VM benötigt Ressourcen; Überbelegung kann mehrere Dienste gleichzeitig verlangsamen.\n\n3. Container: Container isolieren Anwendungen und ihre Abhängigkeiten auf Betriebssystemebene. Sie teilen gewöhnlich den Kernel ihres Hosts. Ein Container ist deshalb keine kleine VM mit eigenem Kernel. Für beide Varianten müssen Updates, Datenhaltung und Wiederherstellung geplant werden.","sections":[{"title":"1. Host und Hypervisor","body":"Der Host stellt CPU, RAM, Speicher und Netzwerk bereit. Ein Hypervisor verwaltet virtuelle Maschinen und teilt ihnen Ressourcen zu. Aus Sicht einer VM erscheinen diese Ressourcen wie eigene Hardware."},{"title":"2. Virtuelle Maschine","body":"Eine VM besitzt gewöhnlich ein eigenes Gastbetriebssystem einschließlich Kernel. Dadurch lassen sich verschiedene Betriebssysteme getrennt betreiben. Jede VM benötigt Ressourcen; Überbelegung kann mehrere Dienste gleichzeitig verlangsamen."},{"title":"3. Container","body":"Container isolieren Anwendungen und ihre Abhängigkeiten auf Betriebssystemebene. Sie teilen gewöhnlich den Kernel ihres Hosts. Ein Container ist deshalb keine kleine VM mit eigenem Kernel. Für beide Varianten müssen Updates, Datenhaltung und Wiederherstellung geplant werden."}],"example":"Ein Host besitzt 32 GB RAM. Zwei VMs bekommen je 8 GB, eine weitere 4 GB. Die geplanten 20 GB lassen Reserven für Host und Verwaltung; zusätzlich prüfst du den tatsächlichen Lastbedarf. Ein Snapshot hilft bei bestimmten Änderungen, ersetzt aber keine unabhängig gespeicherte Datensicherung.","mistake":"Eine VM ist nur so ausfallsicher wie die tatsächlich geplante Host-, Speicher- und Wiederherstellungsarchitektur.","terms":[["Host","Physisches oder übergeordnetes System, das Ressourcen bereitstellt."],["Hypervisor","Software zur Verwaltung virtueller Maschinen."],["VM","Virtuelle Maschine mit eigenem Gastbetriebssystem."],["Container","Isolierte Anwendungsumgebung auf Betriebssystemebene."],["Snapshot","Zustandsabbild zu einem bestimmten Zeitpunkt."],["Overcommitment","Zuweisung von mehr virtuellen als gleichzeitig verfügbaren physischen Ressourcen."]],"q":"Was teilen Container gewöhnlich mit ihrem Host?","options":["Den Betriebssystemkernel","Alle Passwörter","Jeden Anwendungsprozess"],"answer":0,"feedback":"Container isolieren Anwendungen, nutzen aber normalerweise den Kernel des Hosts.","remember":["Der Hypervisor verteilt Ressourcen an VMs.","Eine VM hat gewöhnlich einen eigenen Kernel; Container teilen gewöhnlich den Hostkernel.","Snapshot und unabhängig gespeichertes Backup erfüllen unterschiedliche Aufgaben."],"summary":"Die passende Isolierung ergibt sich aus Betriebssystembedarf, Ressourcen und Ausfallplanung statt allein aus der Anzahl virtueller Systeme."},"fa":{"title":"تفاوت ماشین مجازی و Container","goal":"نقش Host، Hypervisor، ماشین مجازی و Container را توضیح بدهی.","definition":"مجازی‌سازی منابع یک دستگاه را به محیط‌های مجازی جدا تقسیم می‌کند. به این شکل چند محیط کاری روی یک Host اجرا می‌شود و استفاده از منابع قابل برنامه‌ریزی است.","explanation":"۱. Host و Hypervisor: Host پردازنده، RAM، فضای ذخیره و شبکه را فراهم می‌کند. Hypervisor ماشین‌های مجازی را مدیریت و منابع را بین آن‌ها تقسیم می‌کند. از دید ماشین مجازی، این منابع شبیه سخت‌افزار خودش هستند.\n\n۲. ماشین مجازی: یک VM معمولاً سیستم‌عامل مهمان و Kernel جداگانه دارد؛ بنابراین می‌توان سیستم‌عامل‌های مختلف را جدا اجرا کرد. هر VM منابع مصرف می‌کند و اختصاص بیش از حد منابع می‌تواند چند سرویس را هم‌زمان کند کند.\n\n۳. Container: Container برنامه و وابستگی‌های آن را در سطح سیستم‌عامل جدا می‌کند و معمولاً Kernel را با Host مشترک دارد. پس Container یک VM کوچک با Kernel مستقل نیست. در هر دو روش باید به‌روزرسانی، نگهداری داده و بازیابی مشخص باشد.","sections":[{"title":"۱. Host و Hypervisor","body":"Host پردازنده، RAM، فضای ذخیره و شبکه را فراهم می‌کند. Hypervisor ماشین‌های مجازی را مدیریت و منابع را بین آن‌ها تقسیم می‌کند. از دید ماشین مجازی، این منابع شبیه سخت‌افزار خودش هستند."},{"title":"۲. ماشین مجازی","body":"یک VM معمولاً سیستم‌عامل مهمان و Kernel جداگانه دارد؛ بنابراین می‌توان سیستم‌عامل‌های مختلف را جدا اجرا کرد. هر VM منابع مصرف می‌کند و اختصاص بیش از حد منابع می‌تواند چند سرویس را هم‌زمان کند کند."},{"title":"۳. Container","body":"Container برنامه و وابستگی‌های آن را در سطح سیستم‌عامل جدا می‌کند و معمولاً Kernel را با Host مشترک دارد. پس Container یک VM کوچک با Kernel مستقل نیست. در هر دو روش باید به‌روزرسانی، نگهداری داده و بازیابی مشخص باشد."}],"example":"Host دارای ۳۲ گیگابایت RAM است. دو VM هرکدام ۸ و یک VM دیگر ۴ گیگابایت می‌گیرند؛ مجموع ۲۰ گیگابایت است و برای Host هم فضا باقی می‌ماند. مصرف واقعی نیز باید بررسی شود. Snapshot برای بعضی تغییرات مفید است اما جای پشتیبان مستقل را نمی‌گیرد.","mistake":"ماشین مجازی به‌تنهایی مانع قطعی نیست؛ خرابی Host و محل ذخیره هنوز باید در طرح دیده شود.","terms":[["Host","سیستم میزبان که منابع را فراهم می‌کند."],["Hypervisor","نرم‌افزار مدیریت ماشین‌های مجازی."],["VM","ماشین مجازی با سیستم‌عامل مهمان."],["Container","محیط جداشدهٔ اجرای برنامه در سطح سیستم‌عامل."],["Snapshot","ثبت وضعیت یک لحظهٔ مشخص."],["Overcommitment","اختصاص منابع مجازی بیشتر از منابع فیزیکی هم‌زمان موجود."]],"q":"Container معمولاً چه چیزی را با Host شریک است؟","options":["Kernel سیستم‌عامل","همهٔ رمزهای عبور","همهٔ پردازش‌های برنامه"],"answer":0,"feedback":"Container برنامه‌ها را جدا می‌کند اما معمولاً Kernel میزبان را به کار می‌گیرد.","remember":["Hypervisor منابع را بین ماشین‌های مجازی تقسیم می‌کند.","VM معمولاً Kernel مستقل دارد؛ Container معمولاً Kernel میزبان را شریک است.","Snapshot با پشتیبان مستقل یک کار انجام نمی‌دهد."],"summary":"انتخاب روش جداسازی به نیاز سیستم‌عامل، منابع و طرح مقابله با خرابی بستگی دارد؛ نه فقط تعداد محیط‌های مجازی."},"minutes":9,"source":["Microsoft Learn · Containers vs. virtual machines","https://learn.microsoft.com/en-us/virtualization/windowscontainers/about/containers-vs-vm"],"editorial":true,"additionalSources":[["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"]]},"k12-server/identitaet":{"de":{"title":"Identitäten, Gruppen und Rechte verwalten","goal":"Du trennst Anmeldung von Berechtigungsprüfung und setzt Gruppenrechte nachvollziehbar ein.","definition":"Identitätsverwaltung organisiert Benutzerkonten und ihre Zuordnung zu Menschen oder Diensten. Sie schafft eine gemeinsame Grundlage dafür, wer sich anmelden und auf welche Ressourcen zugreifen darf.","explanation":"1. Authentifizierung: Das System prüft die behauptete Identität, zum Beispiel mit Kennwort und einem zusätzlichen Faktor. Das beantwortet die Frage: Wer bist du? Ein Verzeichnis speichert Konten und Gruppen; der konkrete Anmeldedienst führt die Prüfung durch.\n\n2. Autorisierung: Nach erfolgreicher Anmeldung wird geprüft, welche Aktionen erlaubt sind. Gruppen bündeln Rechte nach Aufgaben. Vergib Dateizugriff möglichst an fachlich sinnvolle Gruppen und ordne Benutzer diesen Gruppen zu.\n\n3. Kontenlebenszyklus: Beim Eintritt werden nur benötigte Rechte vergeben. Bei einem Abteilungswechsel werden sie angepasst. Beim Austritt wird der Zugang zeitnah beendet. Administrative Aufgaben sollten über getrennte, besonders geschützte Konten erfolgen.","sections":[{"title":"1. Authentifizierung","body":"Das System prüft die behauptete Identität, zum Beispiel mit Kennwort und einem zusätzlichen Faktor. Das beantwortet die Frage: Wer bist du? Ein Verzeichnis speichert Konten und Gruppen; der konkrete Anmeldedienst führt die Prüfung durch."},{"title":"2. Autorisierung","body":"Nach erfolgreicher Anmeldung wird geprüft, welche Aktionen erlaubt sind. Gruppen bündeln Rechte nach Aufgaben. Vergib Dateizugriff möglichst an fachlich sinnvolle Gruppen und ordne Benutzer diesen Gruppen zu."},{"title":"3. Kontenlebenszyklus","body":"Beim Eintritt werden nur benötigte Rechte vergeben. Bei einem Abteilungswechsel werden sie angepasst. Beim Austritt wird der Zugang zeitnah beendet. Administrative Aufgaben sollten über getrennte, besonders geschützte Konten erfolgen."}],"example":"Eine neue Mitarbeiterin im Einkauf erhält ein persönliches Konto und wird Mitglied der Gruppe Einkauf. Diese Gruppe darf Angebote bearbeiten. Sie erhält keine Rechte für Personalakten. Beim Wechsel in den Vertrieb entfernst du die alte Gruppenzuordnung und prüfst die neue.","mistake":"Ein erfolgreich angemeldeter Benutzer ist nicht automatisch berechtigt, jede Datei zu lesen.","terms":[["Authentifizierung","Prüfung einer behaupteten Identität."],["Autorisierung","Prüfung erlaubter Aktionen nach der Anmeldung."],["Verzeichnisdienst","Zentrale Verwaltung von Identitäten und weiteren Objekten."],["Gruppe","Zusammenfassung von Konten oder Rollen für gemeinsame Verwaltung."],["Least Privilege","Nur die für eine Aufgabe notwendigen Rechte."],["Kontenlebenszyklus","Anlegen, Anpassen, Sperren und Entfernen von Konten."]],"q":"Welche Frage beantwortet Autorisierung?","options":["Wer bist du?","Was darfst du tun?","Wie schnell ist dein Netzwerk?"],"answer":1,"feedback":"Autorisierung entscheidet über erlaubte Handlungen auf einer Ressource.","remember":["Authentifizierung prüft Identität; Autorisierung prüft Rechte.","Gruppen bündeln Berechtigungen nach Aufgaben.","Eintritt, Wechsel und Austritt erfordern passende Rechteänderungen."],"summary":"Zuverlässige Identitätsverwaltung verbindet persönliche Konten mit aufgabenbezogenen Gruppen und einem gepflegten Kontenlebenszyklus."},"fa":{"title":"مدیریت حساب‌ها، گروه‌ها و دسترسی‌ها","goal":"احراز هویت را از بررسی مجوز جدا کنی و دسترسی گروهی را درست به کار ببری.","definition":"مدیریت هویت، حساب کاربران و سرویس‌ها را منظم می‌کند. این کار پایه‌ای برای پاسخ به دو سؤال است: چه کسی وارد می‌شود و اجازهٔ استفاده از چه منابعی را دارد؟","explanation":"۱. احراز هویت: سیستم بررسی می‌کند شخص همان کسی باشد که ادعا می‌کند؛ مثلاً با رمز و عامل دوم. سؤال این بخش «تو کی هستی؟» است. سرویس دایرکتوری حساب‌ها و گروه‌ها را نگه می‌دارد و سرویس ورود، بررسی را اجرا می‌کند.\n\n۲. بررسی مجوز: پس از ورود موفق، مشخص می‌شود چه کارهایی مجاز است. گروه‌ها دسترسی‌های یک وظیفه را جمع می‌کنند. بهتر است دسترسی پوشه را به گروه مناسب بدهی و کاربر را عضو همان گروه کنی.\n\n۳. چرخهٔ حساب: هنگام شروع کار فقط دسترسی لازم داده می‌شود. با تغییر بخش، دسترسی هم تغییر می‌کند و هنگام خروج از شرکت پایان می‌یابد. کار مدیریتی باید با حساب جداگانه و حفاظت بیشتر انجام شود.","sections":[{"title":"۱. احراز هویت","body":"سیستم بررسی می‌کند شخص همان کسی باشد که ادعا می‌کند؛ مثلاً با رمز و عامل دوم. سؤال این بخش «تو کی هستی؟» است. سرویس دایرکتوری حساب‌ها و گروه‌ها را نگه می‌دارد و سرویس ورود، بررسی را اجرا می‌کند."},{"title":"۲. بررسی مجوز","body":"پس از ورود موفق، مشخص می‌شود چه کارهایی مجاز است. گروه‌ها دسترسی‌های یک وظیفه را جمع می‌کنند. بهتر است دسترسی پوشه را به گروه مناسب بدهی و کاربر را عضو همان گروه کنی."},{"title":"۳. چرخهٔ حساب","body":"هنگام شروع کار فقط دسترسی لازم داده می‌شود. با تغییر بخش، دسترسی هم تغییر می‌کند و هنگام خروج از شرکت پایان می‌یابد. کار مدیریتی باید با حساب جداگانه و حفاظت بیشتر انجام شود."}],"example":"کارمند جدید خرید، حساب شخصی می‌گیرد و عضو گروه Einkauf می‌شود. گروه می‌تواند پیشنهادهای خرید را ویرایش کند اما پروندهٔ پرسنلی را نمی‌بیند. وقتی کارمند به فروش منتقل شد، عضویت قبلی را حذف و دسترسی جدید را بررسی می‌کنی.","mistake":"ورود موفق به سیستم به معنای اجازهٔ خواندن همهٔ فایل‌ها نیست.","terms":[["Authentifizierung","بررسی هویت ادعاشده."],["Autorisierung","بررسی اجازهٔ عمل پس از ورود."],["Verzeichnisdienst","مدیریت مرکزی هویت‌ها و اشیای مرتبط."],["Gruppe","مجموعهٔ حساب‌ها یا نقش‌ها برای مدیریت مشترک."],["Least Privilege","فقط دسترسی لازم برای انجام وظیفه."],["Kontenlebenszyklus","ساخت، تغییر، مسدودکردن و حذف حساب."]],"q":"Autorisierung به کدام سؤال پاسخ می‌دهد؟","options":["تو کی هستی؟","چه کاری اجازه داری انجام بدهی؟","سرعت شبکه چقدر است؟"],"answer":1,"feedback":"این مرحله اجازهٔ انجام عمل روی یک منبع را بررسی می‌کند.","remember":["احراز هویت، هویت را بررسی می‌کند و Autorisierung اجازهٔ عمل را.","گروه، دسترسی‌های یک وظیفه را جمع می‌کند.","شروع کار، تغییر بخش و خروج به اصلاح دسترسی نیاز دارد."],"summary":"مدیریت درست هویت، حساب شخصی را به گروه شغلی مناسب و چرخهٔ منظم تغییر و پایان دسترسی وصل می‌کند."},"minutes":9,"source":["Microsoft Learn · Authentication vs. authorization","https://learn.microsoft.com/en-us/entra/identity-platform/authentication-vs-authorization"],"editorial":true,"additionalSources":[["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"]]},"k12-server/automation":{"de":{"title":"Administration mit Skripten automatisieren","goal":"Du beschreibst einen sicheren Automatisierungsablauf mit Eingabeprüfung, Test und Protokoll.","definition":"Automatisierung lässt wiederkehrende Administrationsaufgaben nach festgelegten Regeln ausführen. Ein Skript kann etwa Konten anlegen oder Sicherungsstände prüfen. Es soll reproduzierbare Ergebnisse liefern und Fehler sichtbar machen.","explanation":"1. Eingaben und Zielzustand: Lege fest, was eingegeben wird und welches Ergebnis entstehen soll. Prüfe Dateiformat, Pflichtfelder und zulässige Werte, bevor Änderungen erfolgen. Geheimnisse gehören nicht als Klartext in ein veröffentlichtes Skript.\n\n2. Kontrolliert ausführen: Teste zuerst in einer geeigneten Testumgebung oder mit ungefährlicher Beispielmenge. Nutze bei passenden Werkzeugen eine Vorschau. Idempotenz bedeutet: Wiederholtes Anwenden führt zum gleichen gewünschten Zustand, ohne unnötige zusätzliche Änderungen.\n\n3. Fehler behandeln und dokumentieren: Prüfe Rückgabewerte und protokolliere Ergebnis sowie Fehler. Benenne, welche Schritte erfolgreich waren und wie ein Abbruch behandelt wird. Plane Ausführungszeit, benötigte Rechte und verantwortliche Person.","sections":[{"title":"1. Eingaben und Zielzustand","body":"Lege fest, was eingegeben wird und welches Ergebnis entstehen soll. Prüfe Dateiformat, Pflichtfelder und zulässige Werte, bevor Änderungen erfolgen. Geheimnisse gehören nicht als Klartext in ein veröffentlichtes Skript."},{"title":"2. Kontrolliert ausführen","body":"Teste zuerst in einer geeigneten Testumgebung oder mit ungefährlicher Beispielmenge. Nutze bei passenden Werkzeugen eine Vorschau. Idempotenz bedeutet: Wiederholtes Anwenden führt zum gleichen gewünschten Zustand, ohne unnötige zusätzliche Änderungen."},{"title":"3. Fehler behandeln und dokumentieren","body":"Prüfe Rückgabewerte und protokolliere Ergebnis sowie Fehler. Benenne, welche Schritte erfolgreich waren und wie ein Abbruch behandelt wird. Plane Ausführungszeit, benötigte Rechte und verantwortliche Person."}],"example":"Eine CSV-Datei enthält zehn neue Benutzer. Das Skript prüft jede E-Mail-Adresse, legt nur noch nicht vorhandene Konten an und protokolliert jede Zeile. Beim zweiten Lauf sollen keine doppelten Konten entstehen. Eine ungültige Zeile wird mit verständlicher Fehlermeldung zurückgewiesen.","mistake":"Ein Skript, das ohne Meldung endet, ist nicht automatisch erfolgreich. Der gewünschte Zustand muss geprüft werden.","terms":[["Skript","Abfolge ausführbarer Anweisungen."],["Parameter","Wert, der einem Skript beim Aufruf übergeben wird."],["Validierung","Prüfung von Eingaben gegen Regeln."],["Idempotenz","Wiederholung verändert einen bereits erreichten Zielzustand nicht erneut."],["Rückgabewert","Ergebnis, mit dem ein Programm seinen Ausgang meldet."],["Protokoll","Nachvollziehbare Aufzeichnung wichtiger Ereignisse."]],"q":"Was bedeutet Idempotenz beim Anlegen von Konten?","options":["Jeder Lauf legt dieselben Konten noch einmal an.","Ein weiterer Lauf erzeugt keine unnötigen Doppelkonten.","Fehler werden grundsätzlich ignoriert."],"answer":1,"feedback":"Das Skript prüft den bestehenden Zustand und führt nur die noch erforderlichen Änderungen aus.","remember":["Eingaben vor Änderungen validieren.","Idempotente Abläufe erzeugen bei Wiederholung keine unnötigen Änderungen.","Erfolg wird am Zielzustand und Protokoll geprüft."],"summary":"Ein gutes Administrationsskript ist kontrolliert testbar, nachvollziehbar wiederholbar und meldet Fehler verständlich."},"fa":{"title":"خودکارسازی مدیریت با اسکریپت","goal":"مراحل امن خودکارسازی را از بررسی ورودی تا آزمایش و ثبت نتیجه توضیح بدهی.","definition":"خودکارسازی یعنی انجام کار تکراری مدیریت طبق قواعد مشخص؛ مثلاً ساخت حساب یا بررسی پشتیبان. اسکریپت باید نتیجهٔ قابل تکرار داشته باشد و خطا را قابل مشاهده کند.","explanation":"۱. ورودی و وضعیت هدف: مشخص کن چه اطلاعاتی دریافت می‌شود و چه نتیجه‌ای باید ساخته شود. قالب فایل، فیلدهای ضروری و مقادیر مجاز را پیش از تغییر بررسی کن. رمز و کلید محرمانه نباید به شکل ساده در اسکریپت منتشرشده باشد.\n\n۲. اجرای کنترل‌شده: ابتدا در محیط آزمایشی مناسب یا با تعداد کمی دادهٔ بی‌خطر آزمایش کن. اگر ابزار امکان پیش‌نمایش دارد از آن استفاده کن. Idempotenz یعنی اجرای دوباره همان وضعیت مطلوب را حفظ می‌کند و تغییر اضافی نمی‌سازد.\n\n۳. مدیریت خطا: نتیجه و خطاها را بررسی و ثبت کن. روشن باشد کدام مرحله موفق بوده و در توقف چه باید کرد. زمان اجرا، دسترسی لازم و مسئول اجرا را مشخص کن.","sections":[{"title":"۱. ورودی و وضعیت هدف","body":"مشخص کن چه اطلاعاتی دریافت می‌شود و چه نتیجه‌ای باید ساخته شود. قالب فایل، فیلدهای ضروری و مقادیر مجاز را پیش از تغییر بررسی کن. رمز و کلید محرمانه نباید به شکل ساده در اسکریپت منتشرشده باشد."},{"title":"۲. اجرای کنترل‌شده","body":"ابتدا در محیط آزمایشی مناسب یا با تعداد کمی دادهٔ بی‌خطر آزمایش کن. اگر ابزار امکان پیش‌نمایش دارد از آن استفاده کن. Idempotenz یعنی اجرای دوباره همان وضعیت مطلوب را حفظ می‌کند و تغییر اضافی نمی‌سازد."},{"title":"۳. مدیریت خطا","body":"نتیجه و خطاها را بررسی و ثبت کن. روشن باشد کدام مرحله موفق بوده و در توقف چه باید کرد. زمان اجرا، دسترسی لازم و مسئول اجرا را مشخص کن."}],"example":"فایل CSV ده کاربر جدید دارد. اسکریپت آدرس ایمیل‌ها را بررسی می‌کند، فقط حساب‌های موجودنبود‌ه را می‌سازد و نتیجهٔ هر ردیف را ثبت می‌کند. اجرای دوم نباید حساب تکراری بسازد. ردیف خراب با پیام واضح رد می‌شود.","mistake":"پایان بدون پیام به معنای موفقیت نیست؛ باید نتیجهٔ واقعی با وضعیت هدف مقایسه شود.","terms":[["Skript","مجموعه‌ای از دستورهای قابل اجرا."],["Parameter","مقدار داده‌شده هنگام اجرای اسکریپت."],["Validierung","سنجش ورودی با قواعد مشخص."],["Idempotenz","اجرای دوباره، وضعیت مطلوب موجود را دوباره تغییر نمی‌دهد."],["Rückgabewert","مقدار اعلام‌کنندهٔ نتیجهٔ برنامه."],["Protokoll","ثبت قابل پیگیری رویدادهای مهم."]],"q":"Idempotenz در ساخت حساب یعنی چه؟","options":["هر اجرا حساب‌ها را دوباره می‌سازد.","اجرای بعدی حساب تکراری اضافی نمی‌سازد.","همهٔ خطاها نادیده گرفته می‌شوند."],"answer":1,"feedback":"اسکریپت وضعیت موجود را می‌سنجد و فقط تغییر لازم را انجام می‌دهد.","remember":["پیش از تغییر، ورودی را بررسی کن.","اجرای دوبارهٔ فرایند Idempotent تغییر اضافی نمی‌سازد.","موفقیت با وضعیت واقعی و گزارش بررسی می‌شود."],"summary":"اسکریپت خوب قابل آزمایش کنترل‌شده و تکرار قابل پیگیری است و خطا را روشن گزارش می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-server/monitoring":{"de":{"title":"Monitoring: Messen, bewerten, reagieren","goal":"Du unterscheidest Messwert, Grenzwert und Alarm und formulierst eine hilfreiche Überwachung.","definition":"Monitoring beobachtet technische Zustände fortlaufend. Es soll Probleme erkennbar machen, bevor oder während Benutzer beeinträchtigt werden. Ein Messwert allein ist noch keine Bewertung des Dienstes.","explanation":"1. Geeignete Werte erfassen: Erfasse zur Anforderung passende Daten: Antwortzeit, erfolgreiche Anmeldungen, freien Speicher oder Sicherungsfehler. Infrastrukturwerte wie CPU-Auslastung ergänzen Diensttests, ersetzen sie aber nicht.\n\n2. Werte im Kontext bewerten: Ein kurzer Lastanstieg kann normal sein. Ein Alarm sollte auf sinnvollen Grenzwerten, Dauer und Auswirkung beruhen. Über Trends erkennst du, ob Speicher in einigen Wochen knapp wird. Wartungen werden berücksichtigt, damit erwartete Ausfälle nicht unnötig alarmieren.\n\n3. Verantwortlich reagieren: Ein Alarm braucht Empfänger, Priorität und Handlungsanweisung. Dokumentiere Prüfung, Ursache und Maßnahme. Kontrolliere nach der Behebung auch den Dienst aus Nutzersicht. Zu viele unwichtige Meldungen können wichtige Warnungen verdecken.","sections":[{"title":"1. Geeignete Werte erfassen","body":"Erfasse zur Anforderung passende Daten: Antwortzeit, erfolgreiche Anmeldungen, freien Speicher oder Sicherungsfehler. Infrastrukturwerte wie CPU-Auslastung ergänzen Diensttests, ersetzen sie aber nicht."},{"title":"2. Werte im Kontext bewerten","body":"Ein kurzer Lastanstieg kann normal sein. Ein Alarm sollte auf sinnvollen Grenzwerten, Dauer und Auswirkung beruhen. Über Trends erkennst du, ob Speicher in einigen Wochen knapp wird. Wartungen werden berücksichtigt, damit erwartete Ausfälle nicht unnötig alarmieren."},{"title":"3. Verantwortlich reagieren","body":"Ein Alarm braucht Empfänger, Priorität und Handlungsanweisung. Dokumentiere Prüfung, Ursache und Maßnahme. Kontrolliere nach der Behebung auch den Dienst aus Nutzersicht. Zu viele unwichtige Meldungen können wichtige Warnungen verdecken."}],"example":"Eine Dateifreigabe soll mindestens 15 % freien Speicher behalten. Das Monitoring meldet eine Warnung, wenn dieser Wert länger unterschritten wird. Der Trend zeigt zusätzlich 30 GB Zuwachs pro Woche. Du kannst dadurch Kapazität planen, bevor der Dienst keine Dateien mehr speichern kann.","mistake":"Ein antwortender Server beweist nicht, dass seine Anwendung korrekt arbeitet. Prüfe auch die eigentliche Dienstfunktion.","terms":[["Messwert","Erfasste technische Größe."],["Grenzwert","Festgelegte Schwelle für eine Bewertung."],["Alarm","Meldung eines handlungsbedürftigen Zustands."],["Trend","Entwicklung eines Wertes über Zeit."],["Verfügbarkeit","Nutzbarkeit eines Dienstes im betrachteten Zeitraum."],["Alarmmüdigkeit","Nachlassende Aufmerksamkeit durch zu viele unwichtige Meldungen."]],"q":"Welche Prüfung ist für einen Webdienst besonders aussagekräftig?","options":["Nur prüfen, ob der Rechner Strom hat.","Nur den Gehäuseaufkleber lesen.","Eine erwartete Webseite abrufen und Antwort prüfen."],"answer":2,"feedback":"Der Diensttest prüft näher an der tatsächlichen Nutzerfunktion als ein reiner Hardwarezustand.","remember":["Diensttests ergänzen Infrastrukturmesswerte.","Grenzwerte brauchen Kontext, Dauer und passende Empfänger.","Trends unterstützen frühzeitige Kapazitätsplanung."],"summary":"Monitoring wird wirksam, wenn aus passenden Messungen eine begründete Warnung und eine klare Handlung entstehen."},"fa":{"title":"Monitoring؛ اندازه‌گیری و واکنش","goal":"تفاوت مقدار اندازه‌گیری، حد هشدار و Alarm را بدانی.","definition":"Monitoring وضعیت فنی را پیوسته مشاهده می‌کند تا مشکل پیش از آسیب یا هنگام آن مشخص شود. خود عدد هنوز نمی‌گوید سرویس برای کاربر درست کار می‌کند.","explanation":"۱. مقدار مناسب را بسنج: دادهٔ مرتبط با نیاز را بگیر؛ مثل زمان پاسخ، ورود موفق، فضای آزاد یا خطای پشتیبان. مصرف CPU برای شناخت زیرساخت مفید است اما جای آزمایش خود سرویس را نمی‌گیرد.\n\n۲. با زمینه مقایسه کن: افزایش کوتاه مصرف ممکن است عادی باشد. هشدار باید با حد مناسب، مدت و اثر مشکل تعریف شود. روند تغییر نشان می‌دهد مثلاً چند هفته بعد فضا کم خواهد شد. تعمیرات برنامه‌ریزی‌شده نیز باید در ارزیابی دیده شود.\n\n۳. مسئولانه واکنش بده: هشدار باید گیرنده، اولویت و راهنمای اقدام داشته باشد. بررسی، علت و اقدام را ثبت کن. پس از رفع مشکل، کارکرد سرویس را از دید کاربر هم بسنج. پیام‌های کم‌اهمیت زیاد می‌توانند هشدار اصلی را پنهان کنند.","sections":[{"title":"۱. مقدار مناسب را بسنج","body":"دادهٔ مرتبط با نیاز را بگیر؛ مثل زمان پاسخ، ورود موفق، فضای آزاد یا خطای پشتیبان. مصرف CPU برای شناخت زیرساخت مفید است اما جای آزمایش خود سرویس را نمی‌گیرد."},{"title":"۲. با زمینه مقایسه کن","body":"افزایش کوتاه مصرف ممکن است عادی باشد. هشدار باید با حد مناسب، مدت و اثر مشکل تعریف شود. روند تغییر نشان می‌دهد مثلاً چند هفته بعد فضا کم خواهد شد. تعمیرات برنامه‌ریزی‌شده نیز باید در ارزیابی دیده شود."},{"title":"۳. مسئولانه واکنش بده","body":"هشدار باید گیرنده، اولویت و راهنمای اقدام داشته باشد. بررسی، علت و اقدام را ثبت کن. پس از رفع مشکل، کارکرد سرویس را از دید کاربر هم بسنج. پیام‌های کم‌اهمیت زیاد می‌توانند هشدار اصلی را پنهان کنند."}],"example":"برای فایل‌سرور حداقل ۱۵ درصد فضای آزاد توافق شده است. اگر کمبود برای مدتی ادامه داشت، هشدار می‌آید. روند مصرف رشد هفتگی ۳۰ گیگابایت را نشان می‌دهد؛ بنابراین قبل از پرشدن کامل می‌توان ظرفیت را افزایش داد.","mistake":"پاسخ‌دادن دستگاه ثابت نمی‌کند برنامهٔ آن درست کار می‌کند؛ عملکرد خود سرویس را هم بررسی کن.","terms":[["Messwert","مقدار فنی اندازه‌گیری‌شده."],["Grenzwert","مرز مشخص برای ارزیابی وضعیت."],["Alarm","پیام وضعیت نیازمند اقدام."],["Trend","روند تغییر یک مقدار در زمان."],["Verfügbarkeit","قابل استفاده بودن سرویس در بازهٔ بررسی."],["Alarmmüdigkeit","کم‌شدن توجه به علت هشدارهای غیرمهم فراوان."]],"q":"برای سرویس وب کدام آزمایش بهتر است؟","options":["فقط روشن بودن دستگاه.","خواندن برچسب کیس.","دریافت صفحهٔ مورد انتظار و بررسی پاسخ."],"answer":2,"feedback":"این آزمایش به کاری که کاربر واقعاً انجام می‌دهد نزدیک‌تر است.","remember":["آزمایش خود سرویس، اندازه‌گیری زیرساخت را کامل می‌کند.","حد هشدار به زمینه، مدت و گیرندهٔ مناسب نیاز دارد.","روند تغییر برای برنامه‌ریزی ظرفیت مفید است."],"summary":"Monitoring وقتی مؤثر است که اندازه‌گیری مناسب به هشدار مستدل و اقدام روشن منجر شود."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-server/backup":{"de":{"title":"Datensicherung und Wiederherstellung planen","goal":"Du unterscheidest Backup, Restore, RPO und RTO und planst einen Wiederherstellungstest.","definition":"Eine Datensicherung erstellt wiederherstellbare Kopien wichtiger Daten. Ihr Zweck ist die Rückkehr zu einem brauchbaren Zustand nach Verlust, Beschädigung oder einem Angriff. Entscheidend ist, ob die Rücksicherung funktioniert.","explanation":"1. Sicherungsziel festlegen: Bestimme Daten, Verantwortliche und Aufbewahrung. RPO beschreibt den maximal tolerierbaren Datenverlust als Zeitspanne. RTO beschreibt die angestrebte maximale Wiederherstellungsdauer. Diese Ziele bestimmen Häufigkeit und Verfahren.\n\n2. Kopien getrennt schützen: Eine Vollsicherung kopiert den ausgewählten Datenbestand vollständig. Inkrementelle Sicherungen erfassen Änderungen seit der letzten relevanten Sicherung. Bewahre geeignete Kopien getrennt auf und schütze sie vor unberechtigter Änderung oder Löschung.\n\n3. Restore testen: Stelle Daten in einer geeigneten Testumgebung wieder her. Prüfe Inhalt, Zugriffsrechte und benötigte Zeit. Ein Backupbericht mit Erfolgsmeldung ersetzt diesen Test nicht. Dokumentiere, wer im Notfall welche Schritte ausführt.","sections":[{"title":"1. Sicherungsziel festlegen","body":"Bestimme Daten, Verantwortliche und Aufbewahrung. RPO beschreibt den maximal tolerierbaren Datenverlust als Zeitspanne. RTO beschreibt die angestrebte maximale Wiederherstellungsdauer. Diese Ziele bestimmen Häufigkeit und Verfahren."},{"title":"2. Kopien getrennt schützen","body":"Eine Vollsicherung kopiert den ausgewählten Datenbestand vollständig. Inkrementelle Sicherungen erfassen Änderungen seit der letzten relevanten Sicherung. Bewahre geeignete Kopien getrennt auf und schütze sie vor unberechtigter Änderung oder Löschung."},{"title":"3. Restore testen","body":"Stelle Daten in einer geeigneten Testumgebung wieder her. Prüfe Inhalt, Zugriffsrechte und benötigte Zeit. Ein Backupbericht mit Erfolgsmeldung ersetzt diesen Test nicht. Dokumentiere, wer im Notfall welche Schritte ausführt."}],"example":"Ein Team toleriert höchstens vier Stunden Datenverlust: RPO = 4 h. Eine tägliche Sicherung allein kann dieses Ziel nicht zuverlässig erfüllen. Für RTO = 2 h misst du im Test, wie lange Datenbereitstellung, Rücksicherung und Funktionskontrolle zusammen dauern.","mistake":"RAID erhöht je nach Aufbau die Ausfalltoleranz von Laufwerken, schützt aber nicht zuverlässig vor versehentlichem Löschen und ersetzt kein Backup.","terms":[["Backup","Wiederherstellbare Kopie wichtiger Daten."],["Restore","Rücksicherung von Daten oder Systemen."],["RPO","Maximal tolerierter Datenverlust, als Zeitspanne beschrieben."],["RTO","Angestrebte maximale Dauer der Wiederherstellung."],["Vollsicherung","Sicherung des gesamten ausgewählten Bestands."],["Inkrementell","Sicherung der Änderungen seit der letzten relevanten Sicherung."]],"q":"Eine tägliche Sicherung: Erfüllt sie sicher ein RPO von vier Stunden?","options":["Ja, unabhängig vom Zeitpunkt.","Nein, die Sicherungsabstände sind dafür zu groß.","RPO betrifft ausschließlich CPU-Leistung."],"answer":1,"feedback":"Bei täglichen Sicherungen kann seit dem letzten Sicherungsstand deutlich mehr als vier Stunden Arbeit verloren gehen.","remember":["RPO beschreibt tolerierbaren Datenverlust, RTO die angestrebte Wiederherstellungsdauer.","Kopien müssen auch vor unberechtigter Änderung geschützt sein.","Ein Restore-Test prüft Daten, Rechte und benötigte Zeit."],"summary":"Eine brauchbare Datensicherung richtet Sicherungsabstände und Wiederherstellung an den vereinbarten Verlust- und Ausfallgrenzen aus."},"fa":{"title":"برنامه‌ریزی پشتیبان و بازیابی","goal":"Backup، Restore، RPO و RTO را از هم جدا کنی.","definition":"پشتیبان‌گیری، نسخه‌ای قابل بازیابی از دادهٔ مهم می‌سازد تا پس از حذف، خرابی یا حمله بتوان به وضعیت قابل استفاده برگشت. مهم این است که بازگرداندن داده واقعاً موفق شود.","explanation":"۱. هدف را تعیین کن: داده‌ها، مسئول و مدت نگهداری را مشخص کن. RPO میزان تحمل ازدست‌رفتن داده را به شکل زمان می‌گوید. RTO مدت هدف برای بازگرداندن سرویس است. این دو مقدار فاصلهٔ پشتیبان‌ها و روش بازیابی را تعیین می‌کنند.\n\n۲. نسخه‌ها را جدا محافظت کن: پشتیبان کامل تمام دادهٔ انتخابی را کپی می‌کند. پشتیبان افزایشی تغییرات پس از پشتیبان مرتبط قبلی را می‌گیرد. نسخه‌های مناسب را جدا نگه دار و در برابر تغییر یا حذف غیرمجاز حفاظت کن.\n\n۳. بازیابی را آزمایش کن: در محیط مناسب داده را برگردان؛ محتوا، دسترسی‌ها و زمان را بررسی کن. پیام موفق پشتیبان جای آزمایش بازیابی را نمی‌گیرد. مسئول و مراحل کار اضطراری را ثبت کن.","sections":[{"title":"۱. هدف را تعیین کن","body":"داده‌ها، مسئول و مدت نگهداری را مشخص کن. RPO میزان تحمل ازدست‌رفتن داده را به شکل زمان می‌گوید. RTO مدت هدف برای بازگرداندن سرویس است. این دو مقدار فاصلهٔ پشتیبان‌ها و روش بازیابی را تعیین می‌کنند."},{"title":"۲. نسخه‌ها را جدا محافظت کن","body":"پشتیبان کامل تمام دادهٔ انتخابی را کپی می‌کند. پشتیبان افزایشی تغییرات پس از پشتیبان مرتبط قبلی را می‌گیرد. نسخه‌های مناسب را جدا نگه دار و در برابر تغییر یا حذف غیرمجاز حفاظت کن."},{"title":"۳. بازیابی را آزمایش کن","body":"در محیط مناسب داده را برگردان؛ محتوا، دسترسی‌ها و زمان را بررسی کن. پیام موفق پشتیبان جای آزمایش بازیابی را نمی‌گیرد. مسئول و مراحل کار اضطراری را ثبت کن."}],"example":"تیم حداکثر چهار ساعت ازدست‌رفتن داده را تحمل می‌کند؛ یعنی RPO چهار ساعت. پشتیبان روزانه به‌تنهایی کافی نیست. اگر RTO دو ساعت باشد، زمان آماده‌سازی، بازگرداندن و آزمایش عملکرد را با هم اندازه می‌گیری.","mistake":"RAID در بعضی حالت‌ها خرابی دیسک را تحمل می‌کند اما جای پشتیبان را نمی‌گیرد و حذف اشتباهی را جبران نمی‌کند.","terms":[["Backup","نسخهٔ قابل بازیابی دادهٔ مهم."],["Restore","برگرداندن داده یا سیستم از پشتیبان."],["RPO","حد تحمل ازدست‌رفتن داده بر حسب زمان."],["RTO","مدت هدف برای بازگرداندن سرویس."],["Vollsicherung","پشتیبان کامل دادهٔ انتخاب‌شده."],["Inkrementell","ثبت تغییرات پس از پشتیبان مرتبط قبلی."]],"q":"آیا پشتیبان روزانه قطعاً RPO چهار ساعت را تأمین می‌کند؟","options":["بله، در هر زمان.","خیر، فاصلهٔ پشتیبان‌ها خیلی زیاد است.","RPO فقط به قدرت CPU مربوط است."],"answer":1,"feedback":"ممکن است از آخرین پشتیبان روزانه بیش از چهار ساعت گذشته باشد و همان داده‌ها از دست برود.","remember":["RPO تحمل ازدست‌رفتن داده و RTO مدت هدف بازیابی را بیان می‌کند.","نسخهٔ پشتیبان باید از تغییر غیرمجاز هم محافظت شود.","تست Restore داده، دسترسی و زمان را بررسی می‌کند."],"summary":"پشتیبان مناسب، فاصلهٔ نسخه‌ها و روش بازیابی را با حد قابل تحمل ازدست‌رفتن داده و قطعی هماهنگ می‌کند."},"minutes":9,"source":["NIST · Recovery Point Objective","https://csrc.nist.gov/glossary/term/recovery_point_objective"],"editorial":true,"additionalSources":[["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],["NIST · Recovery Time Objective","https://csrc.nist.gov/glossary/term/recovery_time_objective"]]},"k12-security/schutzziele":{"de":{"title":"Schutzziele und Schutzbedarf bestimmen","goal":"Du ordnest Schäden den drei grundlegenden Schutzzielen zu.","definition":"Informationssicherheit schützt Informationen und die Systeme, die sie verarbeiten. Die grundlegenden Schutzziele sind Vertraulichkeit, Integrität und Verfügbarkeit. Sie helfen, Anforderungen zu formulieren, bevor Schutzmaßnahmen ausgewählt werden.","explanation":"1. Vertraulichkeit: Nur berechtigte Personen dürfen bestimmte Informationen erhalten. Bei Personalakten ist schon unbefugtes Lesen ein Schaden. Zugriffsrechte, Verschlüsselung und sichere Freigaben können dieses Ziel unterstützen.\n\n2. Integrität: Informationen sollen vollständig und korrekt bleiben; unberechtigte Änderungen müssen verhindert oder erkannt werden. Änderungsprotokolle, geeignete Prüfwerte und kontrollierte Schreibrechte unterstützen dieses Ziel.\n\n3. Verfügbarkeit: Informationen und Dienste sollen dann nutzbar sein, wenn sie benötigt werden. Redundanz, Wartung und getestete Wiederherstellung unterstützen die Verfügbarkeit. Schutzbedarf richtet sich nach möglichen Schäden, nicht nach dem Kaufpreis eines Geräts.","sections":[{"title":"1. Vertraulichkeit","body":"Nur berechtigte Personen dürfen bestimmte Informationen erhalten. Bei Personalakten ist schon unbefugtes Lesen ein Schaden. Zugriffsrechte, Verschlüsselung und sichere Freigaben können dieses Ziel unterstützen."},{"title":"2. Integrität","body":"Informationen sollen vollständig und korrekt bleiben; unberechtigte Änderungen müssen verhindert oder erkannt werden. Änderungsprotokolle, geeignete Prüfwerte und kontrollierte Schreibrechte unterstützen dieses Ziel."},{"title":"3. Verfügbarkeit","body":"Informationen und Dienste sollen dann nutzbar sein, wenn sie benötigt werden. Redundanz, Wartung und getestete Wiederherstellung unterstützen die Verfügbarkeit. Schutzbedarf richtet sich nach möglichen Schäden, nicht nach dem Kaufpreis eines Geräts."}],"example":"Bei einer Lohnabrechnung verletzt ein öffentlich lesbares Gehaltsdokument die Vertraulichkeit. Eine veränderte Kontonummer betrifft die Integrität. Ein ausgefallener Abrechnungsdienst vor dem Zahlungslauf betrifft die Verfügbarkeit. Dasselbe System kann bei allen drei Zielen hohen Schutzbedarf haben.","mistake":"Verschlüsselung allein löst nicht jedes Sicherheitsproblem: Ein verschlüsseltes System kann trotzdem ausfallen oder durch ein berechtigtes Konto falsch verändert werden.","terms":[["Vertraulichkeit","Informationen sind nur Berechtigten zugänglich."],["Integrität","Informationen bleiben korrekt und vollständig."],["Verfügbarkeit","Benötigte Informationen und Dienste sind nutzbar."],["Schutzbedarf","Erforderlicher Schutz entsprechend möglicher Schäden."],["Schaden","Nachteil durch Verletzung eines Schutzziels."],["Schutzmaßnahme","Handlung oder Technik zur Verringerung eines Risikos."]],"q":"Welches Schutzziel ist durch eine unberechtigt geänderte Kontonummer betroffen?","options":["Vertraulichkeit","Integrität","Nur Speicherplatz"],"answer":1,"feedback":"Die Korrektheit der Daten wurde verletzt; damit ist Integrität betroffen.","remember":["Vertraulichkeit schützt vor unberechtigtem Lesen.","Integrität betrifft korrekte und vollständige Informationen.","Verfügbarkeit betrifft die Nutzbarkeit zum benötigten Zeitpunkt."],"summary":"Der mögliche Schaden an Vertraulichkeit, Integrität und Verfügbarkeit bestimmt den benötigten Schutz eines Systems."},"fa":{"title":"هدف‌های امنیت و نیاز حفاظتی","goal":"آسیب را به سه هدف پایهٔ امنیت مرتبط کنی.","definition":"امنیت اطلاعات از داده و سیستم پردازش آن محافظت می‌کند. سه هدف پایه شامل محرمانگی، یکپارچگی و دسترس‌پذیری است. پیش از انتخاب ابزار باید بدانیم کدام هدف و با چه اهمیتی لازم است.","explanation":"۱. محرمانگی: فقط افراد مجاز باید اطلاعات را ببینند. در پروندهٔ پرسنلی، خواندن غیرمجاز خودش آسیب است. مجوز دسترسی، رمزنگاری و اشتراک‌گذاری امن می‌تواند از این هدف محافظت کند.\n\n۲. یکپارچگی: اطلاعات باید درست و کامل بماند و تغییر غیرمجاز پیشگیری یا تشخیص داده شود. ثبت تغییرات، مقادیر بررسی مناسب و کنترل نوشتن به این هدف کمک می‌کند.\n\n۳. دسترس‌پذیری: داده و سرویس باید هنگام نیاز قابل استفاده باشد. افزونگی، نگهداری و بازیابی آزمایش‌شده کمک می‌کنند. نیاز حفاظتی بر پایهٔ آسیب احتمالی است؛ نه قیمت خرید دستگاه.","sections":[{"title":"۱. محرمانگی","body":"فقط افراد مجاز باید اطلاعات را ببینند. در پروندهٔ پرسنلی، خواندن غیرمجاز خودش آسیب است. مجوز دسترسی، رمزنگاری و اشتراک‌گذاری امن می‌تواند از این هدف محافظت کند."},{"title":"۲. یکپارچگی","body":"اطلاعات باید درست و کامل بماند و تغییر غیرمجاز پیشگیری یا تشخیص داده شود. ثبت تغییرات، مقادیر بررسی مناسب و کنترل نوشتن به این هدف کمک می‌کند."},{"title":"۳. دسترس‌پذیری","body":"داده و سرویس باید هنگام نیاز قابل استفاده باشد. افزونگی، نگهداری و بازیابی آزمایش‌شده کمک می‌کنند. نیاز حفاظتی بر پایهٔ آسیب احتمالی است؛ نه قیمت خرید دستگاه."}],"example":"در حقوق و دستمزد، انتشار عمومی فیش حقوق محرمانگی را نقض می‌کند. تغییر غیرمجاز شمارهٔ حساب به یکپارچگی مربوط است و قطع سرویس پیش از پرداخت، دسترس‌پذیری را تهدید می‌کند. یک سیستم ممکن است در هر سه هدف نیاز حفاظتی بالا داشته باشد.","mistake":"رمزنگاری همهٔ مشکلات را حل نمی‌کند؛ سیستم رمز‌شده هم ممکن است قطع شود یا کاربر مجاز داده را اشتباه تغییر دهد.","terms":[["Vertraulichkeit","فقط شخص مجاز اطلاعات را می‌بیند."],["Integrität","درستی و کامل‌بودن اطلاعات."],["Verfügbarkeit","قابل استفاده بودن داده و سرویس هنگام نیاز."],["Schutzbedarf","مقدار حفاظت لازم بر پایهٔ آسیب احتمالی."],["Schaden","پیامد منفی نقض هدف حفاظتی."],["Schutzmaßnahme","اقدام یا فناوری کاهش خطر."]],"q":"تغییر غیرمجاز شمارهٔ حساب کدام هدف را نقض می‌کند؟","options":["محرمانگی","یکپارچگی","فقط فضای ذخیره"],"answer":1,"feedback":"درستی داده تغییر کرده است؛ پس یکپارچگی آسیب دیده است.","remember":["محرمانگی جلوی خواندن غیرمجاز را می‌گیرد.","یکپارچگی به درستی و کامل‌بودن داده مربوط است.","دسترس‌پذیری یعنی قابل استفاده بودن هنگام نیاز."],"summary":"آسیب احتمالی به محرمانگی، یکپارچگی و دسترس‌پذیری مقدار حفاظت لازم سیستم را تعیین می‌کند."},"minutes":9,"source":["BSI · Standard 200-1","https://www.bsi.bund.de/SharedDocs/Downloads/DE/BSI/Grundschutz/BSI_Standards/standard_200_1.pdf?__blob=publicationFile&v=2"],"editorial":true,"additionalSources":[["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"]]},"k12-security/risiko":{"de":{"title":"Risikoanalyse verständlich durchführen","goal":"Du unterscheidest Bedrohung, Schwachstelle, Risiko und Restrisiko.","definition":"Eine Risikoanalyse untersucht, welche Ereignisse wichtige Werte schädigen könnten, wie wahrscheinlich sie sind und welche Folgen entstehen. Dadurch lassen sich Schutzmaßnahmen begründen und priorisieren.","explanation":"1. Werte und Bedrohungen erfassen: Bestimme zu schützende Daten und Dienste. Eine Bedrohung ist eine mögliche schädliche Einwirkung, beispielsweise Diebstahl oder ein Stromausfall. Eine Schwachstelle ist eine ausnutzbare oder schadensbegünstigende Eigenschaft.\n\n2. Risiko bewerten: Bewerte Eintrittswahrscheinlichkeit und Schadensausmaß mit einer festgelegten, verständlichen Methode. Eine Risikomatrix kann qualitative Stufen verbinden. Die Ergebnisse sind Annahmen mit Begründung, keine sichere Vorhersage einer exakten Schadenshöhe.\n\n3. Risiko behandeln: Du kannst ein Risiko durch Maßnahmen reduzieren, bestimmte Tätigkeiten vermeiden, Folgen teilweise übertragen oder es bewusst akzeptieren lassen. Nach einer Maßnahme wird das verbleibende Restrisiko erneut bewertet. Zuständigkeit und Entscheidung werden dokumentiert.","sections":[{"title":"1. Werte und Bedrohungen erfassen","body":"Bestimme zu schützende Daten und Dienste. Eine Bedrohung ist eine mögliche schädliche Einwirkung, beispielsweise Diebstahl oder ein Stromausfall. Eine Schwachstelle ist eine ausnutzbare oder schadensbegünstigende Eigenschaft."},{"title":"2. Risiko bewerten","body":"Bewerte Eintrittswahrscheinlichkeit und Schadensausmaß mit einer festgelegten, verständlichen Methode. Eine Risikomatrix kann qualitative Stufen verbinden. Die Ergebnisse sind Annahmen mit Begründung, keine sichere Vorhersage einer exakten Schadenshöhe."},{"title":"3. Risiko behandeln","body":"Du kannst ein Risiko durch Maßnahmen reduzieren, bestimmte Tätigkeiten vermeiden, Folgen teilweise übertragen oder es bewusst akzeptieren lassen. Nach einer Maßnahme wird das verbleibende Restrisiko erneut bewertet. Zuständigkeit und Entscheidung werden dokumentiert."}],"example":"Ein Notebook enthält vertrauliche Kundendaten. Verlust ist die Bedrohung; fehlende Datenträgerverschlüsselung begünstigt unbefugtes Lesen. Verschlüsselung und sichere Schlüsselverwaltung reduzieren dieses Risiko. Der Ausfall des verlorenen Geräts bleibt dennoch bestehen und muss gesondert behandelt werden.","mistake":"Eine Schwachstelle und ein Risiko sind nicht dasselbe: Zur Risikobewertung gehören auch eine mögliche Bedrohung und deren Auswirkungen.","terms":[["Bedrohung","Mögliche schädliche Einwirkung."],["Schwachstelle","Eigenschaft, die eine Schädigung begünstigen kann."],["Eintrittswahrscheinlichkeit","Bewertung, wie wahrscheinlich ein Ereignis ist."],["Schadensausmaß","Bewertete Schwere möglicher Folgen."],["Restrisiko","Risiko, das nach Maßnahmen bestehen bleibt."],["Risikoakzeptanz","Bewusste Entscheidung, ein bewertetes Risiko zu tragen."]],"q":"Was ist das Restrisiko?","options":["Jedes Risiko vor einer Maßnahme","Das nach Maßnahmen verbleibende Risiko","Nur ein Softwarefehler"],"answer":1,"feedback":"Auch wirksame Schutzmaßnahmen beseitigen nicht zwangsläufig alle Risiken.","remember":["Bedrohung, Schwachstelle und Risiko sind unterschiedliche Begriffe.","Bewertung braucht Wahrscheinlichkeit und Schadensausmaß.","Nach Maßnahmen bleibt ein zu bewertendes Restrisiko."],"summary":"Risikoanalyse macht Schutzentscheidungen nachvollziehbar, indem sie mögliche Schäden, Maßnahmen und verbleibende Risiken zusammen betrachtet."},"fa":{"title":"تحلیل ریسک به زبان ساده","goal":"تهدید، ضعف، ریسک و ریسک باقی‌مانده را جدا کنی.","definition":"تحلیل ریسک بررسی می‌کند چه اتفاقی ممکن است به دارایی مهم آسیب بزند، احتمال آن چقدر است و چه پیامدی دارد. به این ترتیب می‌توان اولویت حفاظت را با دلیل تعیین کرد.","explanation":"۱. دارایی و تهدید: داده و سرویس نیازمند حفاظت را مشخص کن. تهدید، اثر آسیب‌زای ممکن است؛ مثل سرقت یا قطع برق. ضعف، ویژگی‌ای است که امکان آسیب را بیشتر می‌کند.\n\n۲. ارزیابی: احتمال رخداد و شدت پیامد را با روش روشن بسنج. ماتریس ریسک می‌تواند سطح‌های کیفی را به هم مرتبط کند. این ارزیابی فرض مستدل است، نه پیشگویی قطعی عدد دقیق خسارت.\n\n۳. برخورد با ریسک: می‌توان با اقدام مناسب ریسک را کاهش داد، از فعالیت پرخطر صرف‌نظر کرد، بخشی از پیامد را منتقل کرد یا آگاهانه پذیرفت. پس از اقدام، ریسک باقی‌مانده دوباره ارزیابی و مسئول و تصمیم ثبت می‌شود.","sections":[{"title":"۱. دارایی و تهدید","body":"داده و سرویس نیازمند حفاظت را مشخص کن. تهدید، اثر آسیب‌زای ممکن است؛ مثل سرقت یا قطع برق. ضعف، ویژگی‌ای است که امکان آسیب را بیشتر می‌کند."},{"title":"۲. ارزیابی","body":"احتمال رخداد و شدت پیامد را با روش روشن بسنج. ماتریس ریسک می‌تواند سطح‌های کیفی را به هم مرتبط کند. این ارزیابی فرض مستدل است، نه پیشگویی قطعی عدد دقیق خسارت."},{"title":"۳. برخورد با ریسک","body":"می‌توان با اقدام مناسب ریسک را کاهش داد، از فعالیت پرخطر صرف‌نظر کرد، بخشی از پیامد را منتقل کرد یا آگاهانه پذیرفت. پس از اقدام، ریسک باقی‌مانده دوباره ارزیابی و مسئول و تصمیم ثبت می‌شود."}],"example":"لپ‌تاپ دادهٔ محرمانه دارد. گم‌شدن تهدید است و نبود رمزنگاری دیسک خواندن غیرمجاز را آسان می‌کند. رمزنگاری و نگهداری امن کلید خطر را کم می‌کند؛ اما ازدست‌رفتن خود دستگاه و قطعی کار هنوز مسئله‌ای جداست.","mistake":"ضعف و ریسک یکی نیستند؛ ریسک علاوه بر ضعف به تهدید و اثر احتمالی هم مربوط است.","terms":[["Bedrohung","عامل آسیب‌زای ممکن."],["Schwachstelle","ویژگی آسان‌کنندهٔ آسیب."],["Eintrittswahrscheinlichkeit","ارزیابی احتمال رخداد."],["Schadensausmaß","شدت پیامد احتمالی."],["Restrisiko","ریسکی که پس از اقدام باقی می‌ماند."],["Risikoakzeptanz","پذیرش آگاهانهٔ ریسک ارزیابی‌شده."]],"q":"Restrisiko یعنی چه؟","options":["تمام خطرها پیش از حفاظت","خطر باقی‌مانده پس از اقدام حفاظتی","فقط خطای نرم‌افزار"],"answer":1,"feedback":"اقدام مؤثر هم لزوماً همهٔ خطرها را حذف نمی‌کند.","remember":["تهدید، ضعف و ریسک سه مفهوم متفاوت‌اند.","ارزیابی به احتمال رخداد و شدت آسیب نیاز دارد.","پس از اقدام، ریسک باقی‌مانده دوباره سنجیده می‌شود."],"summary":"تحلیل ریسک با دیدن هم‌زمان آسیب، اقدام و خطر باقی‌مانده، تصمیم حفاظتی را قابل توضیح می‌کند."},"minutes":9,"source":["BSI · Standard 200-1","https://www.bsi.bund.de/SharedDocs/Downloads/DE/BSI/Grundschutz/BSI_Standards/standard_200_1.pdf?__blob=publicationFile&v=2"],"editorial":true,"additionalSources":[["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"]]},"k12-security/firewall":{"de":{"title":"Firewallregeln und Netzsegmentierung","goal":"Du liest eine Regel anhand von Quelle, Ziel, Dienst und Aktion.","definition":"Eine Firewall kontrolliert Netzwerkverkehr nach festgelegten Regeln. Netzsegmentierung trennt Bereiche mit unterschiedlichen Aufgaben oder Schutzbedürfnissen. Zusammen begrenzen sie unerwünschte Zugriffe und die Ausbreitung eines Vorfalls.","explanation":"1. Kommunikationsbedarf bestimmen: Notiere, welcher Client welchen Dienst auf welchem Server benötigt. Eine Regel braucht Quelle, Ziel, Protokoll, gegebenenfalls Port und Aktion. Ein Port bezeichnet hier einen Dienstendpunkt, keine physische Netzwerkbuchse.\n\n2. Regeln gezielt erlauben: Erlaube nur benötigte Verbindungen und berücksichtige die Reihenfolge der Regeln. Bei zustandsbehafteter Prüfung kann die Firewall Verbindungszustände verfolgen. Rückverkehr muss zum jeweiligen Regelwerk und Verbindungsmodell passen.\n\n3. Trennung und Prüfung: VLANs bilden getrennte Layer-2-Bereiche, sind aber allein keine vollständige Sicherheitskontrolle zwischen gerouteten Netzen. Prüfe sowohl erlaubte als auch verbotene Verbindungen. Dokumentiere den Zweck jeder Freigabe und entferne überflüssige Regeln.","sections":[{"title":"1. Kommunikationsbedarf bestimmen","body":"Notiere, welcher Client welchen Dienst auf welchem Server benötigt. Eine Regel braucht Quelle, Ziel, Protokoll, gegebenenfalls Port und Aktion. Ein Port bezeichnet hier einen Dienstendpunkt, keine physische Netzwerkbuchse."},{"title":"2. Regeln gezielt erlauben","body":"Erlaube nur benötigte Verbindungen und berücksichtige die Reihenfolge der Regeln. Bei zustandsbehafteter Prüfung kann die Firewall Verbindungszustände verfolgen. Rückverkehr muss zum jeweiligen Regelwerk und Verbindungsmodell passen."},{"title":"3. Trennung und Prüfung","body":"VLANs bilden getrennte Layer-2-Bereiche, sind aber allein keine vollständige Sicherheitskontrolle zwischen gerouteten Netzen. Prüfe sowohl erlaubte als auch verbotene Verbindungen. Dokumentiere den Zweck jeder Freigabe und entferne überflüssige Regeln."}],"example":"Gäste dürfen per HTTPS auf einen öffentlichen Webdienst zugreifen, aber nicht auf den internen Dateiserver. Du trennst das Gastnetz und setzt passende Regeln am Übergang. Der Test umfasst einen erfolgreichen Webzugriff und den nachweislich blockierten Zugriff auf die interne Freigabe.","mistake":"Ein VLAN trennt Broadcastdomänen. Ob zwischen VLANs Zugriff möglich ist, entscheiden zusätzlich Routing und passende Zugriffskontrollen.","terms":[["Firewall","Kontrollinstanz für Netzwerkverkehr."],["Quelle","Ursprung einer Verbindung oder eines Pakets."],["Ziel","Adressierter Empfänger."],["Port","Nummer eines Transportprotokoll-Endpunkts."],["Stateful Inspection","Prüfung unter Berücksichtigung des Verbindungszustands."],["Segmentierung","Aufteilung eines Netzes in sinnvoll getrennte Bereiche."]],"q":"Was gehört in eine nachvollziehbare Firewallregel?","options":["Nur der Name des Administrators","Quelle, Ziel, Dienst und Aktion","Nur das Kaufdatum des Routers"],"answer":1,"feedback":"Diese Angaben beschreiben, welcher Verkehr erlaubt oder blockiert werden soll.","remember":["Regeln beschreiben Quelle, Ziel, Dienst und Aktion.","Regelreihenfolge und Verbindungszustand beeinflussen das Ergebnis.","Erlaubte und verbotene Verbindungen getrennt testen."],"summary":"Wirksame Netztrennung kombiniert einen begründeten Kommunikationsplan mit passenden Zugriffskontrollen und Gegenproben."},"fa":{"title":"قواعد فایروال و جداسازی شبکه","goal":"قاعدهٔ فایروال را با مبدأ، مقصد، سرویس و عمل بخوانی.","definition":"فایروال ترافیک شبکه را بر اساس قواعد کنترل می‌کند. جداسازی شبکه، قسمت‌هایی با کار و نیاز حفاظتی متفاوت می‌سازد. این دو کار دسترسی ناخواسته و انتشار حادثه را محدود می‌کنند.","explanation":"۱. نیاز ارتباطی: بنویس کدام دستگاه به کدام سرویس روی کدام سرور نیاز دارد. قاعده شامل مبدأ، مقصد، پروتکل، در صورت نیاز پورت، و عمل است. پورت اینجا شمارهٔ نقطهٔ ارتباط سرویس است؛ نه سوکت فیزیکی.\n\n۲. اجازهٔ هدفمند: فقط ارتباط لازم را مجاز کن و ترتیب قواعد را در نظر بگیر. فایروال Stateful می‌تواند وضعیت اتصال را پیگیری کند. ترافیک پاسخ باید با مدل اتصال و قواعد آن سازگار باشد.\n\n۳. جداسازی و آزمایش: VLAN شبکهٔ لایهٔ دو را جدا می‌کند اما به‌تنهایی کنترل کامل ارتباط بین شبکه‌های Routeشده نیست. ارتباط مجاز و ممنوع را هر دو آزمایش کن. علت هر اجازه را ثبت و قواعد اضافی را حذف کن.","sections":[{"title":"۱. نیاز ارتباطی","body":"بنویس کدام دستگاه به کدام سرویس روی کدام سرور نیاز دارد. قاعده شامل مبدأ، مقصد، پروتکل، در صورت نیاز پورت، و عمل است. پورت اینجا شمارهٔ نقطهٔ ارتباط سرویس است؛ نه سوکت فیزیکی."},{"title":"۲. اجازهٔ هدفمند","body":"فقط ارتباط لازم را مجاز کن و ترتیب قواعد را در نظر بگیر. فایروال Stateful می‌تواند وضعیت اتصال را پیگیری کند. ترافیک پاسخ باید با مدل اتصال و قواعد آن سازگار باشد."},{"title":"۳. جداسازی و آزمایش","body":"VLAN شبکهٔ لایهٔ دو را جدا می‌کند اما به‌تنهایی کنترل کامل ارتباط بین شبکه‌های Routeشده نیست. ارتباط مجاز و ممنوع را هر دو آزمایش کن. علت هر اجازه را ثبت و قواعد اضافی را حذف کن."}],"example":"مهمان باید با HTTPS به وب‌سرویس عمومی برسد اما نباید فایل‌سرور داخلی را ببیند. شبکهٔ مهمان را جدا و گذرگاه را با قواعد مناسب کنترل می‌کنی. آزمایش شامل وب موفق و دسترسی مسدودشده به فایل داخلی است.","mistake":"VLAN دامنهٔ Broadcast را جدا می‌کند؛ ارتباط بین VLANها همچنین به Routing و کنترل دسترسی مربوط است.","terms":[["Firewall","کنترل‌کنندهٔ ترافیک شبکه."],["Quelle","مبدأ بسته یا اتصال."],["Ziel","گیرندهٔ مورد نظر."],["Port","شمارهٔ نقطهٔ ارتباط در پروتکل انتقال."],["Stateful Inspection","بررسی با توجه به وضعیت اتصال."],["Segmentierung","تقسیم شبکه به قسمت‌های جدا و هدفمند."]],"q":"چه چیزی باید در قاعدهٔ روشن فایروال باشد؟","options":["فقط نام مدیر","مبدأ، مقصد، سرویس و عمل","فقط تاریخ خرید روتر"],"answer":1,"feedback":"این موارد مشخص می‌کنند چه ترافیکی باید مجاز یا مسدود شود.","remember":["قاعده شامل مبدأ، مقصد، سرویس و عمل است.","ترتیب قواعد و وضعیت اتصال روی نتیجه اثر دارد.","ارتباط مجاز و ممنوع را جداگانه آزمایش کن."],"summary":"جداسازی مؤثر شبکه، طرح ارتباطی مستدل را با کنترل دسترسی و آزمایش حالت ممنوع ترکیب می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-security/kryptografie":{"de":{"title":"Verschlüsselung, Hash und Signatur","goal":"Du wählst das passende Verfahren für Geheimhaltung, Prüfen und Herkunftsnachweis.","definition":"Kryptografische Verfahren erfüllen unterschiedliche Aufgaben. Verschlüsselung schützt die Lesbarkeit, Hashverfahren bilden einen Prüfwert und digitale Signaturen verbinden eine Nachricht mit einem überprüfbaren Signaturschlüssel.","explanation":"1. Verschlüsselung: Symmetrische Verfahren verwenden einen gemeinsamen geheimen Schlüssel. Asymmetrische Verfahren arbeiten mit einem Schlüsselpaar. In realen Protokollen werden diese oft kombiniert: asymmetrische Mechanismen unterstützen den sicheren Aufbau, symmetrische Verschlüsselung schützt größere Datenmengen.\n\n2. Hashwert: Ein kryptografischer Hash bildet Eingaben auf einen Prüfwert fester Länge ab. Er ist keine umkehrbare Verschlüsselung. Ein erwarteter Hash kann Veränderungen erkennbar machen, wenn der Vergleichswert selbst aus einer vertrauenswürdigen Quelle stammt.\n\n3. Signatur und Vertrauen: Eine digitale Signatur wird mit einem privaten Schlüssel erstellt und mit dem passenden öffentlichen Schlüssel geprüft. Sie schützt nicht automatisch die Vertraulichkeit. Die Zuordnung des Schlüssels zum Absender muss vertrauenswürdig geprüft werden, etwa über eine passende Zertifikatskette.","sections":[{"title":"1. Verschlüsselung","body":"Symmetrische Verfahren verwenden einen gemeinsamen geheimen Schlüssel. Asymmetrische Verfahren arbeiten mit einem Schlüsselpaar. In realen Protokollen werden diese oft kombiniert: asymmetrische Mechanismen unterstützen den sicheren Aufbau, symmetrische Verschlüsselung schützt größere Datenmengen."},{"title":"2. Hashwert","body":"Ein kryptografischer Hash bildet Eingaben auf einen Prüfwert fester Länge ab. Er ist keine umkehrbare Verschlüsselung. Ein erwarteter Hash kann Veränderungen erkennbar machen, wenn der Vergleichswert selbst aus einer vertrauenswürdigen Quelle stammt."},{"title":"3. Signatur und Vertrauen","body":"Eine digitale Signatur wird mit einem privaten Schlüssel erstellt und mit dem passenden öffentlichen Schlüssel geprüft. Sie schützt nicht automatisch die Vertraulichkeit. Die Zuordnung des Schlüssels zum Absender muss vertrauenswürdig geprüft werden, etwa über eine passende Zertifikatskette."}],"example":"Du lädst ein Installationspaket. Ein geprüfter Hersteller-Signaturweg unterstützt den Herkunftsnachweis und die Integritätsprüfung. Ein bloßer Hash auf derselben manipulierten Downloadseite reicht nicht als verlässlicher Herkunftsnachweis. Vertrauliche Übertragung wird zusätzlich durch einen geeigneten verschlüsselten Kanal geschützt.","mistake":"Hashen bedeutet nicht verschlüsseln. Eine Signatur versteckt den Inhalt nicht.","terms":[["Symmetrisch","Verfahren mit gemeinsamem geheimem Schlüssel."],["Asymmetrisch","Verfahren mit öffentlichem und privatem Schlüssel."],["Hashwert","Prüfwert aus einer Hashfunktion."],["Digitale Signatur","Kryptografisch prüfbare Signatur einer Nachricht."],["Privater Schlüssel","Geheim zu haltender Teil eines Schlüsselpaares."],["Zertifikat","Signierte Bindung von Identitätsangaben an einen öffentlichen Schlüssel."]],"q":"Welches Verfahren macht einen Inhalt nicht automatisch geheim?","options":["Digitale Signatur","Geeignete Verschlüsselung","Verschlüsselter Transport"],"answer":0,"feedback":"Eine Signatur dient insbesondere der prüfbaren Signaturherkunft und Integrität; der Inhalt kann dabei lesbar bleiben.","remember":["Verschlüsselung, Hash und Signatur erfüllen verschiedene Zwecke.","Ein Hash ist nur mit vertrauenswürdigem Vergleichswert aussagekräftig.","Eine Signatur allein macht den Inhalt nicht geheim."],"summary":"Kryptografischer Schutz funktioniert, wenn Verfahren und Schlüsselvertrauen zum gewünschten Schutzziel passen."},"fa":{"title":"رمزنگاری، Hash و امضای دیجیتال","goal":"برای پنهان‌سازی، بررسی تغییر و بررسی امضا روش مناسب را انتخاب کنی.","definition":"روش‌های رمزنگاری یک کار واحد ندارند. Encryption خواندن داده را محدود می‌کند؛ Hash مقدار بررسی می‌سازد و امضای دیجیتال ارتباط داده با کلید امضا را قابل بررسی می‌کند.","explanation":"۱. رمزگذاری: روش متقارن کلید محرمانهٔ مشترک دارد. روش نامتقارن از جفت کلید استفاده می‌کند. پروتکل‌های واقعی اغلب هر دو را ترکیب می‌کنند؛ سازوکار نامتقارن به برقراری امن کمک می‌کند و رمز متقارن حجم داده را محافظت می‌کند.\n\n۲. Hash: تابع Hash رمزنگاری، ورودی را به مقدار با طول ثابت تبدیل می‌کند و رمزگذاری قابل بازگشت نیست. مقایسه با Hash مورد انتظار می‌تواند تغییر را نشان دهد؛ به شرطی که خود مقدار مرجع قابل اعتماد باشد.\n\n۳. امضا و اعتماد: امضا با کلید خصوصی ساخته و با کلید عمومی متناظر بررسی می‌شود. امضا لزوماً محتوا را پنهان نمی‌کند. ارتباط کلید با صاحب آن هم باید از راه معتبر مثل زنجیرهٔ گواهی مناسب بررسی شود.","sections":[{"title":"۱. رمزگذاری","body":"روش متقارن کلید محرمانهٔ مشترک دارد. روش نامتقارن از جفت کلید استفاده می‌کند. پروتکل‌های واقعی اغلب هر دو را ترکیب می‌کنند؛ سازوکار نامتقارن به برقراری امن کمک می‌کند و رمز متقارن حجم داده را محافظت می‌کند."},{"title":"۲. Hash","body":"تابع Hash رمزنگاری، ورودی را به مقدار با طول ثابت تبدیل می‌کند و رمزگذاری قابل بازگشت نیست. مقایسه با Hash مورد انتظار می‌تواند تغییر را نشان دهد؛ به شرطی که خود مقدار مرجع قابل اعتماد باشد."},{"title":"۳. امضا و اعتماد","body":"امضا با کلید خصوصی ساخته و با کلید عمومی متناظر بررسی می‌شود. امضا لزوماً محتوا را پنهان نمی‌کند. ارتباط کلید با صاحب آن هم باید از راه معتبر مثل زنجیرهٔ گواهی مناسب بررسی شود."}],"example":"برای بستهٔ نصب، امضای سازنده را از مسیر معتبر بررسی می‌کنی. Hash روی همان صفحهٔ دست‌کاری‌شده به‌تنهایی منبع واقعی را اثبات نمی‌کند. برای محرمانگی انتقال نیز کانال رمز‌شدهٔ مناسب لازم است.","mistake":"Hash رمزگذاری نیست و امضا هم خودبه‌خود محتوا را مخفی نمی‌کند.","terms":[["Symmetrisch","روش دارای کلید محرمانهٔ مشترک."],["Asymmetrisch","روش دارای کلید عمومی و خصوصی."],["Hashwert","مقدار بررسی خروجی تابع Hash."],["Digitale Signatur","امضای رمزنگاری‌شدهٔ قابل بررسی."],["Privater Schlüssel","قسمت محرمانهٔ جفت کلید."],["Zertifikat","پیوند امضاشدهٔ مشخصات هویت با کلید عمومی."]],"q":"کدام روش به‌تنهایی محتوا را محرمانه نمی‌کند؟","options":["امضای دیجیتال","رمزگذاری مناسب","انتقال رمز‌شده"],"answer":0,"feedback":"امضا برای بررسی امضا و یکپارچگی است؛ متن ممکن است همچنان خوانا بماند.","remember":["رمزگذاری، Hash و امضا هدف‌های متفاوت دارند.","Hash با مقدار مرجع قابل اعتماد معنا پیدا می‌کند.","امضا به‌تنهایی متن را محرمانه نمی‌کند."],"summary":"حفاظت رمزنگاری وقتی درست کار می‌کند که روش و اعتماد به کلید با هدف امنیتی سازگار باشد."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-security/patch":{"de":{"title":"Updates und Änderungen kontrolliert einführen","goal":"Du planst ein Update einschließlich Test, Rückfalloption und Funktionskontrolle.","definition":"Patchmanagement organisiert Sicherheits- und Fehlerkorrekturen für Systeme. Ein Patch verändert Software; deshalb muss er sowohl das Sicherheitsrisiko als auch mögliche Auswirkungen auf den Betrieb berücksichtigen.","explanation":"1. Erfassen und priorisieren: Eine aktuelle Inventarliste zeigt betroffene Systeme und Versionen. Bewerte Herstellerhinweise, Ausnutzbarkeit, Erreichbarkeit und geschäftliche Bedeutung. Eine kritisch verwundbare, öffentlich erreichbare Anwendung kann dringender sein als ein weniger relevantes internes System.\n\n2. Test und Freigabe: Prüfe Voraussetzungen und Abhängigkeiten. Plane Datensicherung, Wartungszeit und einen realistischen Rückfallweg. Teste in einer passenden Umgebung oder mit einer kontrollierten Pilotgruppe. Die zuständige Stelle muss Änderungen passend zum Betriebsprozess freigeben.\n\n3. Ausrollen und überprüfen: Verteile das Update nachvollziehbar. Prüfe danach Version, Dienststart und wichtige Geschäftsabläufe. Dokumentiere Erfolg, Fehler und Ausnahmen. Ein fehlgeschlagenes Update darf nicht still als erledigt in der Übersicht stehen.","sections":[{"title":"1. Erfassen und priorisieren","body":"Eine aktuelle Inventarliste zeigt betroffene Systeme und Versionen. Bewerte Herstellerhinweise, Ausnutzbarkeit, Erreichbarkeit und geschäftliche Bedeutung. Eine kritisch verwundbare, öffentlich erreichbare Anwendung kann dringender sein als ein weniger relevantes internes System."},{"title":"2. Test und Freigabe","body":"Prüfe Voraussetzungen und Abhängigkeiten. Plane Datensicherung, Wartungszeit und einen realistischen Rückfallweg. Teste in einer passenden Umgebung oder mit einer kontrollierten Pilotgruppe. Die zuständige Stelle muss Änderungen passend zum Betriebsprozess freigeben."},{"title":"3. Ausrollen und überprüfen","body":"Verteile das Update nachvollziehbar. Prüfe danach Version, Dienststart und wichtige Geschäftsabläufe. Dokumentiere Erfolg, Fehler und Ausnahmen. Ein fehlgeschlagenes Update darf nicht still als erledigt in der Übersicht stehen."}],"example":"Ein Update betrifft die Druckverwaltung. Du testest zunächst mit zwei unterschiedlichen Druckermodellen und einer Pilotgruppe. Nach Freigabe erfolgt der Rollout im Wartungsfenster. Anschließend prüfst du Ausdruck, Anmeldung und Ereignisprotokoll. Falls eine kritische Funktion ausfällt, wird der vorher geplante Rückfallweg genutzt.","mistake":"Eine Rückfalloption muss praktisch funktionieren; „irgendwie zurücksetzen“ ist kein belastbarer Plan.","terms":[["Patch","Korrektur oder Aktualisierung vorhandener Software."],["Inventar","Übersicht verwalteter Geräte, Software und Versionen."],["Pilotgruppe","Kleine ausgewählte Gruppe für kontrollierte Einführung."],["Rollback","Geplanter Rückweg zu einem vorherigen Zustand."],["Abhängigkeit","Voraussetzung durch eine andere Komponente."],["Change","Kontrolliert bearbeitete Änderung an einem Dienst oder System."]],"q":"Was gehört nach einem Update dazu?","options":["Nur den Installer schließen","Wichtige Dienste und Funktionen prüfen","Die Dokumentation löschen"],"answer":1,"feedback":"Erst eine Funktionsprüfung zeigt, ob der gewünschte Dienst nach der Änderung tatsächlich nutzbar ist.","remember":["Updates nach Betroffenheit und Risiko priorisieren.","Vor dem Rollout Test, Wartungszeit und Rückfallweg planen.","Nach der Installation Version und Geschäftsabläufe prüfen."],"summary":"Patchmanagement verbindet die zeitnahe Fehlerkorrektur mit einem kontrollierten und überprüften Betriebswechsel."},"fa":{"title":"به‌روزرسانی و تغییر کنترل‌شده","goal":"Update را همراه آزمایش، راه برگشت و بررسی عملکرد برنامه‌ریزی کنی.","definition":"Patchmanagement اصلاحات امنیتی و خطاهای نرم‌افزار را مدیریت می‌کند. چون Patch سیستم را تغییر می‌دهد، هم خطر امنیتی و هم اثر احتمالی روی کار شرکت باید دیده شود.","explanation":"۱. شناسایی و اولویت: فهرست دستگاه و نسخه نشان می‌دهد چه سیستم‌هایی درگیرند. اطلاعیهٔ سازنده، امکان سوءاستفاده، دسترسی از بیرون و اهمیت کاری را بسنج. برنامهٔ آسیب‌پذیر عمومی ممکن است فوری‌تر از سیستم داخلی کم‌اهمیت باشد.\n\n۲. آزمایش و اجازهٔ اجرا: پیش‌نیاز و وابستگی‌ها را بررسی کن. پشتیبان، زمان نگهداری و راه برگشت واقعی داشته باش. ابتدا در محیط مناسب یا گروه کوچک آزمایش کن. مسئول مربوط طبق فرایند شرکت تغییر را تأیید می‌کند.\n\n۳. انتشار و بررسی: Update را قابل پیگیری اجرا کن. سپس نسخه، شروع سرویس و کارهای مهم را آزمایش کن. موفقیت، خطا و موارد استثنا را ثبت کن؛ اجرای ناموفق نباید انجام‌شده حساب شود.","sections":[{"title":"۱. شناسایی و اولویت","body":"فهرست دستگاه و نسخه نشان می‌دهد چه سیستم‌هایی درگیرند. اطلاعیهٔ سازنده، امکان سوءاستفاده، دسترسی از بیرون و اهمیت کاری را بسنج. برنامهٔ آسیب‌پذیر عمومی ممکن است فوری‌تر از سیستم داخلی کم‌اهمیت باشد."},{"title":"۲. آزمایش و اجازهٔ اجرا","body":"پیش‌نیاز و وابستگی‌ها را بررسی کن. پشتیبان، زمان نگهداری و راه برگشت واقعی داشته باش. ابتدا در محیط مناسب یا گروه کوچک آزمایش کن. مسئول مربوط طبق فرایند شرکت تغییر را تأیید می‌کند."},{"title":"۳. انتشار و بررسی","body":"Update را قابل پیگیری اجرا کن. سپس نسخه، شروع سرویس و کارهای مهم را آزمایش کن. موفقیت، خطا و موارد استثنا را ثبت کن؛ اجرای ناموفق نباید انجام‌شده حساب شود."}],"example":"Update روی مدیریت چاپ اثر دارد. ابتدا دو مدل پرینتر و گروه آزمایشی را بررسی می‌کنی. پس از تأیید، در زمان نگهداری اجرا می‌شود. چاپ، ورود و لاگ بررسی می‌شود و برای خرابی مهم راه برگشت از قبل آماده است.","mistake":"راه برگشت باید عملی باشد؛ «یک‌جوری برمی‌گردانیم» برنامهٔ معتبر نیست.","terms":[["Patch","اصلاح یا به‌روزرسانی نرم‌افزار."],["Inventar","فهرست دستگاه، نرم‌افزار و نسخه."],["Pilotgruppe","گروه کوچک برای شروع کنترل‌شده."],["Rollback","راه برنامه‌ریزی‌شده به وضعیت قبلی."],["Abhängigkeit","نیاز یک جزء به جزء دیگر."],["Change","تغییر کنترل‌شدهٔ سرویس یا سیستم."]],"q":"پس از Update چه کاری لازم است؟","options":["فقط بستن Installer","بررسی سرویس‌ها و عملکردهای مهم","حذف مستندات"],"answer":1,"feedback":"فقط آزمایش عملکرد نشان می‌دهد سرویس پس از تغییر قابل استفاده است.","remember":["Update را بر پایهٔ درگیری سیستم و خطر اولویت‌بندی کن.","پیش از انتشار، تست، زمان تعمیر و راه برگشت را آماده کن.","پس از نصب، نسخه و کارهای مهم را بررسی کن."],"summary":"مدیریت Patch اصلاح به‌موقع خطا را با تغییر کنترل‌شده و بررسی‌شدهٔ سیستم همراه می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-security/notfall":{"de":{"title":"Notfälle und Sicherheitsvorfälle behandeln","goal":"Du ordnest Erkennen, Eindämmen, Wiederherstellen und Nachbereiten in einen sinnvollen Ablauf.","definition":"Ein Sicherheitsvorfall ist ein Ereignis, das die Sicherheit von Informationen oder Diensten beeinträchtigt oder bedroht. Notfallmanagement bereitet den Umgang mit schweren Störungen vor, damit im Ernstfall Zuständigkeiten und wichtige Schritte bekannt sind.","explanation":"1. Erkennen und melden: Beobachtungen werden über den vorgesehenen Meldeweg weitergegeben. Beschreibe Zeitpunkt, betroffene Systeme und sichtbare Auswirkungen. Handle nach dem Notfallplan; voreilige Änderungen können wichtige Spuren oder die Betriebsfähigkeit beeinträchtigen.\n\n2. Eindämmen und analysieren: Begrenze die Ausbreitung mit abgestimmten Maßnahmen. Zuständige Personen bewerten Umfang und Ursache. Technische Beweise und Protokolle werden nach dem festgelegten Verfahren gesichert. Nicht jede Person darf eigenmächtig Systeme löschen oder abschalten.\n\n3. Wiederherstellen und lernen: Stelle einen vertrauenswürdigen Betriebszustand her und prüfe die Funktion. Überwache besonders sorgfältig. In der Nachbereitung werden Ursachen, wirksame Schritte und Verbesserungen dokumentiert. Übungen zeigen vorher, ob der Plan verständlich und ausführbar ist.","sections":[{"title":"1. Erkennen und melden","body":"Beobachtungen werden über den vorgesehenen Meldeweg weitergegeben. Beschreibe Zeitpunkt, betroffene Systeme und sichtbare Auswirkungen. Handle nach dem Notfallplan; voreilige Änderungen können wichtige Spuren oder die Betriebsfähigkeit beeinträchtigen."},{"title":"2. Eindämmen und analysieren","body":"Begrenze die Ausbreitung mit abgestimmten Maßnahmen. Zuständige Personen bewerten Umfang und Ursache. Technische Beweise und Protokolle werden nach dem festgelegten Verfahren gesichert. Nicht jede Person darf eigenmächtig Systeme löschen oder abschalten."},{"title":"3. Wiederherstellen und lernen","body":"Stelle einen vertrauenswürdigen Betriebszustand her und prüfe die Funktion. Überwache besonders sorgfältig. In der Nachbereitung werden Ursachen, wirksame Schritte und Verbesserungen dokumentiert. Übungen zeigen vorher, ob der Plan verständlich und ausführbar ist."}],"example":"Ein Client verschlüsselt plötzlich Dateien. Du meldest das Ereignis sofort, dokumentierst die Beobachtung und lässt den Zugang nach festgelegtem Plan isolieren. Das zuständige Team prüft weitere Systeme und die Wiederherstellung aus geprüften Sicherungen. Ein einfaches Neustarten würde die Ursache noch nicht beseitigen.","mistake":"Wiederherstellung ohne Ursachenbehebung kann dazu führen, dass derselbe Angriff erneut wirksam wird.","terms":[["Vorfall","Sicherheitsrelevantes Ereignis mit möglicher Beeinträchtigung."],["Meldeweg","Vorgesehener Kommunikationsweg für Ereignisse."],["Eindämmung","Begrenzung weiterer Auswirkungen."],["Notfallplan","Vorbereiteter Ablauf für schwere Störungen."],["Wiederanlauf","Kontrollierte Rückkehr zum nutzbaren Betrieb."],["Nachbereitung","Auswertung eines Ereignisses zur Verbesserung."]],"q":"Warum wird nach einem Vorfall eine Nachbereitung durchgeführt?","options":["Damit keine Verantwortung mehr besteht","Um Ursachen und Verbesserungen festzuhalten","Nur um die Uhrzeit zu ändern"],"answer":1,"feedback":"Eine dokumentierte Auswertung verbessert Maßnahmen, Abläufe und Vorbereitung.","remember":["Beobachtungen schnell über den vorgesehenen Weg melden.","Eindämmung und Spurensicherung müssen abgestimmt erfolgen.","Wiederherstellung braucht Funktionsprüfung und Nachbereitung."],"summary":"Ein geübter Notfallablauf begrenzt Schäden und ermöglicht die kontrollierte Rückkehr zu einem vertrauenswürdigen Betrieb."},"fa":{"title":"رسیدگی به حادثه و وضعیت اضطراری","goal":"تشخیص، مهار، بازیابی و بررسی پس از حادثه را مرتب کنی.","definition":"حادثهٔ امنیتی رویدادی است که امنیت داده یا سرویس را تهدید یا مختل می‌کند. مدیریت اضطراری از قبل مسئول‌ها و مراحل اختلال شدید را مشخص می‌کند تا هنگام بحران تصمیم‌ها روشن باشد.","explanation":"۱. تشخیص و گزارش: مشاهده را از راه تعیین‌شده گزارش کن. زمان، سیستم‌های درگیر و اثر قابل مشاهده را بنویس. طبق برنامه عمل کن؛ تغییر عجولانه ممکن است آثار مهم یا عملکرد سیستم را از بین ببرد.\n\n۲. مهار و تحلیل: با اقدام هماهنگ جلوی گسترش را بگیر. افراد مسئول دامنه و علت را بررسی می‌کنند. لاگ و شواهد طبق روش تعیین‌شده حفظ می‌شود. هر شخص اجازه ندارد خودسرانه سیستم را حذف یا خاموش کند.\n\n۳. بازیابی و یادگیری: وضعیت قابل اعتماد را بازگردان و کارکرد را آزمایش کن. نظارت بیشتری انجام بده. سپس علت، اقدامات مؤثر و بهبودهای لازم ثبت می‌شود. تمرین قبلی نشان می‌دهد برنامه قابل فهم و اجرا هست یا نه.","sections":[{"title":"۱. تشخیص و گزارش","body":"مشاهده را از راه تعیین‌شده گزارش کن. زمان، سیستم‌های درگیر و اثر قابل مشاهده را بنویس. طبق برنامه عمل کن؛ تغییر عجولانه ممکن است آثار مهم یا عملکرد سیستم را از بین ببرد."},{"title":"۲. مهار و تحلیل","body":"با اقدام هماهنگ جلوی گسترش را بگیر. افراد مسئول دامنه و علت را بررسی می‌کنند. لاگ و شواهد طبق روش تعیین‌شده حفظ می‌شود. هر شخص اجازه ندارد خودسرانه سیستم را حذف یا خاموش کند."},{"title":"۳. بازیابی و یادگیری","body":"وضعیت قابل اعتماد را بازگردان و کارکرد را آزمایش کن. نظارت بیشتری انجام بده. سپس علت، اقدامات مؤثر و بهبودهای لازم ثبت می‌شود. تمرین قبلی نشان می‌دهد برنامه قابل فهم و اجرا هست یا نه."}],"example":"یک کلاینت ناگهان فایل‌ها را رمز می‌کند. فوراً گزارش می‌دهی، مشاهده را ثبت می‌کنی و دسترسی طبق برنامه جدا می‌شود. تیم مسئول سیستم‌های دیگر و بازیابی از نسخهٔ سالم را بررسی می‌کند. راه‌اندازی دوبارهٔ ساده علت را برطرف نمی‌کند.","mistake":"بازیابی بدون رفع علت می‌تواند باعث تکرار همان حمله شود.","terms":[["Vorfall","رویداد دارای اثر یا خطر امنیتی."],["Meldeweg","راه مشخص گزارش حادثه."],["Eindämmung","محدودکردن پیامد و گسترش."],["Notfallplan","برنامهٔ آمادهٔ اختلال شدید."],["Wiederanlauf","بازگشت کنترل‌شده به کار."],["Nachbereitung","ارزیابی پس از رویداد برای بهبود."]],"q":"چرا پس از حادثه بررسی نهایی انجام می‌شود؟","options":["برای حذف مسئولیت","برای ثبت علت و بهبودها","فقط برای تغییر ساعت"],"answer":1,"feedback":"ارزیابی ثبت‌شده به بهترشدن اقدامات، روش‌ها و آمادگی کمک می‌کند.","remember":["مشاهده را سریع از مسیر تعیین‌شده گزارش کن.","مهار و حفظ شواهد باید هماهنگ باشد.","بازیابی به آزمایش عملکرد و بررسی پس از حادثه نیاز دارد."],"summary":"برنامهٔ اضطراری تمرین‌شده آسیب را محدود و بازگشت کنترل‌شده به کار قابل اعتماد را ممکن می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/anforderungen":{"de":{"title":"Kundenanforderungen und Projektziel klären","goal":"Du formulierst aus einem Wunsch eine messbare Anforderung mit Abnahmekriterium.","definition":"Eine Anforderungsanalyse klärt, welches Problem ein Kunde lösen möchte und welche Bedingungen die Lösung erfüllen muss. Das Projektziel beschreibt den gewünschten Zustand; Anforderungen machen diesen Zustand konkret überprüfbar.","explanation":"1. Ist-Zustand und Bedarf: Erfrage Arbeitsabläufe, Probleme, Beteiligte und vorhandene Systeme. Unterscheide den eigentlichen Bedarf von einer schon vorgeschlagenen Technik. „Wir brauchen einen neuen Server“ erklärt noch nicht, welches Problem gelöst werden soll.\n\n2. Soll-Zustand beschreiben: Funktionale Anforderungen sagen, was eine Lösung leisten soll. Qualitätsanforderungen beschreiben beispielsweise Antwortzeit, Sicherheit oder Verfügbarkeit. Rahmenbedingungen begrenzen Budget, Termin, Plattform oder benötigte Schnittstellen.\n\n3. Kriterien abstimmen: Formuliere zu wichtigen Anforderungen ein Test- oder Abnahmekriterium. Kläre Prioritäten und ausdrücklich ausgeschlossene Aufgaben. Halte Annahmen fest und bestätige sie mit den zuständigen Beteiligten. So lassen sich spätere Änderungen bewusst bewerten.","sections":[{"title":"1. Ist-Zustand und Bedarf","body":"Erfrage Arbeitsabläufe, Probleme, Beteiligte und vorhandene Systeme. Unterscheide den eigentlichen Bedarf von einer schon vorgeschlagenen Technik. „Wir brauchen einen neuen Server“ erklärt noch nicht, welches Problem gelöst werden soll."},{"title":"2. Soll-Zustand beschreiben","body":"Funktionale Anforderungen sagen, was eine Lösung leisten soll. Qualitätsanforderungen beschreiben beispielsweise Antwortzeit, Sicherheit oder Verfügbarkeit. Rahmenbedingungen begrenzen Budget, Termin, Plattform oder benötigte Schnittstellen."},{"title":"3. Kriterien abstimmen","body":"Formuliere zu wichtigen Anforderungen ein Test- oder Abnahmekriterium. Kläre Prioritäten und ausdrücklich ausgeschlossene Aufgaben. Halte Annahmen fest und bestätige sie mit den zuständigen Beteiligten. So lassen sich spätere Änderungen bewusst bewerten."}],"example":"Der Kunde sagt: „Der Dateizugriff ist zu langsam.“ Du misst den Ist-Zustand und vereinbarst einen Test: Eine definierte 500-MB-Datei soll unter festgelegten Netzbedingungen innerhalb von 15 Sekunden bereitgestellt werden. Damit gibt es eine prüfbare Anforderung statt nur des Wortes „schnell“.","mistake":"Ein technischer Produktname ersetzt keine Anforderung. Zuerst muss klar sein, welches überprüfbare Ergebnis gebraucht wird.","terms":[["Ist-Zustand","Erfasste Ausgangssituation."],["Soll-Zustand","Gewünschte Situation nach dem Projekt."],["Funktionale Anforderung","Benötigte Funktion der Lösung."],["Qualitätsanforderung","Gewünschte Eigenschaft wie Leistung oder Sicherheit."],["Rahmenbedingung","Vorgegebene Begrenzung des Projekts."],["Abnahmekriterium","Vereinbarter Maßstab für die Prüfung eines Ergebnisses."]],"q":"Welche Formulierung ist am besten überprüfbar?","options":["Die Lösung soll schön schnell sein.","Die festgelegte Datei wird unter definierten Bedingungen in höchstens 15 Sekunden übertragen.","Wir nehmen ein bekanntes Produkt."],"answer":1,"feedback":"Testdaten, Bedingungen und Grenzwert machen die Anforderung messbar.","remember":["Erst den Bedarf klären, dann Produkte auswählen.","Funktion, Qualität und Rahmenbedingungen getrennt beschreiben.","Abnahmekriterien machen Anforderungen prüfbar."],"summary":"Eine verständliche Anforderungsanalyse übersetzt den Kundenwunsch in ein gemeinsames, messbares Projektziel."},"fa":{"title":"روشن‌کردن نیاز مشتری و هدف پروژه","goal":"از خواستهٔ مشتری یک نیاز قابل سنجش و معیار تحویل بسازی.","definition":"تحلیل نیاز روشن می‌کند مشتری چه مسئله‌ای دارد و راه‌حل باید چه شرایطی را برآورده کند. هدف پروژه وضعیت مطلوب را می‌گوید و نیازها آن را قابل آزمایش می‌کنند.","explanation":"۱. وضعیت فعلی و نیاز: روش کار، مشکل، افراد درگیر و سیستم فعلی را بپرس. نیاز واقعی را از فناوری پیشنهادی جدا کن. جملهٔ «سرور جدید می‌خواهیم» هنوز علت و مسئله را توضیح نمی‌دهد.\n\n۲. وضعیت مطلوب: نیاز عملکردی می‌گوید راه‌حل چه کاری انجام دهد. نیاز کیفی، زمان پاسخ، امنیت یا دسترس‌پذیری را مشخص می‌کند. محدودیت‌ها بودجه، زمان، پلتفرم و رابط لازم را تعیین می‌کنند.\n\n۳. توافق روی معیار: برای نیاز مهم معیار آزمایش یا پذیرش بنویس. اولویت و کارهای خارج از پروژه را روشن کن. فرض‌ها را ثبت و با مسئول مربوط تأیید کن تا تغییر بعدی آگاهانه بررسی شود.","sections":[{"title":"۱. وضعیت فعلی و نیاز","body":"روش کار، مشکل، افراد درگیر و سیستم فعلی را بپرس. نیاز واقعی را از فناوری پیشنهادی جدا کن. جملهٔ «سرور جدید می‌خواهیم» هنوز علت و مسئله را توضیح نمی‌دهد."},{"title":"۲. وضعیت مطلوب","body":"نیاز عملکردی می‌گوید راه‌حل چه کاری انجام دهد. نیاز کیفی، زمان پاسخ، امنیت یا دسترس‌پذیری را مشخص می‌کند. محدودیت‌ها بودجه، زمان، پلتفرم و رابط لازم را تعیین می‌کنند."},{"title":"۳. توافق روی معیار","body":"برای نیاز مهم معیار آزمایش یا پذیرش بنویس. اولویت و کارهای خارج از پروژه را روشن کن. فرض‌ها را ثبت و با مسئول مربوط تأیید کن تا تغییر بعدی آگاهانه بررسی شود."}],"example":"مشتری می‌گوید دسترسی فایل کند است. وضعیت فعلی را اندازه می‌گیری و توافق می‌کنی فایل مشخص ۵۰۰ مگابایتی در شرایط شبکهٔ معلوم حداکثر در ۱۵ ثانیه منتقل شود. اکنون به جای «سریع»، نیاز قابل بررسی داری.","mistake":"نام یک محصول جای نیاز را نمی‌گیرد؛ ابتدا نتیجهٔ قابل آزمایش را مشخص کن.","terms":[["Ist-Zustand","وضعیت فعلی ثبت‌شده."],["Soll-Zustand","وضعیت مطلوب پس از پروژه."],["Funktionale Anforderung","کاری که راه‌حل باید انجام دهد."],["Qualitätsanforderung","ویژگی مورد انتظار مثل سرعت یا امنیت."],["Rahmenbedingung","محدودیت تعیین‌شدهٔ پروژه."],["Abnahmekriterium","معیار توافق‌شده برای پذیرش نتیجه."]],"q":"کدام جمله قابل آزمایش‌تر است؟","options":["سیستم خیلی سریع باشد.","فایل مشخص در شرایط معلوم حداکثر در ۱۵ ثانیه منتقل شود.","یک محصول معروف بگیریم."],"answer":1,"feedback":"دادهٔ آزمایش، شرایط و حد زمانی نیاز را قابل سنجش می‌کنند.","remember":["اول نیاز را روشن کن و بعد محصول را انتخاب کن.","کارکرد، کیفیت و محدودیت را جدا بنویس.","معیار پذیرش، نیاز را قابل آزمایش می‌کند."],"summary":"تحلیل نیازِ روشن، خواستهٔ مشتری را به هدف مشترک و قابل سنجش پروژه تبدیل می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/varianten":{"de":{"title":"Lösungsvarianten mit Kriterien vergleichen","goal":"Du führst einen einfachen gewichteten Vergleich durch und erklärst seine Grenzen.","definition":"Ein Variantenvergleich stellt mehrere geeignete Lösungen nach denselben Kriterien gegenüber. Er hilft, eine Entscheidung nachvollziehbar zu begründen. Die teuerste oder bekannteste Lösung ist nicht automatisch die passende.","explanation":"1. Muss-Kriterien prüfen: Muss-Kriterien sind zwingende Anforderungen, etwa eine benötigte Schnittstelle oder ein verbindliches Budget. Eine Variante, die ein echtes Muss-Kriterium nicht erfüllt, wird ausgeschlossen oder muss angepasst werden, bevor sie weiter bewertet wird.\n\n2. Gewichtete Bewertung: Für geeignete Varianten definierst du Kriterien und Gewichte. Gewichte drücken die Wichtigkeit aus; Punkte bewerten die Erfüllung nach einer einheitlichen Skala. Multipliziere Punkte mit Gewicht und addiere die Ergebnisse. Dokumentiere, worauf die Punktwerte beruhen.\n\n3. Ergebnis prüfen: Eine Nutzwertzahl strukturiert die Entscheidung, ist aber kein objektiver Naturwert. Kleine Änderungen der Gewichte können die Rangfolge ändern. Prüfe außerdem Risiken, Betriebskosten, Sicherheit und Abhängigkeiten. Stimme die begründete Auswahl mit dem Kunden ab.","sections":[{"title":"1. Muss-Kriterien prüfen","body":"Muss-Kriterien sind zwingende Anforderungen, etwa eine benötigte Schnittstelle oder ein verbindliches Budget. Eine Variante, die ein echtes Muss-Kriterium nicht erfüllt, wird ausgeschlossen oder muss angepasst werden, bevor sie weiter bewertet wird."},{"title":"2. Gewichtete Bewertung","body":"Für geeignete Varianten definierst du Kriterien und Gewichte. Gewichte drücken die Wichtigkeit aus; Punkte bewerten die Erfüllung nach einer einheitlichen Skala. Multipliziere Punkte mit Gewicht und addiere die Ergebnisse. Dokumentiere, worauf die Punktwerte beruhen."},{"title":"3. Ergebnis prüfen","body":"Eine Nutzwertzahl strukturiert die Entscheidung, ist aber kein objektiver Naturwert. Kleine Änderungen der Gewichte können die Rangfolge ändern. Prüfe außerdem Risiken, Betriebskosten, Sicherheit und Abhängigkeiten. Stimme die begründete Auswahl mit dem Kunden ab."}],"example":"Kriterien: Leistung mit Gewicht 3 und Administrierbarkeit mit Gewicht 2. Variante A bekommt 4 und 2 Punkte: 3×4 + 2×2 = 16. Variante B bekommt 3 und 4 Punkte: 3×3 + 2×4 = 17. Bei dieser begründeten Gewichtung liegt B knapp vorn; die Punkteskala muss für beide gleich sein.","mistake":"Ein nicht erfülltes Muss-Kriterium darf nicht durch viele Punkte bei unwichtigen Eigenschaften verdeckt werden.","terms":[["Variante","Mögliche Ausführung einer Lösung."],["Muss-Kriterium","Zwingend zu erfüllende Bedingung."],["Gewicht","Festgelegte Wichtigkeit eines Kriteriums."],["Bewertungsskala","Einheitlicher Maßstab für Punkte."],["Nutzwert","Zusammengefasster bewerteter Nutzen."],["Sensitivität","Änderung des Ergebnisses bei veränderten Annahmen."]],"q":"Was geschieht mit einer Variante, die ein echtes Muss-Kriterium nicht erfüllt?","options":["Sie gewinnt automatisch.","Sie muss ausgeschlossen oder entsprechend angepasst werden.","Man ignoriert das Kriterium nachträglich."],"answer":1,"feedback":"Zwingende Anforderungen müssen zuerst erfüllt sein; eine Punktesumme ersetzt das nicht.","remember":["Muss-Kriterien vor der Punktebewertung prüfen.","Gewichte und Skalen müssen für alle Varianten gleich gelten.","Ein Nutzwert braucht begründete Annahmen und eine Plausibilitätsprüfung."],"summary":"Ein Variantenvergleich begründet eine passende Auswahl, indem er zwingende Anforderungen zuerst und bewertbare Vorteile danach prüft."},"fa":{"title":"مقایسهٔ راه‌حل‌ها با معیار","goal":"یک مقایسهٔ وزن‌دار ساده انجام بدهی و محدودیت آن را بفهمی.","definition":"مقایسهٔ گزینه‌ها چند راه‌حل مناسب را با معیار یکسان می‌سنجد تا تصمیم دلیل روشن داشته باشد. گران‌ترین یا معروف‌ترین محصول لزوماً مناسب‌ترین نیست.","explanation":"۱. شرط‌های ضروری: شرط ضروری مثل رابط لازم یا سقف قطعی بودجه باید تأمین شود. گزینهٔ نامناسب پیش از امتیازدهی حذف می‌شود یا باید اصلاح شود.\n\n۲. ارزیابی وزن‌دار: برای گزینه‌های مناسب معیار و وزن تعریف کن. وزن اهمیت را نشان می‌دهد و امتیاز میزان برآورده‌شدن را با مقیاس مشترک می‌سنجد. امتیاز را در وزن ضرب و نتیجه‌ها را جمع کن. دلیل امتیازها باید ثبت شود.\n\n۳. بررسی نتیجه: عدد Nutzwert تصمیم را منظم می‌کند اما حقیقت مطلق نیست. تغییر کوچک وزن ممکن است رتبه را عوض کند. خطر، هزینهٔ نگهداری، امنیت و وابستگی را هم بررسی و انتخاب را با مشتری توافق کن.","sections":[{"title":"۱. شرط‌های ضروری","body":"شرط ضروری مثل رابط لازم یا سقف قطعی بودجه باید تأمین شود. گزینهٔ نامناسب پیش از امتیازدهی حذف می‌شود یا باید اصلاح شود."},{"title":"۲. ارزیابی وزن‌دار","body":"برای گزینه‌های مناسب معیار و وزن تعریف کن. وزن اهمیت را نشان می‌دهد و امتیاز میزان برآورده‌شدن را با مقیاس مشترک می‌سنجد. امتیاز را در وزن ضرب و نتیجه‌ها را جمع کن. دلیل امتیازها باید ثبت شود."},{"title":"۳. بررسی نتیجه","body":"عدد Nutzwert تصمیم را منظم می‌کند اما حقیقت مطلق نیست. تغییر کوچک وزن ممکن است رتبه را عوض کند. خطر، هزینهٔ نگهداری، امنیت و وابستگی را هم بررسی و انتخاب را با مشتری توافق کن."}],"example":"کارایی وزن ۳ و مدیریت‌پذیری وزن ۲ دارد. A امتیاز ۴ و ۲ می‌گیرد: ۳×۴ + ۲×۲ = ۱۶. B امتیاز ۳ و ۴ می‌گیرد: ۳×۳ + ۲×۴ = ۱۷. با این وزن‌ها B کمی بهتر است و مقیاس امتیاز هر دو باید یکسان باشد.","mistake":"امتیاز زیاد در ویژگی کم‌اهمیت نباید نبود یک شرط ضروری را پنهان کند.","terms":[["Variante","یکی از راه‌های اجرای راه‌حل."],["Muss-Kriterium","شرطی که حتماً باید تأمین شود."],["Gewicht","مقدار اهمیت معیار."],["Bewertungsskala","مقیاس یکسان امتیازدهی."],["Nutzwert","فایدهٔ ارزیابی‌شده و جمع‌بندی‌شده."],["Sensitivität","تغییر نتیجه با تغییر فرض‌ها."]],"q":"گزینه‌ای که شرط ضروری را ندارد چه می‌شود؟","options":["خودکار برنده می‌شود.","باید حذف یا برای تأمین شرط اصلاح شود.","شرط را پس از مقایسه نادیده می‌گیریم."],"answer":1,"feedback":"ابتدا نیاز ضروری باید تأمین شود؛ جمع امتیاز جای آن را نمی‌گیرد.","remember":["شرط ضروری را پیش از امتیازدهی بررسی کن.","وزن و مقیاس برای همهٔ گزینه‌ها یکسان باشد.","عدد Nutzwert به فرض مستدل و بررسی منطقی نیاز دارد."],"summary":"مقایسهٔ گزینه‌ها ابتدا شرط‌های ضروری و سپس مزیت‌های قابل ارزیابی را می‌سنجد تا انتخاب دلیل روشن داشته باشد."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/planung":{"de":{"title":"Arbeitspakete, Zeiten und Abhängigkeiten","goal":"Du zerlegst ein Projekt in prüfbare Arbeitspakete und erkennst Zeitabhängigkeiten.","definition":"Projektplanung ordnet Aufgaben, Ressourcen und Termine so, dass ein vereinbartes Ergebnis erreichbar wird. Ein Plan zeigt nicht nur, was zu tun ist, sondern auch, in welcher Reihenfolge und mit welchen Voraussetzungen.","explanation":"1. Arbeitspakete bilden: Zerlege das Ergebnis in überschaubare Aufgaben. Jedes Arbeitspaket erhält Ergebnis, Verantwortung und geschätzten Aufwand. „Netzwerk fertig machen“ ist zu ungenau; „VLAN-Konfiguration dokumentiert und getestet“ liefert einen prüfbaren Abschluss.\n\n2. Reihenfolge und Ressourcen: Manche Aufgaben können parallel laufen, andere benötigen ein vorheriges Ergebnis. Aufwand ist benötigte Arbeitszeit; Dauer ist die verstrichene Zeit. Eine Stunde Arbeit kann wegen einer Lieferfrist erst nächste Woche abgeschlossen sein. Berücksichtige verfügbare Personen und Geräte.\n\n3. Meilensteine und Kontrolle: Ein Meilenstein markiert einen wichtigen erreichten Zustand, zum Beispiel die bestätigte Testfreigabe. Vergleiche während des Projekts Plan und Ist. Bewerte Abweichungen früh und stimme Änderungen ab, statt den Plan erst am Ende passend zu schreiben.","sections":[{"title":"1. Arbeitspakete bilden","body":"Zerlege das Ergebnis in überschaubare Aufgaben. Jedes Arbeitspaket erhält Ergebnis, Verantwortung und geschätzten Aufwand. „Netzwerk fertig machen“ ist zu ungenau; „VLAN-Konfiguration dokumentiert und getestet“ liefert einen prüfbaren Abschluss."},{"title":"2. Reihenfolge und Ressourcen","body":"Manche Aufgaben können parallel laufen, andere benötigen ein vorheriges Ergebnis. Aufwand ist benötigte Arbeitszeit; Dauer ist die verstrichene Zeit. Eine Stunde Arbeit kann wegen einer Lieferfrist erst nächste Woche abgeschlossen sein. Berücksichtige verfügbare Personen und Geräte."},{"title":"3. Meilensteine und Kontrolle","body":"Ein Meilenstein markiert einen wichtigen erreichten Zustand, zum Beispiel die bestätigte Testfreigabe. Vergleiche während des Projekts Plan und Ist. Bewerte Abweichungen früh und stimme Änderungen ab, statt den Plan erst am Ende passend zu schreiben."}],"example":"Die Konfiguration dauert 3 Stunden, der Test 2 Stunden. Der Test beginnt erst nach der Konfiguration. Zusammen brauchen diese abhängigen Aufgaben mindestens 5 Stunden Arbeitszeit; eine zusätzliche Lieferfrist oder fehlende Testperson kann die Kalenderdauer verlängern. Dokumentation kann teilweise parallel vorbereitet werden.","mistake":"Aufwand und Dauer sind unterschiedliche Größen. Drei Personen machen eine nicht teilbare Aufgabe nicht automatisch dreimal schneller.","terms":[["Arbeitspaket","Abgegrenzte Aufgabe mit Ergebnis und Verantwortung."],["Aufwand","Benötigte Arbeitszeit."],["Dauer","Verstrichener Zeitraum einer Aufgabe."],["Abhängigkeit","Eine Aufgabe benötigt ein vorheriges Ergebnis."],["Meilenstein","Wichtiger, überprüfbarer Projektzustand."],["Plan-Ist-Vergleich","Gegenüberstellung geplanter und tatsächlicher Werte."]],"q":"Was beschreibt den Aufwand?","options":["Die benötigte Arbeitszeit","Immer die gesamte Kalenderdauer","Nur den Liefertermin"],"answer":0,"feedback":"Aufwand zählt Arbeit; Dauer berücksichtigt den zeitlichen Ablauf und mögliche Wartezeiten.","remember":["Arbeitspakete brauchen Ergebnis, Verantwortung und Aufwand.","Aufwand ist Arbeitszeit; Dauer ist verstrichene Zeit.","Abhängigkeiten und Ressourcen begrenzen mögliche Parallelität."],"summary":"Ein nutzbarer Projektplan verbindet überprüfbare Ergebnisse mit realistischen Reihenfolgen, Ressourcen und laufender Kontrolle."},"fa":{"title":"بستهٔ کاری، زمان و وابستگی","goal":"پروژه را به کارهای قابل بررسی تقسیم و وابستگی زمانی را تشخیص بدهی.","definition":"برنامه‌ریزی پروژه کار، منابع و زمان را برای رسیدن به نتیجه مرتب می‌کند. برنامه باید نشان دهد چه کاری با چه ترتیب و چه پیش‌نیازی انجام می‌شود.","explanation":"۱. بستهٔ کاری: نتیجه را به وظیفه‌های قابل مدیریت تقسیم کن. هر بسته نتیجه، مسئول و برآورد زمان کار دارد. «شبکه را تمام کن» مبهم است؛ «VLAN تنظیم، مستند و آزمایش شده» پایان مشخص دارد.\n\n۲. ترتیب و منابع: بعضی کارها هم‌زمان و بعضی پس از کار قبلی ممکن‌اند. Aufwand زمان کار لازم است و Dauer زمان سپری‌شده. یک ساعت کار به دلیل انتظار قطعه شاید هفتهٔ بعد تمام شود. زمان افراد و دستگاه‌ها را هم لحاظ کن.\n\n۳. نقطهٔ عطف و کنترل: نقطهٔ عطف وضعیت مهم قابل بررسی است؛ مثلاً تأیید آمادگی آزمایش. در طول پروژه وضعیت واقعی را با برنامه مقایسه کن و انحراف را زود بررسی کن؛ نه اینکه آخر کار برنامه را مطابق گذشته بازنویسی کنی.","sections":[{"title":"۱. بستهٔ کاری","body":"نتیجه را به وظیفه‌های قابل مدیریت تقسیم کن. هر بسته نتیجه، مسئول و برآورد زمان کار دارد. «شبکه را تمام کن» مبهم است؛ «VLAN تنظیم، مستند و آزمایش شده» پایان مشخص دارد."},{"title":"۲. ترتیب و منابع","body":"بعضی کارها هم‌زمان و بعضی پس از کار قبلی ممکن‌اند. Aufwand زمان کار لازم است و Dauer زمان سپری‌شده. یک ساعت کار به دلیل انتظار قطعه شاید هفتهٔ بعد تمام شود. زمان افراد و دستگاه‌ها را هم لحاظ کن."},{"title":"۳. نقطهٔ عطف و کنترل","body":"نقطهٔ عطف وضعیت مهم قابل بررسی است؛ مثلاً تأیید آمادگی آزمایش. در طول پروژه وضعیت واقعی را با برنامه مقایسه کن و انحراف را زود بررسی کن؛ نه اینکه آخر کار برنامه را مطابق گذشته بازنویسی کنی."}],"example":"تنظیم سه ساعت و آزمایش دو ساعت زمان کار می‌خواهد. چون آزمایش بعد از تنظیم است، دست‌کم پنج ساعت کار لازم است. تأخیر قطعه یا نبود آزمایش‌کننده مدت تقویمی را بیشتر می‌کند. بخشی از مستندات می‌تواند هم‌زمان آماده شود.","mistake":"زمان کار و مدت تقویمی یکی نیستند. سه نفر یک کار تقسیم‌ناپذیر را خودکار سه برابر سریع‌تر انجام نمی‌دهند.","terms":[["Arbeitspaket","وظیفهٔ مشخص با نتیجه و مسئول."],["Aufwand","زمان کار مورد نیاز."],["Dauer","بازهٔ زمانی سپری‌شدهٔ کار."],["Abhängigkeit","نیاز یک کار به نتیجهٔ قبلی."],["Meilenstein","وضعیت مهم و قابل بررسی پروژه."],["Plan-Ist-Vergleich","مقایسهٔ برنامه با وضعیت واقعی."]],"q":"Aufwand چه چیزی را بیان می‌کند؟","options":["زمان کار مورد نیاز","همیشه کل زمان تقویمی","فقط موعد تحویل"],"answer":0,"feedback":"Aufwand کار را می‌سنجد؛ Dauer ترتیب و انتظارهای زمانی را هم دربرمی‌گیرد.","remember":["بستهٔ کاری نتیجه، مسئول و زمان کار می‌خواهد.","Aufwand زمان کار است و Dauer زمان سپری‌شده.","وابستگی و منابع امکان کار هم‌زمان را محدود می‌کند."],"summary":"برنامهٔ مفید، نتیجهٔ قابل بررسی را با ترتیب واقعی، منابع موجود و کنترل پیوسته پیوند می‌دهد."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/wirtschaft":{"de":{"title":"Kosten und Wirtschaftlichkeit berechnen","goal":"Du unterscheidest einmalige und laufende Kosten und berechnest eine einfache Amortisationszeit.","definition":"Wirtschaftlichkeit vergleicht den Nutzen einer Lösung mit ihrem Ressourceneinsatz. Eine technische Entscheidung berücksichtigt deshalb nicht nur den Kaufpreis, sondern auch Einführung, Betrieb, Wartung und mögliche Einsparungen.","explanation":"1. Kosten vollständig sammeln: Einmalige Kosten entstehen beispielsweise für Hardware, Einrichtung und Schulung. Laufende Kosten betreffen etwa Lizenzen, Energie, Wartung und Administration. Bei Arbeitszeit wird der vereinbarte kalkulatorische Stundensatz genutzt. Der Betrachtungszeitraum muss für alle Varianten gleich sein.\n\n2. Nutzen messbar machen: Nutzen kann in gesparter Arbeitszeit, weniger Ausfällen oder höherer Qualität bestehen. Nicht jede Verbesserung lässt sich zuverlässig in Euro ausdrücken. Benenne deshalb Annahmen und qualitative Vorteile getrennt, statt scheinbar genaue Zahlen zu erfinden.\n\n3. Amortisation einordnen: Eine einfache statische Amortisationsrechnung teilt die Anfangsinvestition durch den jährlichen Netto-Rückfluss beziehungsweise die jährliche Netto-Einsparung. Sie setzt vereinfachend gleichbleibende Werte voraus und berücksichtigt den Zeitwert des Geldes nicht. Sie ist eine Orientierung, keine vollständige Investitionsbewertung.","sections":[{"title":"1. Kosten vollständig sammeln","body":"Einmalige Kosten entstehen beispielsweise für Hardware, Einrichtung und Schulung. Laufende Kosten betreffen etwa Lizenzen, Energie, Wartung und Administration. Bei Arbeitszeit wird der vereinbarte kalkulatorische Stundensatz genutzt. Der Betrachtungszeitraum muss für alle Varianten gleich sein."},{"title":"2. Nutzen messbar machen","body":"Nutzen kann in gesparter Arbeitszeit, weniger Ausfällen oder höherer Qualität bestehen. Nicht jede Verbesserung lässt sich zuverlässig in Euro ausdrücken. Benenne deshalb Annahmen und qualitative Vorteile getrennt, statt scheinbar genaue Zahlen zu erfinden."},{"title":"3. Amortisation einordnen","body":"Eine einfache statische Amortisationsrechnung teilt die Anfangsinvestition durch den jährlichen Netto-Rückfluss beziehungsweise die jährliche Netto-Einsparung. Sie setzt vereinfachend gleichbleibende Werte voraus und berücksichtigt den Zeitwert des Geldes nicht. Sie ist eine Orientierung, keine vollständige Investitionsbewertung."}],"example":"Eine Lösung kostet einmalig 6.000 €. Sie spart jährlich 3.000 €, verursacht aber 1.000 € zusätzliche jährliche Betriebskosten. Netto-Einsparung: 2.000 € pro Jahr. Einfache Amortisationszeit: 6.000 / 2.000 = 3 Jahre. Weitere Risiken und nicht bezifferte Vorteile werden zusätzlich dokumentiert.","mistake":"Die jährlichen Zusatzkosten dürfen nicht vergessen werden. Sonst sieht die Investition fälschlich schneller bezahlt aus.","terms":[["Investition","Anfangsausgabe für eine längerfristig genutzte Lösung."],["Betriebskosten","Kosten während der laufenden Nutzung."],["Stundensatz","Kalkulatorischer Betrag je Arbeitsstunde."],["Netto-Einsparung","Einsparung nach Abzug zusätzlicher Kosten."],["Amortisationszeit","Vereinfachte Zeit bis zum Ausgleich einer Investition."],["TCO","Gesamtkosten über einen festgelegten Betrachtungszeitraum."]],"q":"6.000 € Investition und 2.000 € jährliche Netto-Einsparung ergeben vereinfacht?","options":["3 Jahre","12 Jahre","2 Monate"],"answer":0,"feedback":"6.000 € geteilt durch 2.000 € pro Jahr ergibt 3 Jahre.","remember":["Einmalige und laufende Kosten vollständig erfassen.","Netto-Einsparung berücksichtigt zusätzliche Betriebskosten.","Einfache Amortisation berücksichtigt den Zeitwert des Geldes nicht."],"summary":"Eine belastbare Wirtschaftlichkeitsbetrachtung macht Kosten, messbaren Nutzen und vereinfachende Annahmen gemeinsam sichtbar."},"fa":{"title":"محاسبهٔ هزینه و اقتصادی‌بودن","goal":"هزینهٔ اولیه و جاری را جدا و زمان بازگشت ساده را حساب کنی.","definition":"اقتصادی‌بودن، فایدهٔ راه‌حل را با منابع مصرف‌شده مقایسه می‌کند. پس تصمیم فنی فقط قیمت خرید نیست؛ راه‌اندازی، بهره‌برداری، نگهداری و صرفه‌جویی هم مهم‌اند.","explanation":"۱. جمع‌آوری هزینه: خرید سخت‌افزار، نصب و آموزش معمولاً هزینهٔ اولیه‌اند. مجوز، برق، نگهداری و مدیریت می‌توانند هزینهٔ جاری باشند. زمان کار با نرخ محاسباتی توافق‌شده سنجیده می‌شود. دورهٔ مقایسهٔ گزینه‌ها باید یکسان باشد.\n\n۲. فایدهٔ قابل سنجش: کاهش زمان کار، قطعی کمتر یا کیفیت بالاتر فایده است. همهٔ فایده‌ها دقیقاً به یورو تبدیل نمی‌شوند؛ فرض‌ها و مزیت کیفی را جدا بنویس و عدد دقیق ساختگی نساز.\n\n۳. زمان بازگشت: در محاسبهٔ ساده، سرمایه‌گذاری اولیه بر صرفه‌جویی خالص سالانه تقسیم می‌شود. فرض ساده این است که مقدار سالانه ثابت است و ارزش زمانی پول لحاظ نمی‌شود. این فقط راهنمای اولیه است؛ نه ارزیابی کامل سرمایه‌گذاری.","sections":[{"title":"۱. جمع‌آوری هزینه","body":"خرید سخت‌افزار، نصب و آموزش معمولاً هزینهٔ اولیه‌اند. مجوز، برق، نگهداری و مدیریت می‌توانند هزینهٔ جاری باشند. زمان کار با نرخ محاسباتی توافق‌شده سنجیده می‌شود. دورهٔ مقایسهٔ گزینه‌ها باید یکسان باشد."},{"title":"۲. فایدهٔ قابل سنجش","body":"کاهش زمان کار، قطعی کمتر یا کیفیت بالاتر فایده است. همهٔ فایده‌ها دقیقاً به یورو تبدیل نمی‌شوند؛ فرض‌ها و مزیت کیفی را جدا بنویس و عدد دقیق ساختگی نساز."},{"title":"۳. زمان بازگشت","body":"در محاسبهٔ ساده، سرمایه‌گذاری اولیه بر صرفه‌جویی خالص سالانه تقسیم می‌شود. فرض ساده این است که مقدار سالانه ثابت است و ارزش زمانی پول لحاظ نمی‌شود. این فقط راهنمای اولیه است؛ نه ارزیابی کامل سرمایه‌گذاری."}],"example":"خرید اولیه ۶۰۰۰ یورو است. صرفه‌جویی سالانه ۳۰۰۰ و هزینهٔ جاری اضافی ۱۰۰۰ یورو است. پس صرفه‌جویی خالص ۲۰۰۰ یورو و بازگشت ساده ۶۰۰۰ تقسیم بر ۲۰۰۰ یعنی سه سال می‌شود. خطر و مزیت غیرعددی جدا ثبت می‌شود.","mistake":"اگر هزینهٔ جاری اضافه را حذف کنی، زمان بازگشت به‌اشتباه کوتاه‌تر دیده می‌شود.","terms":[["Investition","هزینهٔ اولیه برای راه‌حل بلندمدت."],["Betriebskosten","هزینهٔ زمان استفادهٔ جاری."],["Stundensatz","مبلغ محاسباتی هر ساعت کار."],["Netto-Einsparung","صرفه‌جویی پس از کسر هزینهٔ اضافی."],["Amortisationszeit","زمان سادهٔ جبران سرمایه‌گذاری."],["TCO","جمع هزینه‌ها در بازهٔ مشخص."]],"q":"سرمایه‌گذاری ۶۰۰۰ و صرفه‌جویی خالص سالانه ۲۰۰۰ یورو، چه زمان بازگشت ساده دارد؟","options":["سه سال","دوازده سال","دو ماه"],"answer":0,"feedback":"۶۰۰۰ یورو تقسیم بر ۲۰۰۰ یورو در سال برابر سه سال است.","remember":["هزینهٔ اولیه و جاری را کامل ثبت کن.","صرفه‌جویی خالص، هزینهٔ جاری اضافی را کم می‌کند.","بازگشت ساده ارزش زمانی پول را در نظر نمی‌گیرد."],"summary":"بررسی اقتصادی معتبر، هزینه، فایدهٔ قابل سنجش و فرض‌های ساده‌کننده را با هم نشان می‌دهد."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/test":{"de":{"title":"Testfälle und Abnahme vorbereiten","goal":"Du formulierst einen Test mit Voraussetzung, Aktion und erwartetem Ergebnis.","definition":"Ein Test prüft, ob ein System eine bestimmte Anforderung erfüllt. Die Abnahme bewertet das vereinbarte Projektergebnis mit dem Kunden. Gute Testfälle machen nachvollziehbar, was tatsächlich geprüft und welches Ergebnis festgestellt wurde.","explanation":"1. Test aus Anforderungen ableiten: Jede wichtige Anforderung braucht passende Prüfungen. Definiere Ausgangszustand, Testdaten, Schritte und erwartetes Ergebnis. Ein positiver Test prüft erlaubte Nutzung; ein negativer Test prüft beispielsweise, ob unberechtigter Zugriff verhindert wird.\n\n2. Ergebnis dokumentieren: Halte den tatsächlichen Ausgang und relevante Belege fest. „Hat funktioniert“ ist zu wenig, wenn niemand Testkonto, Datum oder geprüfte Funktion kennt. Fehler werden beschrieben, priorisiert, behoben und erneut geprüft. Eine Testumgebung soll den relevanten Bedingungen ausreichend entsprechen.\n\n3. Abnahme durchführen: Vergleiche die Ergebnisse mit den vereinbarten Abnahmekriterien. Dokumentiere erfüllte Punkte, bekannte Mängel und vereinbarte nächste Schritte. Eine Abnahme ist keine bloße Präsentation; sie braucht eine klare Prüfung des vereinbarten Leistungsumfangs.","sections":[{"title":"1. Test aus Anforderungen ableiten","body":"Jede wichtige Anforderung braucht passende Prüfungen. Definiere Ausgangszustand, Testdaten, Schritte und erwartetes Ergebnis. Ein positiver Test prüft erlaubte Nutzung; ein negativer Test prüft beispielsweise, ob unberechtigter Zugriff verhindert wird."},{"title":"2. Ergebnis dokumentieren","body":"Halte den tatsächlichen Ausgang und relevante Belege fest. „Hat funktioniert“ ist zu wenig, wenn niemand Testkonto, Datum oder geprüfte Funktion kennt. Fehler werden beschrieben, priorisiert, behoben und erneut geprüft. Eine Testumgebung soll den relevanten Bedingungen ausreichend entsprechen."},{"title":"3. Abnahme durchführen","body":"Vergleiche die Ergebnisse mit den vereinbarten Abnahmekriterien. Dokumentiere erfüllte Punkte, bekannte Mängel und vereinbarte nächste Schritte. Eine Abnahme ist keine bloße Präsentation; sie braucht eine klare Prüfung des vereinbarten Leistungsumfangs."}],"example":"Testfall: Ein Gastkonto darf die Personal-Freigabe nicht lesen. Voraussetzung: aktives Gastkonto ohne Personalgruppe. Aktion: Zugriff auf die Freigabe versuchen. Erwartet: Zugriff verweigert. Tatsächlich: Zugriff verweigert; Test bestanden. Mit einem berechtigten Personalkonto prüfst du zusätzlich, ob notwendiger Zugriff möglich bleibt.","mistake":"Nur erfolgreiche Standardfälle zu testen reicht nicht. Rechte, fehlerhafte Eingaben und wichtige Ausfallsituationen brauchen passende Gegenproben.","terms":[["Testfall","Beschriebene Prüfung mit erwartetem Ergebnis."],["Voraussetzung","Zustand, der vor dem Test vorhanden sein muss."],["Testdaten","Für eine Prüfung ausgewählte Eingabedaten."],["Negativtest","Prüfung, ob unerlaubte oder fehlerhafte Fälle korrekt behandelt werden."],["Soll-Ergebnis","Erwarteter Ausgang einer Prüfung."],["Abnahmeprotokoll","Dokumentiertes Ergebnis der vereinbarten Leistungsprüfung."]],"q":"Was gehört neben Testschritten in einen Testfall?","options":["Nur das Lieblingswerkzeug","Voraussetzungen und erwartetes Ergebnis","Nur der Preis des Geräts"],"answer":1,"feedback":"Ohne Ausgangszustand und Erwartung ist der Testerfolg nicht eindeutig bewertbar.","remember":["Testfälle aus Anforderungen und Abnahmekriterien ableiten.","Voraussetzung, Aktion und erwartetes Ergebnis festhalten.","Negative Tests prüfen unerlaubte oder fehlerhafte Fälle."],"summary":"Nachvollziehbare Tests liefern die Belege, mit denen Kunde und Projektteam die vereinbarte Leistung bewerten können."},"fa":{"title":"آماده‌سازی آزمایش و پذیرش","goal":"آزمایش را با پیش‌نیاز، عمل و نتیجهٔ مورد انتظار بنویسی.","definition":"Test بررسی می‌کند سیستم نیاز مشخص را تأمین می‌کند یا نه. Abnahme نتیجهٔ توافق‌شده را با مشتری ارزیابی می‌کند. آزمایش خوب روشن می‌کند چه چیزی و با چه نتیجه‌ای بررسی شده است.","explanation":"۱. آزمایش از نیاز: هر نیاز مهم آزمایش متناسب می‌خواهد. وضعیت شروع، داده، مراحل و نتیجهٔ مورد انتظار را مشخص کن. آزمایش مثبت استفادهٔ مجاز را می‌سنجد و آزمایش منفی مثلاً جلوگیری از دسترسی غیرمجاز را.\n\n۲. ثبت نتیجه: نتیجهٔ واقعی و شاهد مناسب را بنویس. «کار کرد» کافی نیست اگر حساب آزمایش، تاریخ یا عملکرد مشخص نباشد. خطا شرح، اولویت‌بندی، اصلاح و دوباره آزمایش می‌شود. محیط تست باید شرایط مهم را به اندازهٔ کافی بازنمایی کند.\n\n۳. پذیرش: نتیجه را با معیار توافق‌شده مقایسه کن. موارد موفق، نقص‌های معلوم و کار بعدی را ثبت کن. پذیرش فقط ارائهٔ نمایشی نیست؛ محدودهٔ توافق‌شده باید واقعاً بررسی شود.","sections":[{"title":"۱. آزمایش از نیاز","body":"هر نیاز مهم آزمایش متناسب می‌خواهد. وضعیت شروع، داده، مراحل و نتیجهٔ مورد انتظار را مشخص کن. آزمایش مثبت استفادهٔ مجاز را می‌سنجد و آزمایش منفی مثلاً جلوگیری از دسترسی غیرمجاز را."},{"title":"۲. ثبت نتیجه","body":"نتیجهٔ واقعی و شاهد مناسب را بنویس. «کار کرد» کافی نیست اگر حساب آزمایش، تاریخ یا عملکرد مشخص نباشد. خطا شرح، اولویت‌بندی، اصلاح و دوباره آزمایش می‌شود. محیط تست باید شرایط مهم را به اندازهٔ کافی بازنمایی کند."},{"title":"۳. پذیرش","body":"نتیجه را با معیار توافق‌شده مقایسه کن. موارد موفق، نقص‌های معلوم و کار بعدی را ثبت کن. پذیرش فقط ارائهٔ نمایشی نیست؛ محدودهٔ توافق‌شده باید واقعاً بررسی شود."}],"example":"آزمایش: مهمان نباید پوشهٔ پرسنلی را بخواند. پیش‌نیاز حساب مهمان فعال بدون گروه پرسنل است. عمل، تلاش برای دسترسی است و انتظار، ردشدن. اگر دسترسی رد شد تست موفق است. با حساب مجاز هم بررسی می‌کنی دسترسی لازم همچنان ممکن باشد.","mistake":"فقط حالت عادی موفق را آزمایش نکن؛ مجوز، ورودی خراب و حالت قطعی مهم هم بررسی مناسب می‌خواهد.","terms":[["Testfall","آزمایش شرح‌داده‌شده با انتظار روشن."],["Voraussetzung","شرط لازم پیش از شروع آزمایش."],["Testdaten","دادهٔ انتخاب‌شده برای آزمایش."],["Negativtest","آزمایش برخورد درست با حالت غیرمجاز یا خراب."],["Soll-Ergebnis","نتیجهٔ مورد انتظار."],["Abnahmeprotokoll","ثبت نتیجهٔ بررسی عملکرد توافق‌شده."]],"q":"علاوه بر مراحل، چه چیزی در Testfall لازم است؟","options":["فقط ابزار محبوب","پیش‌نیاز و نتیجهٔ مورد انتظار","فقط قیمت دستگاه"],"answer":1,"feedback":"بدون وضعیت شروع و انتظار نمی‌توان موفقیت تست را روشن سنجید.","remember":["Test را از نیاز و معیار پذیرش بساز.","پیش‌نیاز، عمل و نتیجهٔ مورد انتظار را ثبت کن.","تست منفی، حالت خراب یا غیرمجاز را بررسی می‌کند."],"summary":"تست قابل پیگیری شواهدی می‌دهد که مشتری و تیم بتوانند عملکرد توافق‌شده را ارزیابی کنند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true},"k12-projekt/dokumentation":{"de":{"title":"Dokumentation, Übergabe und Projektbewertung","goal":"Du unterscheidest technische Dokumentation von einer Anleitung und bewertest das Ergebnis anhand des Ziels.","definition":"Dokumentation macht eine Lösung für andere nachvollziehbar und weiter betreibbar. Die Übergabe stellt sicher, dass der Kunde das Ergebnis nutzen und die zuständige Betriebsstelle es betreuen kann. Sie gehört zum Projektabschluss.","explanation":"1. Technische Dokumentation: Erkläre Aufbau, Adressen, wichtige Konfigurationen, Abhängigkeiten und Zuständigkeiten. Dokumentiere außerdem Sicherung, Wiederherstellung und Wartung. Geheimnisse werden über geeignete geschützte Verfahren übergeben; sie gehören nicht offen in eine allgemein verteilte Anleitung.\n\n2. Benutzer und Betrieb einweisen: Eine Benutzeranleitung beschreibt die benötigten Arbeitsschritte in verständlicher Sprache. Eine Betriebseinweisung erklärt Überwachung, typische Störungen und Eskalationswege. Prüfe mit den Empfängern, ob die Unterlagen tatsächlich verständlich und nutzbar sind.\n\n3. Ergebnis bewerten: Vergleiche Projektziel und tatsächliches Ergebnis: Funktion, Qualität, Kosten und Termine. Begründe Abweichungen und benenne sinnvolle Verbesserungen. Rückmeldungen des Kunden sind wichtig. Eine sachliche Reflexion nennt auch Grenzen und offene Punkte, statt nur den Erfolg zu behaupten.","sections":[{"title":"1. Technische Dokumentation","body":"Erkläre Aufbau, Adressen, wichtige Konfigurationen, Abhängigkeiten und Zuständigkeiten. Dokumentiere außerdem Sicherung, Wiederherstellung und Wartung. Geheimnisse werden über geeignete geschützte Verfahren übergeben; sie gehören nicht offen in eine allgemein verteilte Anleitung."},{"title":"2. Benutzer und Betrieb einweisen","body":"Eine Benutzeranleitung beschreibt die benötigten Arbeitsschritte in verständlicher Sprache. Eine Betriebseinweisung erklärt Überwachung, typische Störungen und Eskalationswege. Prüfe mit den Empfängern, ob die Unterlagen tatsächlich verständlich und nutzbar sind."},{"title":"3. Ergebnis bewerten","body":"Vergleiche Projektziel und tatsächliches Ergebnis: Funktion, Qualität, Kosten und Termine. Begründe Abweichungen und benenne sinnvolle Verbesserungen. Rückmeldungen des Kunden sind wichtig. Eine sachliche Reflexion nennt auch Grenzen und offene Punkte, statt nur den Erfolg zu behaupten."}],"example":"Bei Übergabe eines Dateiservers erhält die IT den Netzplan, die Rechteübersicht und das Wiederherstellungsverfahren. Benutzer erhalten eine kurze Anleitung zum Einbinden der Freigabe. Im Abschlussgespräch zeigst du, welche Testkriterien erfüllt wurden und dass eine vereinbarte Zusatzfunktion noch außerhalb des aktuellen Auftrags liegt.","mistake":"Eine Sammlung von Screenshots ohne Erklärung ist keine ausreichende Betriebsdokumentation. Die nächste Person muss verstehen, was und warum konfiguriert wurde.","terms":[["Technische Dokumentation","Nachvollziehbare Beschreibung von Aufbau und Betrieb."],["Benutzeranleitung","Verständliche Anleitung zur Nutzung."],["Übergabe","Geordnete Übermittlung von Ergebnis und benötigtem Wissen."],["Einweisung","Erklärung der Bedienung oder Betreuung."],["Projektbewertung","Vergleich von Ziel und Ergebnis anhand von Kriterien."],["Lessons Learned","Festgehaltene Erkenntnisse für spätere Vorhaben."]],"q":"Welche Unterlage hilft dem Betrieb bei einem Datenverlust besonders?","options":["Nur ein Bild des Servergehäuses","Ein geprüftes Wiederherstellungsverfahren","Nur der Projektname"],"answer":1,"feedback":"Ein nachvollziehbarer und getesteter Restore-Ablauf unterstützt die tatsächliche Wiederaufnahme des Betriebs.","remember":["Technische Dokumentation erklärt Aufbau und Betrieb.","Benutzeranleitungen orientieren sich an den Arbeitsschritten der Nutzer.","Projektbewertung vergleicht Ziel, Ergebnis und begründete Abweichungen."],"summary":"Eine gute Übergabe macht die Lösung nutzbar, betreibbar und anhand der vereinbarten Ziele ehrlich bewertbar."},"fa":{"title":"مستندسازی، تحویل و ارزیابی پروژه","goal":"مستند فنی را از راهنمای کاربر جدا و نتیجه را با هدف مقایسه کنی.","definition":"مستندات باعث می‌شود دیگران راه‌حل را بفهمند و نگهداری کنند. تحویل اطمینان می‌دهد مشتری بتواند نتیجه را استفاده کند و مسئول بهره‌برداری آن را اداره کند. این کار بخشی از پایان پروژه است.","explanation":"۱. مستند فنی: ساختار، آدرس‌ها، تنظیم مهم، وابستگی و مسئول را توضیح بده. روش پشتیبان، بازیابی و نگهداری را هم ثبت کن. اطلاعات محرمانه از راه محافظت‌شدهٔ مناسب تحویل می‌شود؛ نه در راهنمای عمومی.\n\n۲. آموزش کاربر و مسئول: راهنمای کاربر مراحل کار را ساده توضیح می‌دهد. آموزش بهره‌برداری، نظارت، خطاهای معمول و راه ارجاع را روشن می‌کند. با گیرنده بررسی کن که نوشته واقعاً قابل فهم و استفاده باشد.\n\n۳. ارزیابی: هدف و نتیجه را از نظر کارکرد، کیفیت، هزینه و زمان مقایسه کن. اختلاف را دلیل بیاور و بهبود مناسب بنویس. بازخورد مشتری مهم است. ارزیابی واقعی محدودیت و کار باز را هم ذکر می‌کند.","sections":[{"title":"۱. مستند فنی","body":"ساختار، آدرس‌ها، تنظیم مهم، وابستگی و مسئول را توضیح بده. روش پشتیبان، بازیابی و نگهداری را هم ثبت کن. اطلاعات محرمانه از راه محافظت‌شدهٔ مناسب تحویل می‌شود؛ نه در راهنمای عمومی."},{"title":"۲. آموزش کاربر و مسئول","body":"راهنمای کاربر مراحل کار را ساده توضیح می‌دهد. آموزش بهره‌برداری، نظارت، خطاهای معمول و راه ارجاع را روشن می‌کند. با گیرنده بررسی کن که نوشته واقعاً قابل فهم و استفاده باشد."},{"title":"۳. ارزیابی","body":"هدف و نتیجه را از نظر کارکرد، کیفیت، هزینه و زمان مقایسه کن. اختلاف را دلیل بیاور و بهبود مناسب بنویس. بازخورد مشتری مهم است. ارزیابی واقعی محدودیت و کار باز را هم ذکر می‌کند."}],"example":"در تحویل فایل‌سرور، IT نقشهٔ شبکه، جدول دسترسی و روش بازیابی می‌گیرد. کاربر راهنمای کوتاه اتصال پوشه دریافت می‌کند. جلسهٔ پایان نشان می‌دهد کدام تست موفق بوده و قابلیت اضافی مورد توافق خارج از محدودهٔ فعلی است.","mistake":"عکس تنظیمات بدون توضیح مستند کافی نیست؛ شخص بعدی باید بداند چه چیزی و با چه دلیل تنظیم شده است.","terms":[["Technische Dokumentation","شرح قابل پیگیری ساختار و بهره‌برداری."],["Benutzeranleitung","راهنمای قابل فهم استفاده."],["Übergabe","تحویل منظم نتیجه و دانش لازم."],["Einweisung","آموزش استفاده یا نگهداری."],["Projektbewertung","مقایسهٔ هدف و نتیجه با معیار."],["Lessons Learned","درس‌های ثبت‌شده برای پروژه‌های بعد."]],"q":"هنگام ازدست‌رفتن داده کدام مدرک بیشتر به مسئول سیستم کمک می‌کند؟","options":["فقط عکس کیس","روش بازیابی آزمایش‌شده","فقط نام پروژه"],"answer":1,"feedback":"روش روشن و تست‌شدهٔ Restore به بازگشت واقعی سرویس کمک می‌کند.","remember":["مستند فنی، ساختار و بهره‌برداری را توضیح می‌دهد.","راهنمای کاربر بر مراحل کار واقعی او متمرکز است.","ارزیابی، هدف و نتیجه و دلیل اختلاف را مقایسه می‌کند."],"summary":"تحویل خوب راه‌حل را قابل استفاده، قابل نگهداری و بر پایهٔ هدف‌های توافق‌شده قابل ارزیابی می‌کند."},"minutes":9,"source":["ISB Bayern · FISI, Jahrgangsstufe 12","https://www.isb.bayern.de/fileadmin/user_upload/Berufliche_Schulen/Berufsschule/Lehrplan/bs_lpr_fachinformatiker.pdf"],"editorial":true}});
const EXTRA_TERMS={
'it-systeme/subnet':[['Hostanteil','Die Bits einer IP-Adresse, die innerhalb des Subnetzes eine Schnittstelle unterscheiden.','بیت‌هایی از آدرس IP که یک رابط را داخل زیرشبکه مشخص می‌کنند.'],['Blockgröße','Anzahl aller Adressen eines Subnetzes; bei /26 sind es 64.','تعداد کل آدرس‌های زیرشبکه؛ در /26 برابر ۶۴ است.'],['Subnetzmaske','Bitmuster, das Netzanteil und Hostanteil einer IP-Adresse trennt.','الگوی بیتی که بخش شبکه و دستگاهِ آدرس IP را جدا می‌کند.']],
'it-systeme/dns':[['TTL','Gültigkeitsdauer einer zwischengespeicherten DNS-Antwort in Sekunden.','مدت اعتبار پاسخ DNS در حافظهٔ موقت، بر حسب ثانیه.'],['MX-Record','DNS-Eintrag, der einen zuständigen Mailserver einer Domain nennt.','رکورد DNS که سرور مسئول ایمیل یک دامنه را مشخص می‌کند.'],['DHCP','Protokoll zur automatischen Vergabe von Netzwerkkonfiguration; löst selbst keine DNS-Namen auf.','پروتکل واگذاری خودکار تنظیمات شبکه؛ خودش نام DNS را تبدیل نمی‌کند.']],
'it-systeme/ip':[['ARP','Ermittelt in einem lokalen IPv4-Ethernet die MAC-Adresse zu einer IP-Adresse.','در Ethernet محلی با IPv4، آدرس MAC مربوط به یک IP را پیدا می‌کند.'],['Netzadresse','Adresse, die ein IP-Subnetz mit seinen Netzbits bezeichnet.','آدرسی که با بیت‌های شبکه، یک زیرشبکهٔ IP را مشخص می‌کند.'],['Routingtabelle','Enthält bekannte Zielnetze und den jeweiligen nächsten Übertragungsweg.','شامل شبکه‌های مقصد شناخته‌شده و مسیر بعدی رسیدن به آن‌هاست.']],
'aeup/er':[['Primärschlüssel','Ausgewählter eindeutiger Schlüssel einer Tabelle; kann aus mehreren Spalten bestehen.','کلید یکتای انتخاب‌شدهٔ جدول که می‌تواند از چند ستون تشکیل شود.'],['Kardinalität','Beschreibt, wie viele Objekte einer Seite mit Objekten der anderen Seite verbunden sein dürfen oder müssen.','مشخص می‌کند چند مورد از یک طرف می‌توانند یا باید با طرف دیگر مرتبط باشند.'],['Entitätstyp','Art gleichartiger Objekte mit gemeinsamen Eigenschaften, beispielsweise Mitarbeiter.','نوعی از موارد هم‌جنس با ویژگی‌های مشترک؛ مثلاً کارمند.']]
};
for(const [key,terms] of Object.entries(EXTRA_TERMS))for(const [term,de,fa] of terms){REVISED[key].de.terms.push([term,de]);REVISED[key].fa.terms.push([term,fa]);}

for(const [term,de,fa] of [
 ['Presentation','Schicht 6: Datenformate, Codierung und konzeptionell auch Kompression und Verschlüsselung.','لایهٔ ۶؛ قالب داده، کدگذاری و در مدل مفهومی، فشرده‌سازی و رمزنگاری.'],
 ['Session','Schicht 5: Organisation und Verwaltung des Dialogs zwischen Kommunikationspartnern.','لایهٔ ۵؛ سازمان‌دهی و مدیریت گفت‌وگو بین طرف‌های ارتباط.']
]){REVISED['k10-fuit/osi'].de.terms.push([term,de]);REVISED['k10-fuit/osi'].fa.terms.push([term,fa]);}
